package com.pluginideahub.combatachievements;

import com.pluginideahub.combatachievements.core.achievement.AchievementTier;
import com.pluginideahub.combatachievements.core.achievement.CombatAchievement;
import com.pluginideahub.combatachievements.core.achievement.CombatAchievementLibrary;
import com.pluginideahub.combatachievements.core.progress.ProgressSnapshot;
import com.pluginideahub.combatachievements.core.tier.TierMath;
import java.util.HashSet;
import java.util.Set;

/**
 * Builds a deterministic, plausible progress snapshot so the full UI is reviewable while the live
 * varbit reader is gated (see {@code varbit.CaVarbitIds}). Dev-only; never used once
 * {@code CaVarbitIds.VERIFIED} is true.
 */
final class SampleProgress
{
	private SampleProgress()
	{
	}

	static ProgressSnapshot build(CombatAchievementLibrary lib)
	{
		Set<Integer> completed = new HashSet<>();
		for (CombatAchievement task : lib.all())
		{
			if (isSampleComplete(task))
			{
				completed.add(task.id());
			}
		}
		int computed = 0;
		for (Integer id : completed)
		{
			computed += lib.pointsById().getOrDefault(id, 0);
		}
		AchievementTier current = TierMath.currentTierFor(computed, lib.all());
		return new ProgressSnapshot(completed, computed, computed, current, 0L, true);
	}

	private static boolean isSampleComplete(CombatAchievement task)
	{
		switch (task.tier())
		{
			case EASY:
				return true;
			case MEDIUM:
				return task.id() % 2 == 0;
			case HARD:
				return task.id() % 5 == 0;
			default:
				return false;
		}
	}
}

package com.pluginideahub.combatachievements.bridge;

import com.pluginideahub.combatachievements.core.ranking.PlayerProfile;
import java.util.HashMap;
import java.util.HashSet;
import java.util.Map;
import java.util.Set;
import net.runelite.api.Client;
import net.runelite.api.Quest;
import net.runelite.api.QuestState;
import net.runelite.api.Skill;

/**
 * Reads the logged-in account's real skill levels and quest-completion state from the client into a
 * pure {@link PlayerProfile}. The only piece that touches {@link Client} for account state; must run
 * on the client thread. Skills are keyed by {@link Skill#getName()} and quests by
 * {@link Quest#getName()} so they match the dataset's level- and quest-requirement keys.
 */
public final class AccountReader
{
	private AccountReader()
	{
	}

	public static PlayerProfile readProfile(Client client)
	{
		if (client == null)
		{
			return PlayerProfile.empty();
		}
		Map<String, Integer> levels = new HashMap<>();
		for (Skill skill : Skill.values())
		{
			try
			{
				levels.put(skill.getName(), client.getRealSkillLevel(skill));
			}
			catch (RuntimeException ignored)
			{
				// skip any skill the client can't report right now
			}
		}

		Set<String> completed = new HashSet<>();
		Set<String> started = new HashSet<>();
		for (Quest quest : Quest.values())
		{
			try
			{
				QuestState state = quest.getState(client);
				if (state == QuestState.FINISHED)
				{
					completed.add(quest.getName());
					started.add(quest.getName());
				}
				else if (state == QuestState.IN_PROGRESS)
				{
					started.add(quest.getName());
				}
			}
			catch (RuntimeException ignored)
			{
				// skip any quest whose state can't be resolved right now
			}
		}

		return PlayerProfile.of(levels, completed, started);
	}
}

package com.pluginideahub.combatachievements.bridge;

import com.pluginideahub.combatachievements.core.effort.MonsterNames;
import java.util.HashMap;
import java.util.Map;
import net.runelite.client.hiscore.HiscoreResult;
import net.runelite.client.hiscore.HiscoreSkill;
import net.runelite.client.hiscore.HiscoreSkillType;
import net.runelite.client.hiscore.Skill;

/**
 * Backfills historical per-boss kill count from the OSRS HiScores (via RuneLite's {@code HiscoreClient}).
 * The chat tracker only sees kills made while the plugin runs; the hiscores carry the player's whole
 * ranked history, so seeding from them gives competence/partial-progress from kill 1. Maps each
 * {@code HiscoreSkill} of type BOSS to the dataset monster key via {@link MonsterNames}. Unranked
 * bosses report a level of -1 and are skipped.
 */
public final class HiscoreKcReader
{
	private HiscoreKcReader()
	{
	}

	/** Extracts {dataset monster key → kill count} from a hiscore lookup result. */
	public static Map<String, Integer> read(HiscoreResult result)
	{
		Map<String, Integer> out = new HashMap<>();
		if (result == null)
		{
			return out;
		}
		for (HiscoreSkill hs : HiscoreSkill.values())
		{
			if (hs.getType() != HiscoreSkillType.BOSS)
			{
				continue;
			}
			Skill skill = result.getSkill(hs);
			if (skill == null)
			{
				continue;
			}
			int kc = skill.getLevel();
			if (kc <= 0)
			{
				continue; // unranked (-1) or zero
			}
			String key = MonsterNames.toDatasetKey(hs.getName());
			if (!key.isEmpty())
			{
				out.merge(key, kc, Math::max);
			}
		}
		return out;
	}
}

package com.pluginideahub.combatachievements.bridge;

import com.pluginideahub.combatachievements.core.effort.CombatExperience;
import com.pluginideahub.combatachievements.core.effort.MonsterNames;
import java.util.HashMap;
import java.util.Locale;
import java.util.Map;
import java.util.Optional;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

/**
 * Accumulates per-boss kill count from the in-game "kill count is: N" chat messages (the same source
 * the loot/boss trackers use — no special API needed), so the effort engine gets partial progress on
 * Kill Count CAs and a competence signal for execution CAs. The parser is pure and unit-tested; the
 * accumulated map is the live state. Keyed by the boss name as the dataset spells it.
 *
 * <p>Captures kills observed while the plugin runs; the plugin persists the map per account so it
 * survives restarts. (A future enhancement can backfill historical KC from the collection log.)</p>
 */
public final class KillCountTracker
{
	// Boss lines carry an explicit "kill count" / "completion count" / "chest count" phrase, e.g.
	// "Your Vorkath kill count is: 1,234." / "Your Theatre of Blood total completion count is: 12" /
	// "Your Barrows chest count is: 40".
	private static final Pattern KC_PHRASE = Pattern.compile(
		"your (.+?) (?:kill count|total completion count|completion count|chest count) is: ?([\\d,]+)",
		Pattern.CASE_INSENSITIVE);
	// Raid completions use a bare "count" but always behind "completed", e.g.
	// "Your completed Chambers of Xeric count is: 50" — anchoring on "completed" avoids matching
	// unrelated "... count is:" tally lines (slayer tasks, etc.).
	private static final Pattern KC_COMPLETED = Pattern.compile(
		"your completed (.+?) count is: ?([\\d,]+)", Pattern.CASE_INSENSITIVE);

	private final Map<String, Integer> kcByMonster = new HashMap<>();

	/** A parsed kill-count update from a chat message. */
	public static final class Update
	{
		private final String boss;
		private final int count;

		Update(String boss, int count)
		{
			this.boss = boss;
			this.count = count;
		}

		public String boss()
		{
			return boss;
		}

		public int count()
		{
			return count;
		}
	}

	/** Parses a kill-count chat message, or empty when the message is not one. Pure. */
	public static Optional<Update> parse(String message)
	{
		if (message == null)
		{
			return Optional.empty();
		}
		String text = message.trim();
		Matcher m = KC_PHRASE.matcher(text);
		if (!m.find())
		{
			m = KC_COMPLETED.matcher(text);
			if (!m.find())
			{
				return Optional.empty();
			}
		}
		String boss = m.group(1).trim();
		try
		{
			int count = Integer.parseInt(m.group(2).replace(",", ""));
			return boss.isEmpty() ? Optional.empty() : Optional.of(new Update(boss, count));
		}
		catch (NumberFormatException ex)
		{
			return Optional.empty();
		}
	}

	/** Feeds a chat message; updates the tracked KC if it is a kill-count line. Returns true if matched. */
	public synchronized boolean onMessage(String message)
	{
		Optional<Update> update = parse(message);
		if (!update.isPresent())
		{
			return false;
		}
		// Canonicalise the chat boss name to the dataset's monster key, then keep the highest seen.
		String key = MonsterNames.toDatasetKey(update.get().boss());
		if (key.isEmpty())
		{
			return false;
		}
		kcByMonster.merge(key, update.get().count(), Math::max);
		return true;
	}

	/** Replaces the tracked state (e.g. from persisted config). */
	public synchronized void load(Map<String, Integer> persisted)
	{
		kcByMonster.clear();
		mergeMax(persisted);
	}

	/** Merges in KC (taking the higher value), e.g. a hiscore backfill alongside live chat tracking. */
	public synchronized void seed(Map<String, Integer> kc)
	{
		mergeMax(kc);
	}

	private void mergeMax(Map<String, Integer> kc)
	{
		if (kc == null)
		{
			return;
		}
		for (Map.Entry<String, Integer> e : kc.entrySet())
		{
			if (e.getKey() != null && e.getValue() != null && e.getValue() >= 0)
			{
				kcByMonster.merge(e.getKey().trim().toLowerCase(Locale.ROOT), e.getValue(), Math::max);
			}
		}
	}

	public synchronized Map<String, Integer> asMap()
	{
		return new HashMap<>(kcByMonster);
	}

	public synchronized void clear()
	{
		kcByMonster.clear();
	}

	/** A pure snapshot for the effort engine. */
	public synchronized CombatExperience snapshot()
	{
		return CombatExperience.of(kcByMonster);
	}
}

package com.pluginideahub.combatachievements.core.achievement;

/**
 * The six Combat Achievement tiers. A completed task awards points equal to its tier rank
 * (Easy=1 .. Grandmaster=6); this is a structural OSRS constant and is the one value safe to encode
 * here. Task <em>counts</em> and therefore tier-unlock <em>thresholds</em> are NOT hard-coded — they
 * are derived from the loaded dataset at runtime (see {@code core.tier.TierMath}) so they self-update
 * when Jagex adds tasks. See docs/DESIGN.md §4.2.
 */
public enum AchievementTier
{
	EASY("Easy", 1),
	MEDIUM("Medium", 2),
	HARD("Hard", 3),
	ELITE("Elite", 4),
	MASTER("Master", 5),
	GRANDMASTER("Grandmaster", 6);

	private final String displayName;
	private final int pointsPerTask;

	AchievementTier(String displayName, int pointsPerTask)
	{
		this.displayName = displayName;
		this.pointsPerTask = pointsPerTask;
	}

	public String displayName()
	{
		return displayName;
	}

	public int pointsPerTask()
	{
		return pointsPerTask;
	}

	/** Resolves a tier from the wiki's display string (case-insensitive); null if unrecognized. */
	public static AchievementTier fromDisplayName(String name)
	{
		if (name == null)
		{
			return null;
		}
		String trimmed = name.trim();
		for (AchievementTier tier : values())
		{
			if (tier.displayName.equalsIgnoreCase(trimmed))
			{
				return tier;
			}
		}
		return null;
	}
}

