 */
public final class CombatAchievement
{
	private final int id;
	private final String name;
	private final AchievementTier tier;
	private final String monster;
	private final TaskType type;
	private final int points;
	private final String description;
	private final String leagueRegion;
	private final String wikiUrl;
	private final String guideSearchUrl;

	public CombatAchievement(int id, String name, AchievementTier tier, String monster, TaskType type,
		int points, String description, String leagueRegion, String wikiUrl)
	{
		this(id, name, tier, monster, type, points, description, leagueRegion, wikiUrl, "");
	}

	public CombatAchievement(int id, String name, AchievementTier tier, String monster, TaskType type,
		int points, String description, String leagueRegion, String wikiUrl, String guideSearchUrl)
	{
		this.id = id;
		this.name = name == null ? "" : name;
		this.tier = tier;
		this.monster = monster == null ? "" : monster;
		this.type = type;
		this.points = points;
		this.description = description == null ? "" : description;
		this.leagueRegion = leagueRegion == null ? "" : leagueRegion;
		this.wikiUrl = wikiUrl == null ? "" : wikiUrl;
		this.guideSearchUrl = guideSearchUrl == null ? "" : guideSearchUrl;
	}

	public int id()
	{
		return id;
	}

	public String name()
	{
		return name;
	}

	public AchievementTier tier()
	{
		return tier;
	}

	public String monster()
	{
		return monster;
	}

	public TaskType type()
	{
		return type;
	}

	public int points()
	{
		return points;
	}

	public String description()
	{
		return description;
	}

	public String leagueRegion()
	{
		return leagueRegion;
	}

	public String wikiUrl()
	{
		return wikiUrl;
	}

	/** The bundled YouTube-search link used when this task has no curated video guide. */
	public String guideSearchUrl()
	{
		return guideSearchUrl;
	}

	/** True when this task is bound to a specific monster (vs a non-boss activity task). */
	public boolean hasMonster()
	{
		return !monster.isEmpty() && !"None".equalsIgnoreCase(monster);
	}

	@Override
	public boolean equals(Object o)
	{
		if (this == o)
		{
			return true;
		}
		if (!(o instanceof CombatAchievement))
		{
			return false;
		}
		return id == ((CombatAchievement) o).id;
	}

	@Override
	public int hashCode()
	{
		return Objects.hash(id);
	}

	@Override
	public String toString()
	{
		return "CombatAchievement{" + id + ", " + name + ", " + tier + '}';
	}
}

package com.pluginideahub.combatachievements.core.achievement;

/**
 * Thrown when the bundled Combat Achievements dataset cannot be loaded or fails its structural
 * invariants (missing resource, parse error, empty task list, unknown tier/type). The plugin catches
 * this in {@code startUp()} and renders a data-error panel state rather than crashing. See
 * docs/DESIGN.md §5.4.
 */
public class CombatAchievementDataException extends RuntimeException
{
	public CombatAchievementDataException(String message)
	{
		super(message);
	}

	public CombatAchievementDataException(String message, Throwable cause)
	{
		super(message, cause);
	}
}

package com.pluginideahub.combatachievements.core.achievement;

import com.google.gson.JsonArray;
import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import com.google.gson.JsonParser;
import com.google.gson.JsonSyntaxException;
import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.io.Reader;
import java.nio.charset.StandardCharsets;
import java.util.ArrayList;
import java.util.Collections;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;

/**
 * Loads the bundled Combat Achievements task dataset and exposes it as immutable
 * {@link CombatAchievement}s. Pure Java: depends only on Gson (a parser, not a RuneLite type), so it
 * is unit-testable with no game client. Mirrors the {@code BossLibrary.all()} access shape; the JSON
 * loading itself is new (roguescape's libraries are hardcoded) — see docs/DESIGN.md §2.1.
 *
 * <p>Points are <em>derived</em> from each task's tier on load, never trusted from the file.</p>
 */
public final class CombatAchievementLibrary
{
	private static final String BUNDLED_RESOURCE =
		"/com/pluginideahub/combatachievements/combat_achievements.json";

	private final String version;
	private final List<CombatAchievement> tasks;
	private final Map<Integer, CombatAchievement> byId;
	private final Map<Integer, Integer> pointsById;

	private CombatAchievementLibrary(String version, List<CombatAchievement> tasks)
	{
		this.version = version;
		this.tasks = Collections.unmodifiableList(tasks);
		Map<Integer, CombatAchievement> idMap = new LinkedHashMap<>();
		Map<Integer, Integer> pts = new LinkedHashMap<>();
		for (CombatAchievement task : tasks)
		{
			idMap.put(task.id(), task);
			pts.put(task.id(), task.points());
		}
		this.byId = Collections.unmodifiableMap(idMap);
		this.pointsById = Collections.unmodifiableMap(pts);
	}

	/** Loads the dataset bundled in the plugin jar. Throws {@link CombatAchievementDataException} on failure. */
	public static CombatAchievementLibrary loadBundled()
	{
		try (InputStream in = CombatAchievementLibrary.class.getResourceAsStream(BUNDLED_RESOURCE))
		{
			if (in == null)
			{
				throw new CombatAchievementDataException("Bundled dataset not found: " + BUNDLED_RESOURCE);
			}
			return load(in);
		}
		catch (IOException ex)
		{
			throw new CombatAchievementDataException("Failed to read bundled dataset", ex);
		}
	}

	/** Loads the dataset from an arbitrary stream (used by tests with fixtures). */
	public static CombatAchievementLibrary load(InputStream in)
	{
		try (Reader reader = new BufferedReader(new InputStreamReader(in, StandardCharsets.UTF_8)))
		{
			// The instance form, not the newer static parseReader: the plugin hub compiles against the
			// gson the client actually ships, which predates it.
			JsonElement parsed = new JsonParser().parse(reader);
			if (parsed == null || !parsed.isJsonObject())
			{
				throw new CombatAchievementDataException("Dataset root is not a JSON object");
			}
			JsonObject root = parsed.getAsJsonObject();
			String version = root.has("version") && !root.get("version").isJsonNull()
				? root.get("version").getAsString() : "unknown";

			JsonElement tasksElement = root.get("tasks");
			if (tasksElement == null || !tasksElement.isJsonArray())
			{
				throw new CombatAchievementDataException("Dataset has no 'tasks' array");
			}
			JsonArray taskArray = tasksElement.getAsJsonArray();
			if (taskArray.size() == 0)
			{
				throw new CombatAchievementDataException("Dataset 'tasks' array is empty");
			}

			List<CombatAchievement> tasks = new ArrayList<>(taskArray.size());
			for (JsonElement element : taskArray)
			{
				tasks.add(parseTask(element));
			}
			return new CombatAchievementLibrary(version, tasks);
		}
		catch (JsonSyntaxException | IllegalStateException ex)
		{
			throw new CombatAchievementDataException("Malformed dataset JSON", ex);
		}
		catch (IOException ex)
		{
			throw new CombatAchievementDataException("Failed to read dataset stream", ex);
		}
	}

	private static CombatAchievement parseTask(JsonElement element)
	{
		if (element == null || !element.isJsonObject())
		{
			throw new CombatAchievementDataException("Task entry is not a JSON object");
		}
		JsonObject obj = element.getAsJsonObject();
		int id = requireInt(obj, "id");
		String name = optString(obj, "name");

		AchievementTier tier = AchievementTier.fromDisplayName(optString(obj, "tier"));
		if (tier == null)
		{
			throw new CombatAchievementDataException(
				"Task " + id + " has unknown tier: " + optString(obj, "tier"));
		}
		TaskType type = TaskType.fromDisplayName(optString(obj, "type"));
		if (type == null)
		{
			throw new CombatAchievementDataException(
				"Task " + id + " has unknown type: " + optString(obj, "type"));
		}

		String monster = optString(obj, "monster");
		String description = optString(obj, "description");
		String leagueRegion = optString(obj, "leagueRegion");
		String wikiUrl = optString(obj, "wikiUrl");
		String guideSearchUrl = optString(obj, "guideSearchUrl");

		// Points are always derived from the tier, never trusted from the file.
		return new CombatAchievement(id, name, tier, monster, type, tier.pointsPerTask(),
			description, leagueRegion, wikiUrl, guideSearchUrl);
	}

	private static int requireInt(JsonObject obj, String key)
	{
		JsonElement el = obj.get(key);
		if (el == null || el.isJsonNull())
		{
			throw new CombatAchievementDataException("Task missing required field: " + key);
		}
		try
		{
			return el.getAsInt();
		}
		catch (NumberFormatException | IllegalStateException ex)
		{
			throw new CombatAchievementDataException("Task field '" + key + "' is not an integer", ex);
		}
	}

	private static String optString(JsonObject obj, String key)
	{
		JsonElement el = obj.get(key);
		if (el == null || el.isJsonNull())
		{
			return "";
		}
		if (el.isJsonArray())
		{
			JsonArray arr = el.getAsJsonArray();
			return arr.size() == 0 ? "" : arr.get(0).getAsString();
		}
		return el.getAsString();
	}

	public String version()
	{
		return version;
	}

	/** All tasks, in dataset order (sorted by id at build time). Unmodifiable. */
	public List<CombatAchievement> all()
	{
		return tasks;
	}

	public int taskCount()
	{
		return tasks.size();
	}

	public CombatAchievement byId(int id)
	{
		return byId.get(id);
	}

	/** Task id -> derived points. Single owner of this map; consumed by the varbit reader. */
	public Map<Integer, Integer> pointsById()
	{
		return pointsById;
	}

	public List<CombatAchievement> byTier(AchievementTier tier)
	{
		List<CombatAchievement> result = new ArrayList<>();
		for (CombatAchievement task : tasks)
		{
			if (task.tier() == tier)
			{
				result.add(task);
			}
		}
		return Collections.unmodifiableList(result);
	}
}

package com.pluginideahub.combatachievements.core.achievement;

import com.google.gson.JsonArray;
import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import com.pluginideahub.combatachievements.core.data.BundledJson;
import java.io.InputStream;
import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;

/**
 * Loads the curated {@code task_effort.json} (see docs/DESIGN.md §4.6). Sparse with a safe default:
 * any task id without an entry resolves to {@link TaskEffortData#NEUTRAL}, so the ranker degrades
 * gracefully and never silently drops a task. Pure Java (Gson only); unit-testable without a client.
 *
 * <p>The dataset is optional — a missing or malformed effort file yields an empty library where
 * every lookup returns {@code NEUTRAL}, never an exception, so effort data problems never break the
 * panel.</p>
 */
public final class EffortDataLibrary
{
	private static final String BUNDLED_RESOURCE =
		"/com/pluginideahub/combatachievements/task_effort.json";

	private final String version;
	private final Map<Integer, TaskEffortData> byId;

	private EffortDataLibrary(String version, Map<Integer, TaskEffortData> byId)
	{
		this.version = version;
		this.byId = byId;
	}

	/** An empty library: every {@link #effortFor(int)} returns {@link TaskEffortData#NEUTRAL}. */
	public static EffortDataLibrary empty()
	{
		return new EffortDataLibrary("none", new LinkedHashMap<>());
	}

	/** Loads the bundled curated effort dataset; returns {@link #empty()} if absent or unreadable. */
	public static EffortDataLibrary loadBundled()
	{
		return fromRoot(BundledJson.readBundled(EffortDataLibrary.class, BUNDLED_RESOURCE));
	}

	/** Loads from an arbitrary stream; returns {@link #empty()} on any malformed input. */
	public static EffortDataLibrary load(InputStream in)
	{
		return fromRoot(BundledJson.read(in));
	}

	private static EffortDataLibrary fromRoot(JsonObject root)
	{
		if (root == null)
		{
			return empty();
		}
		return new EffortDataLibrary(BundledJson.optString(root, "version", "unknown"),
			BundledJson.idMap(root, "tasks", EffortDataLibrary::parseEntry));
	}

	private static TaskEffortData parseEntry(JsonObject obj)
	{
		String access = BundledJson.optString(obj, "access", "none");
		TaskEffortData.GearTier gearTier = TaskEffortData.GearTier.fromString(
			BundledJson.optString(obj, "gearTier", "mid"), TaskEffortData.GearTier.MID);
		TaskEffortData.Intensity rng = TaskEffortData.Intensity.fromString(
			BundledJson.optString(obj, "rng", "low"), TaskEffortData.Intensity.LOW);
		TaskEffortData.Intensity supply = TaskEffortData.Intensity.fromString(
			BundledJson.optString(obj, "supply", "low"), TaskEffortData.Intensity.LOW);
		boolean soloable = BundledJson.optBoolean(obj, "soloable", true);
		String minigame = BundledJson.optString(obj, "minigameOrRaid", "");

		Map<String, Integer> levelReqs = new LinkedHashMap<>();
		JsonElement reqsEl = obj.get("levelReqs");
		if (reqsEl != null && reqsEl.isJsonObject())
		{
			for (Map.Entry<String, JsonElement> e : reqsEl.getAsJsonObject().entrySet())
			{
				try
				{
					levelReqs.put(e.getKey(), e.getValue().getAsInt());
				}
				catch (RuntimeException ignored)
				{
					// skip malformed level requirement
				}
			}
		}

		List<QuestRequirement> questReqs = parseQuestReqs(obj.get("questReqs"));

		// Only flag "curated" when a real effort signal was authored — a levelReqs/questReqs-only entry
		// (the auto-imported reldo/wiki gates) carries neutral placeholder difficulty and must not pose
		// as curated.
		boolean curated = obj.has("gearTier") || obj.has("rng") || obj.has("supply")
			|| obj.has("access") || obj.has("soloable") || obj.has("minigameOrRaid");
		return new TaskEffortData(access, levelReqs, questReqs, gearTier, rng, supply, soloable,
			minigame, curated);
	}

	/**
	 * Parses the {@code questReqs} array. Each element is either a bare quest-name string (must be
	 * completed) or an object {@code {"name": "...", "startedSuffices": true}} for the few gates where
	 * merely starting the quest grants access. Malformed elements are skipped, never thrown.
	 */
	private static List<QuestRequirement> parseQuestReqs(JsonElement el)
	{
		List<QuestRequirement> out = new ArrayList<>();
		if (el == null || !el.isJsonArray())
		{
			return out;
		}
		JsonArray arr = el.getAsJsonArray();
		for (JsonElement item : arr)
		{
			try
			{
				if (item.isJsonPrimitive() && item.getAsJsonPrimitive().isString())
				{
					String name = item.getAsString();
					if (name != null && !name.trim().isEmpty())
					{
						out.add(new QuestRequirement(name, false));
					}
				}
				else if (item.isJsonObject())
				{
					JsonObject q = item.getAsJsonObject();
					String name = BundledJson.optString(q, "name", "");
					if (!name.trim().isEmpty())
					{
						boolean started = q.has("startedSuffices") && !q.get("startedSuffices").isJsonNull()
							&& q.get("startedSuffices").getAsBoolean();
						out.add(new QuestRequirement(name, started));
					}
				}
			}
			catch (RuntimeException ignored)
			{
				// skip malformed quest requirement
			}
		}
		return out;
	}

	public String version()
	{
		return version;
	}

	public int curatedCount()
	{
		return byId.size();
	}

	/** Curated effort for a task id, or {@link TaskEffortData#NEUTRAL} when none is present. */
	public TaskEffortData effortFor(int taskId)
	{
		return byId.getOrDefault(taskId, TaskEffortData.NEUTRAL);
	}
}

package com.pluginideahub.combatachievements.core.achievement;

import java.util.Locale;
import java.util.Objects;

/**
 * A quest a player must have done to access (and therefore attempt) a task's content. Pure value
 * object — the live "is this quest finished?" check is resolved by the bridge against the client's
 * quest state, keyed by {@link #quest()} (matched to {@code net.runelite.api.Quest.getName()}).
 *
 * <p>{@link #startedSuffices()} captures the handful of cases where merely <em>starting</em> the
 * quest grants access (e.g. Regicide for Zulrah's Zul-Andra) rather than completing it — so a player
 * mid-quest is not wrongly told the task is locked.</p>
 */
public final class QuestRequirement
{
	private final String quest;
	private final boolean startedSuffices;

	public QuestRequirement(String quest, boolean startedSuffices)
	{
		this.quest = quest == null ? "" : quest.trim();
		this.startedSuffices = startedSuffices;
	}

	/** The exact in-game quest name (matches {@code Quest.getName()}). */
	public String quest()
	{
		return quest;
	}

	/** True when starting the quest is enough; false when it must be completed. */
	public boolean startedSuffices()
	{
		return startedSuffices;
	}

	@Override
	public boolean equals(Object o)
	{
		if (this == o)
		{
			return true;
		}
		if (!(o instanceof QuestRequirement))
		{
			return false;
		}
		QuestRequirement that = (QuestRequirement) o;
		return startedSuffices == that.startedSuffices && quest.equalsIgnoreCase(that.quest);
	}

	@Override
	public int hashCode()
	{
		return Objects.hash(quest.toLowerCase(Locale.ROOT), startedSuffices);
	}

	@Override
	public String toString()
	{
		return "QuestRequirement{" + quest + (startedSuffices ? " (started)" : "") + '}';
	}
}

package com.pluginideahub.combatachievements.core.achievement;

import com.google.gson.JsonArray;
import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import com.pluginideahub.combatachievements.core.data.BundledJson;
import java.io.InputStream;
import java.util.ArrayList;
import java.util.Collections;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Locale;
import java.util.Map;

/**
 * Loads the bundled {@code rec_stats.json} (task id → recommended-stat requirements), parsed from the
 * curated "Recommended stats" text. Each task has HARD requirements (tagged (required)/(hard req) — real
 * gates) and SOFT requirements (recommendations). Sparse and safe: a missing/malformed file yields empty
 * lists everywhere, so a data problem never gates or sinks a task. Pure Java (Gson only).
 */
public final class RecStatsLibrary
{
	private static final String BUNDLED_RESOURCE =
		"/com/pluginideahub/combatachievements/rec_stats.json";

	private final Map<Integer, List<StatRequirement>> hard;
	private final Map<Integer, List<StatRequirement>> soft;

	private RecStatsLibrary(Map<Integer, List<StatRequirement>> hard, Map<Integer, List<StatRequirement>> soft)
	{
		this.hard = Collections.unmodifiableMap(hard);
		this.soft = Collections.unmodifiableMap(soft);
	}

	public static RecStatsLibrary empty()
	{
		return new RecStatsLibrary(new LinkedHashMap<>(), new LinkedHashMap<>());
	}

	public static RecStatsLibrary loadBundled()
	{
		return fromRoot(BundledJson.readBundled(RecStatsLibrary.class, BUNDLED_RESOURCE));
	}

	public static RecStatsLibrary load(InputStream in)
	{
		return fromRoot(BundledJson.read(in));
	}

	private static RecStatsLibrary fromRoot(JsonObject root)
	{
		JsonObject tasks = BundledJson.objectMember(root, "tasks");
		if (tasks == null)
		{
			return empty();
		}
		// A task lands in the hard/soft map only when it has requirements of that kind — count()
		// reflects tasks with data, not every id in the file.
		Map<Integer, List<StatRequirement>> hard = new LinkedHashMap<>();
		Map<Integer, List<StatRequirement>> soft = new LinkedHashMap<>();
		for (Map.Entry<String, JsonElement> entry : tasks.entrySet())
		{
			if (entry.getValue() == null || !entry.getValue().isJsonObject())
			{
				continue;
			}
			try
			{
				int id = Integer.parseInt(entry.getKey().trim());
				JsonObject o = entry.getValue().getAsJsonObject();
				List<StatRequirement> h = parseReqs(o.get("hard"));
				List<StatRequirement> s = parseReqs(o.get("soft"));
				if (!h.isEmpty())
				{
					hard.put(id, h);
				}
				if (!s.isEmpty())
				{
					soft.put(id, s);
				}
			}
			catch (RuntimeException ignored)
			{
				// skip malformed entry
			}
		}
		return new RecStatsLibrary(hard, soft);
	}

	private static List<StatRequirement> parseReqs(JsonElement el)
	{
		List<StatRequirement> out = new ArrayList<>();
		if (el == null || !el.isJsonArray())
		{
			return out;
		}
		JsonArray arr = el.getAsJsonArray();
		for (JsonElement e : arr)
		{
			if (e == null || !e.isJsonObject())
			{
				continue;
			}
			try
			{
				JsonObject o = e.getAsJsonObject();
				List<String> skills = new ArrayList<>();
				JsonElement sk = o.get("skills");
				if (sk != null && sk.isJsonArray())
				{
					for (JsonElement s : sk.getAsJsonArray())
					{
						skills.add(s.getAsString());
					}
				}
				int level = o.get("level").getAsInt();
				String modeStr = o.has("mode") ? o.get("mode").getAsString() : "all";
				StatRequirement.Mode mode;
				switch (modeStr.trim().toLowerCase(Locale.ROOT))
				{
					case "any":
						mode = StatRequirement.Mode.ANY;
						break;
					case "primary":
						mode = StatRequirement.Mode.PRIMARY;
						break;
					default:
						mode = StatRequirement.Mode.ALL;
						break;
				}
				if (!skills.isEmpty())
				{
					out.add(new StatRequirement(skills, level, mode));
				}
			}
			catch (RuntimeException ignored)
			{
				// skip malformed requirement
			}
		}
		return out;
	}

	/** HARD (required) stat gates for a task — real requirements; empty when none. */
	public List<StatRequirement> hardFor(int taskId)
	{
		return hard.getOrDefault(taskId, Collections.emptyList());
	}

	/** SOFT recommended stats for a task — recommendations; empty when none. */
	public List<StatRequirement> softFor(int taskId)
	{
		return soft.getOrDefault(taskId, Collections.emptyList());
	}

	public int count()
	{
		return Math.max(hard.size(), soft.size());
	}
}

