	}

	public int defCrush()
	{
		return defCrush;
	}

	public int defRange()
	{
		return defRange;
	}

	public int defMagic()
	{
		return defMagic;
	}

	public boolean isKnown()
	{
		return hitpoints > 0;
	}

	/** The defensive bonus a melee attack of the given type rolls against. */
	public int meleeDefenceBonus(MeleeAttackType type)
	{
		switch (type)
