package com.pluginideahub.combatachievements.core.combat;

/**
 * Judges whether a Speed/time-trial CA is achievable: estimated clear time vs the task's time
 * threshold. For single-boss tasks the estimate is {@code hitpoints / bestDps × (1 + downtimeFactor)};
 * for multi-stage encounters (Gauntlet, Inferno, raids, Colosseum) a curated
 * {@code referenceClearSeconds} is supplied instead, since they have no single HP bar. See
 * docs/SYSTEMS-DESIGN.md §5.3.
 */
public final class SpeedFeasibilityModel
{
	/** Margin at/above which a feasible task is considered comfortable rather than tight. */
	private static final double COMFORTABLE_MARGIN = 1.15;

	public enum Verdict
	{
		FEASIBLE, TIGHT, INFEASIBLE, INSUFFICIENT_DATA
	}

	public static final class Result
	{
		private final Verdict verdict;
		private final double estimatedClearSeconds;
		private final double thresholdSeconds;
		private final double marginRatio;

		Result(Verdict verdict, double estimatedClearSeconds, double thresholdSeconds, double marginRatio)
		{
			this.verdict = verdict;
			this.estimatedClearSeconds = estimatedClearSeconds;
			this.thresholdSeconds = thresholdSeconds;
			this.marginRatio = marginRatio;
		}

		public Verdict verdict()
		{
			return verdict;
		}

		public double estimatedClearSeconds()
		{
			return estimatedClearSeconds;
		}

		public double thresholdSeconds()
		{
			return thresholdSeconds;
		}

		/** thresholdSeconds / estimatedClearSeconds — >1 = feasible, the higher the more comfortable. */
		public double marginRatio()
		{
			return marginRatio;
		}
	}

	private SpeedFeasibilityModel()
	{
	}

	public static final Result INSUFFICIENT = new Result(Verdict.INSUFFICIENT_DATA, 0, 0, 0);

	/**
	 * @param hitpoints            boss HP (single-target); ignored when {@code referenceClearSeconds > 0}
	 * @param bestDps              best DPS across styles (single-target path)
	 * @param thresholdSeconds     the CA's time limit
	 * @param downtimeFactor       per-boss mechanics/downtime fudge (e.g. 0.1 tank-and-spank, 0.6 mechanic-heavy)
	 * @param referenceClearSeconds curated clear time for multi-stage encounters; ≤0 = use HP/DPS
	 */
	public static Result evaluate(int hitpoints, double bestDps, double thresholdSeconds,
		double downtimeFactor, double referenceClearSeconds)
	{
		if (thresholdSeconds <= 0)
		{
			return INSUFFICIENT;
		}

		double estimatedClear;
		if (referenceClearSeconds > 0)
		{
			estimatedClear = referenceClearSeconds;
		}
		else if (hitpoints > 0 && bestDps > 0)
		{
			double ttk = hitpoints / bestDps;
			estimatedClear = ttk * (1.0 + Math.max(0.0, downtimeFactor));
		}
		else
		{
			return INSUFFICIENT;
		}

		double margin = thresholdSeconds / estimatedClear;
		Verdict verdict;
		if (margin >= COMFORTABLE_MARGIN)
		{
			verdict = Verdict.FEASIBLE;
		}
		else if (margin >= 1.0)
		{
			verdict = Verdict.TIGHT;
		}
		else
		{
			verdict = Verdict.INFEASIBLE;
		}
		return new Result(verdict, estimatedClear, thresholdSeconds, margin);
	}
}

package com.pluginideahub.combatachievements.core.data;

import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import com.google.gson.JsonParser;
import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.io.Reader;
import java.nio.charset.StandardCharsets;
import java.util.LinkedHashMap;
import java.util.Locale;
import java.util.Map;
import java.util.function.BiFunction;
import java.util.function.Function;

/**
 * Shared loader for the bundled JSON datasets. Every dataset follows the same contract: a missing or
 * unreadable resource, or a root that is not a JSON object, yields null (so callers fall back to
 * their empty library); a malformed individual entry is skipped, never fatal. Entry iteration
 * preserves file order. Pure Java (Gson only).
 */
public final class BundledJson
{
	private BundledJson()
	{
	}

	/** Parses a classpath resource; null when the resource is absent or unreadable. */
	public static JsonObject readBundled(Class<?> anchor, String resource)
	{
		try (InputStream in = anchor.getResourceAsStream(resource))
		{
			return in == null ? null : read(in);
		}
		catch (IOException ex)
		{
			return null;
		}
	}

	/** Parses a UTF-8 stream (closing it); null unless the root is a JSON object. */
	public static JsonObject read(InputStream in)
	{
		try (Reader reader = new BufferedReader(new InputStreamReader(in, StandardCharsets.UTF_8)))
		{
			// The instance form, not the newer static parseReader: the plugin hub compiles against the
			// gson the client actually ships, which predates it.
			JsonElement parsed = new JsonParser().parse(reader);
			return parsed != null && parsed.isJsonObject() ? parsed.getAsJsonObject() : null;
		}
		catch (RuntimeException | IOException ex)
		{
			return null;
		}
	}

	/** The named member as an object; null when the root or the member is absent or not an object. */
	public static JsonObject objectMember(JsonObject root, String memberName)
	{
		if (root == null)
		{
			return null;
		}
		JsonElement el = root.get(memberName);
		return el != null && el.isJsonObject() ? el.getAsJsonObject() : null;
	}

	/**
	 * Builds an id-keyed map from the named object member. Keys are parsed as integers (trimmed).
	 * Entries whose value is not an object, whose parse returns null, or whose key or parse throws a
	 * {@link RuntimeException} are skipped.
	 */
	public static <V> Map<Integer, V> idMap(JsonObject root, String memberName,
		Function<JsonObject, V> parseEntry)
	{
		return idMapValues(root, memberName,
			el -> el.isJsonObject() ? parseEntry.apply(el.getAsJsonObject()) : null);
	}

	/** As {@link #idMap} but hands the raw value element to the parser, for primitive-valued maps. */
	public static <V> Map<Integer, V> idMapValues(JsonObject root, String memberName,
		Function<JsonElement, V> parseValue)
	{
		Map<Integer, V> out = new LinkedHashMap<>();
		JsonObject member = objectMember(root, memberName);
		if (member == null)
		{
			return out;
		}
		for (Map.Entry<String, JsonElement> entry : member.entrySet())
		{
			try
			{
				int id = Integer.parseInt(entry.getKey().trim());
				V value = parseValue.apply(entry.getValue());
				if (value != null)
				{
					out.put(id, value);
				}
			}
			catch (RuntimeException ignored)
			{
				// skip malformed entry
			}
		}
		return out;
	}

	/**
	 * Builds a name-keyed map from the named object member. Map keys are trimmed and lower-cased
	 * (the datasets are looked up case-insensitively); the parser receives the raw key and the entry
	 * object. Entries whose value is not an object, whose parse returns null, or whose parse throws a
	 * {@link RuntimeException} are skipped.
	 */
	public static <V> Map<String, V> nameMap(JsonObject root, String memberName,
		BiFunction<String, JsonObject, V> parseEntry)
	{
		return nameMapCore(root, memberName,
			(key, el) -> el.isJsonObject() ? parseEntry.apply(key, el.getAsJsonObject()) : null);
	}

	/** As {@link #nameMap} but hands the raw value element to the parser, for primitive-valued maps. */
	public static <V> Map<String, V> nameMapValues(JsonObject root, String memberName,
		Function<JsonElement, V> parseValue)
	{
		return nameMapCore(root, memberName, (key, el) -> parseValue.apply(el));
	}

	private static <V> Map<String, V> nameMapCore(JsonObject root, String memberName,
		BiFunction<String, JsonElement, V> parseValue)
	{
		Map<String, V> out = new LinkedHashMap<>();
		JsonObject member = objectMember(root, memberName);
		if (member == null)
		{
			return out;
		}
		for (Map.Entry<String, JsonElement> entry : member.entrySet())
		{
			try
			{
				V value = parseValue.apply(entry.getKey(), entry.getValue());
				if (value != null)
				{
					out.put(entry.getKey().trim().toLowerCase(Locale.ROOT), value);
				}
			}
			catch (RuntimeException ignored)
			{
				// skip malformed entry
			}
		}
		return out;
	}

	/** The member as a string; the fallback when absent, null, or not readable as a string. */
	public static String optString(JsonObject o, String key, String fallback)
	{
		JsonElement el = o.get(key);
		if (el == null || el.isJsonNull())
		{
			return fallback;
		}
		try
		{
			return el.getAsString();
		}
		catch (RuntimeException ex)
		{
			return fallback;
		}
	}

	/** The member as an int; the fallback when absent, null, or not readable as an int. */
	public static int optInt(JsonObject o, String key, int fallback)
	{
		JsonElement el = o.get(key);
		if (el == null || el.isJsonNull())
		{
			return fallback;
		}
		try
		{
			return el.getAsInt();
		}
		catch (RuntimeException ex)
		{
			return fallback;
		}
	}

	/** The member as a double; the fallback when absent, null, or not readable as a double. */
	public static double optDouble(JsonObject o, String key, double fallback)
	{
		JsonElement el = o.get(key);
		if (el == null || el.isJsonNull())
		{
			return fallback;
		}
		try
		{
			return el.getAsDouble();
		}
		catch (RuntimeException ex)
		{
			return fallback;
		}
	}

	/** The member as a boolean; the fallback when absent, null, or not readable as a boolean. */
	public static boolean optBoolean(JsonObject o, String key, boolean fallback)
	{
		JsonElement el = o.get(key);
		if (el == null || el.isJsonNull())
		{
			return fallback;
		}
		try
		{
			return el.getAsBoolean();
		}
		catch (RuntimeException ex)
		{
			return fallback;
		}
	}
}

package com.pluginideahub.combatachievements.core.debug;

import com.pluginideahub.combatachievements.core.progress.ProgressSnapshot;
import com.pluginideahub.combatachievements.core.ranking.PlayerProfile;
import java.util.Arrays;
import java.util.Collections;
import java.util.HashMap;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Locale;
import java.util.Map;

/**
 * A developer-only "what would this account see?" override: pretend the player has different skill
 * levels, and/or has completed no Combat Achievements at all. Pure — it rewrites the
 * {@link PlayerProfile} and {@link ProgressSnapshot} that the rest of the plugin already runs on, so
 * every downstream surface (doable-now, the beginner rule, the Route's readiness stop-short, Train
 * next, session times) reacts exactly as it would for a real account in that state.
 *
 * <p>Both halves are needed to reproduce a beginner: the beginner rule releases on EITHER Easy-tier
 * points OR 70+ combat, so dropping levels alone leaves an established account's CA points holding
 * the gate open.</p>
 *
 * <p>This never writes anywhere. It is applied to the values in flight on each refresh, so nothing
 * simulated can reach the account's persisted data.</p>
 */
public final class DebugSimulation
{
	/**
	 * The OSRS skills, in the client's own display names so they match both the levels read by the
	 * account reader and the keys the requirement data is written against.
	 */
	public static final List<String> SKILLS = Collections.unmodifiableList(Arrays.asList(
		"Attack", "Strength", "Defence", "Ranged", "Magic", "Prayer", "Hitpoints",
		"Slayer", "Agility", "Herblore", "Thieving", "Crafting", "Fletching", "Mining",
		"Smithing", "Fishing", "Cooking", "Firemaking", "Woodcutting", "Runecraft",
		"Construction", "Farming", "Hunter"));

	/** Hitpoints starts at 10 in OSRS, so a "level 1 in everything" account is still 10 HP (combat 3). */
	public static final int MIN_HITPOINTS = 10;

	private static final DebugSimulation NONE =
		new DebugSimulation(Collections.emptyMap(), false, false);

	private final Map<String, Integer> levelOverrides;
	private final boolean zeroCompletion;
	private final boolean zeroQuests;

	private DebugSimulation(Map<String, Integer> levelOverrides, boolean zeroCompletion,
		boolean zeroQuests)
	{
		this.levelOverrides = Collections.unmodifiableMap(new LinkedHashMap<>(levelOverrides));
		this.zeroCompletion = zeroCompletion;
		this.zeroQuests = zeroQuests;
	}

	/** No simulation: every {@code apply} is the identity. */
	public static DebugSimulation none()
	{
		return NONE;
	}

	public static DebugSimulation of(Map<String, Integer> levelOverrides, boolean zeroCompletion)
	{
		return of(levelOverrides, zeroCompletion, false);
	}

	/**
	 * @param levelOverrides skill name → level to pretend; empty leaves the real levels alone
	 * @param zeroCompletion pretend no Combat Achievement has been completed
	 * @param zeroQuests     pretend no quest has been done — without this a simulated beginner keeps the
	 *                       real account's quest log, so quest-gated content stays unlocked and nothing
	 *                       shows under "Unlock next" (a quest already done is not an unlock)
	 */
	public static DebugSimulation of(Map<String, Integer> levelOverrides, boolean zeroCompletion,
		boolean zeroQuests)
	{
		Map<String, Integer> clean = new LinkedHashMap<>();
		if (levelOverrides != null)
		{
			for (Map.Entry<String, Integer> e : levelOverrides.entrySet())
			{
				if (e.getKey() != null && e.getValue() != null && !e.getKey().trim().isEmpty())
				{
					clean.put(e.getKey().trim(), clamp(e.getKey(), e.getValue()));
				}
			}
		}
		if (clean.isEmpty() && !zeroCompletion && !zeroQuests)
		{
			return NONE;
		}
		return new DebugSimulation(clean, zeroCompletion, zeroQuests);
	}

	/** Every skill set to {@code level} — the preset behind the "3 / 40 / 60 / 80 / 99" buttons. */
	public static Map<String, Integer> allSkillsAt(int level)
	{
		Map<String, Integer> levels = new LinkedHashMap<>();
		for (String skill : SKILLS)
		{
			levels.put(skill, clamp(skill, level));
		}
		return levels;
	}

	private static int clamp(String skill, int level)
	{
		int floor = "Hitpoints".equalsIgnoreCase(skill == null ? "" : skill.trim()) ? MIN_HITPOINTS : 1;
		return Math.max(floor, Math.min(99, level));
	}

	/** True when this changes anything; a false value means the panel should show the real account. */
	public boolean isActive()
	{
		return zeroCompletion || zeroQuests || !levelOverrides.isEmpty();
	}

	public boolean zeroCompletion()
	{
		return zeroCompletion;
	}

	public boolean zeroQuests()
	{
		return zeroQuests;
	}

	/** Skill name → simulated level; empty when levels are not being overridden. */
	public Map<String, Integer> levelOverrides()
	{
		return levelOverrides;
	}

	/** The simulated level for one skill, or {@code fallback} when that skill is not overridden. */
	public int levelOf(String skill, int fallback)
	{
		if (skill == null)
		{
			return fallback;
		}
		for (Map.Entry<String, Integer> e : levelOverrides.entrySet())
		{
			if (e.getKey().equalsIgnoreCase(skill.trim()))
			{
				return e.getValue();
			}
		}
		return fallback;
	}

	/** The real profile with the simulated levels swapped in, and the quest log blanked when asked. */
	public PlayerProfile apply(PlayerProfile real)
	{
		PlayerProfile base = real == null ? PlayerProfile.empty() : real;
		if (zeroQuests)
		{
			base = base.withoutQuests();
		}
		if (levelOverrides.isEmpty())
		{
			return base;
		}
		Map<String, Integer> lowered = new HashMap<>();
		for (Map.Entry<String, Integer> e : levelOverrides.entrySet())
		{
			lowered.put(e.getKey().toLowerCase(Locale.ROOT), e.getValue());
		}
		return base.withLevels(lowered);
	}

	/**
	 * The real progress with every completion cleared when simulating a fresh account. The account hash
	 * is preserved so the snapshot still reads as a present, real-account sync rather than the
	 * logged-out state.
	 */
	public ProgressSnapshot apply(ProgressSnapshot real)
	{
		if (!zeroCompletion || real == null || !real.isPresent())
		{
			return real;
		}
		return new ProgressSnapshot(Collections.emptySet(), 0, 0, null, real.accountHash(),
			real.isSample());
	}
}

package com.pluginideahub.combatachievements.core.effort;

import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import com.pluginideahub.combatachievements.core.data.BundledJson;
import java.io.InputStream;
import java.util.LinkedHashMap;
import java.util.Locale;
import java.util.Map;

/**
 * Loads the bundled {@code boss_difficulty.json} (boss/activity name → pure-skill difficulty 1–10),
 * the hand-rated per-boss backbone the per-task {@code TaskDifficulty} is built on. Sparse and safe:
 * a missing/malformed file yields an empty library where every lookup returns 0 (unknown). Case- and
 * whitespace-insensitive keys. Pure Java (Gson only). Mirrors {@link BossTimingLibrary}. Feeds the
 * future Bosses browse mode and the By-boss sort. See CONTEXT.md "Difficulty".
 */
public final class BossDifficultyLibrary
{
	private static final String BUNDLED_RESOURCE =
		"/com/pluginideahub/combatachievements/boss_difficulty.json";

	private final String version;
	private final Map<String, Integer> byBoss;
	private final java.util.Set<String> endgameAccess;

	private BossDifficultyLibrary(String version, Map<String, Integer> byBoss,
		java.util.Set<String> endgameAccess)
	{
		this.version = version;
		this.byBoss = byBoss;
		this.endgameAccess = endgameAccess;
	}

	public static BossDifficultyLibrary empty()
	{
		return new BossDifficultyLibrary("none", new LinkedHashMap<>(), new java.util.HashSet<>());
	}

	public static BossDifficultyLibrary loadBundled()
	{
		return fromRoot(BundledJson.readBundled(BossDifficultyLibrary.class, BUNDLED_RESOURCE));
	}

	public static BossDifficultyLibrary load(InputStream in)
	{
		return fromRoot(BundledJson.read(in));
	}

	private static BossDifficultyLibrary fromRoot(JsonObject root)
	{
		if (root == null)
		{
			return empty();
		}
		Map<String, Integer> map = BundledJson.nameMapValues(root, "bosses",
			el -> Math.max(0, Math.min(10, el.getAsInt())));
		java.util.Set<String> gated = new java.util.HashSet<>();
		JsonElement ga = root.get("endgameAccess");
		if (ga != null && ga.isJsonArray())
		{
			for (JsonElement e : ga.getAsJsonArray())
			{
				try
				{
					gated.add(e.getAsString().trim().toLowerCase(Locale.ROOT));
				}
				catch (RuntimeException ignored)
				{
					// skip malformed entry
				}
			}
		}
		return new BossDifficultyLibrary(BundledJson.optString(root, "version", "unknown"), map, gated);
	}

	/**
	 * True for content you cannot simply walk up to at a low level — raids, instanced gauntlets and the
	 * coordinated group bosses. Deliberately NOT a difficulty claim: some tasks inside these are genuinely
	 * easy (Chambers of Xeric's "Playing with Lasers" is a puzzle room), which is precisely why it is
	 * curated per-activity in boss_difficulty.csv rather than inferred from task stats.
	 */
	public boolean isEndgameAccess(String boss)
	{
		return boss != null && endgameAccess.contains(boss.trim().toLowerCase(Locale.ROOT));
	}

	public String version()
	{
		return version;
	}

	public int count()
	{
		return byBoss.size();
	}

	/** Difficulty (1–10) for a boss/activity (case-insensitive), or 0 when unknown. */
	public int difficultyFor(String boss)
	{
		if (boss == null)
		{
			return 0;
		}
		return byBoss.getOrDefault(boss.trim().toLowerCase(Locale.ROOT), 0);
	}
}

package com.pluginideahub.combatachievements.core.effort;

import com.pluginideahub.combatachievements.core.achievement.CombatAchievement;
import java.util.Collections;
import java.util.List;

/**
 * A recommended one-trip bundle of CAs at a single boss/activity. The whole point of synergy ranking:
 * doing several CAs in one visit amortises the fixed trip overhead, so a boss with many doable CAs is
 * more efficient per point than scattering. Pure value object.
 */
public final class BossSession
{
	/** A task within a session, paired with its time estimate and its real contribution to the trip. */
	public static final class Item
	{
		private final CombatAchievement task;
		private final TaskTimeModel.Estimate estimate;
		private final int sessionMinutes;

		public Item(CombatAchievement task, TaskTimeModel.Estimate estimate, int sessionMinutes)
		{
			this.task = task;
			this.estimate = estimate;
			this.sessionMinutes = sessionMinutes;
		}

		public CombatAchievement task()
		{
			return task;
		}

		public TaskTimeModel.Estimate estimate()
		{
			return estimate;
		}

		/**
		 * Incremental minutes this task adds to the trip. For stacked Kill Count tasks this is only the
		 * kills needed to reach this threshold from the one below it — so a lower rung (e.g. "kill 25")
		 * stays a viable short task on its own, while the rungs still sum to a single grind, not N grinds.
		 */
		public int sessionMinutes()
		{
			return sessionMinutes;
		}
	}

	private final String monster;
	private final List<Item> items;
	private final int totalPoints;
	private final int totalMinutes;
	private final double score;

	public BossSession(String monster, List<Item> items, int totalPoints, int totalMinutes, double score)
	{
		this.monster = monster == null ? "" : monster;
		this.items = Collections.unmodifiableList(items);
		this.totalPoints = totalPoints;
		this.totalMinutes = totalMinutes;
		this.score = score;
	}

	public String monster()
	{
		return monster;
	}

	public List<Item> items()
	{
		return items;
	}

	public int taskCount()
	{
		return items.size();
	}

	public int totalPoints()
	{
		return totalPoints;
	}

	public int totalMinutes()
	{
		return totalMinutes;
	}

	/** Points per amortised minute (incl. trip overhead) — higher is a better next session. */
	public double score()
	{
		return score;
	}

	/**
	 * Points per hour for this session — {@link #score()} expressed per hour rather than per minute,
	 * so it reads as the same headline efficiency number the curation spreadsheet uses.
	 */
	public double pointsPerHour()
	{
		// Computed from totals (not score * 60) so the degenerate zero-minute case yields 0 rather than
		// an inflated points × 60; in every real session (minutes ≥ 1) this equals score × 60 exactly.
		return totalMinutes <= 0 ? 0.0 : totalPoints * 60.0 / totalMinutes;
	}
}

package com.pluginideahub.combatachievements.core.effort;

/**
 * Rough timing for one boss/activity: time-to-kill, between-kill downtime, and effective kills/hour.
 * Estimates (wiki + judgement) for a competently-geared player; for raids/minigames {@code ttkSeconds}
 * is one full run. Pure value object. Used with a task's kill count to estimate real grind time.
 */
public final class BossTiming
{
	/** The neutral fallback when a boss has no timing data. */
	public static final BossTiming UNKNOWN = new BossTiming(0, 0, 0, "");

	private final int ttkSeconds;
	private final int respawnSeconds;
	private final int killsPerHour;
	private final String note;
	private final double attemptsPerKill;

	public BossTiming(int ttkSeconds, int respawnSeconds, int killsPerHour, String note)
	{
		this(ttkSeconds, respawnSeconds, killsPerHour, note, 1.0);
	}

	public BossTiming(int ttkSeconds, int respawnSeconds, int killsPerHour, String note,
		double attemptsPerKill)
	{
		this.ttkSeconds = Math.max(0, ttkSeconds);
		this.respawnSeconds = Math.max(0, respawnSeconds);
		this.killsPerHour = Math.max(0, killsPerHour);
		this.note = note == null ? "" : note;
		this.attemptsPerKill = Math.max(1.0, attemptsPerKill);
	}

	public int ttkSeconds()
	{
		return ttkSeconds;
	}

	public int respawnSeconds()
	{
		return respawnSeconds;
	}

	public int killsPerHour()
	{
		return killsPerHour;
	}

	public String note()
	{
		return note;
	}

	/** Novice attempts (deaths/fails) per successful kill; ≥ 1. Multiplies a task's estimated time. */
	public double attemptsPerKill()
	{
		return attemptsPerKill;
	}

	public boolean isKnown()
	{
		return ttkSeconds > 0;
	}

	/** Seconds for a single completion including the downtime that precedes the next one. */
	public int secondsPerKill()
	{
		return ttkSeconds + respawnSeconds;
	}
}

