package com.pluginideahub.combatachievements.core.effort;

import java.util.Collections;
import java.util.HashMap;
import java.util.Locale;
import java.util.Map;

/**
 * A pure snapshot of the player's kill count per boss/activity. KC is a three-in-one signal: it gives
 * partial progress on Kill Count tasks, a competence proxy for execution-heavy tasks (someone with
 * 1,000 Gauntlet kills will land a no-hit task far more reliably than someone with 5), and an
 * "already engaged here" hint for session synergy. The bridge fills this from the live client; the
 * core just reads it. Keyed case-insensitively by the dataset's monster name.
 */
public final class CombatExperience
{
	/** How well the player knows a boss, derived from kill count. */
	public enum Competence
	{
		NOVICE, EXPERIENCED, VETERAN
	}

	private final Map<String, Integer> kcByMonster;

	private CombatExperience(Map<String, Integer> kcByMonster)
	{
		this.kcByMonster = Collections.unmodifiableMap(kcByMonster);
	}

	public static CombatExperience empty()
	{
		return new CombatExperience(new HashMap<>());
	}

	/** Builds from a {monster name → kill count} map (names normalised to lower-case). */
	public static CombatExperience of(Map<String, Integer> rawKc)
	{
		Map<String, Integer> m = new HashMap<>();
		if (rawKc != null)
		{
			for (Map.Entry<String, Integer> e : rawKc.entrySet())
			{
				if (e.getKey() != null && e.getValue() != null && e.getValue() >= 0)
				{
					m.put(e.getKey().trim().toLowerCase(Locale.ROOT), e.getValue());
				}
			}
		}
		return new CombatExperience(m);
	}

	public int kcFor(String monster)
	{
		if (monster == null)
		{
			return 0;
		}
		return kcByMonster.getOrDefault(monster.trim().toLowerCase(Locale.ROOT), 0);
	}

	/** True once the player has engaged a boss at all (KC &gt; 0). */
	public boolean hasEngaged(String monster)
	{
		return kcFor(monster) > 0;
	}

	public Competence competence(String monster)
	{
		int kc = kcFor(monster);
		if (kc >= 150)
		{
			return Competence.VETERAN;
		}
		if (kc >= 25)
		{
			return Competence.EXPERIENCED;
		}
		return Competence.NOVICE;
	}

	public boolean isEmpty()
	{
		return kcByMonster.isEmpty();
	}
}

package com.pluginideahub.combatachievements.core.effort;

import java.util.HashMap;
import java.util.Locale;
import java.util.Map;

/**
 * Canonicalises an external boss/activity name (from a kill-count chat line or the hiscores) to the
 * key the dataset uses for that monster, lower-cased. This is the one place the two namespaces meet:
 * the in-game / hiscore spelling ("Nightmare", "The Gauntlet", "Barrows Chests", "Chambers of Xeric
 * Challenge Mode") rarely matches the dataset's {@code monster} field ("The Nightmare", "Crystalline
 * Hunllef", "Barrows", "Chambers of Xeric: Challenge Mode"). Apply this at ingestion so kill counts
 * land in the same namespace the effort engine queries with {@code CombatAchievement.monster()}.
 */
public final class MonsterNames
{
	private static final Map<String, String> ALIASES = build();

	private MonsterNames()
	{
	}

	/** The dataset monster key (lower-cased) for an external boss/activity name. */
	public static String toDatasetKey(String externalName)
	{
		if (externalName == null)
		{
			return "";
		}
		String n = externalName.trim().toLowerCase(Locale.ROOT);
		return ALIASES.getOrDefault(n, n);
	}

	private static Map<String, String> build()
	{
		Map<String, String> m = new HashMap<>();
		// Articled / pluralised names.
		m.put("nightmare", "the nightmare");
		m.put("mimic", "the mimic");
		m.put("barrows chests", "barrows");
		m.put("the leviathan", "leviathan");
		m.put("the whisperer", "whisperer");
		m.put("the royal titans", "royal titans");
		// The Gauntlet's boss is the (Corrupted) Hunllef in the dataset; chat + hiscore use the activity.
		m.put("gauntlet", "crystalline hunllef");
		m.put("the gauntlet", "crystalline hunllef");
		m.put("corrupted gauntlet", "corrupted hunllef");
		m.put("the corrupted gauntlet", "corrupted hunllef");
		// Activities the dataset labels by their reward/area.
		m.put("lunar chests", "moons of peril");
		m.put("sol heredit", "fortis colosseum");
		// Raid mode variants: the completion chat line drops the colon the dataset keeps.
		m.put("chambers of xeric challenge mode", "chambers of xeric: challenge mode");
		m.put("theatre of blood hard mode", "theatre of blood: hard mode");
		m.put("theatre of blood entry mode", "theatre of blood: entry mode");
		m.put("theatre of blood: entry mode", "theatre of blood: entry mode");
		m.put("tombs of amascut expert mode", "tombs of amascut: expert mode");
		m.put("tombs of amascut expert", "tombs of amascut: expert mode");
		m.put("tombs of amascut entry mode", "tombs of amascut: entry mode");
		m.put("tombs of amascut: entry mode", "tombs of amascut: entry mode");
		return m;
	}
}

package com.pluginideahub.combatachievements.core.effort;

import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import com.pluginideahub.combatachievements.core.data.BundledJson;
import java.io.InputStream;
import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import java.util.Set;

/**
 * Loads the bundled {@code quests.json} quest-effort graph (quest name → {@link QuestInfo}). Sparse
 * and safe: a missing/malformed file yields an empty library. Beyond per-quest lookup it walks the
 * {@code directPrerequisiteQuests} edges to answer "what is the full chain behind this quest, and how
 * much of it does a player still have to do?". Pure Java (Gson only).
 */
public final class QuestEffortLibrary
{
	private static final String BUNDLED_RESOURCE =
		"/com/pluginideahub/combatachievements/quests.json";

	private final String version;
	private final Map<String, QuestInfo> byName;

	private QuestEffortLibrary(String version, Map<String, QuestInfo> byName)
	{
		this.version = version;
		this.byName = byName;
	}

	public static QuestEffortLibrary empty()
	{
		return new QuestEffortLibrary("none", new LinkedHashMap<>());
	}

	public static QuestEffortLibrary loadBundled()
	{
		return fromRoot(BundledJson.readBundled(QuestEffortLibrary.class, BUNDLED_RESOURCE));
	}

	public static QuestEffortLibrary load(InputStream in)
	{
		return fromRoot(BundledJson.read(in));
	}

	private static QuestEffortLibrary fromRoot(JsonObject root)
	{
		if (root == null)
		{
			return empty();
		}
		return new QuestEffortLibrary(BundledJson.optString(root, "version", "unknown"),
			BundledJson.nameMap(root, "quests", (name, o) -> parse(o)));
	}

	private static QuestInfo parse(JsonObject o)
	{
		Map<String, Integer> skills = new LinkedHashMap<>();
		JsonElement skEl = o.get("skillRequirements");
		if (skEl != null && skEl.isJsonObject())
		{
			for (Map.Entry<String, JsonElement> s : skEl.getAsJsonObject().entrySet())
			{
				try
				{
					skills.put(s.getKey(), s.getValue().getAsInt());
				}
				catch (RuntimeException ignored)
				{
					// skip malformed skill level
				}
			}
		}
		List<String> prereqs = new ArrayList<>();
		JsonElement pq = o.get("directPrerequisiteQuests");
		if (pq != null && pq.isJsonArray())
		{
			for (JsonElement q : pq.getAsJsonArray())
			{
				try
				{
					if (q.isJsonPrimitive() && q.getAsJsonPrimitive().isString())
					{
						prereqs.add(q.getAsString());
					}
				}
				catch (RuntimeException ignored)
				{
					// skip malformed prerequisite
				}
			}
		}
		return new QuestInfo(BundledJson.optString(o, "name", ""),
			BundledJson.optString(o, "difficulty", ""), BundledJson.optString(o, "length", ""),
			BundledJson.optInt(o, "estMinutes", 0), BundledJson.optInt(o, "effortScore", 0),
			BundledJson.optInt(o, "questPoints", 0), BundledJson.optBoolean(o, "members", false),
			skills, prereqs, BundledJson.optString(o, "wikiUrl", ""));
	}

	public String version()
	{
		return version;
	}

	public int count()
	{
		return byName.size();
	}

	/** Quest metadata (case-insensitive), or {@link QuestInfo#UNKNOWN} when absent. */
	public QuestInfo questFor(String name)
	{
		if (name == null)
		{
			return QuestInfo.UNKNOWN;
		}
		return byName.getOrDefault(name.trim().toLowerCase(Locale.ROOT), QuestInfo.UNKNOWN);
	}

	/**
	 * The full recursive set of prerequisite quests behind {@code questName} (not including the quest
	 * itself), resolved by walking the dependency edges. Cycles and unknown quests are handled safely.
	 */
	public Set<String> fullPrerequisites(String questName)
	{
		Set<String> out = new LinkedHashSet<>();
		collectPrereqs(questName, out, new LinkedHashSet<>());
		return out;
	}

	private void collectPrereqs(String questName, Set<String> out, Set<String> visiting)
	{
		String key = questName == null ? "" : questName.trim().toLowerCase(Locale.ROOT);
		if (key.isEmpty() || visiting.contains(key))
		{
			return;
		}
		visiting.add(key);
		for (String pq : questFor(questName).directPrerequisiteQuests())
		{
			out.add(pq);
			collectPrereqs(pq, out, visiting);
		}
	}

	/**
	 * Estimated minutes of questing a player still has to do to complete {@code questName}: the quest
	 * plus every prerequisite they have not yet finished. Skill-training time is handled separately
	 * (see {@code SkillXpLibrary}). Quests with no data contribute 0.
	 */
	public int remainingQuestMinutes(String questName, Set<String> completedQuestsLower)
	{
		Set<String> needed = new LinkedHashSet<>(fullPrerequisites(questName));
		needed.add(questName);
		int total = 0;
		for (String q : needed)
		{
			String key = q.trim().toLowerCase(Locale.ROOT);
			if (completedQuestsLower != null && completedQuestsLower.contains(key))
			{
				continue;
			}
			total += questFor(q).estMinutes();
		}
		return total;
	}
}

package com.pluginideahub.combatachievements.core.effort;

import java.util.Collections;
