/**
 * Effort metadata for one quest in the CA-relevant universe: difficulty, length, an estimated
 * completion time, quest-point reward, skill requirements and the direct prerequisite quests (the
 * dependency edges). Pure value object sourced from the bundled {@code quests.json}.
 */
public final class QuestInfo
{
	public static final QuestInfo UNKNOWN = new QuestInfo(
		"", "", "", 0, 0, 0, false, Collections.emptyMap(), Collections.emptyList(), "");

	private final String name;
	private final String difficulty;
	private final String length;
	private final int estMinutes;
	private final int effortScore;
	private final int questPoints;
	private final boolean members;
	private final Map<String, Integer> skillRequirements;
	private final List<String> directPrerequisiteQuests;
	private final String wikiUrl;

	public QuestInfo(String name, String difficulty, String length, int estMinutes, int effortScore,
		int questPoints, boolean members, Map<String, Integer> skillRequirements,
		List<String> directPrerequisiteQuests, String wikiUrl)
	{
		this.wikiUrl = wikiUrl == null ? "" : wikiUrl;
		this.name = name == null ? "" : name;
		this.difficulty = difficulty == null ? "" : difficulty;
		this.length = length == null ? "" : length;
		this.estMinutes = Math.max(0, estMinutes);
		this.effortScore = Math.max(0, effortScore);
		this.questPoints = Math.max(0, questPoints);
		this.members = members;
		this.skillRequirements = Collections.unmodifiableMap(
			skillRequirements == null ? Collections.emptyMap() : new java.util.LinkedHashMap<>(skillRequirements));
		this.directPrerequisiteQuests = Collections.unmodifiableList(
			directPrerequisiteQuests == null ? Collections.emptyList()
				: new java.util.ArrayList<>(directPrerequisiteQuests));
	}

	/** The quest's wiki page, as bundled with the dataset. */
	public String wikiUrl()
	{
		return wikiUrl;
	}

	public String name()
	{
		return name;
	}

	public String difficulty()
	{
		return difficulty;
	}

	public String length()
	{
		return length;
	}

	public int estMinutes()
	{
		return estMinutes;
	}

	public int effortScore()
	{
		return effortScore;
	}

	public int questPoints()
	{
		return questPoints;
	}

	public boolean members()
	{
		return members;
	}

	public Map<String, Integer> skillRequirements()
	{
		return skillRequirements;
	}

	public List<String> directPrerequisiteQuests()
	{
		return directPrerequisiteQuests;
	}

	public boolean isKnown()
	{
		return !name.isEmpty();
	}
}

package com.pluginideahub.combatachievements.core.effort;

import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import com.pluginideahub.combatachievements.core.achievement.TaskType;
import com.pluginideahub.combatachievements.core.data.BundledJson;
import java.io.InputStream;
import java.util.HashMap;
import java.util.Locale;
import java.util.Map;

/**
 * The runtime half of the curated scaling table (bundled {@code scaling.json}, compiled from
 * {@code data/curation/scaling.csv}) — the single place the {@link TaskTimeModel} gets its attempt
 * multipliers: per-type base attempts, the difficulty→ability-factor curve, competence discounts and KC
 * thresholds. Sparse and safe: a missing/malformed file falls back to the built-in defaults (which match
 * the old hardcoded constants), so a data problem never breaks the time model. The keyword-offset and cap
 * sections of the file are build-time only and ignored here.
 */
public final class ScalingLibrary
{
	private static final String BUNDLED_RESOURCE =
		"/com/pluginideahub/combatachievements/scaling.json";

	private static final Map<String, Double> DEFAULT_BASE_ATTEMPTS = new HashMap<>();
	private static final Map<Integer, Double> DEFAULT_ABILITY = new HashMap<>();
	private static final Map<String, Double> DEFAULT_COMPETENCE = new HashMap<>();

	static
	{
		DEFAULT_BASE_ATTEMPTS.put("PERFECTION", 5.0);
		DEFAULT_BASE_ATTEMPTS.put("SPEED", 4.0);
		DEFAULT_BASE_ATTEMPTS.put("RESTRICTION", 2.0);
		DEFAULT_BASE_ATTEMPTS.put("MECHANICAL", 2.0);
		DEFAULT_BASE_ATTEMPTS.put("STAMINA", 2.0);
		DEFAULT_BASE_ATTEMPTS.put("KILL_COUNT", 1.0);
		DEFAULT_ABILITY.put(1, 0.5);
		DEFAULT_ABILITY.put(2, 0.7);
		DEFAULT_ABILITY.put(3, 1.0);
		DEFAULT_ABILITY.put(4, 1.8);
		DEFAULT_ABILITY.put(5, 3.0);
		DEFAULT_COMPETENCE.put("NOVICE", 1.0);
		DEFAULT_COMPETENCE.put("EXPERIENCED", 0.6);
		DEFAULT_COMPETENCE.put("VETERAN", 0.35);
	}

	private final Map<String, Double> baseAttempts;
	private final Map<Integer, Double> abilityFactor;
	private final Map<String, Double> competenceFactor;
	private final int experiencedThreshold;
	private final int veteranThreshold;

	private ScalingLibrary(Map<String, Double> baseAttempts, Map<Integer, Double> abilityFactor,
		Map<String, Double> competenceFactor, int experiencedThreshold, int veteranThreshold)
	{
		this.baseAttempts = baseAttempts;
		this.abilityFactor = abilityFactor;
		this.competenceFactor = competenceFactor;
		this.experiencedThreshold = experiencedThreshold;
		this.veteranThreshold = veteranThreshold;
	}

	/** The built-in defaults (matching the old hardcoded constants). */
	public static ScalingLibrary defaults()
	{
		return new ScalingLibrary(new HashMap<>(), new HashMap<>(), new HashMap<>(), 25, 150);
	}

	public static ScalingLibrary loadBundled()
	{
		return fromRoot(BundledJson.readBundled(ScalingLibrary.class, BUNDLED_RESOURCE));
	}

	public static ScalingLibrary load(InputStream in)
	{
		return fromRoot(BundledJson.read(in));
	}

	private static ScalingLibrary fromRoot(JsonObject root)
	{
		if (root == null)
		{
			return defaults();
		}
		Map<String, Double> base = readStringDoubles(root, "type_base_attempts");
		Map<Integer, Double> ability = new HashMap<>();
		for (Map.Entry<String, Double> e : readStringDoubles(root, "ability_factor").entrySet())
		{
			try
			{
				ability.put(Integer.parseInt(e.getKey().trim()), e.getValue());
			}
			catch (NumberFormatException ignored)
			{
				// skip non-integer ability rating key
			}
		}
		Map<String, Double> comp = readStringDoubles(root, "competence_factor");
		Map<String, Double> thresholds = readStringDoubles(root, "competence_threshold");
		int experienced = thresholds.containsKey("EXPERIENCED")
			? (int) Math.round(thresholds.get("EXPERIENCED")) : 25;
		int veteran = thresholds.containsKey("VETERAN")
			? (int) Math.round(thresholds.get("VETERAN")) : 150;
		return new ScalingLibrary(base, ability, comp, experienced, veteran);
	}

	private static Map<String, Double> readStringDoubles(JsonObject root, String section)
	{
		Map<String, Double> out = new HashMap<>();
		JsonElement el = root.get(section);
		if (el != null && el.isJsonObject())
		{
			for (Map.Entry<String, JsonElement> e : el.getAsJsonObject().entrySet())
			{
				try
				{
					out.put(e.getKey().trim().toUpperCase(Locale.ROOT), e.getValue().getAsDouble());
				}
				catch (RuntimeException ignored)
				{
					// skip malformed value
				}
			}
		}
		return out;
	}

	/** Base attempts a novice needs per success for this task type (Kill Count = 1). */
	public double baseAttempts(TaskType type)
	{
		String key = type == null ? "KILL_COUNT" : type.name();
		Double v = baseAttempts.get(key);
		return v != null ? v : DEFAULT_BASE_ATTEMPTS.getOrDefault(key, 1.0);
	}

	/** Attempt multiplier for an execution ability rating 1..5 (3 = neutral). */
	public double abilityFactor(int rating)
	{
		int r = Math.max(1, Math.min(5, rating));
		Double v = abilityFactor.get(r);
		return v != null ? v : DEFAULT_ABILITY.getOrDefault(r, 1.0);
	}

	/** Attempt multiplier for a competence tier (veterans retry far less). */
	public double competenceFactor(CombatExperience.Competence competence)
	{
		String key = competence == null ? "NOVICE" : competence.name();
		Double v = competenceFactor.get(key);
		return v != null ? v : DEFAULT_COMPETENCE.getOrDefault(key, 1.0);
	}

	/** Classifies a kill count into a competence tier using the curated thresholds. */
	public CombatExperience.Competence competenceForKc(int kc)
	{
		if (kc >= veteranThreshold)
		{
			return CombatExperience.Competence.VETERAN;
		}
		if (kc >= experiencedThreshold)
		{
			return CombatExperience.Competence.EXPERIENCED;
		}
		return CombatExperience.Competence.NOVICE;
	}
}

package com.pluginideahub.combatachievements.core.effort;

import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import com.pluginideahub.combatachievements.core.data.BundledJson;
import com.pluginideahub.combatachievements.core.ranking.Tuning;
import java.io.InputStream;
import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Locale;
import java.util.Map;

/**
 * Loads the bundled {@code skills_xp.json} (skill → normal-method XP/hour by level bracket) and turns
 * it into "hours to train skill X→Y", so the cost of meeting a quest's skill requirement can be folded
 * into a CA's unlock effort. Pure Java (Gson only); sparse and safe (missing data → 0 hours).
 */
public final class SkillXpLibrary
{
	private static final String BUNDLED_RESOURCE =
		"/com/pluginideahub/combatachievements/skills_xp.json";

	/** Total experience required to reach each level (index = level, 1..99). OSRS standard table. */
	private static final int[] XP_AT_LEVEL = buildXpTable();

	private static final int FALLBACK_XP_PER_HOUR = Tuning.FALLBACK_XP_PER_HOUR;
	private static final double HOURS_PER_DAY = 24.0;

	/** One rate over a level range for a skill: either per hour played, or per calendar day. */
	public static final class Bracket
	{
		final int fromLevel;
		final int toLevel;
		final int xpPerHour;
		/**
		 * Set instead of {@link #xpPerHour} for a DAILY-GATED bracket — Farming, whose patches grow on
		 * multi-hour timers, so what you get is bounded by the calendar rather than by time at the keyboard.
		 */
		final int xpPerDay;

		Bracket(int fromLevel, int toLevel, int xpPerHour, int xpPerDay)
		{
			this.fromLevel = fromLevel;
			this.toLevel = toLevel;
			this.xpPerDay = Math.max(0, xpPerDay);
			this.xpPerHour = Math.max(1, xpPerHour);
		}

		/**
		 * XP per hour of ELAPSED time. For an ordinary skill that is just the hourly rate; for a daily-gated
		 * one it is the daily allowance spread over the day, so "hours to train" comes out in real time and a
		 * skill you cannot rush stops looking like an afternoon's work.
		 */
		double xpPerElapsedHour()
		{
			return xpPerDay > 0 ? xpPerDay / HOURS_PER_DAY : xpPerHour;
		}
	}

	private final String version;
	private final Map<String, List<Bracket>> bySkill;

	private SkillXpLibrary(String version, Map<String, List<Bracket>> bySkill)
	{
		this.version = version;
		this.bySkill = bySkill;
	}

	public static SkillXpLibrary empty()
	{
		return new SkillXpLibrary("none", new LinkedHashMap<>());
	}

	public static SkillXpLibrary loadBundled()
	{
		return fromRoot(BundledJson.readBundled(SkillXpLibrary.class, BUNDLED_RESOURCE));
	}

	public static SkillXpLibrary load(InputStream in)
	{
		return fromRoot(BundledJson.read(in));
	}

	private static SkillXpLibrary fromRoot(JsonObject root)
	{
		if (root == null)
		{
			return empty();
		}
		return new SkillXpLibrary(BundledJson.optString(root, "version", "unknown"),
			BundledJson.nameMap(root, "skills", (name, o) -> parseBrackets(o)));
	}

	/** Null when the skill has no usable bracket, so it never enters the map. */
	private static List<Bracket> parseBrackets(JsonObject skill)
	{
		List<Bracket> brackets = new ArrayList<>();
		JsonElement bEl = skill.get("brackets");
		if (bEl != null && bEl.isJsonArray())
		{
			for (JsonElement b : bEl.getAsJsonArray())
			{
				if (!b.isJsonObject())
				{
					continue;
				}
				JsonObject bo = b.getAsJsonObject();
				try
				{
					int perHour = optInt(bo, "xpPerHour");
					int perDay = optInt(bo, "xpPerDay");
					if (perHour > 0 || perDay > 0)
					{
						brackets.add(new Bracket(bo.get("fromLevel").getAsInt(),
							bo.get("toLevel").getAsInt(), perHour, perDay));
					}
				}
				catch (RuntimeException ignored)
				{
					// skip malformed bracket
				}
			}
		}
		return brackets.isEmpty() ? null : brackets;
	}

	public String version()
	{
		return version;
	}

	public int count()
	{
		return bySkill.size();
	}

	/** Total experience to reach {@code level} (clamped to 1..99). */
	public static int xpAtLevel(int level)
	{
		int l = Math.max(1, Math.min(99, level));
		return XP_AT_LEVEL[l];
	}

	/** Strict on wrong-typed rates: a non-numeric value invalidates the bracket, not just the field. */
	private static int optInt(JsonObject o, String key)
	{
		JsonElement el = o.get(key);
		return el == null || el.isJsonNull() ? 0 : el.getAsInt();
	}

	/**
	 * Estimated hours to train {@code skill} from {@code fromLevel} to {@code toLevel} using the bundled
	 * normal-method rates. Returns 0 when already at/above the target or when no rate data exists.
	 *
	 * <p>For a daily-gated skill these are hours of ELAPSED time, not hours of play — training Farming is a
	 * calendar commitment however long you sit there, and the estimate says so.</p>
	 */
	public double hoursToTrain(String skill, int fromLevel, int toLevel)
	{
		if (skill == null || toLevel <= fromLevel)
		{
			return 0.0;
		}
		List<Bracket> brackets = bySkill.get(skill.trim().toLowerCase(Locale.ROOT));
		if (brackets == null || brackets.isEmpty())
		{
			return 0.0;
		}
		int from = Math.max(1, Math.min(99, fromLevel));
		int to = Math.max(1, Math.min(99, toLevel));
		double hours = 0.0;
		for (int level = from; level < to; level++)
		{
			int xpThisLevel = XP_AT_LEVEL[level + 1] - XP_AT_LEVEL[level];
			hours += xpThisLevel / rateAt(brackets, level);
		}
		return hours;
	}

	/**
	 * Whether training {@code skill} across this range is bounded by the calendar rather than by time at
	 * the keyboard — true when any bracket involved is daily-gated (Farming's patch timers). Lets the panel
	 * read such an estimate in days, while a skill you simply have to sit and play stays in hours however
	 * long it takes.
	 */
	public boolean isDailyGated(String skill, int fromLevel, int toLevel)
	{
		if (skill == null)
		{
			return false;
		}
		List<Bracket> brackets = bySkill.get(skill.trim().toLowerCase(Locale.ROOT));
		if (brackets == null || brackets.isEmpty())
		{
			return false;
		}
		int from = Math.max(1, Math.min(99, fromLevel));
		int to = Math.max(1, Math.min(99, toLevel));
		for (int level = from; level < Math.max(from + 1, to); level++)
		{
			for (Bracket b : brackets)
			{
				if (level >= b.fromLevel && level < b.toLevel && b.xpPerDay > 0)
				{
					return true;
				}
			}
		}
		return false;
	}

	/** XP per elapsed hour for one level, from the covering bracket (or the nearest one). */
	private static double rateAt(List<Bracket> brackets, int level)
	{
		Bracket best = null;
		for (Bracket b : brackets)
		{
			if (level >= b.fromLevel && level < b.toLevel)
			{
				return b.xpPerElapsedHour();
			}
			// Remember the nearest bracket as a fallback for levels outside all ranges.
			if (best == null || Math.abs(b.fromLevel - level) < Math.abs(best.fromLevel - level))
			{
				best = b;
			}
		}
		return best == null ? FALLBACK_XP_PER_HOUR : best.xpPerElapsedHour();
	}

	private static int[] buildXpTable()
	{
		int[] xp = new int[100];
		double points = 0;
		xp[1] = 0;
		for (int level = 1; level < 99; level++)
		{
			points += Math.floor(level + 300 * Math.pow(2, level / 7.0));
			xp[level + 1] = (int) Math.floor(points / 4);
		}
		return xp;
	}
}

package com.pluginideahub.combatachievements.core.effort;

import com.pluginideahub.combatachievements.core.achievement.CombatAchievement;
import com.pluginideahub.combatachievements.core.achievement.TaskDifficultyLibrary;
import com.pluginideahub.combatachievements.core.achievement.TaskType;
import java.util.ArrayList;
import java.util.Comparator;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;

/**
 * Ranks "next best boss session". Groups the player's doable, incomplete CAs by boss/activity and
 * scores each bundle as {@code totalPoints ÷ (tripOverhead + Σ taskMinutes)}. Because the fixed trip
 * overhead is paid once per bundle, a boss with several doable CAs out-scores scattering across many
 * single-CA trips — synergy falls straight out of the amortisation. The {@code tripOverheadMinutes}
 * dial is the single "clustering strength" knob (bigger ⇒ stronger preference for dense bosses).
 * Pure and deterministic.
 */
public final class SynergyRanker
{
	private final TaskTimeModel timeModel;
	private final int tripOverheadMinutes;

	public SynergyRanker(TaskTimeModel timeModel, int tripOverheadMinutes)
	{
		this.timeModel = timeModel == null ? TaskTimeModel.standard() : timeModel;
		this.tripOverheadMinutes = Math.max(0, tripOverheadMinutes);
	}

	public static SynergyRanker standard()
	{
		return new SynergyRanker(TaskTimeModel.standard(), 6);
	}

	/**
	 * @param doableIncomplete the tasks the player can do now and has not completed
	 * @param timing           per-boss timing data
	 * @param experience       live kill counts (partial progress + competence)
	 * @param difficultyLib    per-task pure-skill Difficulty (drives execution-attempt estimates)
	 * @return boss sessions, best first (by points per amortised minute)
	 */
	public List<BossSession> rank(List<CombatAchievement> doableIncomplete, BossTimingLibrary timing,
		CombatExperience experience, TaskDifficultyLibrary difficultyLib)
	{
		if (doableIncomplete == null || doableIncomplete.isEmpty())
		{
			return new ArrayList<>();
		}
		BossTimingLibrary t = timing == null ? BossTimingLibrary.empty() : timing;
		CombatExperience exp = experience == null ? CombatExperience.empty() : experience;
		TaskDifficultyLibrary diffs = difficultyLib == null ? TaskDifficultyLibrary.empty() : difficultyLib;

		// Group by boss; non-boss activity tasks ("None"/blank) each form a singleton session.
		Map<String, List<CombatAchievement>> byBoss = new LinkedHashMap<>();
		int soloKey = 0;
		for (CombatAchievement task : doableIncomplete)
		{
			String key = task.hasMonster() ? task.monster() : ("�solo" + (soloKey++));
			byBoss.computeIfAbsent(key, k -> new ArrayList<>()).add(task);
		}

		List<BossSession> sessions = new ArrayList<>();
		for (Map.Entry<String, List<CombatAchievement>> e : byBoss.entrySet())
		{
			List<CombatAchievement> tasks = e.getValue();
			String monster = tasks.get(0).hasMonster() ? tasks.get(0).monster() : tasks.get(0).name();
			BossTiming bt = t.timingFor(tasks.get(0).monster());

			// Estimate every task. Nested Kill Count CAs at one boss (25 / 75 / 150) share a single grind:
			// reaching 150 also clears 25 and 75. So each KC rung is charged only the INCREMENTAL kills to
			// reach its threshold from the rung below — the rungs sum to one grind (not N), yet a lower
			// rung keeps a real, shorter time so "just do the 25" stays a viable standalone task.
			List<TaskTimeModel.Estimate> estimates = new ArrayList<>();
			List<Integer> kcRungs = new ArrayList<>();
			for (int i = 0; i < tasks.size(); i++)
			{
				CombatAchievement task = tasks.get(i);
				com.pluginideahub.combatachievements.core.achievement.TaskDifficulty td =
					diffs.difficultyFor(task.id());
				TaskTimeModel.Estimate est =
					timeModel.estimate(task, bt, exp, td.difficulty(), td.attemptsOverride());
				estimates.add(est);
				if (task.type() == TaskType.KILL_COUNT && est.remainingKills() > 0)
				{
					kcRungs.add(i);
				}
			}
			// Ascending by threshold; each rung's incremental minutes = (its threshold − the previous).
			kcRungs.sort(Comparator.comparingInt(i -> estimates.get(i).requiredKills()));
			int[] contribution = new int[tasks.size()];
			int prev = kcRungs.isEmpty() ? 0 : estimates.get(kcRungs.get(0)).currentKc();
			for (int idx : kcRungs)
			{
				int threshold = estimates.get(idx).requiredKills();
				// Scale the incremental grind by this rung's death rate too, so a deadly boss's KC
				// milestones (or an Awakened-boss override) aren't charged as plain kills.
				contribution[idx] = timeModel.minutesForKills(
					threshold - prev, bt, estimates.get(idx).killAttemptFactor());
				prev = threshold;
			}

			List<BossSession.Item> items = new ArrayList<>();
			int totalPoints = 0;
			int taskMinutes = 0;
			for (int i = 0; i < tasks.size(); i++)
			{
				CombatAchievement task = tasks.get(i);
				TaskTimeModel.Estimate est = estimates.get(i);
				// Incomplete KC tasks already have their incremental contribution; others use their own
				// estimate (execution attempts add up; an already-done KC task contributes 0).
				int contrib = task.type() == TaskType.KILL_COUNT ? contribution[i] : est.minutes();
				items.add(new BossSession.Item(task, est, contrib));
				totalPoints += task.points();
				taskMinutes += contrib;
			}
			// Cheapest, highest-value tasks first within the session (by real session contribution,
			// so KC tasks cleared en route float to the top as effectively free).
			items.sort(Comparator
				.comparingDouble((BossSession.Item it) ->
					it.sessionMinutes() == 0 ? Double.MAX_VALUE
						: it.task().points() / (double) it.sessionMinutes())
				.reversed()
				.thenComparingInt(it -> it.task().id()));

			int totalMinutes = tripOverheadMinutes + taskMinutes;
			double score = totalMinutes <= 0 ? totalPoints : totalPoints / (double) totalMinutes;
			sessions.add(new BossSession(monster, items, totalPoints, totalMinutes, score));
		}

		sessions.sort(Comparator
			.comparingDouble(BossSession::score).reversed()
			.thenComparing(BossSession::monster));
		return sessions;
	}
}

package com.pluginideahub.combatachievements.core.effort;

import com.pluginideahub.combatachievements.core.achievement.CombatAchievement;
import com.pluginideahub.combatachievements.core.achievement.TaskType;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

/**
 * Estimates the real time to finish a single CA, in minutes. The core is
 * {@code requiredKills × attemptsPerCompletion × (TTK + respawn)}, where:
 * <ul>
 *   <li><b>requiredKills</b> subtracts live KC for Kill Count tasks (partial progress);</li>
 *   <li><b>attemptsPerCompletion</b> folds in the boss's <em>deadliness</em> — a curated per-CA attempts
 *       override, else the boss's attempts-per-kill (so a single kill of a brutal boss like an Awakened
 *       DT2 boss is no longer treated as "one quick kill") — and, for execution tasks, the type's base
 *       attempts × the difficulty-derived ability factor, all discounted by the player's competence.</li>
 * </ul>
 * Deadliness of 1 (every non-deadly boss) reproduces the previous behaviour exactly. All attempt
 * multipliers come from the curated {@link ScalingLibrary} (bundled {@code scaling.json}) — the single
 * place to tune them. Pure and deterministic.
 */
public final class TaskTimeModel
{
	private static final Pattern COUNT_TIMES =
		Pattern.compile("(\\d+)\\s*(?:times|kills?)", Pattern.CASE_INSENSITIVE);
	private static final Pattern KILL_N =
		Pattern.compile("kill\\s+(\\d+)\\b", Pattern.CASE_INSENSITIVE);

	/** Fallback seconds-per-kill when a boss has no timing data. */
	private final int fallbackSecondsPerKill;
	private final ScalingLibrary scaling;

	public TaskTimeModel(int fallbackSecondsPerKill)
	{
		this(fallbackSecondsPerKill, ScalingLibrary.defaults());
	}

	public TaskTimeModel(int fallbackSecondsPerKill, ScalingLibrary scaling)
	{
		this.fallbackSecondsPerKill = Math.max(1, fallbackSecondsPerKill);
		this.scaling = scaling == null ? ScalingLibrary.defaults() : scaling;
	}

	/** Uses the built-in default scaling constants (for tests / when the bundled table is unavailable). */
	public static TaskTimeModel standard()
	{
		return new TaskTimeModel(120);
	}

	/** Uses the curated {@link ScalingLibrary} so sheet edits to the attempt multipliers take effect. */
	public static TaskTimeModel standard(ScalingLibrary scaling)
	{
		return new TaskTimeModel(120, scaling);
	}

	/** Minutes to do {@code kills} kills at a boss (used for incremental Kill Count milestones). */
	public int minutesForKills(int kills, BossTiming timing)
	{
		return minutesForKills(kills, timing, 1.0);
	}

	/**
	 * Minutes for {@code kills} kills, scaled by an attempt factor (the boss's competence-discounted
	 * deadliness) so incremental Kill Count milestones at a deadly boss also reflect its death rate.
	 */
	public int minutesForKills(int kills, BossTiming timing, double attemptFactor)
	{
		int spk = timing != null && timing.isKnown() ? timing.secondsPerKill() : fallbackSecondsPerKill;
		double factor = Math.max(1.0, attemptFactor);
		return (int) Math.ceil(Math.max(0, kills) * factor * spk / 60.0);
	}

	/** The competence-discount multiplier for a given kill count, via the curated thresholds/factors. */
	public double competenceFactorForKc(int kc)
	{
		return scaling.competenceFactor(scaling.competenceForKc(kc));
	}

	/** The completion/kill count stated in a task's wording (the grind-length signal); 1 if none. */
	public static int requiredKills(String description)
	{
		if (description == null)
		{
			return 1;
		}
		Matcher m = COUNT_TIMES.matcher(description);
		if (m.find())
		{
			return parseOr1(m.group(1));
		}
		m = KILL_N.matcher(description);
		if (m.find())
		{
			return parseOr1(m.group(1));
		}
		return 1;
	}

	private static int parseOr1(String s)
	{
		try
		{
			return Math.max(1, Integer.parseInt(s));
		}
		catch (RuntimeException ex)
		{
			return 1; // overflow / malformed → treat as a single completion
		}
	}

	/** The result of estimating one task's effort. */
	public static final class Estimate
	{
		private final int minutes;
		private final int requiredKills;
		private final int currentKc;
		private final int remainingKills;
		private final CombatExperience.Competence competence;
		private final int abilityRating;
		private final double killAttemptFactor;

		Estimate(int minutes, int requiredKills, int currentKc, int remainingKills,
			CombatExperience.Competence competence, int abilityRating, double killAttemptFactor)
		{
			this.minutes = minutes;
			this.requiredKills = requiredKills;
			this.currentKc = currentKc;
			this.remainingKills = remainingKills;
			this.competence = competence;
			this.abilityRating = abilityRating;
			this.killAttemptFactor = killAttemptFactor;
		}

		/** Mechanical execution difficulty 1 (trivial) .. 5 (very fiddly); 1 for pure Kill Count grinds. */
		public int abilityRating()
		{
			return abilityRating;
		}

		/** Attempts per kill applied (competence-discounted deadliness); ≥ 1. Used for incremental KC time. */
		public double killAttemptFactor()
		{
			return killAttemptFactor;
		}

		public int minutes()
		{
			return minutes;
		}

		public int requiredKills()
		{
			return requiredKills;
		}

		public int currentKc()
		{
			return currentKc;
		}

		public int remainingKills()
		{
			return remainingKills;
		}

		public CombatExperience.Competence competence()
		{
			return competence;
		}

		/** True when this is a multi-kill task the player has already made progress on. */
		public boolean hasPartialProgress()
		{
			return requiredKills > 1 && currentKc > 0 && remainingKills < requiredKills;
		}
	}

	/**
	 * Mechanical execution difficulty 1..5 for an execution task, derived from the curated pure-skill
	 * Difficulty (1..10) — which already folds in the task's keyword bumps. Two difficulty points per
	 * rung: mid difficulty (5–6) maps to the neutral rating 3.
	 */
	static int abilityRating(int difficulty)
	{
		int d = Math.max(1, Math.min(10, difficulty));
		return Math.max(1, Math.min(5, (int) Math.round(d / 2.0)));
	}

	public Estimate estimate(CombatAchievement task, BossTiming timing, CombatExperience experience)
	{
		return estimate(task, timing, experience, 3, 0.0);
	}

	public Estimate estimate(CombatAchievement task, BossTiming timing, CombatExperience experience,
		int difficulty)
	{
		return estimate(task, timing, experience, difficulty, 0.0);
	}

	/**
	 * @param difficulty       the task's curated pure-skill Difficulty (1..10); the execution-attempt seed
	 * @param attemptsOverride curated attempts-to-complete for this CA (0 ⇒ use the boss's attempts/kill)
	 */
	public Estimate estimate(CombatAchievement task, BossTiming timing, CombatExperience experience,
		int difficulty, double attemptsOverride)
	{
		CombatExperience exp = experience == null ? CombatExperience.empty() : experience;
		BossTiming t = timing == null ? BossTiming.UNKNOWN : timing;
		int spk = t.isKnown() ? t.secondsPerKill() : fallbackSecondsPerKill;

		int required = requiredKills(task.description());
		int kc = task.hasMonster() ? exp.kcFor(task.monster()) : 0;
		CombatExperience.Competence comp = scaling.competenceForKc(kc);
		double cf = scaling.competenceFactor(comp);

		// Deaths/fails per successful kill: a curated per-CA override wins, else the boss's deadliness.
		// Only the attempts BEYOND the guaranteed first are discounted by competence, so deadliness 1
		// leaves the estimate exactly as it was before this signal existed.
		double deadliness = attemptsOverride > 0 ? attemptsOverride : t.attemptsPerKill();
		double deadlinessFactor = 1.0 + Math.max(0.0, deadliness - 1.0) * cf;

		double effectiveKills;
		int remaining;
		int rating;
		if (task.type() == TaskType.KILL_COUNT)
		{
			// Pure grind: live KC is genuine progress and is subtracted; then scaled by the death rate.
			remaining = Math.max(0, required - kc);
			rating = 1;
			effectiveKills = remaining * deadlinessFactor;
		}
		else
		{
			remaining = required;
			rating = abilityRating(difficulty);
			if (attemptsOverride > 0)
			{
				// A curated/research per-CA override is the TOTAL attempts-to-complete (survival + skill
				// already folded in), so it is authoritative — use it directly rather than multiplying it
				// by the type × ability estimate (which would double-count the skill component).
				effectiveKills = required * deadlinessFactor;
			}
			else
			{
				// No override: each success may take several attempts (type × ability × competence), all
				// further scaled by the boss's deadliness (you must survive to even attempt the constraint).
				double execution = Math.max(1.0,
					scaling.baseAttempts(task.type()) * scaling.abilityFactor(rating) * cf);
				effectiveKills = required * execution * deadlinessFactor;
			}
		}

		int minutes = (int) Math.ceil(effectiveKills * spk / 60.0);
		return new Estimate(minutes, required, kc, remaining, comp, rating, deadlinessFactor);
	}
}

package com.pluginideahub.combatachievements.core.effort;

import com.pluginideahub.combatachievements.core.achievement.CombatAchievement;
import com.pluginideahub.combatachievements.core.achievement.EffortDataLibrary;
import com.pluginideahub.combatachievements.core.achievement.RecStatsLibrary;
import com.pluginideahub.combatachievements.core.achievement.StatRequirement;
import com.pluginideahub.combatachievements.core.ranking.PlayerProfile;
import com.pluginideahub.combatachievements.core.ranking.ProfileSignalsProvider;
import com.pluginideahub.combatachievements.core.ranking.TaskLiveSignals;
import com.pluginideahub.combatachievements.core.ranking.Tuning;
import java.util.ArrayList;
import java.util.Comparator;
import java.util.HashMap;
import java.util.HashSet;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.Set;
import java.util.TreeSet;

/**
 * Answers "what should I train to open up Combat Achievements?" — the counterpart to {@link UnlockPlanner},
 * which answers the same question for quests.
 *
 * <p>A task counts as VIABLE when it is both doable (gates satisfied) and not hopelessly under-levelled
 * (its recommended-stat distance is within reach). Training can flip a task to viable two different ways —
 * by clearing a hard gate (Firemaking 50 → Wintertodt) or by pulling the readiness distance down (combat) —
 * and counting newly-viable tasks captures both without needing to special-case them.</p>
 *
 * <p>Self-suppressing: an account that already meets everything gains nothing from any goal, so every
 * candidate scores zero and the result is empty. Only players who are actually held back see suggestions.</p>
 */
public final class TrainingPlanner
{
	/** See {@link Tuning#VIABLE_WORST_GAP}. */
	public static final int VIABLE_WORST_GAP = Tuning.VIABLE_WORST_GAP;

	/** Combat stats never appear as scored single-skill goals; the ladder rungs below cover them. */
	private static final Set<String> COMBAT_KIT_SET = new HashSet<>(java.util.Arrays.asList(
		"Attack", "Strength", "Defence", "Ranged", "Magic", "Hitpoints"));

	/**
	 * Below this level a combat skill's rungs come from non-endgame content only — a raid's low-stat
	 * puzzle room must not set a fresh account's goal. From 50 up, raids and quest bosses are simply
	 * the next content, and their recommended stats become the rungs.
	 */
	private static final int LADDER_CUTOFF = 50;

	/** Ladder rungs are goals you train AT something; Hitpoints rises on its own and is never one. */
	private static final String[] LADDER_SKILLS = {"Attack", "Strength", "Defence", "Ranged", "Magic"};

	private final SkillXpLibrary skillXp;
	private final BossDifficultyLibrary bossDifficulty;

	public TrainingPlanner(SkillXpLibrary skillXp)
	{
		this(skillXp, null);
	}

	public TrainingPlanner(SkillXpLibrary skillXp, BossDifficultyLibrary bossDifficulty)
	{
		this.skillXp = skillXp == null ? SkillXpLibrary.empty() : skillXp;
		this.bossDifficulty = bossDifficulty == null ? BossDifficultyLibrary.empty() : bossDifficulty;
	}

	/**
	 * Ranks training goals by the CA points they open per hour of training, best first.
	 *
	 * @param all          every task in the dataset
	 * @param completedIds tasks already done (never counted as newly unlocked)
	 * @param effortLib    curated per-task gates
	 * @param recStatsLib  curated recommended stats (drives the readiness distance)
	 * @param profile      the player's live levels + quests
	 * @param limit        how many suggestions to return
	 */
	public List<TrainingSuggestion> plan(List<CombatAchievement> all, Set<Integer> completedIds,
		EffortDataLibrary effortLib, RecStatsLibrary recStatsLib, PlayerProfile profile, int limit)
	{
		if (all == null || all.isEmpty() || profile == null || profile.isEmpty())
		{
			return new ArrayList<>();
		}
		EffortDataLibrary effort = effortLib == null ? EffortDataLibrary.empty() : effortLib;
		RecStatsLibrary rec = recStatsLib == null ? RecStatsLibrary.empty() : recStatsLib;
		Set<Integer> done = completedIds == null ? new HashSet<>() : completedIds;

		Set<Integer> baseViable = viable(all, done, effort, rec, profile);

		// Candidate goals: every hard-gate threshold above the player's current level (these are the levels
		// that actually open something), plus combat milestones for the soft readiness side.
		Map<String, Set<Integer>> thresholds = new LinkedHashMap<>();
		for (CombatAchievement a : all)
		{
			if (done.contains(a.id()))
			{
				continue;
			}
			// Combat-kit skills never become single-skill goals, gate or not: they train together, the
			// "All combat N" milestones cover them, and "Strength 60" pointed at one boss is exactly the
			// kind of advice this section must not give a fresh account.
			for (Map.Entry<String, Integer> req : effort.effortFor(a.id()).levelReqs().entrySet())
			{
				if (req.getValue() != null && req.getValue() > profile.levelOf(req.getKey())
					&& !COMBAT_KIT_SET.contains(req.getKey()))
				{
					thresholds.computeIfAbsent(req.getKey(), k -> new TreeSet<>()).add(req.getValue());
				}
			}
			// RECOMMENDED levels are candidates too, not just hard gates. Without them the planner could
			// only aim at levels some quest happens to demand, and would land one short of what the content
			// actually wants: it suggested "Prayer 42" (a Vorkath gate) for a row about Bryophyta, whose
			// CAs ask for 43. The goal should be the number the player is actually trying to reach.
			for (StatRequirement req : rec.softFor(a.id()))
			{
				for (String skill : req.skills())
				{
					if (req.level() > profile.levelOf(skill) && !COMBAT_KIT_SET.contains(skill))
					{
						thresholds.computeIfAbsent(skill, k -> new TreeSet<>()).add(req.level());
					}
				}
			}
		}

		List<TrainingSuggestion> out = new ArrayList<>();
		for (Map.Entry<String, Set<Integer>> e : thresholds.entrySet())
		{
			for (int target : e.getValue())
			{
				if (target > 99)
				{
					continue;
				}
				Map<String, Integer> raise = new HashMap<>();
				raise.put(e.getKey(), target);
				add(out, e.getKey() + " " + target, raise, all, done, effort, rec, profile, baseViable);
			}
		}
		// One goal per skill — the best rate — so "Ranged 25 / 30 / 40" collapses to a single suggestion.
		Map<String, TrainingSuggestion> best = new LinkedHashMap<>();
		for (TrainingSuggestion s : out)
		{
			String key = String.join("/", s.skills());
			TrainingSuggestion cur = best.get(key);
			if (cur == null || s.score() > cur.score())
			{
				best.put(key, s);
			}
		}
		List<TrainingSuggestion> ranked = new ArrayList<>(best.values());
		ranked.sort(Comparator.comparingDouble(TrainingSuggestion::score).reversed()
			.thenComparing(TrainingSuggestion::label));
		List<TrainingSuggestion> shown = ranked.size() > limit
			? new ArrayList<>(ranked.subList(0, limit)) : ranked;

		// The combat ladder rides AFTER the skilling goals (which every account should just do —
		// Tempoross, Wintertodt, Prayer 43): one rung per combat skill, aimed at the recommended
		// stats of the next content up, lowest first. There is no round-number goal anywhere — the
		// next rung is always whatever the next boss actually asks for.
		shown.addAll(ladderRungs(all, done, effort, rec, profile));
		return shown;
	}

	/**
	 * One rung per combat skill, at any level: "Attack 40", aimed at the lowest level any content above
	 * the player recommends, with the CAs that threshold serves as the prize it works toward. The next
	 * rung is always what the next boss actually asks for — never a round number. Below the cutoff,
	 * endgame-access content cannot set a rung (a raid's "Magic 13" puzzle room is not the reason a
	 * fresh account trains Magic); past it, raids and quest bosses ARE the next content up.
	 */
	private List<TrainingSuggestion> ladderRungs(List<CombatAchievement> all, Set<Integer> done,
		EffortDataLibrary effort, RecStatsLibrary rec, PlayerProfile profile)
	{
		List<TrainingSuggestion> rungs = new ArrayList<>();
		for (String skill : LADDER_SKILLS)
		{
			int have = profile.levelOf(skill);
			boolean allowEndgame = have >= LADDER_CUTOFF;
			// Rung targets come from the curated RECOMMENDED stats only. The hard levelReqs carry
			// quest-chain artifacts (a "Ranged 25" buried in Zulrah's access chain), which made a
			// level-3's first ranged goal read "Ranged 25 — toward Zulrah". The recs are what the
			// content actually wants; quest chains are the Unlock section's business.
			int target = Integer.MAX_VALUE;
			for (CombatAchievement a : all)
			{
				if (done.contains(a.id()) || (!allowEndgame && bossDifficulty.isEndgameAccess(a.monster())))
				{
					continue;
				}
				for (StatRequirement req : rec.softFor(a.id()))
				{
					if (req.skills().contains(skill) && req.level() > have && req.level() < target)
					{
						target = req.level();
					}
				}
			}
			if (target == Integer.MAX_VALUE || target > 99)
			{
				continue;
			}
			// Stepping stone: nothing in the game recommends below 40 for the melee/ranged stats, and
			// "Attack 40" is a big ask from level 3. A skill still under 20 gets a 20 rung first —
			// toward the same content — and the real rec level becomes the next rung after it.
			int rung = have < 20 && target > 20 ? 20 : target;

			// The prize this rung works toward: every CA whose ask on this skill is answered by it.
			int count = 0;
			int points = 0;
			Map<String, Integer> byMonster = new HashMap<>();
			for (CombatAchievement a : all)
			{
				if (done.contains(a.id()) || (!allowEndgame && bossDifficulty.isEndgameAccess(a.monster())))
				{
					continue;
				}
				boolean answered = false;
				for (StatRequirement req : rec.softFor(a.id()))
				{
					if (req.skills().contains(skill) && req.level() > have && req.level() <= target)
					{
						answered = true;
					}
				}
				if (answered)
				{
					count++;
					points += a.points();
					if (a.hasMonster())
					{
						byMonster.merge(a.monster(), 1, Integer::sum);
					}
				}
			}
			if (count == 0)
			{
				continue;
			}
			String hint = byMonster.entrySet().stream()
				.max(Map.Entry.comparingByValue())
				.map(Map.Entry::getKey)
				.orElse("");
			int minutes = (int) Math.round(
				Math.max(0, skillXp.hoursToTrain(skill, have, rung)) * 60);
			rungs.add(new TrainingSuggestion(skill + " " + rung,
				new ArrayList<>(java.util.Collections.singletonList(skill)), rung, count, points,
				minutes, hint, false, true));
		}
		rungs.sort(Comparator.comparingInt(TrainingSuggestion::targetLevel)
			.thenComparingInt(r -> kitOrder(r.skills().get(0))));
		return rungs;
	}

	private static int kitOrder(String skill)
	{
		for (int i = 0; i < LADDER_SKILLS.length; i++)
		{
			if (LADDER_SKILLS[i].equals(skill))
			{
				return i;
			}
		}
		return LADDER_SKILLS.length;
	}

	private void add(List<TrainingSuggestion> out, String label, Map<String, Integer> raise,
		List<CombatAchievement> all, Set<Integer> done, EffortDataLibrary effort, RecStatsLibrary rec,
		PlayerProfile profile, Set<Integer> baseViable)
	{
		Set<Integer> after = viable(all, done, effort, rec, profile.withLevels(raise));
		int count = 0;
		int points = 0;
		Map<String, Integer> byMonster = new HashMap<>();
		for (CombatAchievement a : all)
		{
			if (after.contains(a.id()) && !baseViable.contains(a.id()))
			{
				count++;
				points += a.points();
				if (a.hasMonster())
				{
					byMonster.merge(a.monster(), 1, Integer::sum);
				}
			}
		}
		if (count == 0)
		{
			return; // trains nothing open — not worth suggesting
		}
		double hours = 0;
		boolean calendarTime = false;
		for (Map.Entry<String, Integer> e : raise.entrySet())
		{
			int have = profile.levelOf(e.getKey());
			hours += Math.max(0, skillXp.hoursToTrain(e.getKey(), have, e.getValue()));
			// Farming is bounded by patch timers, so its estimate is elapsed time and reads in days. A goal
			// you simply have to sit and play stays in hours however long it runs.
			calendarTime |= skillXp.isDailyGated(e.getKey(), have, e.getValue());
		}
		String hint = byMonster.entrySet().stream()
			.max(Map.Entry.comparingByValue())
			.map(Map.Entry::getKey)
			.orElse("");
		int target = raise.values().stream().max(Integer::compareTo).orElse(0);
		out.add(new TrainingSuggestion(label, new ArrayList<>(raise.keySet()), target, count, points,
			(int) Math.round(hours * 60), hint, calendarTime));
	}

	/** Tasks that are both doable and within reach — the set a training goal is trying to grow. */
	private Set<Integer> viable(List<CombatAchievement> all, Set<Integer> done, EffortDataLibrary effort,
		RecStatsLibrary rec, PlayerProfile profile)
	{
		ProfileSignalsProvider signals = new ProfileSignalsProvider(effort, rec, profile);
		Set<Integer> out = new HashSet<>();
		for (CombatAchievement a : all)
		{
			if (done.contains(a.id()))
			{
				continue;
			}
			TaskLiveSignals sig = signals.signalsFor(a.id());
			// A training GOAL aims at the level the content actually asks for, not the cheapest level that
			// brings it inside the tolerance window. Scored on the window, the planner undershot on purpose:
			// it suggested "Prayer 37" for a row about Bryophyta, whose CAs want 43, because 37 was enough
			// to land within 15 of it. Someone who trains to the number they were given should arrive ready.
			if (sig.doableNow() && profile.worstShortfall(rec.softFor(a.id())) == 0)
			{
				out.add(a.id());
			}
		}
		return out;
	}
}

package com.pluginideahub.combatachievements.core.effort;

import java.util.Collections;
import java.util.List;

/**
 * "Train this to open up CAs": one suggested training goal, with what it would unlock and what it costs.
 * Produced by {@link TrainingPlanner}. Pure value object.
 */
public final class TrainingSuggestion
{
	private final String label;
	private final List<String> skills;
	private final int targetLevel;
	private final int unlockedTaskCount;
	private final int unlockedPoints;
	private final int trainingMinutes;
	private final String unlocksHint;
	private final boolean calendarTime;
	private final boolean toward;

	public TrainingSuggestion(String label, List<String> skills, int targetLevel, int unlockedTaskCount,
		int unlockedPoints, int trainingMinutes, String unlocksHint)
	{
		this(label, skills, targetLevel, unlockedTaskCount, unlockedPoints, trainingMinutes, unlocksHint,
			false);
	}

	public TrainingSuggestion(String label, List<String> skills, int targetLevel, int unlockedTaskCount,
		int unlockedPoints, int trainingMinutes, String unlocksHint, boolean calendarTime)
	{
		this(label, skills, targetLevel, unlockedTaskCount, unlockedPoints, trainingMinutes, unlocksHint,
			calendarTime, false);
	}

	public TrainingSuggestion(String label, List<String> skills, int targetLevel, int unlockedTaskCount,
		int unlockedPoints, int trainingMinutes, String unlocksHint, boolean calendarTime, boolean toward)
	{
		this.toward = toward;
		this.calendarTime = calendarTime;
		this.label = label == null ? "" : label;
		this.skills = Collections.unmodifiableList(
			skills == null ? Collections.emptyList() : skills);
		this.targetLevel = targetLevel;
		this.unlockedTaskCount = Math.max(0, unlockedTaskCount);
		this.unlockedPoints = Math.max(0, unlockedPoints);
		this.trainingMinutes = Math.max(0, trainingMinutes);
		this.unlocksHint = unlocksHint == null ? "" : unlocksHint;
	}

	/** Display label, e.g. "Fishing 35" or "All combat 20". */
	public String label()
	{
		return label;
	}

	/** The skill(s) this goal raises. */
	public List<String> skills()
	{
		return skills;
	}

	public int targetLevel()
	{
		return targetLevel;
	}

	/** How many CAs become genuinely attemptable once trained. */
	public int unlockedTaskCount()
	{
		return unlockedTaskCount;
	}

	public int unlockedPoints()
	{
		return unlockedPoints;
	}

	public int trainingMinutes()
	{
		return trainingMinutes;
	}

	/**
	 * True when {@link #trainingMinutes()} is elapsed time on a daily-gated skill (Farming's patch timers)
	 * rather than time spent playing — the panel reads those in days, and everything else in hours.
	 */
	public boolean isCalendarTime()
	{
		return calendarTime;
	}

	/** The most-unlocked boss/activity, e.g. "Tempoross" — the reason this goal is worth it. */
	public String unlocksHint()
	{
		return unlocksHint;
	}

	/**
	 * True for a beginner ladder rung — a single combat stat raised TOWARD content whose recommended
	 * stats also need its sibling skills, so the prize is what this rung works toward, not what it
	 * opens by itself. The panel words those "toward", never "opens".
	 */
	public boolean isToward()
	{
		return toward;
	}

	/** Points opened per hour of training — the ranking metric, comparable with the quest unlocks. */
	public double score()
	{
		return trainingMinutes <= 0 ? unlockedPoints : unlockedPoints * 60.0 / trainingMinutes;
	}
}

package com.pluginideahub.combatachievements.core.effort;

import com.pluginideahub.combatachievements.core.achievement.CombatAchievement;
import com.pluginideahub.combatachievements.core.achievement.EffortDataLibrary;
import com.pluginideahub.combatachievements.core.achievement.QuestRequirement;
import com.pluginideahub.combatachievements.core.achievement.RecStatsLibrary;
import com.pluginideahub.combatachievements.core.achievement.TaskDifficultyLibrary;
import com.pluginideahub.combatachievements.core.achievement.TaskEffortData;
import com.pluginideahub.combatachievements.core.ranking.PlayerProfile;
import com.pluginideahub.combatachievements.core.ranking.Tuning;
import java.util.ArrayList;
import java.util.Comparator;
import java.util.LinkedHashMap;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import java.util.Set;

/**
 * Builds the "Unlock next" suggestions: for each quest the player has not finished, how many incomplete
 * CAs (and points) completing it would open up, weighed against the remaining effort to do that quest's
 * chain plus train its unmet skills. Kept deliberately separate from the doable-now CA ranking (a
 * decided design point) so it surfaces the "a few short quests beats an Elite CA" tradeoff without
 * muddying the main list. Pure and deterministic.
 */
public final class UnlockPlanner
{
	private static final double OUT_OF_REACH_WEIGHT = Tuning.OUT_OF_REACH_WEIGHT;

	private final QuestEffortLibrary questLib;
	private final SkillXpLibrary skillLib;

	public UnlockPlanner(QuestEffortLibrary questLib, SkillXpLibrary skillLib)
	{
		this.questLib = questLib == null ? QuestEffortLibrary.empty() : questLib;
		this.skillLib = skillLib == null ? SkillXpLibrary.empty() : skillLib;
	}

	/**
	 * Everything a plan needs beyond the task list and the completed set. Every field defaults to
	 * neutral (empty library, weight 1.0), so a caller sets only what it actually has.
	 */
	public static final class Request
	{
		private EffortDataLibrary effortLib = EffortDataLibrary.empty();
		private PlayerProfile profile = PlayerProfile.empty();
		private TaskDifficultyLibrary difficultyLib = TaskDifficultyLibrary.empty();
		private double unlockBias = 1.0;
		private double unlockDifficultyWeight = 1.0;
		private RecStatsLibrary recStatsLib = RecStatsLibrary.empty();

		public Request effortLib(EffortDataLibrary effortLib)
		{
			this.effortLib = effortLib == null ? EffortDataLibrary.empty() : effortLib;
			return this;
		}

		public Request profile(PlayerProfile profile)
		{
			this.profile = profile == null ? PlayerProfile.empty() : profile;
			return this;
		}

		/**
		 * Per-task pure-skill Difficulty, used to weight the unlocked points so a quest that opens easy
		 * CAs out-ranks one opening equally many hard CAs at the same time cost (empty ⇒ neutral, every
		 * unlock counts its full points).
		 */
		public Request difficultyLib(TaskDifficultyLibrary difficultyLib)
		{
			this.difficultyLib = difficultyLib == null ? TaskDifficultyLibrary.empty() : difficultyLib;
			return this;
		}

		/**
		 * Exponent on a quest's achievable points in its score (1.0 = neutral; &gt;1 favours big-unlock
		 * quests, &lt;1 favours quick ones).
		 */
		public Request unlockBias(double unlockBias)
		{
			this.unlockBias = unlockBias;
			return this;
		}

		/**
		 * How strongly a hard CA's points are discounted (1.0 = the 3/difficulty curve; 0 = count every
		 * unlocked CA's points in full).
		 */
		public Request unlockDifficultyWeight(double unlockDifficultyWeight)
		{
			this.unlockDifficultyWeight = unlockDifficultyWeight;
			return this;
		}

		/**
		 * Curated recommended stats, used to judge which of a quest's unlocked CAs the player could
		 * actually do afterwards. A quest that opens nothing they are ready for is not a suggestion and
		 * is dropped. Empty ⇒ every unlocked CA counts, i.e. exactly the behaviour before readiness was
		 * considered.
		 */
		public Request recStatsLib(RecStatsLibrary recStatsLib)
		{
			this.recStatsLib = recStatsLib == null ? RecStatsLibrary.empty() : recStatsLib;
			return this;
		}
	}

	public List<UnlockSuggestion> plan(List<CombatAchievement> allTasks, Set<Integer> completedTaskIds,
		EffortDataLibrary effortLib, PlayerProfile profile)
	{
		return plan(allTasks, completedTaskIds, new Request().effortLib(effortLib).profile(profile));
	}

	/**
	 * @param difficultyLib per-task pure-skill Difficulty, used to weight the unlocked points so a quest
	 *                      that opens easy CAs out-ranks one opening equally many hard CAs at the same
	 *                      time cost (empty ⇒ neutral, every unlock counts its full points).
	 */
	public List<UnlockSuggestion> plan(List<CombatAchievement> allTasks, Set<Integer> completedTaskIds,
		EffortDataLibrary effortLib, PlayerProfile profile, TaskDifficultyLibrary difficultyLib)
	{
		return plan(allTasks, completedTaskIds,
			new Request().effortLib(effortLib).profile(profile).difficultyLib(difficultyLib));
	}

	/**
	 * @param unlockBias             exponent on a quest's achievable points in its score (1.0 = neutral;
	 *                               &gt;1 favours big-unlock quests, &lt;1 favours quick ones)
	 * @param unlockDifficultyWeight how strongly a hard CA's points are discounted (1.0 = the 3/difficulty
	 *                               curve; 0 = count every unlocked CA's points in full)
	 */
	public List<UnlockSuggestion> plan(List<CombatAchievement> allTasks, Set<Integer> completedTaskIds,
		EffortDataLibrary effortLib, PlayerProfile profile, TaskDifficultyLibrary difficultyLib,
		double unlockBias, double unlockDifficultyWeight)
	{
		return plan(allTasks, completedTaskIds,
			new Request().effortLib(effortLib).profile(profile).difficultyLib(difficultyLib)
				.unlockBias(unlockBias).unlockDifficultyWeight(unlockDifficultyWeight));
	}

	/**
	 * @param recStatsLib curated recommended stats, used to judge which of a quest's unlocked CAs the
	 *                    player could actually do afterwards. A quest that opens nothing they are ready
	 *                    for is not a suggestion and is dropped. Empty ⇒ every unlocked CA counts, i.e.
	 *                    exactly the behaviour before readiness was considered.
	 */
	public List<UnlockSuggestion> plan(List<CombatAchievement> allTasks, Set<Integer> completedTaskIds,
		EffortDataLibrary effortLib, PlayerProfile profile, TaskDifficultyLibrary difficultyLib,
		double unlockBias, double unlockDifficultyWeight, RecStatsLibrary recStatsLib)
	{
		return plan(allTasks, completedTaskIds,
			new Request().effortLib(effortLib).profile(profile).difficultyLib(difficultyLib)
				.unlockBias(unlockBias).unlockDifficultyWeight(unlockDifficultyWeight)
				.recStatsLib(recStatsLib));
	}

	public List<UnlockSuggestion> plan(List<CombatAchievement> allTasks, Set<Integer> completedTaskIds,
		Request request)
	{
		if (allTasks == null)
		{
			return new ArrayList<>();
		}
		Request r = request == null ? new Request() : request;
		Set<Integer> doneTaskIds = completedTaskIds == null ? java.util.Collections.emptySet() : completedTaskIds;
		EffortDataLibrary el = r.effortLib;
		PlayerProfile p = r.profile;
		TaskDifficultyLibrary diffs = r.difficultyLib;
		RecStatsLibrary rec = r.recStatsLib;
		double unlockBias = r.unlockBias;
		double unlockDifficultyWeight = r.unlockDifficultyWeight;

		// quest name -> incomplete tasks it would unlock (skills + other gates already met)
		Map<String, List<CombatAchievement>> unlockedByQuest = new LinkedHashMap<>();
		for (CombatAchievement task : allTasks)
		{
			if (doneTaskIds.contains(task.id()))
			{
				continue;
			}
			TaskEffortData effort = el.effortFor(task.id());
			if (!effort.hasQuestGate() || !p.meets(effort.levelReqs()))
			{
				continue; // not a pure quest-unlock (no quest gate, or skills not yet met)
			}
			for (QuestRequirement req : effort.questReqs())
			{
				String quest = req.quest();
				// Honour startedSuffices: a "started is enough" gate the player has already STARTED is
				// satisfied, so this quest unlocks nothing here (else the CA is already doable and would
				// wrongly show as a locked "needs <quest>" card). Mirrors otherGatesMet / hasQuestAccess.
				boolean gateSatisfied = req.startedSuffices() ? p.hasStarted(quest) : p.hasCompleted(quest);
				if (quest.isEmpty() || gateSatisfied)
				{
					continue; // gate already satisfied — not an unlock
				}
				// Only attribute when every OTHER quest gate on this task is already satisfied.
				if (otherGatesMet(effort, p, quest))
				{
					unlockedByQuest.computeIfAbsent(quest, k -> new ArrayList<>()).add(task);
				}
			}
		}

		List<UnlockSuggestion> out = new ArrayList<>();
		for (Map.Entry<String, List<CombatAchievement>> e : unlockedByQuest.entrySet())
		{
			String quest = e.getKey();
			List<CombatAchievement> tasks = e.getValue();
			int points = tasks.stream().mapToInt(CombatAchievement::points).sum();

			Set<String> completed = p.completedQuestsLower();
			List<String> remainingPrereqs = new ArrayList<>();
			for (String pq : questLib.fullPrerequisites(quest))
			{
				if (!completed.contains(pq.trim().toLowerCase(Locale.ROOT)))
				{
					remainingPrereqs.add(pq);
				}
			}
			int questMinutes = questLib.remainingQuestMinutes(quest, completed);

			// Skill training cost: union the skill reqs of the quest + every remaining prereq, then
			// charge for the levels the player is short.
			Map<String, Integer> needed = new LinkedHashMap<>();
			Set<String> chain = new LinkedHashSet<>(remainingPrereqs);
			chain.add(quest);
			for (String q : chain)
			{
				for (Map.Entry<String, Integer> s : questLib.questFor(q).skillRequirements().entrySet())
				{
					needed.merge(s.getKey(), s.getValue(), Math::max);
				}
			}
			double trainingHours = 0.0;
			int worstShortfall = 0;
			List<String> unmet = new ArrayList<>();
			Map<String, Integer> raised = new LinkedHashMap<>();
			for (Map.Entry<String, Integer> s : needed.entrySet())
			{
				int have = p.levelOf(s.getKey());
				if (have < s.getValue())
				{
					trainingHours += skillLib.hoursToTrain(s.getKey(), have, s.getValue());
					worstShortfall = Math.max(worstShortfall, s.getValue() - have);
					unmet.add(s.getKey() + " " + have + "→" + s.getValue());
					raised.put(s.getKey(), s.getValue()); // only ever upward — never lower a met skill
				}
			}

			// Judge readiness at the levels the player would HAVE once the chain's requirements were met,
			// not at today's: a quest that trains you on the way would otherwise look like it opens nothing.
			PlayerProfile after = raised.isEmpty() ? p : p.withLevels(raised);

			// The reachable part of the prize, and its difficulty-weighted value: an unlock opening easy CAs
			// is worth more per quest-minute than one opening equally many brutal CAs. CAs the player still
			// could not attempt afterwards count for nothing — a quest that opens 15 CAs you are 40 levels
			// short of has not opened 15 CAs.
			int reachableCount = 0;
			int reachablePoints = 0;
			double achievable = 0.0;
			for (CombatAchievement task : tasks)
			{
				boolean inReach = after.worstShortfall(rec.softFor(task.id()))
					<= TrainingPlanner.VIABLE_WORST_GAP;
				if (inReach)
				{
					reachableCount++;
					reachablePoints += task.points();
				}
				achievable += task.points()
					* achievableWeight(diffs.difficultyFor(task.id()).difficulty(), unlockDifficultyWeight)
					* (inReach ? 1.0 : OUT_OF_REACH_WEIGHT);
			}
			// A quest opening nothing reachable keeps a zero score and sinks to the bottom; it is not dropped
			// here because the Route's locked "needs <quest>" pile is built from this same list and is
			// deliberately aspirational. The "Unlock next" section is what filters on reachableTaskCount.
			achievable = Math.pow(Math.max(0.0, achievable), Math.max(0.0, unlockBias));

			List<Integer> taskIds = new ArrayList<>();
			for (CombatAchievement t : tasks)
			{
				taskIds.add(t.id());
			}
			out.add(UnlockSuggestion.builder()
				.questName(quest)
				.difficulty(questLib.questFor(quest).difficulty())
				.unlockedTaskCount(tasks.size())
				.unlockedPoints(points)
				.reachableTaskCount(reachableCount)
				.reachablePoints(reachablePoints)
				.achievablePoints((int) Math.round(achievable))
				.questMinutes(questMinutes)
				.trainingMinutes((int) Math.round(trainingHours * 60))
				.remainingPrerequisites(remainingPrereqs)
				.unmetSkills(unmet)
				.unlockedTaskIds(taskIds)
				.worstSkillShortfall(worstShortfall)
				.build());
		}

		out.sort(Comparator.comparingDouble(UnlockSuggestion::score).reversed()
			.thenComparing(UnlockSuggestion::questName));
		return out;
	}

	/**
	 * Ease weight for a CA's pure-skill Difficulty (1–10): easy points count near full, hard points are
	 * discounted. Bounded to [0.3, 1.0] and never inflates above the raw points — neutral difficulty (3)
	 * and below map to 1.0. Mirrors the inverse of the quick-wins difficulty factor (difficulty / 3).
	 */
	private static double achievableWeight(int difficulty, double weight)
	{
		int d = Math.max(1, Math.min(10, difficulty));
		double base = 3.0 / d;                    // weight 1.0 → the current 3/difficulty discount
		double w = 1.0 - (1.0 - base) * weight;   // weight 0 → 1.0 (difficulty ignored, full points)
		return Math.max(0.3, Math.min(1.0, w));
	}

	private static boolean otherGatesMet(TaskEffortData effort, PlayerProfile p, String thisQuest)
	{
		for (QuestRequirement req : effort.questReqs())
		{
			if (req.quest().equalsIgnoreCase(thisQuest))
			{
				continue;
			}
			boolean ok = req.startedSuffices() ? p.hasStarted(req.quest()) : p.hasCompleted(req.quest());
			if (!ok)
			{
				return false;
			}
		}
		return true;
	}
}

package com.pluginideahub.combatachievements.core.effort;

import java.util.Collections;
import java.util.List;

/**
 * A "do this quest to open up CAs" suggestion: how many incomplete CAs (and points) completing a
 * quest would unlock, against the remaining effort to do that quest's chain plus train its unmet
 * skills. Pure value object; ranked by {@link #score()} (difficulty-weighted "achievable" points per
 * effort-minute — a quest that opens easy points is worth more than one opening equally many hard ones).
 */
public final class UnlockSuggestion
{
	private final String questName;
	private final String difficulty;
	private final int unlockedTaskCount;
	private final int unlockedPoints;
	private final int reachableTaskCount;
	private final int reachablePoints;
	private final int achievablePoints;
	private final int questMinutes;
	private final int trainingMinutes;
	private final List<String> remainingPrerequisites;
	private final List<String> unmetSkills;
	private final List<Integer> unlockedTaskIds;
	private final int worstSkillShortfall;

	public UnlockSuggestion(String questName, String difficulty, int unlockedTaskCount,
		int unlockedPoints, int reachableTaskCount, int reachablePoints, int achievablePoints,
		int questMinutes, int trainingMinutes,
		List<String> remainingPrerequisites, List<String> unmetSkills, List<Integer> unlockedTaskIds)
	{
		this(questName, difficulty, unlockedTaskCount, unlockedPoints, reachableTaskCount,
			reachablePoints, achievablePoints, questMinutes, trainingMinutes, remainingPrerequisites,
			unmetSkills, unlockedTaskIds, 0);
	}

	public UnlockSuggestion(String questName, String difficulty, int unlockedTaskCount,
		int unlockedPoints, int reachableTaskCount, int reachablePoints, int achievablePoints,
		int questMinutes, int trainingMinutes,
		List<String> remainingPrerequisites, List<String> unmetSkills, List<Integer> unlockedTaskIds,
		int worstSkillShortfall)
	{
		this(builder()
			.questName(questName)
			.difficulty(difficulty)
			.unlockedTaskCount(unlockedTaskCount)
			.unlockedPoints(unlockedPoints)
			.reachableTaskCount(reachableTaskCount)
			.reachablePoints(reachablePoints)
			.achievablePoints(achievablePoints)
			.questMinutes(questMinutes)
			.trainingMinutes(trainingMinutes)
			.remainingPrerequisites(remainingPrerequisites)
			.unmetSkills(unmetSkills)
			.unlockedTaskIds(unlockedTaskIds)
			.worstSkillShortfall(worstSkillShortfall));
	}

	private UnlockSuggestion(Builder builder)
	{
		this.worstSkillShortfall = Math.max(0, builder.worstSkillShortfall);
		this.questName = builder.questName == null ? "" : builder.questName;
		this.difficulty = builder.difficulty == null ? "" : builder.difficulty;
		this.unlockedTaskCount = builder.unlockedTaskCount;
		this.unlockedPoints = builder.unlockedPoints;
		this.reachableTaskCount = builder.reachableTaskCount;
		this.reachablePoints = builder.reachablePoints;
		this.achievablePoints = Math.max(0, builder.achievablePoints);
		this.questMinutes = Math.max(0, builder.questMinutes);
		this.trainingMinutes = Math.max(0, builder.trainingMinutes);
		this.remainingPrerequisites = Collections.unmodifiableList(
			builder.remainingPrerequisites == null ? Collections.emptyList() : builder.remainingPrerequisites);
		this.unmetSkills = Collections.unmodifiableList(
			builder.unmetSkills == null ? Collections.emptyList() : builder.unmetSkills);
		this.unlockedTaskIds = Collections.unmodifiableList(
			builder.unlockedTaskIds == null ? Collections.emptyList() : builder.unlockedTaskIds);
	}

	public static Builder builder()
	{
		return new Builder();
	}

	/** Names each of the thirteen fields at the call site; unset fields keep their neutral defaults. */
	public static final class Builder
	{
		private String questName = "";
		private String difficulty = "";
		private int unlockedTaskCount;
		private int unlockedPoints;
		private int reachableTaskCount;
		private int reachablePoints;
		private int achievablePoints;
		private int questMinutes;
		private int trainingMinutes;
		private List<String> remainingPrerequisites;
		private List<String> unmetSkills;
		private List<Integer> unlockedTaskIds;
		private int worstSkillShortfall;

		public Builder questName(String questName)
		{
			this.questName = questName;
			return this;
		}

		public Builder difficulty(String difficulty)
		{
			this.difficulty = difficulty;
			return this;
		}

		public Builder unlockedTaskCount(int unlockedTaskCount)
		{
			this.unlockedTaskCount = unlockedTaskCount;
			return this;
		}

		public Builder unlockedPoints(int unlockedPoints)
		{
			this.unlockedPoints = unlockedPoints;
			return this;
		}

		public Builder reachableTaskCount(int reachableTaskCount)
		{
			this.reachableTaskCount = reachableTaskCount;
			return this;
		}

		public Builder reachablePoints(int reachablePoints)
		{
			this.reachablePoints = reachablePoints;
			return this;
		}

		public Builder achievablePoints(int achievablePoints)
		{
			this.achievablePoints = achievablePoints;
			return this;
		}

		public Builder questMinutes(int questMinutes)
		{
			this.questMinutes = questMinutes;
			return this;
		}

		public Builder trainingMinutes(int trainingMinutes)
		{
			this.trainingMinutes = trainingMinutes;
			return this;
		}

		public Builder remainingPrerequisites(List<String> remainingPrerequisites)
		{
			this.remainingPrerequisites = remainingPrerequisites;
			return this;
		}

		public Builder unmetSkills(List<String> unmetSkills)
		{
			this.unmetSkills = unmetSkills;
			return this;
		}

		public Builder unlockedTaskIds(List<Integer> unlockedTaskIds)
		{
			this.unlockedTaskIds = unlockedTaskIds;
			return this;
		}

		public Builder worstSkillShortfall(int worstSkillShortfall)
		{
			this.worstSkillShortfall = worstSkillShortfall;
			return this;
		}

		public UnlockSuggestion build()
		{
			return new UnlockSuggestion(this);
		}
	}

	public String questName()
	{
		return questName;
	}

	public String difficulty()
	{
		return difficulty;
	}

	public int unlockedTaskCount()
	{
		return unlockedTaskCount;
	}

	public int unlockedPoints()
	{
		return unlockedPoints;
	}

	/**
	 * How many of the unlocked CAs the player would actually be ready for once this quest chain's own
	 * skill requirements were met. The prize the panel shows: a quest that opens 15 CAs you are 40 levels
	 * short of has not opened 15 CAs.
	 */
	public int reachableTaskCount()
	{
		return reachableTaskCount;
	}

	/** Points from {@link #reachableTaskCount()} — the part of the prize you could go and collect. */
	public int reachablePoints()
	{
		return reachablePoints;
	}

	/**
	 * The REACHABLE points weighted by how easy those CAs are (difficulty-discounted): easy points count
	 * near full, hard points are worth less. Drives {@link #score()}; {@link #unlockedPoints()} stays the
	 * raw total for reference.
	 */
	public int achievablePoints()
	{
		return achievablePoints;
	}

	public int questMinutes()
	{
		return questMinutes;
	}

	public int trainingMinutes()
	{
		return trainingMinutes;
	}

	public int totalMinutes()
	{
		return questMinutes + trainingMinutes;
	}

	public List<String> remainingPrerequisites()
	{
		return remainingPrerequisites;
	}

	public List<String> unmetSkills()
	{
		return unmetSkills;
	}

	/** Ids of the incomplete CAs this quest would unlock (skills already met). */
	public List<Integer> unlockedTaskIds()
	{
		return unlockedTaskIds;
	}

	/**
	 * The single worst level gap across the quest chain's own skill requirements — how far the player is
	 * from being ABLE to do this quest, in levels. 0 when every requirement is met. This is the "is this
	 * quest anywhere near me?" number: a level-3 shown a Master questline needing 70s has a shortfall in
	 * the 60s, however many points it would open.
	 */
	public int worstSkillShortfall()
	{
		return worstSkillShortfall;
	}

	/**
	 * Difficulty-weighted achievable points per total effort-minute (quest chain + skill training).
	 * Higher is better. Uses {@link #achievablePoints()} so a quest opening easy points out-ranks one
	 * opening equally many hard points at the same time cost.
	 */
	public double score()
	{
		int total = totalMinutes();
		return total <= 0 ? achievablePoints : achievablePoints / (double) total;
	}
}

package com.pluginideahub.combatachievements.core.guide;

import com.pluginideahub.combatachievements.core.achievement.AchievementTier;
import java.util.Collections;
import java.util.List;

/**
 * An authored route guide (e.g. "0 → Medium: The Fastest Path"). Carries a walkthrough video, a
 * summary, authored tips, and an optional {@code targetTier} — when set, the UI also renders the
 * player's live optimal route to that tier from {@code OptimalPathSolver}, so an authored guide and
 * a personalised route live in one place. Pure value object.
 */
public final class Guide
{
	private final String id;
	private final String title;
	private final String author;
	private final String summary;
	private final String videoUrl;
	private final AchievementTier targetTier;
	private final List<String> tags;
	private final List<GuideStep> steps;

	public Guide(String id, String title, String author, String summary, String videoUrl,
		AchievementTier targetTier, List<String> tags, List<GuideStep> steps)
	{
		this.id = id == null ? "" : id;
		this.title = title == null ? "" : title;
		this.author = author == null ? "" : author;
		this.summary = summary == null ? "" : summary;
		this.videoUrl = videoUrl == null ? "" : videoUrl;
		this.targetTier = targetTier;
		this.tags = Collections.unmodifiableList(tags);
		this.steps = Collections.unmodifiableList(steps);
	}

	public String id()
	{
		return id;
	}

	public String title()
	{
		return title;
	}

	public String author()
	{
		return author;
	}

	public String summary()
	{
		return summary;
	}

	public String videoUrl()
	{
		return videoUrl;
	}

	public boolean hasVideo()
	{
		return !videoUrl.isEmpty();
	}

	/** The tier this guide routes toward, or null for a non-route guide. */
	public AchievementTier targetTier()
	{
		return targetTier;
	}

	public List<String> tags()
	{
		return tags;
	}

	public List<GuideStep> steps()
	{
		return steps;
	}
}

package com.pluginideahub.combatachievements.core.guide;

import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import com.pluginideahub.combatachievements.core.achievement.AchievementTier;
import com.pluginideahub.combatachievements.core.data.BundledJson;
import java.io.InputStream;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;

/**
 * Loads bundled authored route guides ({@code guides.json}). Pure Java (Gson only). A missing or
 * malformed file yields an empty library rather than an error, so guide problems never break the
 * panel. See docs/DESIGN.md (Guide section).
 */
public final class GuideLibrary
{
	private static final String BUNDLED_RESOURCE =
		"/com/pluginideahub/combatachievements/guides.json";

	private final List<Guide> guides;

	private GuideLibrary(List<Guide> guides)
	{
		this.guides = Collections.unmodifiableList(guides);
	}

	public static GuideLibrary empty()
	{
		return new GuideLibrary(new ArrayList<>());
	}

	public static GuideLibrary loadBundled()
	{
		return fromRoot(BundledJson.readBundled(GuideLibrary.class, BUNDLED_RESOURCE));
	}

	public static GuideLibrary load(InputStream in)
	{
		return fromRoot(BundledJson.read(in));
	}

	private static GuideLibrary fromRoot(JsonObject root)
	{
		JsonElement guidesEl = root == null ? null : root.get("guides");
		if (guidesEl == null || !guidesEl.isJsonArray())
		{
			return empty();
		}
		// Guides are an ordered, authored list — one broken guide means a broken file, so the whole
		// library is discarded rather than a guide silently dropped.
		try
		{
			List<Guide> guides = new ArrayList<>();
			for (JsonElement el : guidesEl.getAsJsonArray())
			{
				if (el.isJsonObject())
				{
					guides.add(parseGuide(el.getAsJsonObject()));
				}
			}
			return new GuideLibrary(guides);
		}
		catch (RuntimeException ex)
		{
			return empty();
		}
	}

	private static Guide parseGuide(JsonObject obj)
	{
		String id = BundledJson.optString(obj, "id", "");
		String title = BundledJson.optString(obj, "title", "");
		String author = BundledJson.optString(obj, "author", "");
		String summary = BundledJson.optString(obj, "summary", "");
		String videoUrl = BundledJson.optString(obj, "videoUrl", "");
		AchievementTier targetTier = AchievementTier.fromDisplayName(
			BundledJson.optString(obj, "targetTier", ""));

		List<String> tags = new ArrayList<>();
		JsonElement tagsEl = obj.get("tags");
		if (tagsEl != null && tagsEl.isJsonArray())
		{
			for (JsonElement t : tagsEl.getAsJsonArray())
			{
				tags.add(t.getAsString());
			}
		}

		List<GuideStep> steps = new ArrayList<>();
		JsonElement stepsEl = obj.get("steps");
		if (stepsEl != null && stepsEl.isJsonArray())
		{
			for (JsonElement s : stepsEl.getAsJsonArray())
			{
				if (s.isJsonObject())
				{
					JsonObject so = s.getAsJsonObject();
					steps.add(new GuideStep(BundledJson.optString(so, "note", ""),
						BundledJson.optInt(so, "taskId", -1)));
				}
				else if (s.isJsonPrimitive())
				{
					steps.add(new GuideStep(s.getAsString(), -1));
				}
			}
		}

		return new Guide(id, title, author, summary, videoUrl, targetTier, tags, steps);
	}

	public List<Guide> all()
	{
		return guides;
	}

	public int count()
	{
		return guides.size();
	}
}

