package com.pluginideahub.combatachievements.core.path;

import com.pluginideahub.combatachievements.core.achievement.AchievementTier;
import com.pluginideahub.combatachievements.core.achievement.CombatAchievement;
import com.pluginideahub.combatachievements.core.ranking.RankedTask;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.Comparator;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.function.ToDoubleFunction;

/**
 * Finds the minimum-total-effort set of incomplete tasks whose points close the gap to a target
 * tier's cumulative threshold — an exact min-cost covering knapsack solved by DP over the integer
 * points axis (effort, a real number, is the minimized cost). O(N·gap) time, O(N·gap) space; with
 * N ≤ 637 and gap ≤ 2630 this is instant. Deterministic: candidates are processed in (effort asc, id
 * asc) order and ties resolve to "skip", so the same input always yields the same plan. See
 * docs/DESIGN.md §6c.
 */
public final class OptimalPathSolver
{
	/** Float-equality tolerance for effort comparisons. */
	public static final double EPS = 1e-9;

	/**
	 * Min-effort path to cross {@code pointsGap} points using {@code candidates} (incomplete,
	 * typically doable-now tasks, each carrying its effort). Steps are returned easiest-first.
	 */
	public PathPlan solve(AchievementTier targetTier, int pointsGap, List<RankedTask> candidates)
	{
		return solve(targetTier, pointsGap, candidates, RankedTask::effort);
	}

	/**
	 * As {@link #solve(AchievementTier, int, List)} but minimising an arbitrary per-task {@code cost}
	 * (e.g. estimated minutes for the quickest path) instead of the default abstract effort. Steps are
	 * returned cheapest-first by the same cost.
	 */
	public PathPlan solve(AchievementTier targetTier, int pointsGap, List<RankedTask> candidates,
		ToDoubleFunction<RankedTask> cost)
	{
		if (pointsGap <= 0)
		{
			return PathPlan.alreadyUnlocked(targetTier);
		}

		List<RankedTask> items = sortedByCost(candidates, cost);
		int n = items.size();

		int sumPoints = 0;
		for (RankedTask rt : items)
		{
			sumPoints += rt.achievement().points();
		}
		if (sumPoints < pointsGap)
		{
			// Not enough doable tasks to reach the gap: surface them all, flagged unreachable.
			return buildPlan(targetTier, pointsGap, items, false);
		}

		int gap = pointsGap;
		double[][] dp = new double[n + 1][gap + 1];
		boolean[][] took = new boolean[n + 1][gap + 1];
		for (int p = 1; p <= gap; p++)
		{
			dp[0][p] = Double.POSITIVE_INFINITY;
		}
		for (int i = 1; i <= n; i++)
		{
			int value = items.get(i - 1).achievement().points();
			double c = cost.applyAsDouble(items.get(i - 1));
			for (int p = 0; p <= gap; p++)
			{
				double skip = dp[i - 1][p];
				int prev = Math.max(0, p - value);
				double take = dp[i - 1][prev] + c;
				if (take < skip - EPS)
				{
					dp[i][p] = take;
					took[i][p] = true;
				}
				else
				{
					dp[i][p] = skip;
				}
			}
		}

		List<RankedTask> chosen = new ArrayList<>();
		int p = gap;
		for (int i = n; i >= 1; i--)
		{
			if (took[i][p])
			{
				chosen.add(items.get(i - 1));
				p = Math.max(0, p - items.get(i - 1).achievement().points());
			}
		}
		return buildPlan(targetTier, pointsGap, sortedByCost(chosen, cost), true);
	}

	/**
	 * As {@link #solve} but boss-aware: it charges a fixed {@code tripOverhead} once per boss visited, so
	 * the cheapest way to close the gap prefers doing several CAs at one boss over one CA at each of many.
	 * Without this the plain solver scattered a route across a dozen one-CA trips and closed the last gap
	 * at a far-off boss (Nex) when a couple more at a boss already on the route would have been quicker.
	 *
	 * <p>Exact, in two levels. Per boss, a 0/1 knapsack gives the minimum-cost subset for every
	 * achievable point total there. A group knapsack then picks one point total per boss, paying one
	 * trip overhead whenever a boss is used at all, to reach the gap at minimum total cost.</p>
	 */
	public PathPlan solveClustered(AchievementTier targetTier, int pointsGap, List<RankedTask> candidates,
		ToDoubleFunction<RankedTask> cost, double tripOverhead)
	{
		if (pointsGap <= 0)
		{
			return PathPlan.alreadyUnlocked(targetTier);
		}
		double overhead = Math.max(0.0, tripOverhead);

		// Group by boss (a task with no monster is its own group so it is never wrongly clustered).
		LinkedHashMap<String, List<RankedTask>> byBoss = new LinkedHashMap<>();
		int sumPoints = 0;
		for (RankedTask rt : candidates)
		{
			CombatAchievement a = rt.achievement();
			String key = a.hasMonster() ? a.monster() : ("�solo:" + a.id());
			byBoss.computeIfAbsent(key, k -> new ArrayList<>()).add(rt);
			sumPoints += a.points();
		}
		if (sumPoints < pointsGap)
		{
			// Not enough content to reach the gap: surface everything, flagged unreachable (as solve does).
			return buildPlan(targetTier, pointsGap, sortedByCost(candidates, cost), false);
		}

		List<BossKnapsack> bosses = new ArrayList<>();
		for (List<RankedTask> group : byBoss.values())
		{
			bosses.add(new BossKnapsack(group, cost));
		}

		// Group knapsack over the per-boss options. dp[p] = min cost to reach at least p points; pick[i][p]
		// = the point total taken from boss i to land at coverage p (0 = boss skipped).
		int b = bosses.size();
		double[] dp = new double[pointsGap + 1];
		int[][] pick = new int[b][pointsGap + 1];
		for (int p = 1; p <= pointsGap; p++)
		{
			dp[p] = Double.POSITIVE_INFINITY;
		}
		for (int i = 0; i < b; i++)
		{
			double[] bossCost = bosses.get(i).minCostByPoints;
			double[] ndp = dp.clone(); // boss i skipped (contributes 0 points at 0 cost)
			for (int q = 1; q < bossCost.length; q++)
			{
				if (Double.isInfinite(bossCost[q]))
				{
					continue;
				}
				double add = bossCost[q] + overhead; // one trip, whatever subset of this boss you do
				for (int p = 0; p <= pointsGap; p++)
				{
					int from = Math.max(0, p - q);
					double take = dp[from] + add;
					if (take < ndp[p] - EPS)
					{
						ndp[p] = take;
						pick[i][p] = q;
					}
				}
			}
			dp = ndp;
		}

		// Backtrack: for each boss, the point total taken, then its min-cost subset for that total.
		List<RankedTask> chosen = new ArrayList<>();
		int p = pointsGap;
		for (int i = b - 1; i >= 0; i--)
		{
			int q = pick[i][p];
			if (q > 0)
			{
				chosen.addAll(bosses.get(i).subsetForPoints(q));
				p = Math.max(0, p - q);
			}
		}

		// Order bosses by their total chosen cost (least-effort boss first); CAs within a boss cheapest-first.
		Map<String, Double> bossTotal = new LinkedHashMap<>();
		for (RankedTask rt : chosen)
		{
			bossTotal.merge(bossKey(rt), cost.applyAsDouble(rt), Double::sum);
		}
		chosen.sort(Comparator
			.comparingDouble((RankedTask rt) -> bossTotal.getOrDefault(bossKey(rt), 0.0))
			.thenComparing(OptimalPathSolver::bossKey)
			.thenComparingDouble(cost)
			.thenComparingInt(rt -> rt.achievement().id()));

		return buildPlan(targetTier, pointsGap, chosen, true);
	}

	private static String bossKey(RankedTask rt)
	{
		CombatAchievement a = rt.achievement();
		return a.hasMonster() ? a.monster() : (" solo:" + a.id());
	}

	/**
	 * One boss's CAs as a 0/1 knapsack over points: minCostByPoints[q] is the least-cost subset that sums
	 * to exactly q points, and subsetForPoints recovers it. The trip overhead is charged by the caller,
	 * once, when the boss is used at all.
	 */
	private static final class BossKnapsack
	{
		private final List<RankedTask> items;
		private final double[] minCostByPoints; // index = exact points, value = min subset cost (INF if none)
		private final double[][] dp;            // dp[i][q] over the first i items, kept for backtracking

		BossKnapsack(List<RankedTask> group, ToDoubleFunction<RankedTask> cost)
		{
			this.items = new ArrayList<>(group);
			int total = 0;
			for (RankedTask rt : items)
			{
				total += rt.achievement().points();
			}
			int m = items.size();
			dp = new double[m + 1][total + 1];
			for (double[] row : dp)
			{
				Arrays.fill(row, Double.POSITIVE_INFINITY);
			}
			dp[0][0] = 0.0;
			for (int i = 1; i <= m; i++)
			{
				int pts = items.get(i - 1).achievement().points();
				double c = cost.applyAsDouble(items.get(i - 1));
				for (int q = 0; q <= total; q++)
				{
					dp[i][q] = dp[i - 1][q]; // skip item i
					if (q >= pts && dp[i - 1][q - pts] + c < dp[i][q])
					{
						dp[i][q] = dp[i - 1][q - pts] + c; // take item i
					}
				}
			}
			minCostByPoints = dp[m];
		}

		/** The min-cost subset summing to exactly q points, recovered from the DP table. */
		List<RankedTask> subsetForPoints(int q)
		{
			List<RankedTask> out = new ArrayList<>();
			int points = q;
			for (int i = items.size(); i >= 1 && points > 0; i--)
			{
				// Item i was taken when the value improved on "skip item i".
				if (Double.isInfinite(dp[i - 1][points]) || dp[i][points] < dp[i - 1][points] - EPS)
				{
					RankedTask taken = items.get(i - 1);
					out.add(taken);
					points -= taken.achievement().points();
				}
			}
			return out;
		}
	}

	/**
	 * Grandmaster branch: GM additionally requires completing <em>every</em> remaining task, so the
	 * "path" is simply all incomplete candidates, cheapest-first. See docs/DESIGN.md §4.2/§6c.
	 */
	public PathPlan solveCompleteAll(AchievementTier targetTier, List<RankedTask> candidates)
	{
		return solveCompleteAll(targetTier, candidates, RankedTask::effort);
	}

	public PathPlan solveCompleteAll(AchievementTier targetTier, List<RankedTask> candidates,
		ToDoubleFunction<RankedTask> cost)
	{
		if (candidates == null || candidates.isEmpty())
		{
			return PathPlan.alreadyUnlocked(targetTier);
		}
		List<RankedTask> ordered = sortedByCost(candidates, cost);
		int gap = 0;
		for (RankedTask rt : ordered)
		{
			gap += rt.achievement().points();
		}
		return buildPlan(targetTier, gap, ordered, true);
	}


	private static List<RankedTask> sortedByCost(List<RankedTask> candidates,
		ToDoubleFunction<RankedTask> cost)
	{
		List<RankedTask> items = new ArrayList<>(candidates);
		items.sort(Comparator
			.comparingDouble(cost)
			.thenComparingInt(rt -> rt.achievement().id()));
		return items;
	}

	private static PathPlan buildPlan(AchievementTier targetTier, int pointsGap,
		List<RankedTask> ordered, boolean reachable)
	{
		List<PathStep> steps = new ArrayList<>();
		int cumulative = 0;
		double totalEffort = 0.0;
		for (RankedTask rt : ordered)
		{
			cumulative += rt.achievement().points();
			totalEffort += rt.effort();
			steps.add(new PathStep(rt.achievement(), rt.effort(), cumulative));
		}
		return new PathPlan(targetTier, pointsGap, steps, cumulative, totalEffort, reachable, false);
	}
}

package com.pluginideahub.combatachievements.core.path;

import com.pluginideahub.combatachievements.core.achievement.AchievementTier;
import java.util.Collections;
import java.util.List;

/**
 * The result of {@link OptimalPathSolver}: the ordered set of tasks that closes the points gap to a
 * target tier with minimum total effort. Pure value object.
 */
public final class PathPlan
{
	private final AchievementTier targetTier;
	private final int pointsGap;
	private final List<PathStep> steps;
	private final int totalPoints;
	private final double totalEffort;
	private final boolean reachable;
	private final boolean alreadyUnlocked;

	public PathPlan(AchievementTier targetTier, int pointsGap, List<PathStep> steps,
		int totalPoints, double totalEffort, boolean reachable, boolean alreadyUnlocked)
	{
		this.targetTier = targetTier;
		this.pointsGap = pointsGap;
		this.steps = Collections.unmodifiableList(steps);
		this.totalPoints = totalPoints;
		this.totalEffort = totalEffort;
		this.reachable = reachable;
		this.alreadyUnlocked = alreadyUnlocked;
	}

	/** The "nothing to do — already unlocked" plan. */
	public static PathPlan alreadyUnlocked(AchievementTier targetTier)
	{
		return new PathPlan(targetTier, 0, Collections.emptyList(), 0, 0.0, true, true);
	}

	public AchievementTier targetTier()
	{
		return targetTier;
	}

	public int pointsGap()
	{
		return pointsGap;
	}

	public List<PathStep> steps()
	{
		return steps;
	}

	public int totalPoints()
	{
		return totalPoints;
	}

	public double totalEffort()
	{
		return totalEffort;
	}

	/** True when the chosen tasks actually reach the gap; false when there aren't enough doable tasks. */
	public boolean reachable()
	{
		return reachable;
	}

	public boolean alreadyUnlocked()
	{
		return alreadyUnlocked;
	}
}

