/**
 * Pure assembler: turns a {@link ProgressSnapshot} plus the loaded libraries into a render-ready
 * {@link SidePanelViewModel}. No RuneLite types — all live account facts arrive via
 * {@link SignalsProvider}, so the whole view can be built and tested without a game client.
 */
public final class SidePanelViewModelBuilder
{
	private final CombatAchievementLibrary lib;
	private final EffortDataLibrary effortLib;
	private final VideoGuideLibrary videoLib;
	private final GuideLibrary guideLib;
	private final TierRewardLibrary rewardLib;
	private final EffortModel model;
	private TaskDifficultyLibrary difficultyLib = TaskDifficultyLibrary.empty();
	private TaskDetailLibrary detailLib = TaskDetailLibrary.empty();
	private LowHangingFruitRanker ranker;
	private final OptimalPathSolver solver;

	// Effort-engine inputs (optional; default to empty/neutral so existing callers are unaffected).
	private BossTimingLibrary timingLib = BossTimingLibrary.empty();
	private QuestEffortLibrary questEffortLib = QuestEffortLibrary.empty();
	private SkillXpLibrary skillXpLib = SkillXpLibrary.empty();
	private CombatExperience experience = CombatExperience.empty();
	private PlayerProfile profile = PlayerProfile.empty();
	private ScalingLibrary scalingLib = ScalingLibrary.defaults();
	private RecStatsLibrary recStatsLib = RecStatsLibrary.empty();
	private BossDifficultyLibrary bossDifficultyLib = BossDifficultyLibrary.empty();
	private int tripOverheadMinutes = 6;
	// Configurable CAs-ranking weights (1.0 = neutral). The Route no longer uses these — it has its own
	// time-based cost (see routeCost) — so the CAs list and Route are decoupled.
	private double caPointsWeight = 1.0;
	private double caDifficultyWeight = 1.0;
	private double unlockBias = 1.0;
	private double unlockDifficultyWeight = 1.0;
	private long routeShuffleSeed;
	/** Task ids the player has barred from the Route ("I'm not doing that one"). */
	private Set<Integer> barredTasks = Collections.emptySet();
	/** Task ids the player has pinned INTO the Route ("I want to do this one"). */
	private Set<Integer> pinnedTasks = Collections.emptySet();
	// Deliberately fixed (not config): the panel shows a focused shortlist of the best sessions/unlocks;
	// the underlying rankings are complete, these just cap what is rendered.
	private static final int SESSIONS_LIMIT = 8;
	private static final int UNLOCKS_LIMIT = 6;
	private static final int LOCKED_ROUTE_CAS_LIMIT = 30;
	private static final int TRAININGS_LIMIT = 4;
	private static final int BEGINNER_COMBAT_LEVEL = Tuning.BEGINNER_COMBAT_LEVEL;

	public SidePanelViewModelBuilder(CombatAchievementLibrary lib, EffortDataLibrary effortLib,
		VideoGuideLibrary videoLib, GuideLibrary guideLib, EffortModel model)
	{
		this(lib, effortLib, videoLib, guideLib, TierRewardLibrary.empty(), model);
	}

	public SidePanelViewModelBuilder(CombatAchievementLibrary lib, EffortDataLibrary effortLib,
		VideoGuideLibrary videoLib, GuideLibrary guideLib, TierRewardLibrary rewardLib, EffortModel model)
	{
		this.lib = lib;
		this.effortLib = effortLib == null ? EffortDataLibrary.empty() : effortLib;
		this.videoLib = videoLib == null ? VideoGuideLibrary.empty() : videoLib;
		this.guideLib = guideLib == null ? GuideLibrary.empty() : guideLib;
		this.rewardLib = rewardLib == null ? TierRewardLibrary.empty() : rewardLib;
		this.model = model == null ? EffortModel.standard() : model;
		rebuildRanker();
		this.solver = new OptimalPathSolver();
	}

	/**
	 * Supplies the curated pure-skill Difficulty library the Recommended/Quick-wins ranking uses to
	 * order tasks (easy, worthwhile wins first). Optional — when omitted, ranking falls back to the
	 * neutral difficulty and behaves as before. Rebuilds the ranker so the data takes effect.
	 */
	public SidePanelViewModelBuilder difficulty(TaskDifficultyLibrary difficultyLib)
	{
		this.difficultyLib = difficultyLib == null ? TaskDifficultyLibrary.empty() : difficultyLib;
		rebuildRanker();
		return this;
	}

	private void rebuildRanker()
	{
		// Hand the ranker the same per-task minutes the Route costs by, so a "kill it 15 times" task is
		// priced at what it actually takes rather than by a repeat count. Safe before the effort engine is
		// wired: taskMinutes falls back to the empty timing library and the ranker ignores a zero.
		this.ranker = new LowHangingFruitRanker(this.effortLib, this.model, this.difficultyLib,
			caPointsWeight, caDifficultyWeight)
			.withMinutes(this::curatedTaskMinutes);
	}

	/**
	 * Sets the CAs-ranking weights: {@code pointsWeight} (exponent on points) and {@code difficultyWeight}
	 * (how strongly difficulty inflates effort), each 1.0 = neutral. Affects the CAs list only — the Route
	 * has its own time-based cost ({@link #routeCost}). Rebuilds the ranker.
	 */
	public SidePanelViewModelBuilder rankingWeights(double pointsWeight, double difficultyWeight)
	{
		this.caPointsWeight = pointsWeight;
		this.caDifficultyWeight = difficultyWeight;
		rebuildRanker();
		return this;
	}

	/**
	 * Supplies the per-boss data carrying the curated "Endgame access" flag, used to hold raid/group content
	 * back until the player has unlocked the Easy tier. Optional — without it nothing is held back.
	 */
	public SidePanelViewModelBuilder bossDifficulty(BossDifficultyLibrary bossDifficultyLib)
	{
		this.bossDifficultyLib = bossDifficultyLib == null
			? BossDifficultyLibrary.empty() : bossDifficultyLib;
		return this;
	}

	/**
	 * Supplies the curated recommended stats so the "Train next" planner can model what training would open
	 * up. Optional — without it the training section is simply empty.
	 */
	public SidePanelViewModelBuilder recStats(RecStatsLibrary recStatsLib)
	{
		this.recStatsLib = recStatsLib == null ? RecStatsLibrary.empty() : recStatsLib;
		return this;
	}

	/** Sets the Route "Unlock next" weights: bias (favour big vs quick unlocks) + difficulty weighting. */
	public SidePanelViewModelBuilder unlockWeights(double unlockBias, double unlockDifficultyWeight)
	{
		this.unlockBias = unlockBias;
		this.unlockDifficultyWeight = unlockDifficultyWeight;
		return this;
	}

	/**
	 * Tasks the player has barred from the Route. They are dropped from the candidate set before the solve,
	 * so the solver closes the gap with the next-best task instead — or, if nothing can replace them, leaves
	 * the gap open and the Route says what is still needed.
	 */
	public SidePanelViewModelBuilder barred(Set<Integer> taskIds)
	{
		this.barredTasks = taskIds == null || taskIds.isEmpty()
			? Collections.emptySet() : new HashSet<>(taskIds);
		return this;
	}

	/**
	 * Tasks the player has pinned into the Route. They are taken first and their points come off the gap,
	 * then the solver optimally fills whatever is left — so pinning steers the route without abandoning
	 * the optimisation for everything else.
	 */
	public SidePanelViewModelBuilder pinned(Set<Integer> taskIds)
	{
		this.pinnedTasks = taskIds == null || taskIds.isEmpty()
			? Collections.emptySet() : new HashSet<>(taskIds);
		return this;
	}

	/**
	 * Seed for the Route "suggest new" reshuffle: a non-zero value perturbs the path cost so the solver
	 * re-picks a different but still-quick set. 0 = the true optimum.
	 */
	public SidePanelViewModelBuilder routeShuffle(long seed)
	{
		this.routeShuffleSeed = seed;
		return this;
	}

	/** Supplies the curated stats/setup/strategy/items text for the CA-detail drill-in. Optional. */
	public SidePanelViewModelBuilder detail(TaskDetailLibrary detailLib)
	{
		this.detailLib = detailLib == null ? TaskDetailLibrary.empty() : detailLib;
		return this;
	}

	/**
	 * Supplies the effort-engine inputs that drive the synergy "Next session" bundles and the
	 * "Unlock next" suggestions. Optional — when omitted those views are simply empty.
	 *
	 * @param tripOverheadMinutes the fixed per-visit overhead (the clustering-strength dial)
	 */
	public SidePanelViewModelBuilder effortEngine(BossTimingLibrary timing, QuestEffortLibrary questEffort,
		SkillXpLibrary skillXp, CombatExperience experience, PlayerProfile profile, int tripOverheadMinutes)
	{
		this.timingLib = timing == null ? BossTimingLibrary.empty() : timing;
		this.questEffortLib = questEffort == null ? QuestEffortLibrary.empty() : questEffort;
		this.skillXpLib = skillXp == null ? SkillXpLibrary.empty() : skillXp;
		this.experience = experience == null ? CombatExperience.empty() : experience;
		this.profile = profile == null ? PlayerProfile.empty() : profile;
		this.tripOverheadMinutes = Math.max(0, tripOverheadMinutes);
		rebuildRanker(); // timing data has landed; re-bind so the ranker costs by real minutes
		return this;
	}

	/**
	 * Supplies the curated attempt-scaling table (the single place the time model gets its per-type base
	 * attempts, ability curve and competence discounts). Optional — defaults to the built-in constants.
	 */
	public SidePanelViewModelBuilder scaling(ScalingLibrary scaling)
	{
		this.scalingLib = scaling == null ? ScalingLibrary.defaults() : scaling;
		return this;
	}

	/** The time model built on the curated scaling table, shared by the session ranker and CA details. */
	private TaskTimeModel timeModel()
	{
		return TaskTimeModel.standard(scalingLib);
	}

	/** Estimated minutes to finish one task, folding in difficulty + attempts + the player's kill count. */
	/**
	 * Estimated minutes, but only when this boss actually HAS curated timing — 0 otherwise, which tells the
	 * ranker to fall back to its effort model. Without the guard a boss with no timing produced a fallback
	 * figure carrying no real signal, and costing by it quietly flattened the difficulty ordering the
	 * quick-wins list depends on.
	 */
	private int curatedTaskMinutes(CombatAchievement task)
	{
		return timingLib.timingFor(task.monster()) == BossTiming.UNKNOWN ? 0 : taskMinutes(task);
	}

	private int taskMinutes(CombatAchievement task)
	{
		TaskDifficulty diff = difficultyLib.difficultyFor(task.id());
		BossTiming timing = timingLib.timingFor(task.monster());
		return timeModel().estimate(task, timing, experience, diff.difficulty(), diff.attemptsOverride())
			.minutes();
	}

	/**
	 * The Route's per-task cost: estimated minutes, weighted by difficulty so an EASY task is preferred
	 * over a HARD one even when the hard one is quicker per point. Without this the route optimised pure
	 * time and sent a player to Nex (difficulty 7–8) instead of finishing the easy CAs at a boss they were
	 * already at (Chaos Fanatic, difficulty 2–4), because Nex is time-efficient per point. The linear
	 * {@code difficulty/3} factor matches how the CAs list ranks, so the two surfaces now agree.
	 */
	/** Same boss key the route solver groups on: the monster, or the task itself when it has none. */
	private static String routeBossKey(CombatAchievement a)
	{
		return a.hasMonster() ? a.monster() : (" solo:" + a.id());
	}

	private double routeCost(RankedTask rt)
	{
		CombatAchievement task = rt.achievement();
		double minutes = Math.max(1, taskMinutes(task));
		int d = rt.difficulty() == null ? 3 : Math.max(1, rt.difficulty().difficulty());
		double difficultyFactor = d / 3.0; // linear, neutral at difficulty 3 — as the CAs ranker uses
		// Below the task's soft recommended stats -> push it later in the route (attemptable, not advised).
		// Same shared sink as the CAs ranker and the Sessions/Bosses ordering.
		double recStatsFactor = rt.recStatsSinkFactor();
		// "Suggest new" reshuffle: a ±30% cost jitter nudges the solver onto a different but still-quick set.
		double jitter = routeShuffleSeed == 0 ? 1.0 : 0.7 + 0.6 * hashUnit(routeShuffleSeed, task.id());
		return minutes * difficultyFactor * recStatsFactor * jitter;
	}

	/** Deterministic uniform [0,1) hash of (seed, id) via a splitmix64 finaliser (decorrelated seeds). */
	private static double hashUnit(long seed, int id)
	{
		long h = seed * 0x9E3779B97F4A7C15L + (id + 1L) * 0xD1B54A32D192ED03L;
		h ^= h >>> 30;
		h *= 0xBF58476D1CE4E5B9L;
		h ^= h >>> 27;
		h *= 0x94D049BB133111EBL;
		h ^= h >>> 31;
		return (h >>> 11) * 0x1.0p-53;
	}

	/**
	 * @param snapshot     the account progress (or {@link ProgressSnapshot#absent()})
	 * @param signals      live per-task signals
	 * @param explicitTarget optional tier the user is aiming for; null = the next tier to unlock
	 */
	public SidePanelViewModel build(ProgressSnapshot snapshot, SignalsProvider signals,
		AchievementTier explicitTarget)
	{
		List<CombatAchievement> all = lib.all();

		if (snapshot == null || !snapshot.isPresent())
		{
			// Guides (their static parts) are available pre-login; live routes fill in once synced.
			return SidePanelViewModel.loggedOut(buildGuides(all, 0, null));
		}

		int gamePoints = snapshot.gamePoints();
		int totalAvailable = TierMath.totalPointsAvailable(all);

		List<TierProgress> tiers = TierMath.progressByTier(snapshot.completedIds(), all, gamePoints);
		List<SidePanelViewModel.TierRow> tierRows = new ArrayList<>();
		for (TierProgress tp : tiers)
		{
			TierReward reward = rewardLib.forTier(tp.tier());
			tierRows.add(new SidePanelViewModel.TierRow(
				tp.tier().displayName(), tp.completedCount(), tp.totalCount(),
				tp.earnedPointsInTier(), tp.totalPointsInTier(), tp.cumulativeThreshold(),
				tp.unlocked(), tp.pointsRemainingToUnlock(), tp.fullyComplete(),
				reward.headline(), reward.rewards()));
		}

		AchievementTier currentTier = TierMath.currentTierFor(gamePoints, all);
		TierMath.TierGap gap = TierMath.gapToNextTier(gamePoints, all);
		String currentTierName = currentTier == null ? "None" : currentTier.displayName();
		String nextTierName = gap == null ? "" : gap.nextTier().displayName();
		int nextNeeded = gap == null ? 0 : gap.pointsNeeded();
		boolean allUnlocked = gap == null;

		// Rank every incomplete task once. The CAs panel gets the FULL doable-now list (it filters by
		// search + sort and caps rendering itself), so those work over everything, not just a top-N.
		List<RankedTask> rankedIncomplete = ranker.rank(all, snapshot.completedIds(), signals, false);

		// Beginner rule: until the Easy tier is unlocked, hold back raid/group content ("Endgame access") —
		// unless the account is already 70+ combat, in which case it is an established player who simply
		// hasn't started Combat Achievements, and nothing should be held back from them.
		// It is NOT hidden because those tasks are hard — several are genuinely easy mechanics — but because
		// a brand-new account cannot realistically get INTO that content, and recommending it reads as noise.
		// Once Easy is unlocked, everything returns and the normal readiness weighting takes over.
		boolean beginner = gamePoints < TierMath.thresholdFor(AchievementTier.EASY, all)
			&& profile.combatLevel() < BEGINNER_COMBAT_LEVEL;
		List<RankedTask> recommendable = beginner ? withoutGated(rankedIncomplete) : rankedIncomplete;

		List<SidePanelViewModel.TaskRow> quickWins = new ArrayList<>();
		for (RankedTask rt : recommendable)
		{
			if (rt.doableNow())
			{
				quickWins.add(toTaskRow(rt));
			}
		}

		// Unlock suggestions drive both the "Unlock next" list and the locked CAs shown in the Route.
		Map<Integer, CombatAchievement> byId = new HashMap<>();
		for (CombatAchievement a : all)
		{
			byId.put(a.id(), a);
		}
		List<UnlockSuggestion> unlockSuggestions = readinessRanked(
			new UnlockPlanner(questEffortLib, skillXpLib)
				.plan(all, snapshot.completedIds(), effortLib, profile, difficultyLib, unlockBias,
					unlockDifficultyWeight, recStatsLib),
			byId, signals);
		List<SidePanelViewModel.CaDetail> lockedRouteCas = lockedRouteCas(unlockSuggestions, all, signals, beginner);

		SidePanelViewModel.PathView path = buildPath(all, gamePoints, gap, explicitTarget,
			recommendable, lockedRouteCas);

		List<SidePanelViewModel.SessionView> sessions = buildSessions(recommendable);
		List<SidePanelViewModel.UnlockView> unlocks = buildUnlocks(unlockSuggestions, byId);
		List<SidePanelViewModel.TrainingView> trainings = buildTrainings(
			beginner ? withoutGatedTasks(all) : all, snapshot.completedIds());
		// Deliberately UNGATED, unlike the other surfaces: the directory is where bosses are looked up
		// (search, quest-page jumps, "View boss"), so hiding endgame content for a beginner made those
		// links dead-end — the Colosseum was simply not findable. The readiness sink on each row keeps
		// raid content out of a beginner's top Recommended rows; it just no longer erases the pages.
		List<SidePanelViewModel.BossRow> bosses = buildBossDirectory(rankedIncomplete, all,
			snapshot.completedIds());

		return SidePanelViewModel.ready(lib.version(), gamePoints, totalAvailable,
			snapshot.completedCount(), lib.taskCount(), currentTierName, nextTierName, nextNeeded,
			allUnlocked, snapshot.datasetLooksStale(), tierRows, quickWins, path,
			buildGuides(all, gamePoints, rankedIncomplete), sessions, unlocks, trainings, bosses,
			snapshot.isSample());
	}

	/**
	 * Builds the guide views. When a guide has a target tier and the player is synced
	 * ({@code rankedIncomplete != null}), its live optimal route to that tier is resolved too.
	 */
	private List<SidePanelViewModel.GuideView> buildGuides(List<CombatAchievement> all,
		int gamePoints, List<RankedTask> rankedIncomplete)
	{
		List<SidePanelViewModel.GuideView> views = new ArrayList<>();
		for (Guide guide : guideLib.all())
		{
			List<String> tips = new ArrayList<>();
			for (GuideStep step : guide.steps())
			{
				String note = step.note();
				if (step.hasTask())
				{
					CombatAchievement task = lib.byId(step.taskId());
					if (task != null)
					{
						note = task.name() + " — " + note;
					}
				}
				tips.add(note);
			}

			SidePanelViewModel.PathView route = null;
			if (guide.targetTier() != null && rankedIncomplete != null)
			{
				route = buildPath(all, gamePoints, null, guide.targetTier(), rankedIncomplete,
					java.util.Collections.<SidePanelViewModel.CaDetail>emptyList());
			}

			views.add(new SidePanelViewModel.GuideView(guide.id(), guide.title(), guide.author(),
				guide.summary(), guide.videoUrl(),
				guide.targetTier() == null ? "" : guide.targetTier().displayName(),
				guide.tags(), tips, route));
		}
		return views;
	}

	private SidePanelViewModel.PathView buildPath(List<CombatAchievement> all, int gamePoints,
		TierMath.TierGap gap, AchievementTier explicitTarget, List<RankedTask> rankedIncomplete,
		List<SidePanelViewModel.CaDetail> lockedCas)
	{
		AchievementTier target = explicitTarget != null
			? explicitTarget
			: (gap != null ? gap.nextTier() : AchievementTier.GRANDMASTER);

		PathPlan plan;
		boolean trainFirst = false;
		List<RankedTask> pinnedSteps = Collections.emptyList();
		// The gap the PLAYER still has to the tier. Pinning shrinks what the solver has left to cover, but
		// it must never change the "N pts to go" the panel shows: that is a fact about the account, not
		// about which tasks are pinned, and watching it drop as you pin reads as if pinning earned points.
		int trueGap = 0;
		if (target == AchievementTier.GRANDMASTER)
		{
			// GM additionally requires completing every task, so the path is all incomplete tasks.
			plan = solver.solveCompleteAll(target, rankedIncomplete, this::routeCost);
			trueGap = plan.pointsGap();
		}
		else
		{
			int threshold = TierMath.thresholdFor(target, all);
			int pointsGap = Math.max(0, threshold - gamePoints);
			trueGap = pointsGap;
			List<RankedTask> doableNow = new ArrayList<>();
			List<RankedTask> ready = new ArrayList<>();
			// Pinned tasks are taken whatever the solver would have chosen. They are honoured even when the
			// account is below their recommended stats: the player asked for this one specifically, and
			// second-guessing an explicit choice is worse than letting them take a hard task early.
			List<RankedTask> forced = new ArrayList<>();
			int forcedPoints = 0;
			int doablePoints = 0;
			int readyPoints = 0;
			for (RankedTask rt : rankedIncomplete)
			{
				if (pinnedTasks.contains(rt.achievement().id()) && rt.doableNow())
				{
					forced.add(rt);
					forcedPoints += rt.achievement().points();
					continue;
				}
				// Barred tasks are ones the player has explicitly said they do not want to do. Dropping them
				// before the solve (rather than filtering the result) is what lets the next-best task take
				// the freed slot; if nothing is left to take it, the gap simply stays open and the Route
				// falls back to Train next / "not enough doable tasks", which is the honest answer.
				if (!rt.doableNow() || barredTasks.contains(rt.achievement().id()))
				{
					continue;
				}
				doableNow.add(rt);
				doablePoints += rt.achievement().points();
				if (isReadyFor(rt))
				{
					ready.add(rt);
					readyPoints += rt.achievement().points();
				}
			}

			// The route is built from what the player is READY for, not merely what is ungated. Without this a
			// level-3 was routed at Dagannoth Kings: those tasks have no hard gate, so they counted as doable
			// and the solver happily used them to close the gap 80 levels early. Stopping short and handing
			// over to "Train next" is the honest answer — see the trainFirst flag.
			// Pinned points already count toward the tier, so only the remainder still needs solving.
			int remainingGap = Math.max(0, pointsGap - forcedPoints);
			trainFirst = readyPoints + forcedPoints < pointsGap && doablePoints + forcedPoints >= pointsGap;
			// Quickest path to the tier, boss-aware: a fixed trip overhead per boss makes the solver keep you
			// at a boss (do several CAs there) rather than scatter one-CA visits across the game and close the
			// last gap at a far-off boss. tripOverheadMinutes is the clustering-strength dial.
			plan = solver.solveClustered(target, remainingGap, ready, this::routeCost, tripOverheadMinutes);
			pinnedSteps = forced;
		}

		// Pinned tasks sit wherever they naturally belong, not bolted to the front. They are merged with
		// the solved set and the whole lot is ordered the way the solver orders its own output — grouped by
		// boss, cheapest boss first — so a pinned CA lands beside its boss-mates instead of dragging its
		// boss to the top of the route.
		List<CombatAchievement> ordered = new ArrayList<>();
		Map<String, Double> bossTotal = new LinkedHashMap<>();
		Map<Integer, Double> costById = new HashMap<>();
		List<RankedTask> merged = new ArrayList<>(pinnedSteps);
		for (PathStep step : plan.steps())
		{
			for (RankedTask rt : rankedIncomplete)
			{
				if (rt.achievement().id() == step.achievement().id())
				{
					merged.add(rt);
					break;
				}
			}
		}
		for (RankedTask rt : merged)
		{
			double c = routeCost(rt);
			costById.put(rt.achievement().id(), c);
			bossTotal.merge(routeBossKey(rt.achievement()), c, Double::sum);
		}
		merged.sort(Comparator
			.comparingDouble((RankedTask rt) -> bossTotal.getOrDefault(routeBossKey(rt.achievement()), 0.0))
			.thenComparing(rt -> routeBossKey(rt.achievement()))
			.thenComparingDouble(rt -> costById.getOrDefault(rt.achievement().id(), 0.0))
			.thenComparingInt(rt -> rt.achievement().id()));
		merged.forEach(rt -> ordered.add(rt.achievement()));

		List<SidePanelViewModel.PathRow> steps = new ArrayList<>();
		int running = 0;
		for (CombatAchievement a : ordered)
		{
			running += a.points();
			steps.add(new SidePanelViewModel.PathRow(a.id(), a.name(), a.tier().displayName(),
				a.points(), running, a.wikiUrl(),
				videoLib.bestGuideUrl(a.id(), a.guideSearchUrl()), buildCaDetail(a, true, "")));
		}
		// The barred pile, so the panel can list what was set aside and offer it back. Drawn from the
		// incomplete tasks, so anything since completed drops off the list by itself.
		List<SidePanelViewModel.CaDetail> barredCas = new ArrayList<>();
		if (!barredTasks.isEmpty())
		{
			for (RankedTask rt : rankedIncomplete)
			{
				if (barredTasks.contains(rt.achievement().id()))
				{
					barredCas.add(buildCaDetail(rt.achievement(), rt.doableNow(), rt.lockReason()));
				}
			}
		}

		return new SidePanelViewModel.PathView(target.displayName(), trueGap,
			plan.reachable(), plan.alreadyUnlocked(), steps, rewardLib.forTier(target).headline(),
			lockedCas, trainFirst, barredCas);
	}

	/**
	 * Whether the account is close enough to a task's recommended stats to be sent there. Uses the WORST
	 * single-stat gap on {@link TrainingPlanner#VIABLE_WORST_GAP} — the same "ready" line Train next
	 * counts by. With no recommended-stats data (or no profile) the gap is 0, so nothing is filtered and
	 * callers that never supplied them behave exactly as before.
	 */
	private boolean isReadyFor(RankedTask rt)
	{
		return profile.worstShortfall(recStatsLib.softFor(rt.achievement().id()))
			<= TrainingPlanner.VIABLE_WORST_GAP;
	}

	/**
	 * The CAs the top recommended unlocks would open — built as LOCKED detail cards (with a "needs
	 * &lt;quest&gt;" reason) so the Route can list them in red beneath the doable steps. Deduped by id,
	 * bounded so the Route stays readable.
	 */
	private List<SidePanelViewModel.CaDetail> lockedRouteCas(List<UnlockSuggestion> unlockSuggestions,
		List<CombatAchievement> all, SignalsProvider signals, boolean beginner)
	{
		Map<Integer, CombatAchievement> byId = new java.util.HashMap<>();
		for (CombatAchievement a : all)
		{
			byId.put(a.id(), a);
		}
		SignalsProvider sig = signals == null ? SignalsProvider.defaults() : signals;

		// Every CA the top unlock suggestions would open, each tagged with how far below its recommended
		// stats the player is (the same distance the CAs list weights by).
		List<LockedCandidate> candidates = new ArrayList<>();
		java.util.Set<Integer> seen = new java.util.HashSet<>();
		int quests = 0;
		for (UnlockSuggestion s : unlockSuggestions)
		{
			if (quests++ >= UNLOCKS_LIMIT)
			{
				break;
			}
			// The quest's time amortised across the CAs it opens — added to each CA's own time so the
			// Route can slot "quest + CA" in by its true total time vs a harder doable CA.
			int amortizedQuestMinutes = s.totalMinutes() / Math.max(1, s.unlockedTaskIds().size());
			for (int id : s.unlockedTaskIds())
			{
				CombatAchievement task = byId.get(id);
				if (task != null && beginner && bossDifficultyLib.isEndgameAccess(task.monster()))
				{
					continue; // don't dangle raid content in front of a pre-Easy-tier account
				}
				if (task != null && seen.add(id))
				{
					candidates.add(new LockedCandidate(task, s.questName(), amortizedQuestMinutes,
						sig.signalsFor(id).recStatsShortfall()));
				}
			}
		}

		// Weight by readiness the same way the CAs list does — points ÷ the soft-stat sink factor — so
		// distance competes against value. A level-3 is hundreds of levels short of Theatre of Blood, so its
		// ×-huge sink crushes ToB's value and it sinks past the display cap; a near-ready main's ×~1 sink
		// leaves ToB's value intact so it stays. Not a hard wall, just the distance-weight applied here too.
		candidates.sort(Comparator.comparingDouble((LockedCandidate c) -> readinessValue(c)).reversed()
			.thenComparingInt(c -> c.task.id()));

		List<SidePanelViewModel.CaDetail> out = new ArrayList<>();
		for (LockedCandidate c : candidates)
		{
			if (out.size() >= LOCKED_ROUTE_CAS_LIMIT)
			{
				break;
			}
			out.add(buildCaDetail(c.task, false, "needs " + c.questName, c.amortizedMinutes));
		}
		return out;
	}

	/**
	 * Re-orders the unlock suggestions by how much of the value they open this player can actually reach.
	 * An unlock is only worth suggesting for the points you can earn — so a level-3's Priest in Peril (which
	 * opens Barrows, Theatre of Blood, the Nightmare… all far out of reach) drops down the list, taking those
	 * CAs out of the route with it, while for a near-ready main it stays near the top. Layers the readiness
	 * factor on the planner's own score so its difficulty/time/bias tuning is preserved.
	 */
	private List<UnlockSuggestion> readinessRanked(List<UnlockSuggestion> suggestions,
		Map<Integer, CombatAchievement> byId, SignalsProvider signals)
	{
		SignalsProvider sig = signals == null ? SignalsProvider.defaults() : signals;
		List<UnlockSuggestion> ranked = new ArrayList<>(suggestions);
		ranked.sort(Comparator.comparingDouble(
			(UnlockSuggestion s) -> s.score() * readinessFactor(s, byId, sig)).reversed());
		return ranked;
	}

	/** Fraction of a suggestion's unlocked points the player is ready for: Σ(points/sink) ÷ Σ(points), in (0,1]. */
	private static double readinessFactor(UnlockSuggestion s, Map<Integer, CombatAchievement> byId,
		SignalsProvider sig)
	{
		double weighted = 0;
		double raw = 0;
		for (int id : s.unlockedTaskIds())
		{
			CombatAchievement t = byId.get(id);
			if (t != null)
			{
				int pts = Math.max(1, t.points());
				raw += pts;
				weighted += pts / RankedTask.recStatsSinkFactor(sig.signalsFor(id).recStatsShortfall());
			}
		}
		return raw <= 0 ? 1.0 : weighted / raw;
	}

	/** Points discounted by how far the player is below the CA's recommended stats (higher = show sooner). */
	private static double readinessValue(LockedCandidate c)
	{
		return Math.max(1, c.task.points()) / RankedTask.recStatsSinkFactor(c.shortfall);
	}

	/** A CA a suggested unlock would open, tagged with the player's readiness (soft-stat shortfall). */
	private static final class LockedCandidate
	{
		private final CombatAchievement task;
		private final String questName;
		private final int amortizedMinutes;
		private final int shortfall;

		private LockedCandidate(CombatAchievement task, String questName, int amortizedMinutes, int shortfall)
		{
			this.task = task;
			this.questName = questName;
			this.amortizedMinutes = amortizedMinutes;
			this.shortfall = shortfall;
		}
	}

	/**
	 * The full Bosses directory: every boss/activity with an incomplete CA, its incomplete CAs split into
	 * doable and locked. Bosses with no doable CA are flagged locked (greyed in the panel). Ordered
	 * doable-first by projected (doable) points.
	 */
	private List<SidePanelViewModel.BossRow> buildBossDirectory(List<RankedTask> rankedIncomplete,
		List<CombatAchievement> all, java.util.Set<Integer> completedIds)
	{
		// Completed CAs never reach the ranker (it only ranks what is left), so they are gathered here
		// straight from the library. A boss whose CAs are ALL done still will not appear: the directory
		// lists bosses with something outstanding, and that is deliberate.
		Map<String, List<SidePanelViewModel.CaDetail>> completedByBoss = new LinkedHashMap<>();
		for (CombatAchievement a : all)
		{
			if (a.hasMonster() && completedIds.contains(a.id()))
			{
				completedByBoss.computeIfAbsent(a.monster(), k -> new ArrayList<>())
					.add(buildCaDetail(a, true, ""));
			}
		}
		Map<String, List<RankedTask>> byBoss = new LinkedHashMap<>();
		for (RankedTask rt : rankedIncomplete)
		{
			CombatAchievement a = rt.achievement();
			if (a.hasMonster())
			{
				byBoss.computeIfAbsent(a.monster(), k -> new ArrayList<>()).add(rt);
			}
		}

		List<SidePanelViewModel.BossRow> rows = new ArrayList<>();
		for (Map.Entry<String, List<RankedTask>> e : byBoss.entrySet())
		{
			List<SidePanelViewModel.CaDetail> doable = new ArrayList<>();
			List<SidePanelViewModel.CaDetail> locked = new ArrayList<>();
			List<Double> doableSinks = new ArrayList<>();
			int projected = 0;
			String stats = "";
			for (RankedTask rt : e.getValue())
			{
				CombatAchievement a = rt.achievement();
				SidePanelViewModel.CaDetail d = buildCaDetail(a, rt.doableNow(), rt.lockReason());
				if (stats.isEmpty() && !d.stats.isEmpty())
				{
					stats = d.stats; // representative recommended stats for the boss
				}
				if (rt.doableNow())
				{
					doable.add(d);
					doableSinks.add(rt.recStatsSinkFactor());
					projected += a.points();
				}
				else
				{
					locked.add(d);
				}
			}
			rows.add(new SidePanelViewModel.BossRow(e.getKey(), projected, doable.size(), locked.size(),
				doable.isEmpty(), stats, doable, locked, medianSink(doableSinks),
				completedByBoss.getOrDefault(e.getKey(), Collections.emptyList())));
		}

		// The Bosses tab is an honest directory: every boss with an incomplete CA, ordered doable-first by
		// the points actually available there. This default order (and the "Most points" sort) is
		// deliberately NOT sunk by rec-stats — the sort key would diverge from the shown points, and a
		// 29-CA raid legitimately holds the most points. Readiness rides on the row instead
		// ({@code readinessSink}) so only the opinionated "Recommended" sort uses it.
		rows.sort(Comparator
			.comparing((SidePanelViewModel.BossRow b) -> b.locked) // doable bosses first
			.thenComparing(Comparator.comparingInt((SidePanelViewModel.BossRow b) -> b.projectedPoints).reversed())
			.thenComparing(b -> b.monster));
		return rows;
	}

	/**
	 * A boss's readiness penalty: the MEDIAN rec-stats sink across its doable CAs. Median rather than min
	 * because several bosses carry one outlier CA with no recommended stats at all (Chambers of Xeric's
	 * "Playing with Lasers" reads distance 0 for a level-3), and a min would let that one row declare the
	 * whole raid ready. 1.0 = the account is up to it.
	 */
	private static double medianSink(List<Double> sinks)
	{
		if (sinks == null || sinks.isEmpty())
		{
			return 1.0;
		}
		List<Double> sorted = new ArrayList<>(sinks);
		java.util.Collections.sort(sorted);
		int mid = sorted.size() / 2;
		double median = sorted.size() % 2 == 1
			? sorted.get(mid)
			: (sorted.get(mid - 1) + sorted.get(mid)) / 2.0;
		return Math.max(1.0, median);
	}

	/** Synergy-ranked boss sessions from the player's doable, incomplete tasks. */
	private List<SidePanelViewModel.SessionView> buildSessions(List<RankedTask> rankedIncomplete)
	{
		List<CombatAchievement> doable = new ArrayList<>();
		Map<Integer, Integer> shortfallById = new HashMap<>();
		for (RankedTask rt : rankedIncomplete)
		{
			if (rt.doableNow())
			{
				doable.add(rt.achievement());
				shortfallById.put(rt.achievement().id(), rt.recStatsShortfall());
			}
		}
		SynergyRanker ranker = new SynergyRanker(timeModel(), tripOverheadMinutes);
		List<BossSession> ranked = new ArrayList<>(ranker.rank(doable, timingLib, experience, difficultyLib));

		// Re-order by a rec-stats-adjusted score: divide each bundle's points/hour by its points-weighted
		// soft-sink factor, so a fresh account isn't suggested an endgame boss (CoX/ToB) as a top "next
		// session" just because it can technically enter it. Applied before the top-N cut below.
		ranked.sort(Comparator
			.comparingDouble((BossSession s) ->
				s.pointsPerHour() / sessionRecStatsSink(s, shortfallById)).reversed()
			.thenComparing(BossSession::monster));

		List<SidePanelViewModel.SessionView> views = new ArrayList<>();
		for (BossSession session : ranked)
		{
			if (views.size() >= SESSIONS_LIMIT)
			{
				break;
			}
			List<SidePanelViewModel.SessionTaskView> tasks = new ArrayList<>();
			for (BossSession.Item item : session.items())
			{
				CombatAchievement a = item.task();
				TaskTimeModel.Estimate est = item.estimate();
				String progress = est.hasPartialProgress()
					? Math.min(est.currentKc(), est.requiredKills()) + " / " + est.requiredKills() + " kills"
					: "";
				tasks.add(new SidePanelViewModel.SessionTaskView(a.id(), a.name(), a.tier().displayName(),
					a.points(), item.sessionMinutes(), progress, a.wikiUrl(),
					videoLib.bestGuideUrl(a.id(), a.guideSearchUrl()), buildCaDetail(a, true, "")));
			}
			views.add(new SidePanelViewModel.SessionView(session.monster(), session.taskCount(),
				session.totalPoints(), session.totalMinutes(),
				(int) Math.round(session.pointsPerHour()), tasks));
		}
		return views;
	}

	/**
	 * A boss session's soft rec-stats sink: the points-weighted average of its tasks' sink factors (1.0 when
	 * the player meets every task's recommended stats). Sinks a bundle in proportion to how much of its
	 * value sits behind stats the player is short of.
	 */
	private static double sessionRecStatsSink(BossSession session, Map<Integer, Integer> shortfallById)
	{
		double weighted = 0;
		double points = 0;
		for (BossSession.Item item : session.items())
		{
			int pts = Math.max(0, item.task().points());
			int shortfall = shortfallById.getOrDefault(item.task().id(), 0);
			weighted += pts * RankedTask.recStatsSinkFactor(shortfall);
			points += pts;
		}
		return points <= 0 ? 1.0 : weighted / points;
	}

	/** Drops ranked tasks whose activity is flagged "Endgame access" (raids / coordinated group content). */
	private List<RankedTask> withoutGated(List<RankedTask> tasks)
	{
		List<RankedTask> out = new ArrayList<>();
		for (RankedTask rt : tasks)
		{
			if (!bossDifficultyLib.isEndgameAccess(rt.achievement().monster()))
			{
				out.add(rt);
			}
		}
		return out;
	}

	/** Same filter over raw tasks, for the training planner's view of what is worth opening up. */
	private List<CombatAchievement> withoutGatedTasks(List<CombatAchievement> tasks)
	{
		List<CombatAchievement> out = new ArrayList<>();
		for (CombatAchievement a : tasks)
		{
			if (!bossDifficultyLib.isEndgameAccess(a.monster()))
			{
				out.add(a);
			}
		}
		return out;
	}

	/**
	 * "Train next": skill goals that would open up CAs, for a player held back by levels. Empty for anyone
	 * who already meets what they need, so the section simply disappears for an established account.
	 */
	private List<SidePanelViewModel.TrainingView> buildTrainings(List<CombatAchievement> all,
		java.util.Set<Integer> completedIds)
	{
		List<SidePanelViewModel.TrainingView> views = new ArrayList<>();
		for (TrainingSuggestion s : new TrainingPlanner(skillXpLib, bossDifficultyLib)
			.plan(all, completedIds, effortLib, recStatsLib, profile, TRAININGS_LIMIT))
		{
			views.add(new SidePanelViewModel.TrainingView(s.label(), s.unlockedTaskCount(),
				s.unlockedPoints(), s.trainingMinutes(), s.unlocksHint(), s.isCalendarTime(),
				s.isToward()));
		}
		return views;
	}

	/** "Unlock next" quest suggestions, best first, from the already-computed suggestions. */
	private List<SidePanelViewModel.UnlockView> buildUnlocks(List<UnlockSuggestion> suggestions,
		Map<Integer, CombatAchievement> byId)
	{
		// A recommendation here means "do this quest, then go collect". Two ways a quest fails that:
		// the player is nowhere near able to DO it (chain skills past the ready line — a level-3 offered
		// Master questlines purely on prize size), or they could do it but could USE nothing it opens
		// (all-40s offered A Kingdom Divided, whose Yama CAs want 90s — the quest was near, the prize
		// was not). Both judged on the same ready line the Route uses. The filters relax in stages so
		// the section never empties out (the standing ruling: this is the one place that answers
		// "what quest next"): full recommendations, else near quests whose prize is still ahead of the
		// account, else everything. Train next raises the stats; a dropped quest resurfaces here on its
		// own the moment its prize comes within reach.
		List<UnlockSuggestion> withinReach = new ArrayList<>();
		List<UnlockSuggestion> collectable = new ArrayList<>();
		for (UnlockSuggestion s : suggestions)
		{
			if (s.worstSkillShortfall() <= TrainingPlanner.VIABLE_WORST_GAP)
			{
				withinReach.add(s);
				if (s.reachableTaskCount() > 0)
				{
					collectable.add(s);
				}
			}
		}
		List<UnlockSuggestion> shown = !collectable.isEmpty() ? collectable
			: !withinReach.isEmpty() ? withinReach : suggestions;

		List<SidePanelViewModel.UnlockView> views = new ArrayList<>();
		for (UnlockSuggestion s : shown)
		{
			if (views.size() >= UNLOCKS_LIMIT)
			{
				break;
			}
			// The card's drill-in page: the actual CAs behind "unlocks N CAs", quickest first, each
			// opening its own CA detail — the same journey a CA card offers.
			List<SidePanelViewModel.CaDetail> unlockedCas = new ArrayList<>();
			for (int id : s.unlockedTaskIds())
			{
				CombatAchievement task = byId.get(id);
				if (task != null)
				{
					unlockedCas.add(buildCaDetail(task, false, "needs " + s.questName()));
				}
			}
			unlockedCas.sort(Comparator.comparingInt(SidePanelViewModel.CaDetail::totalMinutes)
				.thenComparingInt(d -> d.id));
			// The card still shows what the quest OPENS in full — a quest is permanent progress, and the
			// numbers should be the honest prize even when only part of it is collectable today.
			views.add(new SidePanelViewModel.UnlockView(s.questName(), s.difficulty(),
				s.unlockedTaskCount(), s.unlockedPoints(), s.totalMinutes(),
				String.join(", ", s.remainingPrerequisites()), String.join(", ", s.unmetSkills()),
				unlockedCas, s.worstSkillShortfall(), s.remainingPrerequisites(), s.unmetSkills(),
				questEffortLib.questFor(s.questName()).wikiUrl()));
		}
		return views;
	}

	private SidePanelViewModel.TaskRow toTaskRow(RankedTask rt)
	{
		CombatAchievement a = rt.achievement();
		return new SidePanelViewModel.TaskRow(a.id(), a.name(), a.description(), a.tier().displayName(),
			a.monster(), a.points(), rt.difficulty().difficulty(), rt.difficulty().reason(), rt.rationale(),
			rt.lockReason(), rt.doableNow(), rt.curated(),
			videoLib.hasCuratedGuide(a.id()), a.wikiUrl(), videoLib.bestGuideUrl(a.id(), a.guideSearchUrl()),
			buildCaDetail(a, rt.doableNow(), rt.lockReason()));
	}

	private SidePanelViewModel.CaDetail buildCaDetail(CombatAchievement task, boolean doableNow,
		String lockReason)
	{
		return buildCaDetail(task, doableNow, lockReason, 0);
	}

	/** Assembles the full CA-detail view for a task: itemised requirements (met/unmet vs the player),
	 *  Difficulty breakdown, effort estimate, and the curated stats/setup/strategy/items. {@code
	 *  extraMinutes} is the amortised unlock/quest cost for locked CAs (0 for doable ones). */
	private SidePanelViewModel.CaDetail buildCaDetail(CombatAchievement task, boolean doableNow,
		String lockReason, int extraMinutes)
	{
		TaskEffortData effort = effortLib.effortFor(task.id());
		TaskDifficulty diff = difficultyLib.difficultyFor(task.id());
		TaskDetail det = detailLib.detailFor(task.id());
		BossTiming timing = timingLib.timingFor(task.monster());
		TaskTimeModel.Estimate est =
			timeModel().estimate(task, timing, experience, diff.difficulty(), diff.attemptsOverride());
		int mins = est.minutes();
		int pph = mins > 0 ? (int) Math.round(task.points() * 60.0 / mins) : 0;

		List<SidePanelViewModel.CaReq> reqs = new ArrayList<>();
		for (Map.Entry<String, Integer> e : effort.levelReqs().entrySet())
		{
			int have = profile.levelOf(e.getKey());
			boolean met = have >= e.getValue();
			reqs.add(new SidePanelViewModel.CaReq(e.getValue() + " " + e.getKey(), met,
				met ? "" : "you have " + have));
		}
		for (QuestRequirement qr : effort.questReqs())
		{
			if (qr.quest().isEmpty())
			{
				continue;
			}
			boolean met = qr.startedSuffices() ? profile.hasStarted(qr.quest()) : profile.hasCompleted(qr.quest());
			reqs.add(new SidePanelViewModel.CaReq(qr.quest(), met, ""));
		}

		// The same ready line the Route builds its path from, carried onto the card so lists can group by it.
		boolean withinReach = profile.worstShortfall(recStatsLib.softFor(task.id()))
			<= TrainingPlanner.VIABLE_WORST_GAP;

		return new SidePanelViewModel.CaDetail(task.id(), task.name(), task.monster(),
			task.tier().displayName(), task.type() == null ? "" : task.type().displayName(), task.points(),
			task.description(), doableNow, lockReason, diff.difficulty(), diff.bossDifficulty(), diff.bump(),
			diff.reason(), mins, pph, reqs, det.stats(), det.setup(), det.strategy(), det.items(),
			task.wikiUrl(), videoLib.bestGuideUrl(task.id(), task.guideSearchUrl()), videoLib.hasCuratedGuide(task.id()),
			extraMinutes, withinReach);
	}
}

package com.pluginideahub.combatachievements.core.video;

import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import com.pluginideahub.combatachievements.core.data.BundledJson;
import java.io.InputStream;
import java.util.ArrayList;
import java.util.Collections;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;

/**
 * Loads curated per-task guide videos ({@code video_guides.json}, keyed by task id). Sparse and
 * decoupled: any task without a curated entry falls back to the search link bundled with the task
 * itself, so the panel always offers a one-click guide. Pure Java (Gson only). See docs/DESIGN.md §6d.
 */
public final class VideoGuideLibrary
{
	private static final String BUNDLED_RESOURCE =
		"/com/pluginideahub/combatachievements/video_guides.json";

	private final Map<Integer, List<String>> byId;

	private VideoGuideLibrary(Map<Integer, List<String>> byId)
	{
		this.byId = byId;
	}

	public static VideoGuideLibrary empty()
	{
		return new VideoGuideLibrary(new LinkedHashMap<>());
	}

	/** Loads the bundled curated guides; returns {@link #empty()} if absent or unreadable. */
	public static VideoGuideLibrary loadBundled()
	{
		return fromRoot(BundledJson.readBundled(VideoGuideLibrary.class, BUNDLED_RESOURCE));
	}

	/** Loads from a stream; returns {@link #empty()} on malformed input. */
	public static VideoGuideLibrary load(InputStream in)
	{
		return fromRoot(BundledJson.read(in));
	}

	private static VideoGuideLibrary fromRoot(JsonObject root)
	{
		if (root == null)
		{
			return empty();
		}
		// The root object IS the id → urls map (no wrapping member); a value may be a single url
		// string or an array of them.
		Map<Integer, List<String>> map = new LinkedHashMap<>();
		for (Map.Entry<String, JsonElement> entry : root.entrySet())
		{
			Integer id = tryParseId(entry.getKey());
			if (id == null)
			{
				continue;
			}
			List<String> urls = new ArrayList<>();
			JsonElement value = entry.getValue();
			if (value.isJsonArray())
			{
				for (JsonElement url : value.getAsJsonArray())
				{
					addUrl(urls, url);
				}
			}
			else
			{
				addUrl(urls, value);
			}
			if (!urls.isEmpty())
			{
				map.put(id, Collections.unmodifiableList(urls));
			}
		}
		return new VideoGuideLibrary(map);
	}

	private static void addUrl(List<String> urls, JsonElement el)
	{
		if (el == null || el.isJsonNull())
		{
			return;
		}
		try
		{
			String s = el.getAsString();
			if (s != null && !s.trim().isEmpty())
			{
				urls.add(s.trim());
			}
		}
		catch (RuntimeException ignored)
		{
			// skip malformed url entry
		}
	}

	private static Integer tryParseId(String key)
	{
		try
		{
			return Integer.parseInt(key.trim());
		}
		catch (NumberFormatException ex)
		{
			return null;
		}
	}

	public int curatedCount()
	{
		return byId.size();
	}

	public boolean hasCuratedGuide(int taskId)
	{
		List<String> urls = byId.get(taskId);
		return urls != null && !urls.isEmpty();
	}

	/** Curated URLs for a task (empty if none). */
	public List<String> guidesFor(int taskId)
	{
		return byId.getOrDefault(taskId, Collections.emptyList());
	}

	/**
	 * The best guide URL for a task: the first curated link if present, otherwise the search link the
	 * dataset ships for that task.
	 */
	public String bestGuideUrl(int taskId, String searchUrl)
	{
		List<String> urls = byId.get(taskId);
		if (urls != null && !urls.isEmpty())
		{
			return urls.get(0);
		}
		return searchUrl == null ? "" : searchUrl;
	}
}

package com.pluginideahub.combatachievements.ui;

import java.awt.Color;
import java.awt.Component;
import java.awt.Cursor;
import java.awt.Dimension;
import javax.swing.BorderFactory;
import javax.swing.JButton;
import javax.swing.JComponent;
import javax.swing.JLabel;
import javax.swing.JPanel;
import net.runelite.client.ui.ColorScheme;
import net.runelite.client.ui.FontManager;
import net.runelite.client.util.LinkBrowser;

/**
 * Stateless building blocks shared by the side panel's cards: wrapped html labels, full-width
 * sizing, spacers, click/hover wiring, themed colour lookups and the small link/action buttons.
 */
public final class CardKit
{
	private CardKit()
	{
	}

	/**
	 * An html JLabel that truly wraps at {@code width} real pixels. Swing's CSS treats px as scaled
	 * units (~1.3x with this look-and-feel), so a hard-coded {@code body width} style lays out wider
	 * than asked and the text clips at the panel edge — the Route's unlock cards lost their last
	 * prerequisite this way, invisibly, for as long as they have existed. This measures the html view's
	 * actual span and re-asks for a proportionally smaller CSS width, so the real span lands on
	 * {@code width} whatever the scale factor is, then pins the label to the wrapped height.
	 */
	public static JLabel wrappedHtmlLabel(String innerHtml, int width)
	{
		JLabel label = new JLabel(htmlAt(innerHtml, width));
		javax.swing.text.View view = htmlView(label);
		if (view != null)
		{
			float natural = view.getPreferredSpan(javax.swing.text.View.X_AXIS);
			if (natural > width)
			{
				label.setText(htmlAt(innerHtml, Math.max(50, (int) (width * (width / natural)))));
				view = htmlView(label);
			}
			view.setSize(width, 0);
			int height = (int) Math.ceil(view.getPreferredSpan(javax.swing.text.View.Y_AXIS));
			label.setPreferredSize(new Dimension(width, height));
			label.setMaximumSize(new Dimension(width, height));
		}
		return label;
	}

	public static String htmlAt(String innerHtml, int cssWidth)
	{
		return "<html><body style='width:" + cssWidth + "px'>" + innerHtml + "</body></html>";
	}

	public static javax.swing.text.View htmlView(JLabel label)
	{
		return (javax.swing.text.View) label.getClientProperty(javax.swing.plaf.basic.BasicHTML.propertyKey);
	}

	public static <T extends JPanel> T fullWidth(T panel)
	{
		panel.setAlignmentX(Component.LEFT_ALIGNMENT);
		panel.setMaximumSize(new Dimension(Integer.MAX_VALUE, panel.getPreferredSize().height));
		return panel;
	}

	public static JLabel fullWidth(JLabel label)
	{
		label.setAlignmentX(Component.LEFT_ALIGNMENT);
		return label;
	}

	public static JPanel spacer()
	{
		JPanel p = new JPanel();
		p.setOpaque(false);
		p.setPreferredSize(new Dimension(1, 6));
		p.setMaximumSize(new Dimension(Integer.MAX_VALUE, 6));
		return p;
	}

	public static String escape(String s)
	{
		if (s == null)
		{
			return "";
		}
		return s.replace("&", "&amp;").replace("<", "&lt;").replace(">", "&gt;");
	}

	/** Adds a click handler + hand cursor to a card, without disturbing its inner link buttons. */
	public static void onClick(JComponent c, Runnable action)
	{
		c.setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));
		c.addMouseListener(new java.awt.event.MouseAdapter()
		{
			@Override
			public void mouseClicked(java.awt.event.MouseEvent e)
			{
				action.run();
			}
		});
	}

	public static void addHover(JComponent c, Color base, Color hover)
	{
		c.addMouseListener(new java.awt.event.MouseAdapter()
		{
			@Override
			public void mouseEntered(java.awt.event.MouseEvent e)
			{
				c.setBackground(hover);
			}

			@Override
			public void mouseExited(java.awt.event.MouseEvent e)
			{
				c.setBackground(base);
			}
		});
	}

	/** Hover that brightens the TEXT (for transparent link-style buttons), mirroring {@link #addHover}. */
	public static void addForegroundHover(JComponent c, Color base, Color hover)
	{
		c.addMouseListener(new java.awt.event.MouseAdapter()
		{
			@Override
			public void mouseEntered(java.awt.event.MouseEvent e)
			{
				c.setForeground(hover);
			}

			@Override
			public void mouseExited(java.awt.event.MouseEvent e)
			{
				c.setForeground(base);
			}
		});
	}

	/** Easy → mid → hard on the 1–10 Difficulty scale, using the theme's dedicated difficulty ramp so a
	 *  "diff N" never reads as the green points or a gold header sharing its line. */
	public static Color difficultyColor(int d)
	{
		if (d <= 0)
		{
			return CombatAchievementsTheme.DESC;
		}
		if (d <= 3)
		{
			return CombatAchievementsTheme.DIFF_EASY;
		}
		if (d <= 6)
		{
			return CombatAchievementsTheme.DIFF_MID;
		}
		return CombatAchievementsTheme.DIFF_HARD;
	}

	/** Themed grey for the muted "·" separators / secondary meta, as an HTML hex (follows the palette). */
	public static String metaHex()
	{
		return CombatAchievementsTheme.hex(CombatAchievementsTheme.NEUTRAL_META);
	}

	public static JButton linkButton(String text, String url)
	{
		return actionButton(text, () -> LinkBrowser.browse(url));
	}

	public static JButton actionButton(String text, Runnable action)
	{
		JButton button = new JButton(text);
		button.setFont(FontManager.getRunescapeSmallFont());
		button.setFocusPainted(false);
		button.setBorderPainted(false);
		button.setOpaque(true);
		button.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		button.setForeground(CombatAchievementsTheme.HEADER_GOLD);
		button.setBorder(BorderFactory.createEmptyBorder(2, 7, 2, 7));
		button.addActionListener(e -> action.run());
		addHover(button, ColorScheme.DARKER_GRAY_COLOR, ColorScheme.DARK_GRAY_HOVER_COLOR);
		return button;
	}
}

package com.pluginideahub.combatachievements.ui;

import com.pluginideahub.combatachievements.core.achievement.AchievementTier;
import java.awt.Color;

/**
 * The panel's ACTIVE colours. These are read (by name) across the Swing panel; the plugin swaps the
 * whole set at runtime via {@link #apply(Palette)} when the user picks a theme in config.
 * Backgrounds stay on RuneLite's ColorScheme greys — only these text/accent roles are themed. Mutated only
 * on the Swing EDT, so plain (non-volatile) statics are fine for this single-threaded UI.
 */
public final class CombatAchievementsTheme
{
	private CombatAchievementsTheme()
	{
	}

	public static Color POSITIVE;
	public static Color LOCKED;
	public static Color ACCENT;

	/** Brand identity: names, points, headers, descriptions. */
	public static Color NAME;
	public static Color POINTS;
	public static Color HEADER_GOLD;
	public static Color DESC;

	/** Unmet / hard / locked text (was the panel's HARD_RED). */
	public static Color NEGATIVE;
	/** Muted "·" separators and secondary meta. */
	public static Color NEUTRAL_META;

	/** Mode-bar selected fill + its text colour (kept legible per-palette). */
	public static Color MODE_SELECTED;
	public static Color MODE_SELECTED_TEXT;

	/** Difficulty ramp — its own colours so a "diff N" never reads as the points or a header. */
	public static Color DIFF_EASY;
	public static Color DIFF_MID;
	public static Color DIFF_HARD;

	public static Color TIER_EASY;
	public static Color TIER_MEDIUM;
	public static Color TIER_HARD;
	public static Color TIER_ELITE;
	public static Color TIER_MASTER;
	public static Color TIER_GRANDMASTER;

	static
	{
		apply(Palette.CLASSIC);
	}

	/** Swaps the whole active colour set. Call on the EDT, then re-render. */
	public static void apply(Palette p)
	{
		NAME = p.name;
		POINTS = p.points;
		HEADER_GOLD = p.headerAccent;
		DESC = p.desc;
		POSITIVE = p.positive;
		NEGATIVE = p.negative;
		LOCKED = p.locked;
		NEUTRAL_META = p.neutralMeta;
		ACCENT = p.accent;
		MODE_SELECTED = p.modeSelected;
		MODE_SELECTED_TEXT = p.modeSelectedText;
		DIFF_EASY = p.diffEasy;
		DIFF_MID = p.diffMid;
		DIFF_HARD = p.diffHard;
		TIER_EASY = p.tierEasy;
		TIER_MEDIUM = p.tierMedium;
		TIER_HARD = p.tierHard;
		TIER_ELITE = p.tierElite;
		TIER_MASTER = p.tierMaster;
		TIER_GRANDMASTER = p.tierGrandmaster;
	}

	public static Color forTier(AchievementTier tier)
	{
		if (tier == null)
		{
			return LOCKED;
		}
		switch (tier)
		{
			case EASY: return TIER_EASY;
			case MEDIUM: return TIER_MEDIUM;
			case HARD: return TIER_HARD;
			case ELITE: return TIER_ELITE;
			case MASTER: return TIER_MASTER;
			case GRANDMASTER: return TIER_GRANDMASTER;
			default: return LOCKED;
		}
	}

	/** Hex string (e.g. {@code #4caf50}) for embedding a colour in a JLabel's HTML. */
	public static String hex(Color c)
	{
		return String.format("#%02x%02x%02x", c.getRed(), c.getGreen(), c.getBlue());
	}
}

package com.pluginideahub.combatachievements.ui;

import java.awt.Color;

/**
 * An immutable colour palette for the side panel. The user picks one in the config; the chosen palette is
 * pushed into {@link CombatAchievementsTheme}, which the panel reads. The presets were checked for
 * hierarchy, difficulty/points colour separation, and WCAG AA contrast on the RuneLite dark card
 * background (#282828). Backgrounds stay on RuneLite's ColorScheme greys — only the text/accent roles
 * vary between palettes.
 */
public final class Palette
{
	public final Color name;
	public final Color points;
	public final Color headerAccent;
	public final Color desc;
	public final Color positive;
	public final Color negative;
	public final Color locked;
	public final Color neutralMeta;
	public final Color accent;
	public final Color modeSelected;
	public final Color modeSelectedText;
	public final Color diffEasy;
	public final Color diffMid;
	public final Color diffHard;
	public final Color tierEasy;
	public final Color tierMedium;
	public final Color tierHard;
	public final Color tierElite;
	public final Color tierMaster;
	public final Color tierGrandmaster;

	private Palette(Builder b)
	{
		this.name = b.name;
		this.points = b.points;
		this.headerAccent = b.headerAccent;
		this.desc = b.desc;
		this.positive = b.positive;
		this.negative = b.negative;
		this.locked = b.locked;
		this.neutralMeta = b.neutralMeta;
		this.accent = b.accent;
		this.modeSelected = b.modeSelected;
		this.modeSelectedText = b.modeSelectedText;
		this.diffEasy = b.diffEasy;
		this.diffMid = b.diffMid;
		this.diffHard = b.diffHard;
		this.tierEasy = b.tierEasy;
		this.tierMedium = b.tierMedium;
		this.tierHard = b.tierHard;
		this.tierElite = b.tierElite;
		this.tierMaster = b.tierMaster;
		this.tierGrandmaster = b.tierGrandmaster;
	}

	private static Color c(String hex)
	{
		return Color.decode(hex);
	}

	private static Builder builder()
	{
		return new Builder();
	}

	private static final class Builder
	{
		private Color name, points, headerAccent, desc, positive, negative, locked, neutralMeta, accent,
			modeSelected, modeSelectedText, diffEasy, diffMid, diffHard,
			tierEasy, tierMedium, tierHard, tierElite, tierMaster, tierGrandmaster;

		Builder name(String h) { this.name = c(h); return this; }
		Builder points(String h) { this.points = c(h); return this; }
		Builder headerAccent(String h) { this.headerAccent = c(h); return this; }
		Builder desc(String h) { this.desc = c(h); return this; }
		Builder positive(String h) { this.positive = c(h); return this; }
		Builder negative(String h) { this.negative = c(h); return this; }
		Builder locked(String h) { this.locked = c(h); return this; }
		Builder neutralMeta(String h) { this.neutralMeta = c(h); return this; }
		Builder accent(String h) { this.accent = c(h); return this; }
		Builder modeSelected(String h) { this.modeSelected = c(h); return this; }
		Builder modeSelectedText(String h) { this.modeSelectedText = c(h); return this; }
		Builder diffEasy(String h) { this.diffEasy = c(h); return this; }
		Builder diffMid(String h) { this.diffMid = c(h); return this; }
		Builder diffHard(String h) { this.diffHard = c(h); return this; }
		Builder tierEasy(String h) { this.tierEasy = c(h); return this; }
		Builder tierMedium(String h) { this.tierMedium = c(h); return this; }
		Builder tierHard(String h) { this.tierHard = c(h); return this; }
		Builder tierElite(String h) { this.tierElite = c(h); return this; }
		Builder tierMaster(String h) { this.tierMaster = c(h); return this; }
		Builder tierGrandmaster(String h) { this.tierGrandmaster = c(h); return this; }

		Palette build() { return new Palette(this); }
	}

	/**
	 * The panel's default OSRS look, kept as-is in character: orange names, gold headers, green points.
	 * A warm analogous core (OKLCH hue 62 orange to 88 gold) with green for value and red for negatives.
	 * Its green/red difficulty ramp is the pretty one, not the accessible one — under red-green colour
	 * blindness easy and hard collapse together, which is exactly what High contrast exists for.
	 */
	public static final Palette CLASSIC = builder()
		.name("#FFA752").points("#82D67A").headerAccent("#F2D48E").desc("#AEA798")
		.positive("#7CCF73").negative("#E66F62").locked("#7E7A72").neutralMeta("#938F85")
		.accent("#EF912D").modeSelected("#EF912D").modeSelectedText("#1E1E1E")
		.diffEasy("#7CCF73").diffMid("#F4CC64").diffHard("#E66F62")
		.tierEasy("#90D189").tierMedium("#71C9FA").tierHard("#E8C773")
		.tierElite("#C49BF3").tierMaster("#EF7F72").tierGrandmaster("#F0D777").build();

	/**
	 * Loud on purpose: a magenta / green / cyan triad (OKLCH hues 330, 145, 210) at high chroma. Because
	 * every hue sits in the same lightness and chroma band, a saturated scheme still reads as one
	 * deliberate palette rather than a pile of clashing brights.
	 */
	public static final Palette MOLTEN_GAUNTLET = builder()
		.name("#F695EE").points("#7CE782").headerAccent("#27E3FD").desc("#A19BAF")
		.positive("#7CE782").negative("#EE6570").locked("#7C7885").neutralMeta("#918C9D")
		.accent("#E175D9").modeSelected("#AF4DA9").modeSelectedText("#FFFFFF")
		.diffEasy("#7CE782").diffMid("#F3C935").diffHard("#EF656B")
		.tierEasy("#88E48C").tierMedium("#44D7FF").tierHard("#F0CF4C")
		.tierElite("#C896FF").tierMaster("#FD7277").tierGrandmaster("#F0D947").build();

	/**
	 * Cool and airy: one blue family (OKLCH hue 240–245) with analogous cyan/teal carrying value, and a
	 * pale lilac on the requirement ticks, a light green for the easy end of the difficulty ramp (hue 148,
	 * kept clear of the cyan next to it), and a complementary rose for the negatives. Lightness
	 * stays high and chroma stays low throughout,
	 * so the colours read as tinted white rather than as colour.
	 */
	public static final Palette LITE = builder()
		.name("#D0D9E1").points("#84DCE0").headerAccent("#A4D8FE").desc("#95A0AA")
		.positive("#D1B7F1").negative("#E1938C").locked("#798189").neutralMeta("#89949D")
		.accent("#68B2EF").modeSelected("#3E80B4").modeSelectedText("#FFFFFF")
		.diffEasy("#86D391").diffMid("#E0C88E").diffHard("#E3928B")
		.tierEasy("#92D5B7").tierMedium("#9BD2FA").tierHard("#E0C88E")
		.tierElite("#C6B1F0").tierMaster("#ECA19A").tierGrandmaster("#E1D195").build();

	/**
	 * Near-achromatic. The text roles are pure neutral greys; only the semantic ones (points, difficulty,
	 * tiers) carry chroma — muted, but enough to read as colour rather than as grey. A restrained steel
	 * accent carries the interactive bits.
	 */
	public static final Palette MODERN_DARK = builder()
		.name("#DEDEDE").points("#93C69D").headerAccent("#BEBEBE").desc("#929292")
		.positive("#93C69D").negative("#CA827C").locked("#777777").neutralMeta("#8C8C8C")
		.accent("#89B0D2").modeSelected("#4E6D87").modeSelectedText("#FFFFFF")
		.diffEasy("#8DC096").diffMid("#CEB577").diffHard("#CA827C")
		.tierEasy("#8FBF98").tierMedium("#85B8DC").tierHard("#CDB57B")
		.tierElite("#B2A0D6").tierMaster("#D5908A").tierGrandmaster("#CEBE82").build();

	/**
	 * Built for legibility rather than looks. Everything sits high on the lightness scale — every text
	 * role except the deliberately dim "locked" clears WCAG AAA (7:1) on the card — and the hues stay on
	 * the blue/amber axis that survives red-green colour blindness: value is cyan, never green, and the
	 * difficulty ramp separates by LIGHTNESS as well as hue so it still reads in greyscale. Checked with
	 * Vienot-Brettel protanope and deuteranope simulation: every ramp pair keeps clear separation.
	 */
	public static final Palette HIGH_CONTRAST = builder()
		.name("#FFCD94").points("#73EEF4").headerAccent("#FCE39F").desc("#C8C4B9")
		.positive("#73EEF4").negative("#FFA191").locked("#AEAAA4").neutralMeta("#BBB7AF")
		.accent("#FEB354").modeSelected("#FEB354").modeSelectedText("#1E1E1E")
		.diffEasy("#9BD1FF").diffMid("#FFDA7D").diffHard("#FFA191")
		.tierEasy("#A9D7FF").tierMedium("#73EEF4").tierHard("#FFDA7D")
		.tierElite("#D5B1FF").tierMaster("#FFA191").tierGrandmaster("#FDE7A2").build();
}

package com.pluginideahub.combatachievements.ui;

import com.pluginideahub.combatachievements.core.ui.PanelMode;
import com.pluginideahub.combatachievements.core.ui.SidePanelViewModel;

/**
 * Where the side panel is: the active {@link PanelMode} plus the drill-in selections layered over
 * it. Immutable — every transition returns a new value, so the panel can never be caught between
 * two places. There is no history: leaving a drill-in just clears its selection, and whatever the
 * remaining value shows is what shows.
 */
public final class PanelRoute
{
	private final PanelMode mode;
	/** When non-null, the CA-detail drill-in is shown (over whatever mode is active). */
	private final SidePanelViewModel.CaDetail ca;
	/** When non-null (Bosses mode), the boss-detail drill-in is shown. */
	private final String boss;
	/** When non-null (Route mode), the quest-unlock drill-in is shown; a selected CA overlays it. */
	private final SidePanelViewModel.UnlockView unlock;

	private PanelRoute(PanelMode mode, SidePanelViewModel.CaDetail ca, String boss,
		SidePanelViewModel.UnlockView unlock)
	{
		this.mode = mode;
		this.ca = ca;
		this.boss = boss;
		this.unlock = unlock;
	}

	/** A mode selected fresh, with no drill-in open. */
	public static PanelRoute of(PanelMode mode)
	{
		return new PanelRoute(mode, null, null, null);
	}

	public PanelMode mode()
	{
		return mode;
	}

	public SidePanelViewModel.CaDetail ca()
	{
		return ca;
	}

	public String boss()
	{
		return boss;
	}

	public SidePanelViewModel.UnlockView unlock()
	{
		return unlock;
	}

	/** Opens the CA detail over whatever is showing. */
	public PanelRoute withCa(SidePanelViewModel.CaDetail ca)
	{
		return new PanelRoute(mode, ca, boss, unlock);
	}

	/** Back out of the CA detail, to whatever it was covering. */
	public PanelRoute clearCa()
	{
		return new PanelRoute(mode, null, boss, unlock);
	}

	/** Opens a boss page (shown when the mode is Bosses). */
	public PanelRoute withBoss(String boss)
	{
		return new PanelRoute(mode, ca, boss, unlock);
	}

	/** Back out of the boss page, to the boss list. */
	public PanelRoute clearBoss()
	{
		return new PanelRoute(mode, ca, null, unlock);
	}

	/** Opens a quest-unlock page (shown when the mode is Route). */
	public PanelRoute withUnlock(SidePanelViewModel.UnlockView unlock)
	{
		return new PanelRoute(mode, ca, boss, unlock);
	}

	/** Back out of the quest-unlock page, to the Route list. */
	public PanelRoute clearUnlock()
	{
		return new PanelRoute(mode, ca, boss, null);
	}

	/** Jumps to a boss page from anywhere: Bosses mode, this boss open, any CA detail closed. */
	public PanelRoute toBoss(String boss)
	{
		return new PanelRoute(PanelMode.BOSSES, null, boss, unlock);
	}

	/** True when a drill-in page is showing instead of the mode's own list. */
	public boolean detailOpen()
	{
		return ca != null
			|| (boss != null && mode == PanelMode.BOSSES)
			|| (unlock != null && mode == PanelMode.ROUTE);
	}
}

package com.pluginideahub.combatachievements.ui.pages;

import com.pluginideahub.combatachievements.CombatAchievementsPanel;
import com.pluginideahub.combatachievements.core.ui.SidePanelViewModel;
import com.pluginideahub.combatachievements.ui.CardKit;
import com.pluginideahub.combatachievements.ui.CombatAchievementsTheme;
import java.awt.BorderLayout;
import java.awt.Color;
import java.awt.Cursor;
import java.awt.Dimension;
import java.util.ArrayList;
import java.util.List;
import java.util.function.Consumer;
import javax.swing.BorderFactory;
import javax.swing.JButton;
import javax.swing.JLabel;
import javax.swing.JPanel;
import net.runelite.client.ui.ColorScheme;
import net.runelite.client.ui.FontManager;

/** Renders a boss page: its headline, then its CAs split into doable / train-first / locked / done. */
public class BossDetailPage
{
	private final CombatAchievementsPanel panel;
	/** The CA-detail page owns the shared "Recommended stats" prose renderer. */
	private final CaDetailPage caDetail;
	private final JPanel content;

	public BossDetailPage(CombatAchievementsPanel panel, CaDetailPage caDetail)
	{
		this.panel = panel;
		this.caDetail = caDetail;
		this.content = panel.content();
	}

	public void buildBossDetail(String monster)
	{
		content.add(panel.backButton("← All bosses", () -> {
			panel.setRoute(panel.route().clearBoss());
			panel.rebuild();
		}));
		content.add(CardKit.spacer());

		SidePanelViewModel.BossRow boss = null;
		for (SidePanelViewModel.BossRow b : panel.model().bosses())
		{
			if (monster.equals(b.monster))
			{
				boss = b;
				break;
			}
		}
		if (boss == null)
		{
			content.add(panel.messageLabel("Boss not found."));
			return;
		}

		StringBuilder head = new StringBuilder("<span style='color:")
			.append(CombatAchievementsTheme.hex(CombatAchievementsTheme.NAME))
			.append("'><b style='font-size:11px'>").append(CardKit.escape(boss.monster)).append("</b></span>");
		if (boss.locked)
		{
			head.append("<br><span style='color:").append(CombatAchievementsTheme.hex(CombatAchievementsTheme.NEGATIVE))
				.append("'>Locked — no doable CAs yet.</span>");
		}
		else
		{
			head.append("<br><span style='color:").append(CombatAchievementsTheme.hex(CombatAchievementsTheme.POINTS))
				.append("'>").append(boss.projectedPoints).append(" pts available</span>")
				.append(" <span style='color:" + CardKit.metaHex() + "'>· ").append(boss.doableCount)
				.append(boss.doableCount == 1 ? " CA</span>" : " CAs</span>");
		}
		if (!boss.completedCas.isEmpty())
		{
			head.append("<br><span style='color:" + CardKit.metaHex() + "'>")
				.append(boss.completedCas.size()).append(" of ").append(boss.totalCas())
				.append(" done</span>");
		}
		content.add(CardKit.fullWidth(CardKit.wrappedHtmlLabel(head.toString(), CombatAchievementsPanel.CARD_TEXT_WIDTH)));
		content.add(CardKit.spacer());

		if (!boss.recommendedStats.isEmpty())
		{
			caDetail.addDetailText("Recommended stats", boss.recommendedStats);
		}

		// "Doable" only means no hard gate blocks you, so a level-3 saw seven Barrows CAs it was 49-84
		// levels short of, all reading as available. Split on the ready line: what you could go and do
		// now, and below it what is ungated but out of reach. Nothing is hidden either way.
		// Headings: "Doable now" / "Train first" / "Locked". The middle group was called "Not yet", which
		// read as "not unlocked yet" — i.e. the Locked group below, the exact opposite of what it holds.
		// The lesson: a heading describing the CONTENT ("not yet", "out of reach") always blurs into
		// "locked", because from the task's side both mean "you can't have it". These two groups differ in
		// what they are ABOUT — Locked is a gate on the content, this is your stats — so the heading names
		// the fix instead, matching the Route's "Train next".
		List<SidePanelViewModel.CaDetail> reachable = new ArrayList<>();
		List<SidePanelViewModel.CaDetail> notYet = new ArrayList<>();
		for (SidePanelViewModel.CaDetail d : boss.doable)
		{
			(d.withinReach ? reachable : notYet).add(d);
		}
		if (!reachable.isEmpty())
		{
			content.add(panel.collapseHeader("Doable now (" + reachable.size() + ")", panel.doableCollapsed(),
				() -> { panel.setDoableCollapsed(!panel.doableCollapsed()); panel.rebuild(); }));
			if (!panel.doableCollapsed())
			{
				content.add(CardKit.spacer());
				for (SidePanelViewModel.CaDetail d : reachable)
				{
					content.add(caCard(d));
					content.add(CardKit.spacer());
				}
			}
		}
		if (!notYet.isEmpty())
		{
			content.add(panel.collapseHeader("Train first (" + notYet.size() + ")", panel.trainFirstCollapsed(),
				() -> { panel.setTrainFirstCollapsed(!panel.trainFirstCollapsed()); panel.rebuild(); }));
			if (!panel.trainFirstCollapsed())
			{
				content.add(CardKit.spacer());
				for (SidePanelViewModel.CaDetail d : notYet)
				{
					content.add(caCard(d));
					content.add(CardKit.spacer());
				}
			}
		}
		if (!boss.lockedCas.isEmpty())
		{
			content.add(panel.collapseHeader("Locked (" + boss.lockedCas.size() + ")", panel.lockedCollapsed(),
				() -> { panel.setLockedCollapsed(!panel.lockedCollapsed()); panel.rebuild(); }));
			if (!panel.lockedCollapsed())
			{
				content.add(CardKit.spacer());
				for (SidePanelViewModel.CaDetail d : boss.lockedCas)
				{
					content.add(caCard(d));
					content.add(CardKit.spacer());
				}
			}
		}

		// What you have already done here, collapsed by default so the boss page stays forward-looking.
		if (!boss.completedCas.isEmpty())
		{
			content.add(CardKit.spacer());
			content.add(panel.collapseHeader("Completed (" + boss.completedCas.size() + ")", panel.completedCollapsed(),
				() -> { panel.setCompletedCollapsed(!panel.completedCollapsed()); panel.rebuild(); }));
			if (!panel.completedCollapsed())
			{
				content.add(CardKit.spacer());
				for (SidePanelViewModel.CaDetail d : boss.completedCas)
				{
					content.add(completedCard(d));
					content.add(CardKit.spacer());
				}
			}
		}
	}

	/**
	 * A completed CA at a boss: same shape as the other cards but greyed with a tick, so a glance down the
	 * boss page separates "done" from "to do" without reading the text.
	 */
	private JPanel completedCard(SidePanelViewModel.CaDetail d)
	{
		JPanel card = new JPanel(new BorderLayout());
		card.setBackground(ColorScheme.DARK_GRAY_COLOR);
		card.setBorder(BorderFactory.createCompoundBorder(
			BorderFactory.createMatteBorder(0, 3, 0, 0, CombatAchievementsTheme.POSITIVE),
			BorderFactory.createEmptyBorder(5, 7, 5, 7)));

		StringBuilder sb = new StringBuilder("<html><body style='width:166px'>");
		sb.append("<span style='color:").append(CombatAchievementsTheme.hex(CombatAchievementsTheme.POSITIVE))
			.append("'>&#10003; </span>");
		sb.append("<span style='color:").append(CombatAchievementsTheme.hex(CombatAchievementsTheme.LOCKED))
			.append("'><b>").append(CardKit.escape(d.name)).append("</b></span>");
		sb.append("<br><span style='color:" + CardKit.metaHex() + "'>").append(d.points)
			.append(d.points == 1 ? " pt" : " pts").append(" · ").append(CardKit.escape(d.tierName))
			.append("</span>");
		sb.append("</body></html>");
		card.add(new JLabel(sb.toString()), BorderLayout.CENTER);
		CardKit.addHover(card, ColorScheme.DARK_GRAY_COLOR, ColorScheme.DARK_GRAY_HOVER_COLOR);
		CardKit.onClick(card, () -> {
			panel.setRoute(panel.route().withCa(d));
			panel.rebuild();
		});
		return CardKit.fullWidth(card);
	}

	/** A clickable CA row from a CaDetail — orange (doable) or red (locked) — opening the CA detail. */
	/** A CA card for the boss detail — same layout as the CAs-list task card for a consistent look. */
	private JPanel caCard(SidePanelViewModel.CaDetail d)
	{
		boolean toggle = d.doableNow && (panel.onAddToRoute() != null || panel.onRemoveFromRoute() != null);
		final int textWidth = toggle ? 166 - CombatAchievementsPanel.BAR_BUTTON_WIDTH : 166;
		JPanel card = new JPanel(new BorderLayout());
		card.setBackground(ColorScheme.DARK_GRAY_COLOR);
		Color accent = d.doableNow ? CombatAchievementsTheme.NAME : CombatAchievementsTheme.LOCKED;
		card.setBorder(BorderFactory.createCompoundBorder(
			BorderFactory.createMatteBorder(0, 3, 0, 0, accent),
			BorderFactory.createEmptyBorder(5, 7, 5, 7)));

		StringBuilder sb = new StringBuilder();
		sb.append("<span style='color:").append(CombatAchievementsTheme.hex(accent))
			.append("'><b>").append(CardKit.escape(d.name)).append("</b></span>");
		if (!d.doableNow)
		{
			String lock = d.lockReason == null || d.lockReason.isEmpty() ? "locked" : d.lockReason;
			sb.append(" <span style='color:").append(CombatAchievementsTheme.hex(CombatAchievementsTheme.LOCKED))
				.append("'>(").append(CardKit.escape(lock)).append(")</span>");
		}
		sb.append("<br><span style='color:").append(CombatAchievementsTheme.hex(CombatAchievementsTheme.DESC))
			.append("'>").append(CardKit.escape(d.description)).append("</span>");
		sb.append("<br><span style='color:").append(CombatAchievementsTheme.hex(CombatAchievementsTheme.POINTS))
			.append("'>").append(d.points).append(" pts</span>")
			.append(" <span style='color:" + CardKit.metaHex() + "'>· ").append(CardKit.escape(d.tierName)).append("</span>");
		if (d.difficulty > 0)
		{
			sb.append(" <span style='color:" + CardKit.metaHex() + "'>· </span><span style='color:")
				.append(CombatAchievementsTheme.hex(CardKit.difficultyColor(d.difficulty)))
				.append("'>difficulty ").append(d.difficulty).append("</span>");
		}
		JLabel label = CardKit.wrappedHtmlLabel(sb.toString(), textWidth);
		label.setBorder(BorderFactory.createEmptyBorder(0, 0, 3, 0));
		// The border sits inside the pinned size, so grow the pin or it eats the text's height.
		Dimension pinned = label.getPreferredSize();
		Dimension withBorder = new Dimension(pinned.width, pinned.height + 3);
		label.setPreferredSize(withBorder);
		label.setMaximumSize(withBorder);
		card.add(label, BorderLayout.CENTER);

		card.add(panel.linkRow(d.wikiUrl, d.guideUrl, d.curatedVideo), BorderLayout.SOUTH);
		// "-" when this CA is already in the route, "+" when it is not, so a boss page doubles as a way to
		// steer the route: take more of this boss, or drop the ones you would rather skip.
		if (toggle)
		{
			card.add(routeToggle(d), BorderLayout.EAST);
		}
		CardKit.addHover(card, ColorScheme.DARK_GRAY_COLOR, ColorScheme.DARK_GRAY_HOVER_COLOR);
		CardKit.onClick(card, () -> {
			panel.setRoute(panel.route().withCa(d));
			panel.rebuild();
		});
		CardKit.fullWidth(card);
		card.setMaximumSize(new Dimension(CombatAchievementsPanel.ROUTE_CARD_MAX_WIDTH, card.getPreferredSize().height));
		return card;
	}

	/** True when this CA is one of the Route's current steps. */
	private boolean inRoute(int id)
	{
		if (panel.model().path() == null)
		{
			return false;
		}
		for (SidePanelViewModel.PathRow r : panel.model().path().steps)
		{
			if (r.id == id)
			{
				return true;
			}
		}
		return false;
	}

	/** The boss page's route control: "-" to drop a routed CA, "+" to pull one in. */
	private JButton routeToggle(SidePanelViewModel.CaDetail d)
	{
		boolean routed = inRoute(d.id);
		JButton b = new JButton(routed ? "-" : "+");
		b.setFont(FontManager.getRunescapeBoldFont());
		b.setToolTipText(routed
			? "Remove " + d.name + " from the route"
			: "Add " + d.name + " to the route");
		b.setFocusPainted(false);
		b.setBorderPainted(false);
		b.setContentAreaFilled(false);
		b.setOpaque(false);
		Color idle = routed
			? CombatAchievementsPanel.blend(CombatAchievementsTheme.NEUTRAL_META, CombatAchievementsTheme.NEGATIVE, 0.72)
			: CombatAchievementsPanel.blend(CombatAchievementsTheme.NEUTRAL_META, CombatAchievementsTheme.POSITIVE, 0.72);
		b.setForeground(idle);
		CardKit.addForegroundHover(b, idle,
			routed ? CombatAchievementsTheme.NEGATIVE : CombatAchievementsTheme.POSITIVE);
		b.setBorder(BorderFactory.createEmptyBorder(0, 4, 0, 0));
		b.setPreferredSize(new Dimension(CombatAchievementsPanel.BAR_BUTTON_WIDTH, 18));
		b.setCursor(new Cursor(Cursor.HAND_CURSOR));
		b.addActionListener(e -> {
			Consumer<Integer> handler = routed ? panel.onRemoveFromRoute() : panel.onAddToRoute();
			if (handler != null)
			{
				handler.accept(d.id);
			}
		});
		return b;
	}
}

package com.pluginideahub.combatachievements.ui.pages;

import com.pluginideahub.combatachievements.CombatAchievementsPanel;
import com.pluginideahub.combatachievements.core.ui.SidePanelViewModel;
import com.pluginideahub.combatachievements.ui.CardKit;
import com.pluginideahub.combatachievements.ui.CombatAchievementsTheme;
import java.awt.BorderLayout;
import java.awt.Color;
import java.util.ArrayList;
import java.util.Comparator;
import java.util.List;
import java.util.Locale;
import javax.swing.BorderFactory;
import javax.swing.JLabel;
import javax.swing.JPanel;
import net.runelite.client.ui.ColorScheme;

/** Renders the Bosses mode: the ranked boss directory, one row per boss with incomplete CAs. */
public class BossesPage
{
	private final CombatAchievementsPanel panel;
	private final JPanel content;

	public BossesPage(CombatAchievementsPanel panel)
	{
		this.panel = panel;
		this.content = panel.content();
	}

	public void buildBosses()
	{
		String q = panel.searchText();
		List<SidePanelViewModel.BossRow> all = panel.model().bosses();
		if (all == null || all.isEmpty())
		{
			content.add(panel.messageLabel("No bosses with incomplete CAs."));
			return;
		}
		List<SidePanelViewModel.BossRow> bosses = new ArrayList<>();
		for (SidePanelViewModel.BossRow b : all)
		{
			if (q.isEmpty() || b.monster.toLowerCase(Locale.ROOT).contains(q))
			{
				bosses.add(b);
			}
		}
		if (bosses.isEmpty())
		{
			content.add(panel.messageLabel("No bosses match your search."));
			return;
		}
		bosses.sort(bossComparator(panel.sort(), panel.tripOverheadMinutes(), panel.bossTimeWeight()));
		for (SidePanelViewModel.BossRow b : bosses)
		{
			content.add(bossRowCard(b));
			content.add(CardKit.spacer());
		}
	}

	/**
	 * The boss-list ordering for a given {@link CombatAchievementsPanel.Sort}. Locked bosses (no doable
	 * CAs) always sink to the bottom. The metrics are derived from each boss's doable CAs:
	 * <ul>
	 *   <li>{@code RECOMMENDED} — points per hour with the per-trip overhead amortised in
	 *       ({@link #bossPointsPerHour}); because a CA's estimated minutes already scale with its
	 *       Difficulty and the fixed {@code tripOverheadMinutes} is spread across the whole visit, this is
	 *       the "points / time / ease" value blend that also rewards clustering (staying at one boss).</li>
	 *   <li>{@code MOST_POINTS} — projected (doable-now) points, highest first.</li>
	 *   <li>{@code EASIEST} — lowest average doable-CA Difficulty, tie-broken by quickest then most points.</li>
	 * </ul>
	 */
	public static Comparator<SidePanelViewModel.BossRow> bossComparator(CombatAchievementsPanel.Sort sort,
		int tripOverheadMinutes)
	{
		return bossComparator(sort, tripOverheadMinutes, 1.0);
	}

	public static Comparator<SidePanelViewModel.BossRow> bossComparator(CombatAchievementsPanel.Sort sort,
		int tripOverheadMinutes, double timeWeight)
	{
		Comparator<SidePanelViewModel.BossRow> lockedLast =
			Comparator.comparing((SidePanelViewModel.BossRow b) -> b.locked); // false (doable) first
		switch (sort)
		{
			case MOST_POINTS:
				return lockedLast
					.thenComparing(Comparator.comparingInt((SidePanelViewModel.BossRow b) -> b.projectedPoints).reversed())
					.thenComparing(b -> b.monster);
			case EASIEST:
				return lockedLast
					.thenComparing(Comparator.comparingDouble(BossesPage::bossAvgDifficulty))
					.thenComparing(Comparator.comparingInt(BossesPage::bossDoableMinutes))
					.thenComparing(Comparator.comparingInt((SidePanelViewModel.BossRow b) -> b.projectedPoints).reversed())
					.thenComparing(b -> b.monster);
			default: // RECOMMENDED
				return lockedLast
					.thenComparing(Comparator.comparingDouble(
						(SidePanelViewModel.BossRow b) -> bossPointsPerHour(b, tripOverheadMinutes, timeWeight)).reversed())
					.thenComparing(b -> b.monster);
		}
	}

	/** Total estimated minutes across a boss's doable CAs. */
	private static int bossDoableMinutes(SidePanelViewModel.BossRow b)
	{
		int minutes = 0;
		for (SidePanelViewModel.CaDetail d : b.doable)
		{
			minutes += d.estMinutes;
		}
		return minutes;
	}

	/**
	 * Points per hour for a boss's doable CAs, with the fixed per-trip overhead amortised into the time.
	 * Spreading {@code tripOverheadMinutes} across the whole visit rewards bosses with several doable CAs
	 * (clustering) over trivial single-CA hops. Nothing-to-gain bosses score 0; a free (zero-time,
	 * zero-overhead) prize ranks top.
	 */
	private static double bossPointsPerHour(SidePanelViewModel.BossRow b, int tripOverheadMinutes,
		double timeWeight)
	{
		if (b.projectedPoints <= 0)
		{
			return 0.0;
		}
		// Readiness rides on the row: a boss whose doable CAs sit far above the player's recommended stats
		// is worth less per hour to THEM, however good its points-per-hour looks in the abstract. Without
		// this the list was account-blind — a level-3 and a combat-89 account both led with Dagannoth Kings.
		double sink = Math.max(1.0, b.readinessSink);
		double denominator = sink
			* (Math.max(0, tripOverheadMinutes) + Math.max(0.0, timeWeight) * bossDoableMinutes(b));
		// No time cost at all (both dials off, or a zero-minute boss) → rank on points: a large sentinel keeps
		// such bosses above any real points-per-hour figure, and adding the points breaks their ties by points
		// (not alphabetically), so "Time vs points = 0" genuinely ranks on available points.
		return denominator <= 0 ? 1.0e12 + b.projectedPoints : b.projectedPoints * 60.0 / denominator;
	}

	/** Average Difficulty of a boss's doable CAs; MAX when none are rated (sinks below rated bosses). */
	private static double bossAvgDifficulty(SidePanelViewModel.BossRow b)
	{
		int sum = 0;
		int rated = 0;
		for (SidePanelViewModel.CaDetail d : b.doable)
		{
			if (d.difficulty > 0)
			{
				sum += d.difficulty;
				rated++;
			}
		}
		return rated == 0 ? Double.MAX_VALUE : (double) sum / rated;
	}

	private JPanel bossRowCard(SidePanelViewModel.BossRow b)
	{
		JPanel card = new JPanel(new BorderLayout());
		card.setBackground(ColorScheme.DARK_GRAY_COLOR);
		Color accent = b.locked ? CombatAchievementsTheme.LOCKED : CombatAchievementsTheme.NAME;
		card.setBorder(BorderFactory.createCompoundBorder(
			BorderFactory.createMatteBorder(0, 3, 0, 0, accent),
			BorderFactory.createEmptyBorder(6, 7, 6, 7)));

		StringBuilder sb = new StringBuilder("<html><body style='width:182px'>");
		sb.append("<span style='color:").append(CombatAchievementsTheme.hex(accent))
			.append("'><b>").append(CardKit.escape(b.monster)).append("</b></span>");
		if (b.locked)
		{
			String reason = "needs access";
			for (SidePanelViewModel.CaDetail lc : b.lockedCas)
			{
				if (!lc.lockReason.isEmpty())
				{
					reason = lc.lockReason; // usually "needs <quest>" — name the specific gate
					break;
				}
			}
			sb.append(" <span style='color:" + CardKit.metaHex() + "'>(locked)</span>");
			sb.append("<br><span style='color:").append(CombatAchievementsTheme.hex(CombatAchievementsTheme.NEGATIVE))
				.append("'>").append(CardKit.escape(reason)).append("</span>")
				.append(" <span style='color:" + CardKit.metaHex() + "'>· ").append(b.lockedCount)
				.append(b.lockedCount == 1 ? " CA</span>" : " CAs</span>");
		}
		else
		{
			sb.append("<br><span style='color:").append(CombatAchievementsTheme.hex(CombatAchievementsTheme.POINTS))
				.append("'>").append(b.projectedPoints).append(" pts available</span>")
				.append(" <span style='color:" + CardKit.metaHex() + "'>· ").append(b.doableCount)
				.append(b.doableCount == 1 ? " CA" : " CAs");
			if (b.lockedCount > 0)
			{
				sb.append(" (+").append(b.lockedCount).append(" locked)");
			}
			sb.append("</span>");
		}
		sb.append("</body></html>");
		card.add(new JLabel(sb.toString()), BorderLayout.CENTER);
		CardKit.addHover(card, ColorScheme.DARK_GRAY_COLOR, ColorScheme.DARK_GRAY_HOVER_COLOR);
		CardKit.onClick(card, () -> {
			panel.setRoute(panel.route().withBoss(b.monster));
			panel.rebuild();
		});
		return CardKit.fullWidth(card);
	}
}

package com.pluginideahub.combatachievements.ui.pages;

import com.pluginideahub.combatachievements.CombatAchievementsPanel;
import com.pluginideahub.combatachievements.core.ui.SidePanelViewModel;
import com.pluginideahub.combatachievements.ui.CardKit;
import com.pluginideahub.combatachievements.ui.CombatAchievementsTheme;
import java.awt.Color;
import java.awt.Component;
import java.awt.Dimension;
import java.util.Locale;
import javax.swing.BorderFactory;
import javax.swing.JLabel;
import javax.swing.JPanel;
import javax.swing.JTextArea;
import net.runelite.client.ui.FontManager;

/** Renders the CA-detail drill-in: one achievement's crumb, requirements, difficulty and how-to. */
public class CaDetailPage
{
	/** Wrap width for the CA-detail how-to prose, kept clear of the scrollbar the tall view brings in. */
	private static final int DETAIL_TEXT_WIDTH = 170;

	private final CombatAchievementsPanel panel;
	private final JPanel content;

	public CaDetailPage(CombatAchievementsPanel panel)
	{
		this.panel = panel;
		this.content = panel.content();
	}

	public void renderCaDetail(SidePanelViewModel.CaDetail d)
	{
		content.add(panel.backButton("← Back", () -> {
			panel.setRoute(panel.route().clearCa());
			panel.rebuild();
		}));
		content.add(CardKit.spacer());

		StringBuilder crumb = new StringBuilder();
		if (!d.monster.isEmpty())
		{
			crumb.append(CardKit.escape(d.monster)).append(" · ");
		}
		crumb.append(CardKit.escape(d.tierName)).append(" · ").append(d.points).append(" pts");
		if (!d.type.isEmpty())
		{
			crumb.append(" · ").append(CardKit.escape(d.type));
		}

		StringBuilder sb = new StringBuilder();
		sb.append("<span style='color:").append(CombatAchievementsTheme.hex(CombatAchievementsTheme.NAME))
			.append("'><b style='font-size:11px'>").append(CardKit.escape(d.name)).append("</b></span>");
		sb.append("<br><span style='color:" + CardKit.metaHex() + "'>").append(crumb).append("</span>");
		if (!d.description.isEmpty())
		{
			sb.append("<br><span style='color:").append(CombatAchievementsTheme.hex(CombatAchievementsTheme.DESC))
				.append("'>").append(CardKit.escape(d.description)).append("</span>");
		}
		if (!d.doableNow && !d.lockReason.isEmpty())
		{
			sb.append("<br><span style='color:").append(CombatAchievementsTheme.hex(CombatAchievementsTheme.NEGATIVE))
				.append("'>").append(CardKit.escape(d.lockReason)).append("</span>");
		}
		content.add(CardKit.fullWidth(CardKit.wrappedHtmlLabel(sb.toString(), CombatAchievementsPanel.CARD_TEXT_WIDTH)));
		content.add(CardKit.spacer());

		// Jump to the boss this CA is at, to see everything else you could knock out on the same trip.
		// Only offered when that boss actually has a page in the directory, so it can never be a dead end.
		if (!d.monster.isEmpty() && panel.bossExists(d.monster))
		{
			String label = d.monster.length() > 18 ? d.monster.substring(0, 17) + "…" : d.monster;
			content.add(panel.backButton("View " + label + " →", () -> {
				panel.setRoute(panel.route().toBoss(d.monster));
				panel.buildModeBar();
				panel.rebuild();
			}));
			content.add(CardKit.spacer());
		}

		if (!d.requirements.isEmpty())
		{
			content.add(panel.collapseHeader("Requirements", !panel.reqsExpanded(),
				() -> { panel.setReqsExpanded(!panel.reqsExpanded()); panel.rebuild(); }));
			if (panel.reqsExpanded())
			{
				content.add(CardKit.spacer());
				for (SidePanelViewModel.CaReq r : d.requirements)
				{
					content.add(reqRow(r));
				}
			}
			content.add(CardKit.spacer());
		}

		content.add(panel.sectionHeader("Difficulty"));
		double rating = displayedDifficulty(d);
		StringBuilder diff = new StringBuilder();
		diff.append("<span style='color:").append(CombatAchievementsTheme.hex(CardKit.difficultyColor(d.difficulty)))
			.append("'>").append(String.format(Locale.ROOT, "%.1f", rating)).append(" / 10</span>");
		if (d.bossDifficulty > 0)
		{
			diff.append("<br><span style='color:" + CardKit.metaHex() + "'>").append(CardKit.escape(d.monster)).append(" (boss ")
				.append(d.bossDifficulty).append(")");
			if (d.bump != 0 && !d.difficultyReason.isEmpty())
			{
				diff.append(" + ").append(CardKit.escape(d.difficultyReason))
					.append(String.format(Locale.ROOT, " (+%.1f)", d.bump));
			}
			diff.append("</span>");
		}
		content.add(CardKit.fullWidth(CardKit.wrappedHtmlLabel(diff.toString(), CombatAchievementsPanel.CARD_TEXT_WIDTH)));
		content.add(CardKit.spacer());


		// Curated how-to (stats/setup/items/strategy) behind a collapsible arrow so the detail stays lean;
		// the config option seeds whether it starts expanded.
		boolean hasHowTo = !d.stats.isEmpty() || !d.setup.isEmpty() || !d.items.isEmpty()
			|| !d.strategy.isEmpty();
		if (hasHowTo)
		{
			content.add(panel.collapseHeader("How to do it", !panel.howToExpanded(),
				() -> { panel.setHowToExpanded(!panel.howToExpanded()); panel.rebuild(); }));
			if (panel.howToExpanded())
			{
				content.add(CardKit.spacer());
				addDetailText("Recommended stats", d.stats);
				addDetailText("Recommended setup", d.setup);
				addDetailText("Items", d.items);
				addDetailText("Strategy", d.strategy);
			}
			content.add(CardKit.spacer());
		}

		// "Suggest fix" only belongs on a task's own page, so it is appended here rather than baked into
		// the shared link row the Bosses and Recommended cards use.
		JPanel links = panel.linkRow(d.wikiUrl, d.guideUrl, d.curatedVideo);
		links.add(CardKit.linkButton("Suggest fix", CombatAchievementsPanel.SUGGEST_FIX_URL));
		content.add(CardKit.fullWidth(links));
	}

	void addDetailText(String header, String text)
	{
		if (text == null || text.isEmpty())
		{
			return;
		}
		content.add(panel.sectionHeader(header));
		// A JTextArea rather than an HTML JLabel: the label's body-width style is unreliable here — a long
		// word ("thrownhammer") keeps the whole line intact and it clips at the panel edge. A word-wrapping
		// text area reflows to its actual width every time, which is the whole point.
		JTextArea body = new JTextArea(text);
		body.setLineWrap(true);
		body.setWrapStyleWord(true);
		body.setEditable(false);
		body.setFocusable(false);
		body.setOpaque(false);
		body.setBorder(null);
		body.setFont(FontManager.getRunescapeSmallFont());
		body.setForeground(CombatAchievementsTheme.DESC);
		body.setAlignmentX(Component.LEFT_ALIGNMENT);
		// A word-wrapping JTextArea reports a one-line preferred height until it knows its width, so under
		// BoxLayout it would collapse to a single line. Fix the width first, then the reported height is the
		// wrapped height; pin both so the layout gives it exactly that.
		body.setSize(DETAIL_TEXT_WIDTH, Short.MAX_VALUE);
		int wrappedHeight = body.getPreferredSize().height;
		body.setPreferredSize(new Dimension(DETAIL_TEXT_WIDTH, wrappedHeight));
		body.setMaximumSize(new Dimension(DETAIL_TEXT_WIDTH, wrappedHeight));
		content.add(body);
		content.add(CardKit.spacer());
	}

	private JLabel reqRow(SidePanelViewModel.CaReq r)
	{
		Color colour = r.met ? CombatAchievementsTheme.POSITIVE : CombatAchievementsTheme.NEGATIVE;
		String mark = r.met ? "&#10003;" : "&#10007;"; // check / cross
		StringBuilder sb = new StringBuilder("<span style='color:")
			.append(CombatAchievementsTheme.hex(colour)).append("'>").append(mark).append(" ")
			.append(CardKit.escape(r.label)).append("</span>");
		if (!r.note.isEmpty())
		{
			sb.append(" <span style='color:").append(CombatAchievementsTheme.hex(CombatAchievementsTheme.NEGATIVE))
				.append("'>— ").append(CardKit.escape(r.note)).append("</span>");
		}
		return CardKit.fullWidth(CardKit.wrappedHtmlLabel(sb.toString(), CombatAchievementsPanel.CARD_TEXT_WIDTH));
	}

	/** The Difficulty rating the panel shows: the boss rating plus this task's bump, else the raw value. */
	private static double displayedDifficulty(SidePanelViewModel.CaDetail d)
	{
		return d.bossDifficulty > 0 ? d.bossDifficulty + d.bump : d.difficulty;
	}
}

package com.pluginideahub.combatachievements.ui.pages;

import com.pluginideahub.combatachievements.CombatAchievementsPanel;
import com.pluginideahub.combatachievements.core.ui.SidePanelViewModel;
import com.pluginideahub.combatachievements.ui.CardKit;
import com.pluginideahub.combatachievements.ui.CombatAchievementsTheme;
import java.awt.BorderLayout;
import java.awt.Color;
import java.util.ArrayList;
import java.util.Comparator;
import java.util.HashMap;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import javax.swing.BorderFactory;
import javax.swing.JLabel;
import javax.swing.JPanel;
import net.runelite.client.ui.ColorScheme;

/** Renders the Recommended mode: the searched, sorted, shuffleable list of doable-now CA cards. */
public class RecommendedPage
{
	/** Cap on cards rendered at once in the (now full) CAs list; refine the search to see more. */
	private static final int RENDER_CAP = 60;
	/** Max rank positions a CA can move when the CAs list is shuffled — big enough to surface a different
	 *  set, small enough to keep good CAs near the top. */
	private static final double SHUFFLE_JITTER = 12.0;

	private final CombatAchievementsPanel panel;
	private final JPanel content;

	public RecommendedPage(CombatAchievementsPanel panel)
	{
		this.panel = panel;
		this.content = panel.content();
	}

	private static boolean matches(SidePanelViewModel.TaskRow r, String q)
	{
		return q.isEmpty()
			|| r.name.toLowerCase(Locale.ROOT).contains(q)
			|| r.monster.toLowerCase(Locale.ROOT).contains(q);
	}

	public void buildRecommended()
	{
		String q = panel.searchText();
		List<SidePanelViewModel.TaskRow> rows = new ArrayList<>();
		for (SidePanelViewModel.TaskRow r : panel.model().quickWins())
		{
			if (r.doableNow && matches(r, q)) // Recommended is strictly doable-now
			{
				rows.add(r);
			}
		}
		sortRows(rows);
		if (panel.shuffleSeed() != 0)
		{
			applyShuffle(rows);
		}

		if (rows.isEmpty())
		{
			content.add(panel.messageLabel(q.isEmpty()
				? "No doable Combat Achievements right now."
				: "No CAs match your search."));
			return;
		}
		int shown = 0;
		for (SidePanelViewModel.TaskRow r : rows)
		{
			if (shown >= RENDER_CAP)
			{
				content.add(panel.messageLabel("+" + (rows.size() - shown) + " more — refine your search."));
				break;
			}
			content.add(taskCard(r));
			content.add(CardKit.spacer());
			shown++;
		}
	}

	private void sortRows(List<SidePanelViewModel.TaskRow> rows)
	{
		switch (panel.sort())
		{
			case MOST_POINTS:
				rows.sort(Comparator.comparingInt((SidePanelViewModel.TaskRow r) -> r.points).reversed()
					.thenComparingInt(r -> r.id));
				break;
			case EASIEST:
				rows.sort(Comparator.comparingInt((SidePanelViewModel.TaskRow r) -> r.difficulty)
					.thenComparing(Comparator.comparingInt((SidePanelViewModel.TaskRow r) -> r.points).reversed())
					.thenComparingInt(r -> r.id));
				break;
			default: // RECOMMENDED: keep the model's ranked order
				break;
		}
	}

	/**
	 * Reorders the doable CAs with a bounded random rank jitter so each reshuffle surfaces a different but
	 * still-sensible set. Deterministic per {@link CombatAchievementsPanel#shuffleSeed}, so per-tick
	 * refreshes don't re-scramble the list — only pressing the shuffle button (which bumps the seed)
	 * changes it.
	 */
	private void applyShuffle(List<SidePanelViewModel.TaskRow> rows)
	{
		Map<Integer, Double> key = new HashMap<>();
		for (int i = 0; i < rows.size(); i++)
		{
			SidePanelViewModel.TaskRow r = rows.get(i);
			key.put(r.id, jitteredKey(i, r.id, panel.shuffleSeed()));
		}
		rows.sort(Comparator.comparingDouble(r -> key.get(r.id)));
	}

	/**
	 * A task's jittered sort key: its rank plus a bounded, deterministic offset. Uses a splitmix64 hash of
	 * (seed, id) rather than {@link java.util.Random} — Random's first output is correlated across nearby
	 * seeds, which would make consecutive reshuffles produce almost the same order.
	 */
	public static double jitteredKey(int rank, int id, long seed)
	{
		long h = seed * 0x9E3779B97F4A7C15L + (id + 1L) * 0xD1B54A32D192ED03L;
		h ^= h >>> 30;
		h *= 0xBF58476D1CE4E5B9L;
		h ^= h >>> 27;
		h *= 0x94D049BB133111EBL;
		h ^= h >>> 31;
		double u = (h >>> 11) * 0x1.0p-53; // uniform in [0, 1)
		return rank + (u * 2.0 - 1.0) * SHUFFLE_JITTER;
	}

	private JPanel taskCard(SidePanelViewModel.TaskRow row)
	{
		JPanel card = new JPanel(new BorderLayout());
		card.setBackground(ColorScheme.DARK_GRAY_COLOR);
		Color accent = row.doableNow ? CombatAchievementsTheme.NAME : CombatAchievementsTheme.LOCKED;
		card.setBorder(BorderFactory.createCompoundBorder(
			BorderFactory.createMatteBorder(0, 3, 0, 0, accent),
			BorderFactory.createEmptyBorder(5, 7, 5, 7)));

		String name = CombatAchievementsTheme.hex(row.doableNow
			? CombatAchievementsTheme.NAME : CombatAchievementsTheme.LOCKED);
		StringBuilder sb = new StringBuilder("<html><body style='width:166px'>");
		sb.append("<span style='color:").append(name).append("'><b>").append(CardKit.escape(row.name)).append("</b></span>");
		if (!row.doableNow)
		{
			String lock = (row.lockReason == null || row.lockReason.isEmpty()) ? "locked" : row.lockReason;
			sb.append(" <span style='color:").append(CombatAchievementsTheme.hex(CombatAchievementsTheme.LOCKED))
				.append("'>(").append(CardKit.escape(lock)).append(")</span>");
		}
		if (!row.curated)
		{
			sb.append(" <span style='color:#6f6f6f'>&#9679;</span>");
		}
		sb.append("<br><span style='color:").append(CombatAchievementsTheme.hex(CombatAchievementsTheme.DESC))
			.append("'>").append(CardKit.escape(row.description)).append("</span>");
		sb.append("<br><span style='color:").append(CombatAchievementsTheme.hex(CombatAchievementsTheme.POINTS))
			.append("'>").append(row.points).append(" pts</span>")
			.append(" <span style='color:" + CardKit.metaHex() + "'>· ").append(CardKit.escape(row.tierName)).append("</span>");
		if (row.difficulty > 0)
		{
			sb.append(" <span style='color:" + CardKit.metaHex() + "'>· </span><span style='color:")
				.append(CombatAchievementsTheme.hex(CardKit.difficultyColor(row.difficulty)))
				.append("'>difficulty ").append(row.difficulty).append("</span>");
		}
		sb.append("</body></html>");
		JLabel label = new JLabel(sb.toString());
		label.setBorder(BorderFactory.createEmptyBorder(0, 0, 3, 0));
		card.add(label, BorderLayout.CENTER);

		card.add(panel.linkRow(row.wikiUrl, row.guideUrl, row.curatedVideo), BorderLayout.SOUTH);
		CardKit.addHover(card, ColorScheme.DARK_GRAY_COLOR, ColorScheme.DARK_GRAY_HOVER_COLOR);
		CardKit.onClick(card, () -> {
			panel.setRoute(panel.route().withCa(row.detail));
			panel.rebuild();
		});
		return CardKit.fullWidth(card);
	}
}

package com.pluginideahub.combatachievements.ui.pages;

import com.pluginideahub.combatachievements.CombatAchievementsPanel;
import com.pluginideahub.combatachievements.core.ui.SidePanelViewModel;
import com.pluginideahub.combatachievements.ui.CardKit;
import com.pluginideahub.combatachievements.ui.CombatAchievementsTheme;
import java.awt.BorderLayout;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.Insets;
import java.util.ArrayList;
import java.util.Comparator;
import java.util.HashSet;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import java.util.Set;
import javax.swing.BorderFactory;
import javax.swing.JButton;
import javax.swing.JLabel;
import javax.swing.JPanel;
import net.runelite.client.ui.ColorScheme;
import net.runelite.client.ui.FontManager;

/** Renders the Route mode: unlock and training suggestions, then the boss-grouped path to the next tier. */
public class RoutePage
{
	private final CombatAchievementsPanel panel;
	private final JPanel content;

	public RoutePage(CombatAchievementsPanel panel)
	{
		this.panel = panel;
		this.content = panel.content();
	}

	/** The route to the next tier: unlock shortcuts first (a quest can open points faster than grinding),
	 *  then the CA steps. The unlock section is collapsible. */
	public void buildRoute()
	{
		SidePanelViewModel.PathView path = panel.model().path();
		List<SidePanelViewModel.UnlockView> unlocks = panel.model().unlocks();
		boolean haveUnlocks = unlocks != null && !unlocks.isEmpty();

		if (path == null && !haveUnlocks)
		{
			content.add(panel.messageLabel("Log in to see your route."));
			return;
		}

		// Unlocks on top: doing a quest can open a chunk of points faster than grinding CAs. Hideable.
		if (haveUnlocks)
		{
			content.add(panel.collapseHeader("Unlock next", panel.unlocksCollapsed(),
				() -> { panel.setUnlocksCollapsed(!panel.unlocksCollapsed()); panel.rebuild(); }));
			if (!panel.unlocksCollapsed())
			{
				content.add(CardKit.spacer());
				for (SidePanelViewModel.UnlockView u : unlocks)
				{
					content.add(unlockCard(u));
					content.add(CardKit.spacer());
				}
			}
			content.add(CardKit.spacer());
		}

		// "Train next": only present when the account is actually held back by levels, so it quietly
		// disappears once you can attempt things — no empty section for an established player.
		List<SidePanelViewModel.TrainingView> trainings = panel.model().trainings();
		if (trainings != null && !trainings.isEmpty())
		{
			content.add(panel.collapseHeader("Train next", panel.trainingsCollapsed(),
				() -> { panel.setTrainingsCollapsed(!panel.trainingsCollapsed()); panel.rebuild(); }));
			if (!panel.trainingsCollapsed())
			{
				content.add(CardKit.spacer());
				for (SidePanelViewModel.TrainingView t : trainings)
				{
					content.add(trainingCard(t));
					content.add(CardKit.spacer());
				}
			}
			content.add(CardKit.spacer());
		}

		if (path != null)
		{
			StringBuilder sb = new StringBuilder();
			sb.append("Goal: <b>").append(CardKit.escape(path.targetTierName)).append("</b>");
			if (path.alreadyUnlocked)
			{
				sb.append("<br><span style='color:")
					.append(CombatAchievementsTheme.hex(CombatAchievementsTheme.POSITIVE))
					.append("'>Already unlocked.</span>");
			}
			else
			{
				sb.append("<br>").append(path.pointsGap).append(" pts to go");
				if (path.trainFirst)
				{
					// The route stopped at what the account is ready for rather than padding it out with
					// content 40+ levels away. "Train next" sits directly above with the way forward.
					// Kept to two short lines: a long line clips mid-word at this panel width rather than
					// wrapping (a JLabel sizes itself from its own preferred width, so the body width style
					// does not rescue it).
					int within = path.steps.size();
					sb.append("<br><span style='color:")
						.append(CombatAchievementsTheme.hex(CombatAchievementsTheme.ACCENT))
						.append("'>").append(within).append(within == 1 ? " CA" : " CAs")
						.append(" within reach.<br>Train for the rest.</span>");
				}
				else if (!path.reachable)
				{
					sb.append("<br><span style='color:")
						.append(CombatAchievementsTheme.hex(CombatAchievementsTheme.ACCENT))
						.append("'>Not enough doable tasks yet —<br>shows the closest set.</span>");
				}
			}
			content.add(CardKit.fullWidth(CardKit.wrappedHtmlLabel(sb.toString(), CombatAchievementsPanel.CARD_TEXT_WIDTH)));
			content.add(CardKit.spacer());

			// Only CAs the player can go and do right now, grouped by boss so one trip clears several.
			// Nothing out of reach and nothing behind a quest: the Route is a plan to follow, and listing
			// content that cannot be attempted made the whole thing read as if it were all available. The
			// quest that would open more is recommended above, in Unlock next, where it can be acted on.
			List<SidePanelViewModel.CaDetail> route = new ArrayList<>();
			for (SidePanelViewModel.PathRow step : path.steps)
			{
				if (step.detail != null)
				{
					route.add(step.detail);
				}
			}

			// What the whole visible list is worth, so the total is readable without adding the cards up.
			if (!route.isEmpty())
			{
				StringBuilder tot = new StringBuilder();
				tot.append("<span style='color:" + CardKit.metaHex() + "'>").append(route.size())
					.append(route.size() == 1 ? " CA · " : " CAs · ")
					.append("</span><span style='color:")
					.append(CombatAchievementsTheme.hex(CombatAchievementsTheme.POINTS))
					.append("'>").append(path.shownPoints()).append(" pts</span>");
				content.add(CardKit.fullWidth(CardKit.wrappedHtmlLabel(tot.toString(), CombatAchievementsPanel.CARD_TEXT_WIDTH)));
				content.add(CardKit.spacer());
			}
			// Sits with the route it affects rather than in the control bar, and only exists once something
			// is actually pinned or barred.
			if (panel.routeCustomised() && panel.onResetCustom() != null)
			{
				content.add(panel.backButton("Reset custom CAs", () -> {
					if (panel.onResetCustom() != null)
					{
						panel.onResetCustom().run();
					}
				}));
				content.add(CardKit.spacer());
			}
			renderRouteGroups(route);

			// "Not doing these": the CAs barred out of the route, collapsible like Unlock/Train next, each
			// restorable on its own. Absent entirely when nothing is barred, so it costs nothing normally.
			List<SidePanelViewModel.CaDetail> barred = path.barredCas;
			if (barred != null && !barred.isEmpty())
			{
				content.add(CardKit.spacer());
				content.add(panel.collapseHeader("Not doing these", panel.barredCollapsed(),
					() -> { panel.setBarredCollapsed(!panel.barredCollapsed()); panel.rebuild(); }));
				if (!panel.barredCollapsed())
				{
					content.add(CardKit.spacer());
					for (SidePanelViewModel.CaDetail c : barred)
					{
						content.add(barredCard(c));
						content.add(CardKit.spacer());
					}
					if (barred.size() > 1 && panel.onClearBarred() != null)
					{
						content.add(panel.backButton("Restore all " + barred.size(), () -> {
							if (panel.onClearBarred() != null)
							{
								panel.onClearBarred().run();
							}
						}));
					}
				}
				content.add(CardKit.spacer());
			}
		}
	}

	/**
	 * Renders the route clustered by boss so the same boss's tasks sit together (one trip), with the groups
	 * ordered by their quickest task. A boss with two or more tasks gets a header.
	 */
	private void renderRouteGroups(List<SidePanelViewModel.CaDetail> route)
	{
		LinkedHashMap<String, List<SidePanelViewModel.CaDetail>> byBoss = new LinkedHashMap<>();
		Set<Integer> seen = new HashSet<>();
		for (SidePanelViewModel.CaDetail c : route)
		{
			// A Grandmaster (complete-all) route can list a CA as both a step and a locked CA — dedupe
			// by id (keep the first, the doable step) so it is not rendered twice or double-counted.
			if (!seen.add(c.id))
			{
				continue;
			}
			// No-boss tasks stay solo (unique key); real bosses cluster (case-insensitive).
			String key = c.monster.isEmpty() ? ("solo:" + c.id) : c.monster.toLowerCase(Locale.ROOT);
			byBoss.computeIfAbsent(key, k -> new ArrayList<>()).add(c);
		}
		// Groups keep the order the solver put their first task in, which already accounts for how ready the
		// player is. Sorting groups by raw time instead let one quick outlier drag a whole boss forward —
		// Bryophyta led the route off the back of "Quick Cutter" (kill a growthling with an axe) while its
		// other six tasks want 50 combat.
		Map<String, Integer> firstSeen = new LinkedHashMap<>();
		int order = 0;
		for (SidePanelViewModel.CaDetail c : route)
		{
			String key = c.monster.isEmpty() ? ("solo:" + c.id) : c.monster.toLowerCase(Locale.ROOT);
			firstSeen.putIfAbsent(key, order++);
		}
		List<Map.Entry<String, List<SidePanelViewModel.CaDetail>>> entries =
			new ArrayList<>(byBoss.entrySet());
		for (Map.Entry<String, List<SidePanelViewModel.CaDetail>> e : entries)
		{
			e.getValue().sort(Comparator.comparingInt(SidePanelViewModel.CaDetail::totalMinutes)
				.thenComparingInt(c -> -c.points));
		}
		entries.sort(Comparator.comparingInt(e -> firstSeen.getOrDefault(e.getKey(), Integer.MAX_VALUE)));
		List<List<SidePanelViewModel.CaDetail>> groups = new ArrayList<>();
		for (Map.Entry<String, List<SidePanelViewModel.CaDetail>> e : entries)
		{
			groups.add(e.getValue());
		}
		for (List<SidePanelViewModel.CaDetail> g : groups)
		{
			SidePanelViewModel.CaDetail first = g.get(0);
			// Every real boss gets a header, even a single-task one: a lone card sandwiched between two
			// headed clusters used to read as if it belonged to the cluster above it.
			boolean grouped = !first.monster.isEmpty();
			if (grouped)
			{
				content.add(routeGroupHeader(first.monster, g.size()));
			}
			for (SidePanelViewModel.CaDetail c : g)
			{
				content.add(routeCaCard(c, grouped));
				content.add(CardKit.spacer());
			}
		}
	}

	/** A small boss header for a route cluster: "General Graardor · 3 tasks". */
	private JPanel routeGroupHeader(String boss, int count)
	{
		// Just the boss name: the cards beneath it already show how many there are, and keeping it short
		// avoids the clipping a longer label hit ("Deranged Archaeologist · 2 tasks" cut off mid-word —
		// Swing sizes an HTML label from its own preferred width, so a body-width wrap doesn't rescue it).
		JLabel label = new JLabel(CardKit.escape(boss));
		label.setFont(FontManager.getRunescapeBoldFont());
		label.setForeground(CombatAchievementsTheme.HEADER_GOLD);

		JPanel row = new JPanel(new BorderLayout());
		row.setOpaque(false);
		row.setBorder(BorderFactory.createEmptyBorder(6, 0, 2, 0));
		row.add(label, BorderLayout.CENTER);

		// Clicking the boss name opens that boss, so a route group is a way in to everything else there.
		// Formatting is untouched — only a hand cursor and a hover tint mark it as clickable — and it is
		// only wired up when the boss actually has a page, so it can never be a dead click.
		if (panel.bossExists(boss))
		{
			Runnable openBoss = () -> {
				panel.setRoute(panel.route().toBoss(boss));
				panel.buildModeBar();
				panel.rebuild();
			};
			CardKit.addForegroundHover(label, CombatAchievementsTheme.HEADER_GOLD, CombatAchievementsTheme.NAME);
			// The listener has to go on the LABEL as well as the row. AWT does not bubble mouse events the
			// way the DOM does: a component with any listener of its own consumes them, and the hover tint
			// above gives the label one — so a click on the name never reached a row-only handler.
			CardKit.onClick(label, openBoss);
			CardKit.onClick(row, openBoss);
		}
		return CardKit.fullWidth(row);
	}

	private JPanel routeCaCard(SidePanelViewModel.CaDetail c, boolean grouped)
	{
		final int textWidth = panel.onBarTask() != null
			? CombatAchievementsPanel.ROUTE_TEXT_WIDTH - CombatAchievementsPanel.BAR_BUTTON_WIDTH
			: CombatAchievementsPanel.ROUTE_TEXT_WIDTH;
		JPanel card = new JPanel(new BorderLayout());
		card.setBackground(ColorScheme.DARK_GRAY_COLOR);
		Color accent = c.doableNow ? CombatAchievementsTheme.NAME : CombatAchievementsTheme.NEGATIVE;
		card.setBorder(BorderFactory.createCompoundBorder(
			BorderFactory.createMatteBorder(0, 3, 0, 0, accent),
			BorderFactory.createEmptyBorder(5, 7, 5, 7)));
		StringBuilder sb = new StringBuilder("<html><body style='width:" + textWidth + "px'>");
		sb.append("<span style='color:").append(CombatAchievementsTheme.hex(accent))
			.append("'><b>").append(CardKit.escape(c.name)).append("</b></span>");
		sb.append("<br><span style='color:").append(CombatAchievementsTheme.hex(CombatAchievementsTheme.POINTS))
			.append("'>").append(c.points).append(" pts</span>");
		if (c.difficulty > 0)
		{
			sb.append(" <span style='color:" + CardKit.metaHex() + "'>· </span><span style='color:")
				.append(CombatAchievementsTheme.hex(CardKit.difficultyColor(c.difficulty)))
				.append("'>difficulty ").append(c.difficulty).append("</span>");
		}
		// Time estimates are intentionally not shown — the engine still uses them for ordering.
		// When not under a boss header, name the boss so a solo route step still tells you where to go.
		if (!grouped && !c.monster.isEmpty())
		{
			sb.append("<br><span style='color:" + CardKit.metaHex() + "'>").append(CardKit.escape(c.monster)).append("</span>");
		}
		if (!c.doableNow && !c.lockReason.isEmpty())
		{
			sb.append("<br><span style='color:").append(CombatAchievementsTheme.hex(CombatAchievementsTheme.NEGATIVE))
				.append("'>").append(CardKit.escape(c.lockReason)).append("</span>");
		}
		sb.append("</body></html>");
		JLabel routeLabel = new JLabel(sb.toString());
		// The HTML body width only drives WRAPPING; the label still reports a wider preferred size,
		// which pushed the card past the panel and clipped the "-" clean off the right edge.
		Dimension routePref = routeLabel.getPreferredSize();
		Dimension capped = new Dimension(Math.min(routePref.width, textWidth), routePref.height);
		routeLabel.setPreferredSize(capped);
		routeLabel.setMaximumSize(capped);
		card.add(routeLabel, BorderLayout.CENTER);
		// "Not doing that one" — bars the task so the solver closes the gap with the next best instead.
		if (panel.onBarTask() != null)
		{
			card.add(barButton(c), BorderLayout.EAST);
		}
		CardKit.addHover(card, ColorScheme.DARK_GRAY_COLOR, ColorScheme.DARK_GRAY_HOVER_COLOR);
		CardKit.onClick(card, () -> {
			panel.setRoute(panel.route().withCa(c));
			panel.rebuild();
		});
		CardKit.fullWidth(card);
		card.setMaximumSize(new Dimension(CombatAchievementsPanel.ROUTE_CARD_MAX_WIDTH, card.getPreferredSize().height));
		return card;
	}

	/**
	 * A barred CA, listed under "Not doing these". Same card shape as the route, with a "+" that puts this
	 * one back in the running instead of the "-" that took it out.
	 */
	private JPanel barredCard(SidePanelViewModel.CaDetail c)
	{
		JPanel card = new JPanel(new BorderLayout());
		card.setBackground(ColorScheme.DARK_GRAY_COLOR);
		card.setBorder(BorderFactory.createCompoundBorder(
			BorderFactory.createMatteBorder(0, 3, 0, 0, CombatAchievementsTheme.LOCKED),
			BorderFactory.createEmptyBorder(5, 7, 5, 7)));

		int textWidth = CombatAchievementsPanel.ROUTE_TEXT_WIDTH - CombatAchievementsPanel.BAR_BUTTON_WIDTH;
		StringBuilder sb = new StringBuilder("<html><body style='width:" + textWidth + "px'>");
		sb.append("<span style='color:").append(CombatAchievementsTheme.hex(CombatAchievementsTheme.LOCKED))
			.append("'><b>").append(CardKit.escape(c.name)).append("</b></span>");
		sb.append("<br><span style='color:" + CardKit.metaHex() + "'>").append(c.points)
			.append(c.points == 1 ? " pt" : " pts");
		if (!c.monster.isEmpty())
		{
			sb.append(" · ").append(CardKit.escape(c.monster));
		}
		sb.append("</span></body></html>");
		JLabel label = new JLabel(sb.toString());
		Dimension pref = label.getPreferredSize();
		Dimension capped = new Dimension(Math.min(pref.width, textWidth), pref.height);
		label.setPreferredSize(capped);
		label.setMaximumSize(capped);
		card.add(label, BorderLayout.CENTER);

		if (panel.onUnbarTask() != null)
		{
			JButton restore = new JButton("+");
			// Matches the route card's "-" in weight and size: they are a pair, and a small "+" against a
			// bold "-" reads as two unrelated controls.
			restore.setFont(FontManager.getRunescapeBoldFont());
			restore.setToolTipText("Put " + c.name + " back in the route");
			restore.setFocusPainted(false);
			restore.setBorderPainted(false);
			restore.setContentAreaFilled(false);
			restore.setOpaque(false);
			restore.setForeground(CombatAchievementsTheme.POSITIVE);
			CardKit.addForegroundHover(restore, CombatAchievementsTheme.POSITIVE,
				CombatAchievementsTheme.NAME);
			restore.setBorder(BorderFactory.createEmptyBorder(0, 4, 0, 0));
			restore.setPreferredSize(new Dimension(CombatAchievementsPanel.BAR_BUTTON_WIDTH, 18));
			restore.setCursor(java.awt.Cursor.getPredefinedCursor(java.awt.Cursor.HAND_CURSOR));
			restore.addActionListener(e -> {
				if (panel.onUnbarTask() != null)
				{
					panel.onUnbarTask().accept(c.id);
				}
			});
			card.add(restore, BorderLayout.EAST);
		}
		CardKit.addHover(card, ColorScheme.DARK_GRAY_COLOR, ColorScheme.DARK_GRAY_HOVER_COLOR);
		CardKit.onClick(card, () -> {
			panel.setRoute(panel.route().withCa(c));
			panel.rebuild();
		});
		CardKit.fullWidth(card);
		card.setMaximumSize(new Dimension(CombatAchievementsPanel.ROUTE_CARD_MAX_WIDTH, card.getPreferredSize().height));
		return card;
	}

	/**
	 * The small "−" on a route card. Kept visually quiet so it never competes with the task name, and it
	 * consumes its own click so barring a task cannot also open its detail.
	 */
	private JButton barButton(SidePanelViewModel.CaDetail c)
	{
		// Plain ASCII "-": the RuneScape font does not carry U+2212, which rendered as nothing.
		JButton bar = new JButton("-");
		// Bigger than the card text and tinted toward the theme's negative, so it reads as a remove
		// control at a glance. Muted rather than full red at rest - it is an option, not a warning - and
		// it comes up to the full negative on hover.
		bar.setFont(FontManager.getRunescapeBoldFont());
		bar.setToolTipText("Don't show " + c.name + " in the route");
		bar.setFocusPainted(false);
		bar.setBorderPainted(false);
		bar.setContentAreaFilled(false);
		bar.setOpaque(false);
		Color barIdle = CombatAchievementsPanel.blend(CombatAchievementsTheme.NEUTRAL_META,
			CombatAchievementsTheme.NEGATIVE, 0.72);
		bar.setForeground(barIdle);
		CardKit.addForegroundHover(bar, barIdle, CombatAchievementsTheme.NEGATIVE);
		bar.setPreferredSize(new Dimension(CombatAchievementsPanel.BAR_BUTTON_WIDTH, 18));
		bar.setMargin(new Insets(0, 4, 0, 0));
		bar.setBorder(BorderFactory.createEmptyBorder(0, 4, 0, 0));
		bar.setCursor(java.awt.Cursor.getPredefinedCursor(java.awt.Cursor.HAND_CURSOR));
		bar.addActionListener(e -> {
			if (panel.onBarTask() != null)
			{
				panel.onBarTask().accept(c.id);
			}
		});
		return bar;
	}

	/** A "train X to N" goal: what it opens and roughly how long, styled as a quieter sibling of unlockCard. */
	private JPanel trainingCard(SidePanelViewModel.TrainingView t)
	{
		JPanel card = new JPanel(new BorderLayout());
		card.setBackground(ColorScheme.DARK_GRAY_COLOR);
		card.setBorder(BorderFactory.createCompoundBorder(
			BorderFactory.createMatteBorder(0, 3, 0, 0, CombatAchievementsTheme.ACCENT),
			BorderFactory.createEmptyBorder(5, 7, 5, 7)));

		StringBuilder sb = new StringBuilder();
		sb.append("<span style='color:").append(CombatAchievementsTheme.hex(CombatAchievementsTheme.HEADER_GOLD))
			.append("'><b>").append(CardKit.escape(t.label)).append("</b></span>");
		sb.append("<br><span style='color:").append(CombatAchievementsTheme.hex(CombatAchievementsTheme.POSITIVE))
			.append("'>").append(t.toward ? "toward " : "opens ").append(t.unlockedTaskCount)
			.append(t.unlockedTaskCount == 1 ? " CA (" : " CAs (")
			.append(t.unlockedPoints).append(t.unlockedPoints == 1 ? " pt)</span>" : " pts)</span>");
		// Just the stat and the prize; naming a boss here read oddly when the nearest rec happened
		// to be some niche monster.
		card.add(CardKit.wrappedHtmlLabel(sb.toString(), CombatAchievementsPanel.CARD_TEXT_WIDTH), BorderLayout.CENTER);
		CardKit.addHover(card, ColorScheme.DARK_GRAY_COLOR, ColorScheme.DARK_GRAY_HOVER_COLOR);
		return CardKit.fullWidth(card);
	}

	/** The unlock card's text (inner html, for {@link CardKit#wrappedHtmlLabel}): quest, difficulty, prize,
	 *  prerequisites, unmet skills. Shared with the quest drill-in header so the two can never drift. */
	String unlockCardHtml(SidePanelViewModel.UnlockView u)
	{
		StringBuilder sb = new StringBuilder();
		sb.append("<span style='color:").append(CombatAchievementsTheme.hex(CombatAchievementsTheme.HEADER_GOLD))
			.append("'><b>").append(CardKit.escape(u.questName)).append("</b></span>");
		if (u.difficulty != null && !u.difficulty.isEmpty())
		{
			sb.append(" <span style='color:" + CardKit.metaHex() + "'>· ").append(CardKit.escape(u.difficulty)).append("</span>");
		}
		sb.append("<br><span style='color:").append(CombatAchievementsTheme.hex(CombatAchievementsTheme.POSITIVE))
			.append("'>unlocks ").append(u.unlockedTaskCount).append(" CAs (").append(u.unlockedPoints)
			.append(" pts)</span>");
		// One prerequisite gets named; a chain becomes a count — A Kingdom Divided's seven-quest
		// comma wall made the card unreadable. The drill-in page lists the chain properly.
		if (!u.prerequisiteList.isEmpty())
		{
			String first = u.prerequisiteList.size() == 1
				? "first: " + u.prerequisiteList.get(0)
				: u.prerequisiteList.size() + " quests first";
			sb.append("<br><span style='color:").append(CombatAchievementsTheme.hex(CombatAchievementsTheme.DESC))
				.append("'>").append(CardKit.escape(first)).append("</span>");
		}
		// Same rule as the quest chain: one stat gets named, several become a count.
		if (!u.unmetSkillList.isEmpty())
		{
			String train = u.unmetSkillList.size() == 1
				? "train: " + trainGoal(u.unmetSkillList.get(0))
				: u.unmetSkillList.size() + " stats to train";
			sb.append("<br><span style='color:").append(CombatAchievementsTheme.hex(CombatAchievementsTheme.LOCKED))
				.append("'>").append(CardKit.escape(train)).append("</span>");
		}
		return sb.toString();
	}

	/** "Magic 3→75" → "Magic 75": on a card only the goal matters, the drill-in shows the journey. */
	private static String trainGoal(String raw)
	{
		int arrow = raw.indexOf('→');
		if (arrow < 0)
		{
			return raw;
		}
		String head = raw.substring(0, arrow).trim();
		int lastSpace = head.lastIndexOf(' ');
		String skill = lastSpace > 0 ? head.substring(0, lastSpace) : head;
		return skill + " " + raw.substring(arrow + 1).trim();
	}

	private JPanel unlockCard(SidePanelViewModel.UnlockView u)
	{
		JPanel card = new JPanel(new BorderLayout());
		card.setBackground(ColorScheme.DARK_GRAY_COLOR);
		card.setBorder(BorderFactory.createCompoundBorder(
			BorderFactory.createMatteBorder(0, 3, 0, 0, CombatAchievementsTheme.HEADER_GOLD),
			BorderFactory.createEmptyBorder(5, 7, 5, 7)));
		card.add(CardKit.wrappedHtmlLabel(unlockCardHtml(u), CombatAchievementsPanel.CARD_TEXT_WIDTH), BorderLayout.CENTER);
		CardKit.addHover(card, ColorScheme.DARK_GRAY_COLOR, ColorScheme.DARK_GRAY_HOVER_COLOR);
		if (!u.unlockedCas.isEmpty())
		{
			CardKit.onClick(card, () -> {
				panel.setRoute(panel.route().withUnlock(u));
				panel.expandedUnlockBosses().clear();
				panel.setUnlockPrereqsExpanded(false);
				panel.setUnlockStatsExpanded(false);
				panel.rebuild();
			});
		}
		return CardKit.fullWidth(card);
	}
}

package com.pluginideahub.combatachievements.ui.pages;

import com.pluginideahub.combatachievements.CombatAchievementsPanel;
import com.pluginideahub.combatachievements.core.ui.PanelMode;
import com.pluginideahub.combatachievements.core.ui.SidePanelViewModel;
import com.pluginideahub.combatachievements.ui.CardKit;
import com.pluginideahub.combatachievements.ui.CombatAchievementsTheme;
import com.pluginideahub.combatachievements.ui.PanelRoute;
import java.awt.BorderLayout;
import java.awt.Component;
import java.awt.Dimension;
import java.awt.FlowLayout;
import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import javax.swing.BorderFactory;
import javax.swing.BoxLayout;
import javax.swing.JLabel;
import javax.swing.JPanel;
import net.runelite.client.ui.ColorScheme;
import net.runelite.client.ui.FontManager;

/** Renders the quest-unlock drill-in: the quest's headline card, then the CAs it opens, by boss. */
public class UnlockDetailPage
{
	private final CombatAchievementsPanel panel;
	/** The Route page owns the unlock card html this page's header shares. */
	private final RoutePage routePage;
	private final JPanel content;

	public UnlockDetailPage(CombatAchievementsPanel panel, RoutePage routePage)
	{
		this.panel = panel;
		this.routePage = routePage;
		this.content = panel.content();
	}

	/** The quest-unlock drill-in: the quest's headline, then the CAs it opens, each clickable. */
	public void renderUnlockDetail(SidePanelViewModel.UnlockView u)
	{
		content.add(panel.backButton("← Back", () -> {
			panel.setRoute(panel.route().clearUnlock());
			panel.rebuild();
		}));
		content.add(CardKit.spacer());

		// The same card the Route shows, minus the click: an html JLabel added bare to the BoxLayout
		// clips long lines at the panel edge (its CSS body width is unreliable), while the card's
		// BorderLayout demonstrably wraps this exact content in the Route list.
		JPanel header = new JPanel(new BorderLayout());
		header.setBackground(ColorScheme.DARK_GRAY_COLOR);
		header.setBorder(BorderFactory.createCompoundBorder(
			BorderFactory.createMatteBorder(0, 3, 0, 0, CombatAchievementsTheme.HEADER_GOLD),
			BorderFactory.createEmptyBorder(5, 7, 5, 7)));
		header.add(CardKit.wrappedHtmlLabel(routePage.unlockCardHtml(u), CombatAchievementsPanel.CARD_TEXT_WIDTH),
			BorderLayout.CENTER);
		content.add(CardKit.fullWidth(header));
		content.add(CardKit.spacer());

		if (!u.questWikiUrl.isEmpty())
		{
			JPanel links = new JPanel(new FlowLayout(FlowLayout.LEFT, 4, 1));
			links.setOpaque(false);
			links.add(CardKit.linkButton("Wiki", u.questWikiUrl));
			content.add(CardKit.fullWidth(links));
			content.add(CardKit.spacer());
		}

		// The prerequisite chain as its own foldable section, one quest per line in chain order —
		// prose on the card turned into a wall for the long questlines.
		if (!u.prerequisiteList.isEmpty())
		{
			content.add(panel.collapseHeader("Quests first · " + u.prerequisiteList.size(),
				!panel.unlockPrereqsExpanded(),
				() -> { panel.setUnlockPrereqsExpanded(!panel.unlockPrereqsExpanded()); panel.rebuild(); }));
			if (panel.unlockPrereqsExpanded())
			{
				content.add(CardKit.spacer());
				for (String quest : u.prerequisiteList)
				{
					JLabel row = new JLabel(CardKit.escape(quest));
					row.setFont(FontManager.getRunescapeSmallFont());
					row.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
					row.setBorder(BorderFactory.createEmptyBorder(1, 10, 1, 0));
					content.add(CardKit.fullWidth(row));
				}
			}
			content.add(CardKit.spacer());
		}

		// The chain's unmet stats, same shape as the quest list: a count on the card, the detail here.
		if (!u.unmetSkillList.isEmpty())
		{
			content.add(panel.collapseHeader("Stats first · " + u.unmetSkillList.size(),
				!panel.unlockStatsExpanded(),
				() -> { panel.setUnlockStatsExpanded(!panel.unlockStatsExpanded()); panel.rebuild(); }));
			if (panel.unlockStatsExpanded())
			{
				content.add(CardKit.spacer());
				for (String stat : u.unmetSkillList)
				{
					JLabel row = new JLabel(CardKit.escape(stat.replace("→", " → ")));
					row.setFont(FontManager.getRunescapeSmallFont());
					row.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
					row.setBorder(BorderFactory.createEmptyBorder(1, 10, 1, 0));
					content.add(CardKit.fullWidth(row));
				}
			}
			content.add(CardKit.spacer());
		}

		// Grouped by boss, same as the Route: each boss header is a way in to its page, with the
		// prize at that boss beside it. Group order follows the quickest-first CA order.
		content.add(panel.sectionHeader("Unlocks"));
		content.add(CardKit.spacer());
		LinkedHashMap<String, List<SidePanelViewModel.CaDetail>> byBoss = new LinkedHashMap<>();
		for (SidePanelViewModel.CaDetail c : u.unlockedCas)
		{
			byBoss.computeIfAbsent(c.monster.isEmpty() ? "Other" : c.monster,
				k -> new ArrayList<>()).add(c);
		}
		for (Map.Entry<String, List<SidePanelViewModel.CaDetail>> e : byBoss.entrySet())
		{
			int pts = 0;
			for (SidePanelViewModel.CaDetail c : e.getValue())
			{
				pts += c.points;
			}
			boolean expanded = panel.expandedUnlockBosses().contains(e.getKey());
			content.add(unlockBossHeader(e.getKey(), e.getValue().size(), pts, expanded));
			content.add(CardKit.spacer());
			if (expanded)
			{
				for (SidePanelViewModel.CaDetail c : e.getValue())
				{
					content.add(unlockCaCard(c));
					content.add(CardKit.spacer());
				}
			}
		}
	}

	/**
	 * A boss group header on the quest page: an arrow that shows/hides the group's CAs (all groups
	 * start closed), the boss name — clickable through to the boss page when it has one — and the
	 * group's share of the prize.
	 */
	private JPanel unlockBossHeader(String boss, int count, int points, boolean expanded)
	{
		JLabel arrow = new JLabel(expanded ? "▾ " : "▸ ");
		arrow.setFont(FontManager.getRunescapeBoldFont());
		arrow.setForeground(CombatAchievementsTheme.HEADER_GOLD);

		JLabel label = new JLabel(CardKit.escape(boss));
		label.setFont(FontManager.getRunescapeBoldFont());
		label.setForeground(CombatAchievementsTheme.HEADER_GOLD);

		JLabel meta = new JLabel(count + (count == 1 ? " CA · " : " CAs · ") + points + " pts");
		meta.setFont(FontManager.getRunescapeSmallFont());
		meta.setForeground(ColorScheme.LIGHT_GRAY_COLOR);

		// The prize goes UNDER the name, not beside it: three "Tombs of Am…" rows squeezed against
		// an inline count were indistinguishable, and the boss name is the part that must survive.
		JPanel textCol = new JPanel();
		textCol.setOpaque(false);
		textCol.setLayout(new BoxLayout(textCol, BoxLayout.Y_AXIS));
		label.setAlignmentX(Component.LEFT_ALIGNMENT);
		meta.setAlignmentX(Component.LEFT_ALIGNMENT);
		textCol.add(label);
		textCol.add(meta);

		JPanel row = new JPanel(new BorderLayout(4, 0));
		row.setOpaque(false);
		row.setBorder(BorderFactory.createEmptyBorder(6, 0, 2, 0));
		row.add(arrow, BorderLayout.WEST);
		row.add(textCol, BorderLayout.CENTER);
		// Cap the row's preferred width or a long name widens the whole content column past the panel
		// (the widest-child trap; same cap as the route cards). The name still ellipsizes past this.
		row.setPreferredSize(new Dimension(CombatAchievementsPanel.ROUTE_TEXT_WIDTH, row.getPreferredSize().height));

		Runnable toggle = () -> {
			if (!panel.expandedUnlockBosses().remove(boss))
			{
				panel.expandedUnlockBosses().add(boss);
			}
			panel.rebuild();
		};
		// The row (and the arrow) toggle the group; the boss NAME jumps to the boss page instead,
		// when there is one. AWT does not bubble mouse events, so each part needs its own handler —
		// the name's hover listener alone would swallow clicks meant for the row.
		CardKit.onClick(arrow, toggle);
		CardKit.onClick(row, toggle);
		if (panel.bossExists(boss))
		{
			Runnable openBoss = () -> {
				panel.setRoute(PanelRoute.of(PanelMode.BOSSES).withBoss(boss));
				panel.buildModeBar();
				panel.rebuild();
			};
			CardKit.addForegroundHover(label, CombatAchievementsTheme.HEADER_GOLD, CombatAchievementsTheme.NAME);
			CardKit.onClick(label, openBoss);
		}
		else
		{
			CardKit.onClick(label, toggle);
		}
		return CardKit.fullWidth(row);
	}

	/** A CA the quest would open, on the quest's own page — grouped under its boss header, so no
	 *  per-card monster or "needs <quest>" line. */
	private JPanel unlockCaCard(SidePanelViewModel.CaDetail c)
	{
		JPanel card = new JPanel(new BorderLayout());
		card.setBackground(ColorScheme.DARK_GRAY_COLOR);
		card.setBorder(BorderFactory.createCompoundBorder(
			BorderFactory.createMatteBorder(0, 3, 0, 0, CombatAchievementsTheme.NAME),
			BorderFactory.createEmptyBorder(5, 7, 5, 7)));

		StringBuilder sb = new StringBuilder();
		sb.append("<span style='color:").append(CombatAchievementsTheme.hex(CombatAchievementsTheme.NAME))
			.append("'><b>").append(CardKit.escape(c.name)).append("</b></span>");
		sb.append("<br><span style='color:").append(CombatAchievementsTheme.hex(CombatAchievementsTheme.POINTS))
			.append("'>").append(c.points).append(" pts</span>");
		if (c.difficulty > 0)
		{
			sb.append(" <span style='color:" + CardKit.metaHex() + "'>· </span><span style='color:")
				.append(CombatAchievementsTheme.hex(CardKit.difficultyColor(c.difficulty)))
				.append("'>difficulty ").append(c.difficulty).append("</span>");
		}
		card.add(CardKit.wrappedHtmlLabel(sb.toString(), CombatAchievementsPanel.CARD_TEXT_WIDTH), BorderLayout.CENTER);
		CardKit.addHover(card, ColorScheme.DARK_GRAY_COLOR, ColorScheme.DARK_GRAY_HOVER_COLOR);
		CardKit.onClick(card, () -> {
			panel.setRoute(panel.route().withCa(c));
			panel.rebuild();
		});
		return CardKit.fullWidth(card);
	}
}

package com.pluginideahub.combatachievements.varbit;

import net.runelite.api.Client;
import net.runelite.api.gameval.VarPlayerID;
import net.runelite.api.gameval.VarbitID;

/**
 * Reads Combat Achievement task completion from the live client.
 *
 * <p>Completion is stored as a <b>packed bitfield across VarPlayers</b>
 * ({@code CA_TASK_COMPLETED_0 ..}, 32 tasks per varp): task {@code id}'s completion is bit
 * {@code id % 32} of varp {@code id / 32}. The task {@code id} here is the in-game CA struct's id
 * param (1306), which we validated equals our dataset id (see {@code data/struct-id-bridge.json}).
 * When Jagex adds tasks past the current capacity the game gains a new varp; the cache calls them
 * {@code ca_task_completed_N}. {@link CaVarbitIdsTest} fails the build when the bundled dataset
 * outgrows this list, which is exactly what happened at 646 tasks (Maggot King, bits 640-645).</p>
 *
 * <p>The varps are RuneLite {@code gameval} constants, so they track game updates rather than
 * hard-coded raw ids. Mechanism confirmed against the open-source {@code combat-achievements-tracker}
 * plugin (BSD-2-Clause) and the RuneLite API; see docs/DESIGN.md §5.1.1.</p>
 */
public final class CaVarbitIds
{
	private CaVarbitIds()
	{
	}

	/** The completion-reading mechanism is confirmed and live. */
	public static final boolean VERIFIED = true;

	private static final int[] COMPLETION_VARPS = {
		VarPlayerID.CA_TASK_COMPLETED_0, VarPlayerID.CA_TASK_COMPLETED_1,
		VarPlayerID.CA_TASK_COMPLETED_2, VarPlayerID.CA_TASK_COMPLETED_3,
		VarPlayerID.CA_TASK_COMPLETED_4, VarPlayerID.CA_TASK_COMPLETED_5,
		VarPlayerID.CA_TASK_COMPLETED_6, VarPlayerID.CA_TASK_COMPLETED_7,
		VarPlayerID.CA_TASK_COMPLETED_8, VarPlayerID.CA_TASK_COMPLETED_9,
		VarPlayerID.CA_TASK_COMPLETED_10, VarPlayerID.CA_TASK_COMPLETED_11,
		VarPlayerID.CA_TASK_COMPLETED_12, VarPlayerID.CA_TASK_COMPLETED_13,
		VarPlayerID.CA_TASK_COMPLETED_14, VarPlayerID.CA_TASK_COMPLETED_15,
		VarPlayerID.CA_TASK_COMPLETED_16, VarPlayerID.CA_TASK_COMPLETED_17,
		VarPlayerID.CA_TASK_COMPLETED_18, VarPlayerID.CA_TASK_COMPLETED_19,
		// ca_task_completed_20: not yet in RuneLite's gameval (their VarPlayerID stops at _19), so the
		// raw id from the cache dump until they add it. Holds tasks 640-671; Maggot King lives here.
		5673,
	};

	/** True when task {@code taskId} is complete on the logged-in account. Call on the client thread. */
	public static boolean isComplete(Client client, int taskId)
	{
		if (client == null || taskId < 0 || taskId >= COMPLETION_VARPS.length * 32)
		{
			return false;
		}
		int varpValue = client.getVarpValue(COMPLETION_VARPS[taskId / 32]);
		return (varpValue & (1 << (taskId % 32))) != 0;
	}

	/** The number of completion varps backing the bitfield (used to bound id ranges / sanity checks). */
	public static int varpCount()
	{
		return COMPLETION_VARPS.length;
	}

	/**
	 * True when {@code varpId} is one of the 20 CA-completion varps. Lets a VarbitChanged handler ignore
	 * the flood of unrelated varp changes (which is most of them, especially on login) and only refresh
	 * when a completion bit could have changed.
	 */
	public static boolean isCompletionVarp(int varpId)
	{
		for (int v : COMPLETION_VARPS)
		{
			if (v == varpId)
			{
				return true;
			}
		}
		return false;
	}

	/**
	 * Total CA points as the game itself counts them ({@code VarbitID.CA_POINTS}). Ground truth for
	 * tier maths: it stays right even when the bundled dataset or the bitfield above lags a game
	 * update, which is the failure the derived sum cannot see. 0 before login / before the varbit
	 * syncs; the reader falls back to the derived sum then.
	 */
	public static int readTotalPoints(Client client)
	{
		return client == null ? 0 : client.getVarbitValue(VarbitID.CA_POINTS);
	}
}

package com.pluginideahub.combatachievements.varbit;

import com.pluginideahub.combatachievements.core.achievement.CombatAchievement;
import com.pluginideahub.combatachievements.core.achievement.CombatAchievementLibrary;
import com.pluginideahub.combatachievements.core.progress.ProgressSnapshot;
import com.pluginideahub.combatachievements.core.tier.TierMath;
import java.util.HashSet;
import java.util.Map;
import java.util.Set;
import net.runelite.api.Client;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

/**
 * Reads the live account's Combat Achievement completion into a pure {@link ProgressSnapshot}. The
 * only place that touches {@link Client} for progress. Must run on the client thread (varbit/varp
 * reads are only valid there). See docs/DESIGN.md §5.2.
 *
 * <p>The game's own points varp is treated as ground truth for tier unlocks; the dataset-summed
 * {@code computedPoints} is kept for the per-task breakdown and as a staleness signal.</p>
 */
public final class CombatAchievementVarbitReader
{
	private static final Logger log = LoggerFactory.getLogger(CombatAchievementVarbitReader.class);

	/** True once {@link CaVarbitIds} holds confirmed IDs; gates whether the reader can be trusted. */
	public boolean isVerified()
	{
		return CaVarbitIds.VERIFIED;
	}

	/** Full read of the logged-in account. Caller guarantees the client thread. */
	public ProgressSnapshot read(Client client, CombatAchievementLibrary lib)
	{
		if (client == null || lib == null)
		{
			return ProgressSnapshot.absent();
		}

		Map<Integer, Integer> pointsById = lib.pointsById();
		Set<Integer> completed = new HashSet<>();
		for (CombatAchievement task : lib.all())
		{
			if (CaVarbitIds.isComplete(client, task.id()))
			{
				completed.add(task.id());
			}
		}

		int computedPoints = 0;
		for (Integer id : completed)
		{
			computedPoints += pointsById.getOrDefault(id, 0);
		}

		int gamePoints = CaVarbitIds.readTotalPoints(client);
		if (gamePoints <= 0)
		{
			// Varbit not synced yet (pre-login read) — fall back to the derived sum.
			gamePoints = computedPoints;
		}
		else if (gamePoints != computedPoints)
		{
			// The game says a different total than our task sum: the dataset or the bitfield is lagging
			// a game update. Tier maths stays right (it uses gamePoints); the task list is what's stale.
			log.debug("CA points mismatch: game says {}, dataset sum is {}", gamePoints, computedPoints);
		}
		long accountHash = client.getAccountHash();

		return new ProgressSnapshot(
			completed,
			computedPoints,
			gamePoints,
			TierMath.currentTierFor(gamePoints, lib.all()),
			accountHash);
	}
}

package com.pluginideahub.combatachievements;

import com.pluginideahub.combatachievements.core.achievement.CombatAchievementLibrary;
