import com.pluginideahub.combatachievements.core.ranking.ProfileSignalsProvider;
import com.pluginideahub.combatachievements.core.ui.SidePanelViewModel;
import com.pluginideahub.combatachievements.core.ui.SidePanelViewModelBuilder;
import com.pluginideahub.combatachievements.core.video.VideoGuideLibrary;
import java.util.Arrays;
import java.util.Collections;
import java.util.HashMap;
import java.util.HashSet;
import java.util.Map;
import java.util.Set;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;

/**
 * The beginner rule: raid / coordinated group content ("Endgame access") is held back until the player has
 * unlocked the Easy tier — UNLESS they are already 70+ combat, which means an established player who simply
 * has not started Combat Achievements and must not be treated as new.
 */
public class BeginnerGateTest
{
	private final CombatAchievementLibrary lib = CombatAchievementLibrary.loadBundled();
	private final EffortDataLibrary effort = EffortDataLibrary.loadBundled();
	private final RecStatsLibrary recStats = RecStatsLibrary.loadBundled();
	private final BossDifficultyLibrary bossDiff = BossDifficultyLibrary.loadBundled();

	private static PlayerProfile account(int everyStat)
	{
		Map<String, Integer> levels = new HashMap<>();
		for (String s : new String[]{"Attack", "Strength", "Defence", "Ranged", "Magic", "Prayer", "Slayer",
			"Mining", "Herblore", "Farming", "Construction", "Agility", "Thieving", "Firemaking", "Fishing",
			"Woodcutting", "Crafting", "Fletching", "Runecraft", "Hunter", "Smithing", "Cooking"})
		{
			levels.put(s, everyStat);
		}
		levels.put("Hitpoints", Math.max(10, everyStat));
		Set<String> quests = new HashSet<>(Arrays.asList(
			"Priest in Peril", "The Restless Ghost", "Children of the Sun"));
		return PlayerProfile.of(levels, quests, quests);
	}

	/** Endgame-access tasks surfaced in the CAs list, for an account with no CA points yet. */
	private long gatedShown(PlayerProfile profile)
	{
		SidePanelViewModel vm = new SidePanelViewModelBuilder(lib, effort, VideoGuideLibrary.loadBundled(),
			GuideLibrary.loadBundled(), TierRewardLibrary.loadBundled(), EffortModel.standard())
			.difficulty(TaskDifficultyLibrary.loadBundled())
			.recStats(recStats)
			.bossDifficulty(bossDiff)
			.detail(TaskDetailLibrary.loadBundled())
			.effortEngine(BossTimingLibrary.loadBundled(), QuestEffortLibrary.loadBundled(),
				SkillXpLibrary.loadBundled(), CombatExperience.empty(), profile, 6)
			.build(new ProgressSnapshot(Collections.emptySet(), 0, 0, null, 1L),
				new ProfileSignalsProvider(effort, recStats, profile), null);
		return vm.quickWins().stream().filter(r -> bossDiff.isEndgameAccess(r.monster)).count();
	}

	@Test
	public void combatLevelMatchesTheGameFormula()
	{
		assertEquals("a brand-new account is combat 3", 3, account(1).combatLevel());
		assertEquals("all 99s is the max combat level", 126, account(99).combatLevel());
	}

	@Test
	public void aBeginnerIsNotShownRaidContent()
	{
		PlayerProfile fresh = account(1);
		assertTrue("precondition: a fresh account is low combat", fresh.combatLevel() < 70);
		assertEquals("no endgame-access content for a brand-new account", 0, gatedShown(fresh));
	}

	@Test
	public void anEstablishedPlayerWithNoCaPointsIsNotTreatedAsNew()
	{
		// The case the combat check exists for: a main who just installed the plugin has 0 CA points, but
		// hiding raids from them would be plainly wrong.
		PlayerProfile main = account(90);
		assertTrue("precondition: this is a high-combat account", main.combatLevel() >= 70);
		assertTrue("an established player sees endgame content immediately", gatedShown(main) > 0);
	}

	@Test
	public void theGateReleasesAtSeventyCombat()
	{
		// 40s across the board is combat 51 — still a beginner. 55s is combat 70 — released.
		assertTrue("combat 51 is still gated", account(40).combatLevel() < 70);
		assertEquals(0, gatedShown(account(40)));

		assertTrue("55s reaches combat 70", account(55).combatLevel() >= 70);
		assertTrue("and the gate releases", gatedShown(account(55)) > 0);
	}

	@Test
	public void unlockingTheEasyTierAlsoReleasesTheGateForALowLevel()
	{
		// The other half of the rule: CA points release it too, independent of combat level.
		PlayerProfile fresh = account(1);
		SidePanelViewModel vm = new SidePanelViewModelBuilder(lib, effort, VideoGuideLibrary.loadBundled(),
			GuideLibrary.loadBundled(), TierRewardLibrary.loadBundled(), EffortModel.standard())
			.difficulty(TaskDifficultyLibrary.loadBundled())
			.recStats(recStats)
			.bossDifficulty(bossDiff)
			.detail(TaskDetailLibrary.loadBundled())
			.effortEngine(BossTimingLibrary.loadBundled(), QuestEffortLibrary.loadBundled(),
				SkillXpLibrary.loadBundled(), CombatExperience.empty(), fresh, 6)
			.build(new ProgressSnapshot(Collections.emptySet(), 500, 500, null, 1L),
				new ProfileSignalsProvider(effort, recStats, fresh), null);
		assertTrue("plenty of CA points releases the gate too",
			vm.quickWins().stream().anyMatch(r -> bossDiff.isEndgameAccess(r.monster)));
	}
}

package com.pluginideahub.combatachievements;

import com.pluginideahub.combatachievements.core.achievement.CombatAchievement;
import com.pluginideahub.combatachievements.core.achievement.CombatAchievementLibrary;
import com.pluginideahub.combatachievements.core.achievement.EffortDataLibrary;
import com.pluginideahub.combatachievements.core.achievement.RecStatsLibrary;
import com.pluginideahub.combatachievements.core.achievement.TaskDetailLibrary;
import com.pluginideahub.combatachievements.core.achievement.TaskDifficultyLibrary;
import com.pluginideahub.combatachievements.core.achievement.TierRewardLibrary;
import com.pluginideahub.combatachievements.core.effort.BossDifficultyLibrary;
import com.pluginideahub.combatachievements.core.effort.BossTimingLibrary;
import com.pluginideahub.combatachievements.core.effort.CombatExperience;
import com.pluginideahub.combatachievements.core.effort.QuestEffortLibrary;
import com.pluginideahub.combatachievements.core.effort.SkillXpLibrary;
import com.pluginideahub.combatachievements.core.guide.GuideLibrary;
import com.pluginideahub.combatachievements.core.progress.ProgressSnapshot;
import com.pluginideahub.combatachievements.core.ranking.EffortModel;
import com.pluginideahub.combatachievements.core.ranking.PlayerProfile;
import com.pluginideahub.combatachievements.core.ranking.ProfileSignalsProvider;
import com.pluginideahub.combatachievements.core.ui.SidePanelViewModel;
import com.pluginideahub.combatachievements.core.ui.SidePanelViewModelBuilder;
import com.pluginideahub.combatachievements.core.video.VideoGuideLibrary;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.HashSet;
import java.util.List;
import java.util.Map;
import java.util.Set;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

/**
 * The Bosses page shows how far through a boss you are. Completed CAs never reach the ranker — it only
 * ranks what is left — so they are gathered separately, and this guards that they actually arrive.
 */
public class BossCompletedCasTest
{
	private final CombatAchievementLibrary lib = CombatAchievementLibrary.loadBundled();

	private static PlayerProfile maxed()
	{
		Map<String, Integer> levels = new HashMap<>();
		for (String s : new String[]{"Attack", "Strength", "Defence", "Ranged", "Magic", "Prayer", "Slayer",
			"Hitpoints", "Mining", "Herblore", "Farming", "Construction", "Agility", "Thieving", "Firemaking",
			"Fishing", "Woodcutting", "Crafting", "Fletching", "Runecraft", "Hunter", "Smithing", "Cooking"})
		{
			levels.put(s, 99);
		}
		return PlayerProfile.of(levels);
	}

	private SidePanelViewModel model(Set<Integer> completed)
	{
		PlayerProfile profile = maxed();
		EffortDataLibrary effort = EffortDataLibrary.loadBundled();
		RecStatsLibrary rec = RecStatsLibrary.loadBundled();
		return new SidePanelViewModelBuilder(lib, effort, VideoGuideLibrary.loadBundled(),
			GuideLibrary.loadBundled(), TierRewardLibrary.loadBundled(), EffortModel.standard())
			.difficulty(TaskDifficultyLibrary.loadBundled())
			.recStats(rec)
			.bossDifficulty(BossDifficultyLibrary.loadBundled())
			.detail(TaskDetailLibrary.loadBundled())
			.effortEngine(BossTimingLibrary.loadBundled(), QuestEffortLibrary.loadBundled(),
				SkillXpLibrary.loadBundled(), CombatExperience.empty(), profile, 6)
			.build(new ProgressSnapshot(completed, 500, 500, null, 1L),
				new ProfileSignalsProvider(effort, rec, profile), null);
	}

	@Test
	public void aBossCarriesTheCAsAlreadyCompletedThere()
	{
		// Take a boss with several CAs and mark one of them done.
		Map<String, List<CombatAchievement>> byBoss = new HashMap<>();
		for (CombatAchievement t : lib.all())
		{
			if (t.hasMonster())
			{
				byBoss.computeIfAbsent(t.monster(), k -> new ArrayList<>()).add(t);
			}
		}
		Map.Entry<String, List<CombatAchievement>> pick = byBoss.entrySet().stream()
			.filter(e -> e.getValue().size() >= 3)
			.findFirst().orElseThrow(() -> new AssertionError("expected a boss with 3+ CAs"));
		String boss = pick.getKey();
		CombatAchievement done = pick.getValue().get(0);

		SidePanelViewModel before = model(new HashSet<>());
		SidePanelViewModel after = model(new HashSet<>(java.util.Collections.singletonList(done.id())));

		SidePanelViewModel.BossRow rowBefore = row(before, boss);
		SidePanelViewModel.BossRow rowAfter = row(after, boss);

		assertTrue("nothing completed to begin with", rowBefore.completedCas.isEmpty());
		assertEquals("the completed CA is listed against its boss", 1, rowAfter.completedCas.size());
		assertEquals(done.id(), rowAfter.completedCas.get(0).id);

		// It moved from outstanding to completed, so the boss's total is unchanged - that total is what
		// the "N of M done" figure divides by, and it must not drift as tasks are completed.
		assertEquals("total CAs at the boss is stable", rowBefore.totalCas(), rowAfter.totalCas());
		assertFalse("and it is no longer listed as something still to do",
			rowAfter.doable.stream().anyMatch(d -> d.id == done.id()));
	}

	private static SidePanelViewModel.BossRow row(SidePanelViewModel vm, String boss)
	{
		return vm.bosses().stream().filter(b -> boss.equals(b.monster)).findFirst()
			.orElseThrow(() -> new AssertionError("boss missing from the directory: " + boss));
	}
}

package com.pluginideahub.combatachievements;

import com.pluginideahub.combatachievements.core.achievement.CombatAchievementLibrary;
import com.pluginideahub.combatachievements.core.achievement.EffortDataLibrary;
import com.pluginideahub.combatachievements.core.achievement.RecStatsLibrary;
import com.pluginideahub.combatachievements.core.achievement.TaskDetailLibrary;
import com.pluginideahub.combatachievements.core.achievement.TaskDifficultyLibrary;
import com.pluginideahub.combatachievements.core.achievement.TierRewardLibrary;
import com.pluginideahub.combatachievements.core.effort.BossDifficultyLibrary;
import com.pluginideahub.combatachievements.core.effort.BossTimingLibrary;
import com.pluginideahub.combatachievements.core.effort.CombatExperience;
import com.pluginideahub.combatachievements.core.effort.QuestEffortLibrary;
import com.pluginideahub.combatachievements.core.effort.SkillXpLibrary;
import com.pluginideahub.combatachievements.core.guide.GuideLibrary;
import com.pluginideahub.combatachievements.core.progress.ProgressSnapshot;
import com.pluginideahub.combatachievements.core.ranking.EffortModel;
import com.pluginideahub.combatachievements.core.ranking.PlayerProfile;
import com.pluginideahub.combatachievements.core.ranking.ProfileSignalsProvider;
import com.pluginideahub.combatachievements.core.ui.SidePanelViewModel;
import com.pluginideahub.combatachievements.core.ui.SidePanelViewModelBuilder;
import com.pluginideahub.combatachievements.core.video.VideoGuideLibrary;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.HashMap;
import java.util.HashSet;
import java.util.List;
import java.util.Map;
import java.util.Set;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotEquals;
import static org.junit.Assert.assertTrue;

/**
 * The Bosses tab used to be account-blind: its "Recommended" order was points-per-hour of the content
 * alone, so a level-3 and a combat-89 account both led with Dagannoth Kings, and the list was built from
 * the ungated ranking so a brand-new account saw Chambers of Xeric and Theatre of Blood too.
 */
public class BossReadinessTest
{
	private final CombatAchievementLibrary lib = CombatAchievementLibrary.loadBundled();
	private final EffortDataLibrary effort = EffortDataLibrary.loadBundled();
	private final RecStatsLibrary recStats = RecStatsLibrary.loadBundled();

	private static PlayerProfile account(int everyStat)
	{
		Map<String, Integer> levels = new HashMap<>();
		for (String s : new String[]{"Attack", "Strength", "Defence", "Ranged", "Magic", "Prayer", "Slayer",
			"Mining", "Herblore", "Farming", "Construction", "Agility", "Thieving", "Firemaking", "Fishing",
			"Woodcutting", "Crafting", "Fletching", "Runecraft", "Hunter", "Smithing", "Cooking"})
		{
			levels.put(s, everyStat);
		}
		levels.put("Hitpoints", Math.max(10, everyStat));
		Set<String> quests = new HashSet<>(Arrays.asList(
			"Priest in Peril", "The Restless Ghost", "Children of the Sun"));
		return PlayerProfile.of(levels, quests, quests);
	}

	/** The boss list in the order the panel's default "Recommended" sort puts it. */
	private List<SidePanelViewModel.BossRow> bossesFor(PlayerProfile profile)
	{
		SidePanelViewModel vm = new SidePanelViewModelBuilder(lib, effort, VideoGuideLibrary.loadBundled(),
			GuideLibrary.loadBundled(), TierRewardLibrary.loadBundled(), EffortModel.standard())
			.difficulty(TaskDifficultyLibrary.loadBundled())
			.recStats(recStats)
			.bossDifficulty(BossDifficultyLibrary.loadBundled())
			.detail(TaskDetailLibrary.loadBundled())
			.effortEngine(BossTimingLibrary.loadBundled(), QuestEffortLibrary.loadBundled(),
				SkillXpLibrary.loadBundled(), CombatExperience.empty(), profile, 6)
			.build(new ProgressSnapshot(Collections.emptySet(), 0, 0, null, 1L),
				new ProfileSignalsProvider(effort, recStats, profile), null);

		List<SidePanelViewModel.BossRow> rows = new ArrayList<>(vm.bosses());
		rows.sort(CombatAchievementsPanel.bossComparator(
			CombatAchievementsPanel.Sort.RECOMMENDED, 6, 1.0));
		return rows;
	}

	private static List<String> topMonsters(List<SidePanelViewModel.BossRow> rows, int n)
	{
		List<String> names = new ArrayList<>();
		for (int i = 0; i < Math.min(n, rows.size()); i++)
		{
			names.add(rows.get(i).monster);
		}
		return names;
	}

	@Test
	public void theRecommendedOrderRespondsToTheAccount()
	{
		// The bug: identical top-6 from a level-3 to a combat-89 account.
		assertNotEquals("a level-3 and a maxed-ish account must not get the same boss list",
			topMonsters(bossesFor(account(1)), 6), topMonsters(bossesFor(account(90)), 6));
	}

	@Test
	public void aLevelThreeIsNotSentToDagannothKings()
	{
		List<String> top = topMonsters(bossesFor(account(1)), 3);
		for (String monster : top)
		{
			assertFalse("a level-3's top bosses must not be Dagannoth Kings (" + top + ")",
				monster.startsWith("Dagannoth"));
		}
		assertTrue("its starter bosses lead instead (" + top + ")",
			top.contains("Bryophyta") || top.contains("Obor") || top.contains("Greater Demon"));
	}

	@Test
	public void anEstablishedAccountGetsADifferentListFromABeginner()
	{
		// The other direction: readiness must not flatten the list for someone ready for everything. Asserted
		// on the SHAPE rather than by naming bosses — this test used to require a Dagannoth in the top six,
		// which stopped being true the moment their kill times were corrected (they had been recorded at a
		// 7-second respawn against the wiki's 90, making them look like the fastest points in the game).
		List<String> top = topMonsters(bossesFor(account(90)), 6);
		List<String> beginner = topMonsters(bossesFor(account(1)), 6);

		assertEquals("a maxed account still gets a full shortlist", 6, top.size());
		assertNotEquals("and it is not the beginner's list", beginner, top);
		assertTrue("no boss it is unready for leads the list",
			bossesFor(account(90)).get(0).readinessSink < 2.0);
	}

	@Test
	public void theDirectoryListsEveryBossEvenForABeginnerButMarksItsUnreadiness()
	{
		// Unlike the recommendation surfaces, the directory is a lookup: search, quest-page jumps and
		// "View boss" links all resolve against it, and hiding endgame content for a beginner made the
		// Colosseum unfindable and its links dead. So everything is listed — a beginner's unreadiness
		// shows in the row's sink (which the Recommended sort divides by), not in the boss being erased.
		List<SidePanelViewModel.BossRow> beginner = bossesFor(account(1));
		SidePanelViewModel.BossRow colosseum = named(beginner, "Fortis Colosseum");
		SidePanelViewModel.BossRow hueycoatl = named(beginner, "The Hueycoatl");
		named(beginner, "Chambers of Xeric");
		assertTrue("a level-3 is marked far from the Colosseum", colosseum.readinessSink > 2.0
			|| colosseum.locked);
		assertTrue("and from the Hueycoatl", hueycoatl.readinessSink > 2.0 || hueycoatl.locked);
	}

	private static SidePanelViewModel.BossRow named(List<SidePanelViewModel.BossRow> rows, String monster)
	{
		return rows.stream().filter(b -> b.monster.equals(monster)).findFirst().orElseThrow(
			() -> new AssertionError("no boss row for " + monster));
	}

	@Test
	public void aBossDetailSeparatesWhatYouCanDoFromWhatIsMerelyUngated()
	{
		// "Doable" only means no hard gate blocks you. A level-3 was shown all seven Barrows CAs as
		// available while being 49-84 levels short of every one of them, so the panel groups on reach.
		SidePanelViewModel.BossRow beginnerBarrows = named(bossesFor(account(1)), "Barrows");
		assertTrue("precondition: nothing hard-gates Barrows for a level-3",
			beginnerBarrows.doableCount > 0);
		assertTrue("but a level-3 is not ready for any of it",
			beginnerBarrows.doable.stream().noneMatch(d -> d.withinReach));

		// Mid-game is the interesting case: one Barrows CA wants only Magic 50, the rest want 70-85, so
		// the list must split rather than read as seven equally available tasks.
		SidePanelViewModel.BossRow midBarrows = named(bossesFor(account(45)), "Barrows");
		assertTrue("some Barrows CAs are within reach at all-45s",
			midBarrows.doable.stream().anyMatch(d -> d.withinReach));
		assertTrue("and some are not",
			midBarrows.doable.stream().anyMatch(d -> !d.withinReach));
	}

	@Test
	public void aMaxedAccountSeesNoNotYetGroup()
	{
		for (SidePanelViewModel.BossRow b : bossesFor(account(99)))
		{
			assertTrue("a maxed account is within reach of everything it can see (" + b.monster + ")",
				b.doable.stream().allMatch(d -> d.withinReach));
		}
	}

	@Test
	public void readinessIsCarriedOnTheRowAndIsNeutralByDefault()
	{
		for (SidePanelViewModel.BossRow b : bossesFor(account(90)))
		{
			assertTrue("a maxed account is ready for everything it can see (" + b.monster + ")",
				b.readinessSink < 3.0);
		}
		// Back-compat: the old constructor still yields a neutral row, so the raw directory is unaffected.
		assertEquals(1.0, new SidePanelViewModel.BossRow("X", 1, 1, 0, false, "",
			Collections.emptyList(), Collections.emptyList()).readinessSink, 1e-9);
	}
}

package com.pluginideahub.combatachievements;

import com.pluginideahub.combatachievements.core.ui.SidePanelViewModel;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.List;
import org.junit.Test;

import static org.junit.Assert.assertEquals;

/**
 * Guards the Bosses-mode Order control ({@link CombatAchievementsPanel#bossComparator}). The bosses are
 * engineered so the three sorts each produce a DISTINCT order (proving each uses its own metric), the
 * difficulty tie-break is exercised (Alpha vs Echo tie on avg difficulty, split by time), and the locked
 * boss sinks to the bottom in every sort. Figures below are at the default overhead (6 min):
 * <pre>
 *   Alpha   : 10 pts, CAs diff 2/10min + diff 4/10min  ->  20 min, 23.1 pts/hr, avg diff 3.0
 *   Bravo   : 20 pts, CA   diff 8/60min                ->  60 min, 18.2 pts/hr, avg diff 8.0
 *   Charlie :  6 pts, CA   diff 1/5min                 ->   5 min, 32.7 pts/hr, avg diff 1.0
 *   Echo    : 30 pts, CA   diff 3/120min               -> 120 min, 14.3 pts/hr, avg diff 3.0 (easy but slow)
 *   Delta   :  0 pts, no doable CAs                     -> locked (always last)
 * </pre>
 * {@link #clusteringWeightPromotesMultiCaBossOverTrivialHop} separately proves the overhead does its job:
 * the amortised trip cost pulls a meaty multi-CA boss above a trivial single-CA hop.
 */
public class BossSortTest
{
	private static final int DEFAULT_OVERHEAD = 6;

	private static SidePanelViewModel.CaDetail ca(int difficulty, int estMinutes)
	{
		return new SidePanelViewModel.CaDetail(0, "ca", "", "", "", 0, "", true, "",
			difficulty, 0, 0.0, "", estMinutes, 0, Collections.emptyList(),
			"", "", "", "", "", "", false, 0);
	}

	private static SidePanelViewModel.BossRow boss(String name, int projectedPoints,
		SidePanelViewModel.CaDetail... doable)
	{
		List<SidePanelViewModel.CaDetail> list = Arrays.asList(doable);
		return new SidePanelViewModel.BossRow(name, projectedPoints, list.size(), 0,
			list.isEmpty(), "", list, Collections.emptyList());
	}

	private static List<String> order(List<SidePanelViewModel.BossRow> rows,
		CombatAchievementsPanel.Sort sort, int tripOverhead)
	{
		List<SidePanelViewModel.BossRow> copy = new ArrayList<>(rows);
		copy.sort(CombatAchievementsPanel.bossComparator(sort, tripOverhead));
		List<String> names = new ArrayList<>();
		for (SidePanelViewModel.BossRow b : copy)
		{
			names.add(b.monster);
		}
		return names;
	}

	// Deliberately not pre-sorted, so the comparator has real work to do.
	private static List<SidePanelViewModel.BossRow> bosses()
	{
		return new ArrayList<>(Arrays.asList(
			boss("Bravo", 20, ca(8, 60)),
			boss("Delta", 0),
			boss("Echo", 30, ca(3, 120)),
			boss("Charlie", 6, ca(1, 5)),
			boss("Alpha", 10, ca(2, 10), ca(4, 10))));
	}

	@Test
	public void recommendedSortsByAmortisedPointsPerHour()
	{
		assertEquals(Arrays.asList("Charlie", "Alpha", "Bravo", "Echo", "Delta"),
			order(bosses(), CombatAchievementsPanel.Sort.RECOMMENDED, DEFAULT_OVERHEAD));
	}

	@Test
	public void mostPointsSortsByProjectedPoints()
	{
		assertEquals(Arrays.asList("Echo", "Bravo", "Alpha", "Charlie", "Delta"),
			order(bosses(), CombatAchievementsPanel.Sort.MOST_POINTS, DEFAULT_OVERHEAD));
	}

	@Test
	public void easiestSortsByAverageDifficultyThenQuickest()
	{
		// Alpha and Echo tie at avg difficulty 3.0; the quicker one (Alpha, 20 min) comes first.
		assertEquals(Arrays.asList("Charlie", "Alpha", "Echo", "Bravo", "Delta"),
			order(bosses(), CombatAchievementsPanel.Sort.EASIEST, DEFAULT_OVERHEAD));
	}

	@Test
	public void lockedBossAlwaysSinksToBottom()
	{
		for (CombatAchievementsPanel.Sort sort : CombatAchievementsPanel.Sort.values())
		{
			List<String> names = order(bosses(), sort, DEFAULT_OVERHEAD);
			assertEquals("locked boss must be last for " + sort, "Delta", names.get(names.size() - 1));
		}
	}

	@Test
	public void recommendedWithTimeOffRanksByPointsNotAlphabetically()
	{
		// Both Bosses dials off (overhead 0, time weight 0): every boss's pts/hr denominator vanishes, so the
		// sort must fall back to available points — NOT collapse to alphabetical (the fixed edge case).
		List<SidePanelViewModel.BossRow> copy = new ArrayList<>(bosses());
		copy.sort(CombatAchievementsPanel.bossComparator(CombatAchievementsPanel.Sort.RECOMMENDED, 0, 0.0));
		List<String> names = new ArrayList<>();
		for (SidePanelViewModel.BossRow b : copy)
		{
			names.add(b.monster);
		}
		assertEquals(Arrays.asList("Echo", "Bravo", "Alpha", "Charlie", "Delta"), names);
	}

	@Test
	public void clusteringWeightPromotesMultiCaBossOverTrivialHop()
	{
		List<SidePanelViewModel.BossRow> rows = new ArrayList<>(Arrays.asList(
			boss("Trivial", 3, ca(1, 3)),               // one quick 3-pt CA
			boss("Meaty", 40, ca(3, 50), ca(4, 50))));  // 40 pts across a longer, multi-CA visit

		// No overhead: raw points-per-time favours the trivial single-CA hop (60 vs 24 pts/hr).
		assertEquals(Arrays.asList("Trivial", "Meaty"),
			order(rows, CombatAchievementsPanel.Sort.RECOMMENDED, 0));

		// With the clustering overhead the fixed trip cost amortises across the meaty boss's CAs, pulling
		// it above the trivial hop (22.6 vs 20 pts/hr) — the whole point of the weighting.
		assertEquals(Arrays.asList("Meaty", "Trivial"),
			order(rows, CombatAchievementsPanel.Sort.RECOMMENDED, DEFAULT_OVERHEAD));
	}
}

package com.pluginideahub.combatachievements;

import java.util.ArrayList;
import java.util.Comparator;
import java.util.List;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotEquals;
import static org.junit.Assert.assertTrue;

/** Guards the CAs-list reshuffle jitter ({@link CombatAchievementsPanel#jitteredKey}). */
public class CaShuffleTest
{
	@Test
	public void jitterIsDeterministicAndBounded()
	{
		// Same (rank, id, seed) always yields the same key, so per-tick rebuilds don't re-scramble.
		assertEquals(CombatAchievementsPanel.jitteredKey(5, 42, 7L),
			CombatAchievementsPanel.jitteredKey(5, 42, 7L), 0.0);

		// A task never moves more than the jitter window (SHUFFLE_JITTER = 12) from its rank.
		for (int rank = 0; rank < 40; rank++)
		{
			double key = CombatAchievementsPanel.jitteredKey(rank, rank * 3 + 1, 9L);
			assertTrue("bounded jitter at rank " + rank, Math.abs(key - rank) <= 12.0 + 1e-9);
		}
	}

	@Test
	public void differentSeedsReshuffleButSameSeedIsStable()
	{
		List<Integer> underSeed1 = orderUnder(1L);
		assertNotEquals("a new seed reshuffles the list", underSeed1, orderUnder(2L));
		assertEquals("same seed is deterministic", underSeed1, orderUnder(1L));
	}

	private static List<Integer> orderUnder(long seed)
	{
		List<Integer> ids = new ArrayList<>();
		for (int i = 0; i < 25; i++)
		{
			ids.add(i);
		}
		ids.sort(Comparator.comparingDouble(id -> CombatAchievementsPanel.jitteredKey(id, id, seed)));
		return ids;
	}
}

