/**
 * Cross-file data invariants. These guard the "id-shift catastrophe": every id-keyed dataset must
 * stay aligned with the canonical task id space (0 .. taskCount-1). A dataset regen that drops
 * entries or shifts ids fails here instead of silently mislabelling the player's progress.
 */
public class DataIntegrityTest
{
	private static final String PKG = "/com/pluginideahub/combatachievements/";

	@Test
	public void taskIdsAreContiguousFromZero()
	{
		CombatAchievementLibrary lib = CombatAchievementLibrary.loadBundled();
		int n = lib.taskCount();
		assertTrue("expected a populated dataset", n > 0);
		for (int id = 0; id < n; id++)
		{
			assertNotNull("task ids must be contiguous 0.." + (n - 1) + "; missing " + id, lib.byId(id));
		}
	}

	@Test
	public void difficultyCoversEveryTaskWithKeysInRangeAndOnScale()
	{
		CombatAchievementLibrary lib = CombatAchievementLibrary.loadBundled();
		TaskDifficultyLibrary diff = TaskDifficultyLibrary.loadBundled();
		assertEquals("difficulty must cover every task", lib.taskCount(), diff.count());
		for (CombatAchievement t : lib.all())
		{
			int d = diff.difficultyFor(t.id()).difficulty();
			assertTrue("difficulty for task " + t.id() + " must be on the 1-10 scale, was " + d,
				d >= 1 && d <= 10);
		}
		for (int key : taskKeys(PKG + "task_difficulty.json"))
		{
			assertInRange(key, lib.taskCount());
		}
	}

	@Test
	public void effortKeysAreValidTaskIds()
	{
		int n = CombatAchievementLibrary.loadBundled().taskCount();
		for (int key : taskKeys(PKG + "task_effort.json"))
		{
			assertInRange(key, n);
		}
	}

	@Test
	public void recStatsKeysAreValidTaskIds()
	{
		// The two biggest id-keyed datasets are both regenerated from the free-form curation CSV, so
		// they are the most likely to drift — and they were the only ones this suite didn't guard.
		int n = CombatAchievementLibrary.loadBundled().taskCount();
		List<Integer> keys = taskKeys(PKG + "rec_stats.json");
		assertTrue("rec_stats.json is unexpectedly sparse (" + keys.size() + " entries)", keys.size() > 400);
		for (int key : keys)
		{
			assertInRange(key, n);
		}
	}

	@Test
	public void taskDetailKeysAreValidTaskIds()
	{
		int n = CombatAchievementLibrary.loadBundled().taskCount();
		List<Integer> keys = taskKeys(PKG + "task_detail.json");
		assertTrue("task_detail.json is unexpectedly sparse (" + keys.size() + " entries)", keys.size() > 400);
		for (int key : keys)
		{
			assertInRange(key, n);
		}
	}

	@Test
	public void monsterStatsArePresent()
	{
		assertTrue("expected the auto-sourced monster stats", MonsterStatsLibrary.loadBundled().count() >= 60);
	}

	@Test
	public void tierRewardsCoverEveryTier()
	{
		TierRewardLibrary rewards = TierRewardLibrary.loadBundled();
		for (AchievementTier tier : AchievementTier.values())
		{
			assertTrue("missing tier reward for " + tier, rewards.forTier(tier).isPresent());
		}
	}

	private static void assertInRange(int key, int taskCount)
	{
		assertTrue("dataset key " + key + " is outside the task id range [0," + (taskCount - 1) + "]",
			key >= 0 && key < taskCount);
	}

	/** Numeric keys of the {@code tasks} object in a bundled JSON resource. */
	private static List<Integer> taskKeys(String resource)
	{
		List<Integer> keys = new ArrayList<>();
		try (InputStream in = DataIntegrityTest.class.getResourceAsStream(resource))
		{
			assertNotNull("missing bundled resource " + resource, in);
			JsonObject root = JsonParser.parseReader(
				new InputStreamReader(in, StandardCharsets.UTF_8)).getAsJsonObject();
			JsonElement tasks = root.get("tasks");
			assertNotNull("no 'tasks' object in " + resource, tasks);
			for (String k : tasks.getAsJsonObject().keySet())
			{
				keys.add(Integer.parseInt(k.trim()));
			}
		}
		catch (Exception ex)
		{
			throw new AssertionError("failed reading " + resource + ": " + ex, ex);
		}
		return keys;
	}

	/**
	 * A monster's curated kills/hour must agree with what the engine derives from its kill time and
	 * respawn, because the engine only reads the latter — killsPerHour is documentation. The Mimic sat at
	 * a curated 1/hr while the engine computed 20/hr from a zero respawn, which made a boss you reach once
	 * per ~18 elite clue scrolls look like the best points-per-hour in the game.
	 */
	@Test
	public void curatedKillsPerHourAgreesWithWhatTheEngineDerives()
	{
		BossTimingLibrary timings = BossTimingLibrary.loadBundled();
		List<String> off = new ArrayList<>();
		for (CombatAchievement task : CombatAchievementLibrary.loadBundled().all())
		{
			BossTiming t = timings.timingFor(task.monster());
			if (!t.isKnown() || t.secondsPerKill() <= 0)
			{
				continue;
			}
			if (t.killsPerHour() <= 0)
			{
				// 0 means "under one an hour" — the integer field cannot say 0.29. Honest only if the
				// timing really is that slow; a lazily-zeroed entry would hide a disagreement here.
				assertTrue(task.monster() + " has killsPerHour 0 but is quicker than one an hour",
					t.secondsPerKill() >= 3600);
				continue;
			}
			double derived = 3600.0 / t.secondsPerKill();
			double ratio = derived / t.killsPerHour();
			// Generous: the curated figure is a whole number, so a boss at "1/hr" that really runs at 1.9
			// is rounding, not a mistake. Anything past 2x is the two fields telling different stories.
			if (ratio > 2.0 || ratio < 0.5)
			{
				String line = task.monster() + " curated " + t.killsPerHour() + "/hr vs derived "
					+ Math.round(derived) + "/hr";
				if (!off.contains(line))
				{
					off.add(line);
				}
			}
		}
		assertTrue("kill-rate fields disagree: " + off, off.isEmpty());
	}
}

package com.pluginideahub.combatachievements;

import com.pluginideahub.combatachievements.core.debug.DebugSimulation;
import com.pluginideahub.combatachievements.core.ranking.PlayerProfile;
import com.pluginideahub.combatachievements.core.ui.PanelAction;
import java.lang.reflect.InvocationTargetException;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.concurrent.CopyOnWriteArrayList;
import javax.swing.SwingUtilities;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

/**
 * The developer-mode simulation controls. The property that matters most is the gate: a simulation left
 * running must become inert the moment developer mode goes off, or the panel would keep reporting fake
 * figures for a real account with no visible sign of it.
 */
public class DebugPanelTest
{
	private final List<PanelAction> actions = new CopyOnWriteArrayList<>();

	private CombatAchievementsPanel panel()
	{
		return new CombatAchievementsPanel(actions::add);
	}

	/** Swing state must be touched on the EDT, and the panel's setters defer when called off it. */
	private static void onEdt(Runnable body) throws InterruptedException, InvocationTargetException
	{
		SwingUtilities.invokeAndWait(body);
	}

	private static PlayerProfile maxed()
	{
		Map<String, Integer> levels = new HashMap<>();
		for (String s : DebugSimulation.SKILLS)
		{
			levels.put(s, 99);
		}
		return PlayerProfile.of(levels);
	}

	@Test
	public void aSimulationIsInertUntilDeveloperModeIsOn() throws Exception
	{
		onEdt(() ->
		{
			CombatAchievementsPanel panel = panel();
			panel.setDeveloperMode(false);
			panel.applyLevelPreset(1);

			assertFalse("developer mode off means the plugin is handed no simulation",
				panel.debugSimulation().isActive());

			panel.setDeveloperMode(true);
			assertTrue("and gets it once developer mode is on", panel.debugSimulation().isActive());

			// The guard that matters: turning developer mode back off must not leave a live simulation
			// silently rewriting a real account's panel.
			panel.setDeveloperMode(false);
			assertFalse("switching developer mode off retires the simulation",
				panel.debugSimulation().isActive());
		});
	}

	@Test
	public void aPresetSimulatesEverySkillAtOnce() throws Exception
	{
		onEdt(() ->
		{
			CombatAchievementsPanel panel = panel();
			panel.setDeveloperMode(true);
			panel.applyLevelPreset(1);

			DebugSimulation sim = panel.debugSimulation();
			assertEquals("all 23 skills, so nothing is left at the real level",
				23, sim.levelOverrides().size());
			assertEquals("a maxed account now reads as a brand-new one",
				3, sim.apply(maxed()).combatLevel());
			assertEquals("Hitpoints keeps its floor of 10", 10, panel.devSpinnerValue("Hitpoints"));
		});
	}

	@Test
	public void realGivesTheAccountItsOwnLevelsBack() throws Exception
	{
		onEdt(() ->
		{
			CombatAchievementsPanel panel = panel();
			panel.setDeveloperMode(true);
			panel.applyLevelPreset(40);
			assertTrue(panel.debugSimulation().isActive());

			panel.clearLevelSimulation();
			assertFalse("no override left, so the real profile passes through",
				panel.debugSimulation().isActive());
			assertEquals(99, panel.debugSimulation().apply(maxed()).levelOf("Attack"));
		});
	}

	@Test
	public void zeroCompletionIsIndependentOfTheLevels() throws Exception
	{
		onEdt(() ->
		{
			CombatAchievementsPanel panel = panel();
			panel.setDeveloperMode(true);
			panel.setZeroCompletion(true);

			DebugSimulation sim = panel.debugSimulation();
			assertTrue("hiding completions alone is a simulation", sim.isActive());
			assertTrue(sim.zeroCompletion());
			assertTrue("and it did not invent level overrides", sim.levelOverrides().isEmpty());
		});
	}

	@Test
	public void theRealAccountSeedsTheSpinnersButNeverClobbersASimulation() throws Exception
	{
		onEdt(() ->
		{
			CombatAchievementsPanel panel = panel();
			panel.setDeveloperMode(true);

			Map<String, Integer> real = new HashMap<>();
			real.put("Attack", 70);
			panel.setRealLevels(real);
			assertEquals("the grid starts from the truth", 70, panel.devSpinnerValue("Attack"));

			panel.applyLevelPreset(1);
			assertEquals(1, panel.devSpinnerValue("Attack"));

			// Every refresh pushes the real levels again — while simulating, that must be ignored, or the
			// next game tick would overwrite what was just dialled in.
			panel.setRealLevels(real);
			assertEquals("a refresh mid-simulation leaves the dialled-in value alone",
				1, panel.devSpinnerValue("Attack"));

			panel.clearLevelSimulation();
			panel.setRealLevels(real);
			assertEquals("and the real level returns once the simulation is cleared",
				70, panel.devSpinnerValue("Attack"));
		});
	}

	@Test
	public void hidingCompletionsDoesNotFreezeTheLevelGrid() throws Exception
	{
		onEdt(() ->
		{
			CombatAchievementsPanel panel = panel();
			panel.setDeveloperMode(true);

			Map<String, Integer> real = new HashMap<>();
			real.put("Attack", 70);
			panel.setRealLevels(real);

			// "No CAs completed" is about progress, not levels. It leaves a simulation active, so gating the
			// re-seed on that alone used to freeze the grid: "Real" would restore the account's levels in the
			// panel while the spinners still showed the old preset, and one nudge re-applied them.
			panel.setZeroCompletion(true);
			panel.applyLevelPreset(1);
			assertEquals(1, panel.devSpinnerValue("Attack"));

			panel.clearLevelSimulation();
			panel.setRealLevels(real);
			assertEquals("the grid follows the real account again even while completions stay hidden",
				70, panel.devSpinnerValue("Attack"));
			assertTrue("and hiding completions is still in force",
				panel.debugSimulation().zeroCompletion());
		});
	}

	@Test
	public void everyControlAsksThePluginForAFreshModel() throws Exception
	{
		actions.clear();
		onEdt(() ->
		{
			CombatAchievementsPanel panel = panel();
			panel.setDeveloperMode(true);
			panel.applyLevelPreset(60);
			panel.setZeroCompletion(true);
			panel.clearLevelSimulation();
		});
		assertEquals("a simulation is useless if the panel does not re-render",
			3, actions.stream().filter(a -> a == PanelAction.REFRESH).count());
	}
}

package com.pluginideahub.combatachievements;

import com.pluginideahub.combatachievements.core.achievement.AchievementTier;
import com.pluginideahub.combatachievements.core.achievement.CombatAchievementLibrary;
import com.pluginideahub.combatachievements.core.achievement.EffortDataLibrary;
import com.pluginideahub.combatachievements.core.achievement.RecStatsLibrary;
import com.pluginideahub.combatachievements.core.achievement.TaskDifficultyLibrary;
import com.pluginideahub.combatachievements.core.achievement.TierRewardLibrary;
import com.pluginideahub.combatachievements.core.effort.BossTimingLibrary;
import com.pluginideahub.combatachievements.core.effort.CombatExperience;
import com.pluginideahub.combatachievements.core.effort.QuestEffortLibrary;
import com.pluginideahub.combatachievements.core.effort.SkillXpLibrary;
import com.pluginideahub.combatachievements.core.guide.GuideLibrary;
import com.pluginideahub.combatachievements.core.progress.ProgressSnapshot;
import com.pluginideahub.combatachievements.core.ranking.EffortModel;
import com.pluginideahub.combatachievements.core.ranking.LowHangingFruitRanker;
import com.pluginideahub.combatachievements.core.ranking.PlayerProfile;
import com.pluginideahub.combatachievements.core.ranking.ProfileSignalsProvider;
import com.pluginideahub.combatachievements.core.ranking.RankedTask;
import com.pluginideahub.combatachievements.core.ranking.SignalsProvider;
import com.pluginideahub.combatachievements.core.ui.SidePanelViewModel;
import com.pluginideahub.combatachievements.core.ui.SidePanelViewModelBuilder;
import com.pluginideahub.combatachievements.core.video.VideoGuideLibrary;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.HashMap;
import java.util.HashSet;
import java.util.List;
import java.util.Map;
import java.util.Set;
import org.junit.Test;

import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

/**
 * End-to-end regression for the fresh-account fix: a brand-new low-combat account that has done the
 * quests gating Morytania/raid content must NOT be recommended endgame CAs. The soft rec-stats sink
 * (and the redundant-but-safe hard gate) push attemptable-but-underlevelled content down the list
 * without ever hiding it. Guards against the "level-45 account told to do CoX Grandmaster" bug.
 */
public class FreshAccountRecStatsSimTest
{
	// Chambers of Xeric (5-Scale) Speed-Runner: Grandmaster, "Maxed" team, and — critically — no OSRS
	// level gate and no quest gate, so only the soft rec-stats sink can keep it off a fresh account's list.
	private static final int COX_GM_5SCALE = 325;

	private final CombatAchievementLibrary lib = CombatAchievementLibrary.loadBundled();
	private final EffortDataLibrary effort = EffortDataLibrary.loadBundled();
	private final TaskDifficultyLibrary diff = TaskDifficultyLibrary.loadBundled();
	private final RecStatsLibrary recStats = RecStatsLibrary.loadBundled();

	private static PlayerProfile freshAccount()
	{
		Map<String, Integer> levels = new HashMap<>();
		levels.put("Attack", 40);
		levels.put("Strength", 45);
		levels.put("Defence", 30);
		levels.put("Hitpoints", 44);
		levels.put("Ranged", 35);
		levels.put("Magic", 33);
		levels.put("Prayer", 31);
		levels.put("Slayer", 20);
		levels.put("Mining", 30);
		levels.put("Firemaking", 30);
		// Quests that unlock Morytania/raid content — this is what let endgame CAs slip through before.
		Set<String> quests = new HashSet<>(Arrays.asList(
			"Priest in Peril", "The Restless Ghost", "Vampyre Slayer", "Nature Spirit",
			"Death Plateau", "Dragon Slayer I"));
		return PlayerProfile.of(levels, quests, quests);
	}

	private List<RankedTask> rankDoableNow(SignalsProvider signals)
	{
		return new LowHangingFruitRanker(effort, EffortModel.standard(), diff)
			.rank(lib.all(), Collections.emptySet(), signals, true);
	}

	private static int indexOfTask(List<RankedTask> ranked, int taskId)
	{
		for (int i = 0; i < ranked.size(); i++)
		{
			if (ranked.get(i).achievement().id() == taskId)
			{
				return i;
			}
		}
		return -1;
	}

	@Test
	public void recStatsSinkBuriesEndgameForAFreshAccount()
	{
		PlayerProfile profile = freshAccount();
		List<RankedTask> without = rankDoableNow(new ProfileSignalsProvider(effort, profile));
		List<RankedTask> with = rankDoableNow(new ProfileSignalsProvider(effort, recStats, profile));

		int rankWithout = indexOfTask(without, COX_GM_5SCALE);
		int rankWith = indexOfTask(with, COX_GM_5SCALE);

		// The task is ungated, so it is doable-now (present in the list) in BOTH rankings — the fix is
		// about ORDER, not hiding. If the dataset ever gains a real gate here, this precondition tells us.
		assertTrue("CoX GM 5-scale should be an ungated doable-now task", rankWithout >= 0 && rankWith >= 0);

		// The sink must still push it down, and must leave it buried at the bottom of the list — which is
		// the property that actually matters for a fresh account.
		//
		// This deliberately measures WHERE it ends up rather than "at least 30 places moved". Task 325 is a
		// Speed-Runner, so the speed-tier cost now sinks it in BOTH rankings; the baseline it is compared
		// against is itself near the floor, leaving fewer places left to fall. An absolute distance
		// silently encodes how high the naive ranking used to put it, and breaks whenever anything else
		// legitimately sinks the same task.
		assertTrue("rec-stats sink should push CoX GM further down (was #" + (rankWithout + 1)
			+ ", now #" + (rankWith + 1) + ")", rankWith > rankWithout);
		int bottomTenth = with.size() - Math.max(10, with.size() / 10);
		assertTrue("CoX GM should sit in the bottom tenth for a fresh account (#" + (rankWith + 1)
			+ " of " + with.size() + ")", rankWith >= bottomTenth);

		RankedTask cox = with.get(rankWith);
		assertTrue("flagged below rec stats", cox.belowRecStats());
		assertTrue("large shortfall for a fresh account", cox.recStatsShortfall() > 200);
	}

	@Test
	public void freshAccountTopRecommendationsAreNotGrandmaster()
	{
		List<RankedTask> with = rankDoableNow(new ProfileSignalsProvider(effort, recStats, freshAccount()));
		int limit = Math.min(10, with.size());
		for (int i = 0; i < limit; i++)
		{
			RankedTask rt = with.get(i);
			assertFalse("no Grandmaster CA in the fresh-account top 10 (#" + (i + 1) + " "
					+ rt.achievement().name() + ")",
				rt.achievement().tier() == AchievementTier.GRANDMASTER);
		}
	}

	private SidePanelViewModel buildVm(SignalsProvider signals)
	{
		PlayerProfile profile = freshAccount();
		// A fresh account with a real (present) but empty progress snapshot — nothing completed yet.
		ProgressSnapshot snapshot = new ProgressSnapshot(Collections.emptySet(), 0, 0, null, 1L);
		return new SidePanelViewModelBuilder(lib, effort, VideoGuideLibrary.loadBundled(),
			GuideLibrary.loadBundled(), TierRewardLibrary.loadBundled(), EffortModel.standard())
			.difficulty(diff)
			.effortEngine(BossTimingLibrary.loadBundled(), QuestEffortLibrary.loadBundled(),
				SkillXpLibrary.loadBundled(), CombatExperience.empty(), profile, 6)
			.build(snapshot, signals, null);
	}

	private static List<String> sessionMonsters(SidePanelViewModel vm)
	{
		List<String> names = new ArrayList<>();
		for (SidePanelViewModel.SessionView s : vm.sessions())
		{
			names.add(s.monster);
		}
		return names;
	}

	/** monster -> the biggest soft rec-stats shortfall among its doable tasks, for a rec-stats-aware fresh acct. */
	private Map<String, Integer> maxShortfallByMonster()
	{
		Map<String, Integer> byMonster = new HashMap<>();
		for (RankedTask rt : rankDoableNow(new ProfileSignalsProvider(effort, recStats, freshAccount())))
		{
			String m = rt.achievement().monster();
			byMonster.merge(m, rt.recStatsShortfall(), Math::max);
		}
		return byMonster;
	}

	private static int totalShortfall(List<String> monsters, int topN, Map<String, Integer> byMonster)
	{
		int total = 0;
		for (int i = 0; i < Math.min(topN, monsters.size()); i++)
		{
			total += byMonster.getOrDefault(monsters.get(i), 0);
		}
		return total;
	}

	@Test
	public void sessionsRespectRecStatsSink()
	{
		// The "Next session" list is an opinionated recommendation, so it must prefer bosses the account is
		// actually ready for. With the rec-stats sink, the top sessions should skew toward lower-shortfall
		// bosses than the naive points/time ordering does.
		SidePanelViewModel without = buildVm(new ProfileSignalsProvider(effort, freshAccount()));
		SidePanelViewModel with = buildVm(new ProfileSignalsProvider(effort, recStats, freshAccount()));

		List<String> withSessions = sessionMonsters(with);
		List<String> withoutSessions = sessionMonsters(without);
		assertFalse("sessions are produced for a fresh account (precondition)", withSessions.isEmpty());

		// The sink must actually change the ordering (otherwise it's a no-op on this surface)...
		assertFalse("rec-stats sink should re-order the session suggestions",
			withSessions.equals(withoutSessions));

		// ...and the change must be in the right direction: the sunk top-3 sessions carry less rec-stats
		// shortfall (i.e. the account is more ready for them) than the naive top-3.
		Map<String, Integer> shortfall = maxShortfallByMonster();
		int withTop3 = totalShortfall(withSessions, 3, shortfall);
		int withoutTop3 = totalShortfall(withoutSessions, 3, shortfall);
		assertTrue("sunk top sessions should be more attainable (shortfall " + withTop3
				+ " vs naive " + withoutTop3 + ")",
			withTop3 < withoutTop3);
	}
}

package com.pluginideahub.combatachievements;

