import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

/**
 * The quest page's boss groups start closed, and clicking a group's arrow opens it. Simulated with a
 * real mouse event rather than eyeballed: AWT does not bubble clicks, so a toggle that renders
 * perfectly can still be dead if the handler sits on the wrong component.
 */
public class UnlockBossGroupToggleTest
{
	/** An account with quests left to do, so the Route has "Unlock next" cards to drill into. */
	private static SidePanelViewModel model()
	{
		Map<String, Integer> levels = new HashMap<>();
		for (String s : new String[]{"Attack", "Strength", "Defence", "Ranged", "Magic", "Prayer", "Slayer",
			"Hitpoints", "Mining", "Herblore", "Farming", "Construction", "Agility", "Thieving", "Firemaking",
			"Fishing", "Woodcutting", "Crafting", "Fletching", "Runecraft", "Hunter", "Smithing", "Cooking"})
		{
			levels.put(s, 80);
		}
		PlayerProfile profile = PlayerProfile.of(levels);
		EffortDataLibrary effort = EffortDataLibrary.loadBundled();
		RecStatsLibrary rec = RecStatsLibrary.loadBundled();
		return new SidePanelViewModelBuilder(CombatAchievementLibrary.loadBundled(), effort,
			VideoGuideLibrary.loadBundled(), GuideLibrary.loadBundled(), TierRewardLibrary.loadBundled(),
			EffortModel.standard())
			.difficulty(TaskDifficultyLibrary.loadBundled())
			.recStats(rec)
			.bossDifficulty(BossDifficultyLibrary.loadBundled())
			.detail(TaskDetailLibrary.loadBundled())
			.effortEngine(BossTimingLibrary.loadBundled(), QuestEffortLibrary.loadBundled(),
				SkillXpLibrary.loadBundled(), CombatExperience.empty(), profile, 6)
			.build(new ProgressSnapshot(Collections.emptySet(), 0, 0, null, 1L),
				new ProfileSignalsProvider(effort, rec, profile), null);
	}

	private static List<JLabel> labels(Container c, List<JLabel> out)
	{
		for (Component child : c.getComponents())
		{
			if (child instanceof JLabel)
			{
				out.add((JLabel) child);
			}
			if (child instanceof Container)
			{
				labels((Container) child, out);
			}
		}
		return out;
	}

	/** The quest page's group arrows are the only bare "▸ "/"▾ " labels on show. */
	private static List<JLabel> arrows(Container panel)
	{
		List<JLabel> out = new ArrayList<>();
		for (JLabel l : labels(panel, new ArrayList<>()))
		{
			if ("▸ ".equals(l.getText()) || "▾ ".equals(l.getText()))
			{
				out.add(l);
			}
		}
		return out;
	}

	@Test
	public void bossGroupsStartClosedAndOpenOnAClick() throws Exception
	{
		SidePanelViewModel vm = model();
		assertFalse("fixture must produce unlock suggestions", vm.unlocks().isEmpty());
		final int groupCas = vm.unlocks().get(0).unlockedCas.size();
		assertTrue("fixture's first quest must unlock something", groupCas > 0);

		SwingUtilities.invokeAndWait(() ->
		{
			CombatAchievementsPanel panel = new CombatAchievementsPanel(action -> { });
			panel.render(vm);
			panel.openFirstUnlockDetail();

			List<JLabel> closed = arrows(panel);
			assertTrue("the quest page shows at least one boss group", !closed.isEmpty());
			for (JLabel a : closed)
			{
				assertTrue("every group starts closed", "▸ ".equals(a.getText()));
			}
			int labelsBefore = labels(panel, new ArrayList<>()).size();

			JLabel first = closed.get(0);
			first.dispatchEvent(new MouseEvent(first, MouseEvent.MOUSE_CLICKED,
				System.currentTimeMillis(), 0, 1, 1, 1, false));

			assertTrue("clicking the arrow opens the group",
				arrows(panel).stream().anyMatch(a -> "▾ ".equals(a.getText())));
			assertTrue("the group's CA cards are now on show",
				labels(panel, new ArrayList<>()).size() > labelsBefore);
		});
	}
}

package com.pluginideahub.combatachievements.bridge;

import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import com.google.gson.JsonParser;
import com.pluginideahub.combatachievements.core.effort.MonsterNames;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Paths;
import java.util.Locale;
import java.util.Set;
import java.util.TreeMap;
import java.util.TreeSet;
import net.runelite.client.hiscore.HiscoreSkill;
import net.runelite.client.hiscore.HiscoreSkillType;
import org.junit.Test;

import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertTrue;

/**
 * Diagnostic + guard for hiscore KC coverage: which dataset monsters get a hiscore source via the
 * {@code MonsterNames} canonicaliser, which hiscore bosses map to a key no task uses (orphans), and
 * which dataset monsters have no hiscore source at all (expected: slayer/quest/sub-mode monsters).
 * Writes a human-readable report to {@code build/hiscore-coverage.txt}.
 */
public class HiscoreCoverageTest
{
	@Test
	public void reportHiscoreCoverage() throws Exception
	{
		Set<String> datasetMonsters = datasetMonsterKeys();

		TreeMap<String, String> matched = new TreeMap<>();   // hiscore boss -> dataset key
		TreeSet<String> orphanHiscore = new TreeSet<>();      // hiscore boss -> key not in dataset
		for (HiscoreSkill hs : HiscoreSkill.values())
		{
			if (hs.getType() != HiscoreSkillType.BOSS)
			{
				continue;
			}
			String key = MonsterNames.toDatasetKey(hs.getName());
			if (datasetMonsters.contains(key))
			{
				matched.put(hs.getName(), key);
			}
			else
			{
				orphanHiscore.add(hs.getName() + "  ->  " + key);
			}
		}

		TreeSet<String> uncovered = new TreeSet<>(datasetMonsters);
		uncovered.removeAll(matched.values());

		StringBuilder sb = new StringBuilder();
		sb.append("HISCORE KC COVERAGE\n===================\n\n");
		sb.append("Dataset monsters WITH a hiscore source: ").append(matched.size()).append("\n");
		for (String b : matched.keySet())
		{
			sb.append("  ").append(b).append("  ->  ").append(matched.get(b)).append('\n');
		}
		sb.append("\nHiscore bosses with NO matching dataset monster (orphans — harmless): ")
			.append(orphanHiscore.size()).append('\n');
		for (String o : orphanHiscore)
		{
			sb.append("  ").append(o).append('\n');
		}
		sb.append("\nDataset monsters with NO hiscore source (chat-only; expected slayer/quest/sub-mode): ")
			.append(uncovered.size()).append('\n');
		for (String u : uncovered)
		{
			sb.append("  ").append(u).append('\n');
		}

		Files.createDirectories(Paths.get("build"));
		Files.write(Paths.get("build/hiscore-coverage.txt"), sb.toString().getBytes(StandardCharsets.UTF_8));

		// Guard: the bulk of CA bosses must resolve to a hiscore source, and the alias-mapped ones in
		// particular must stay connected (a rename in the dataset or the HiscoreSkill enum fails here).
		assertTrue("expected most CA bosses to have a hiscore source; got " + matched.size(),
			matched.size() >= 60);
		for (String mustMap : new String[]{
			"vorkath", "zulrah", "barrows", "the nightmare", "crystalline hunllef", "corrupted hunllef",
			"moons of peril", "fortis colosseum", "royal titans", "leviathan", "whisperer",
			"tombs of amascut", "chambers of xeric", "theatre of blood"})
		{
			assertTrue("CA boss '" + mustMap + "' lost its hiscore source",
				matched.values().contains(mustMap));
		}
	}

	private static Set<String> datasetMonsterKeys()
	{
		Set<String> monsters = new TreeSet<>();
		try (InputStream in = HiscoreCoverageTest.class.getResourceAsStream(
			"/com/pluginideahub/combatachievements/combat_achievements.json"))
		{
			assertNotNull(in);
			JsonObject root = JsonParser.parseReader(
				new InputStreamReader(in, StandardCharsets.UTF_8)).getAsJsonObject();
			for (JsonElement t : root.getAsJsonArray("tasks"))
			{
				JsonElement m = t.getAsJsonObject().get("monster");
				if (m != null && !m.isJsonNull())
				{
					String name = m.getAsString().trim();
					if (!name.isEmpty() && !"None".equalsIgnoreCase(name))
					{
						monsters.add(name.toLowerCase(Locale.ROOT));
					}
				}
			}
		}
		catch (Exception ex)
		{
			throw new AssertionError(ex);
		}
		return monsters;
	}
}

package com.pluginideahub.combatachievements.bridge;

import java.util.HashMap;
import java.util.Map;
import net.runelite.client.hiscore.HiscoreResult;
import net.runelite.client.hiscore.HiscoreSkill;
import net.runelite.client.hiscore.Skill;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;

public class HiscoreKcReaderTest
{
	private static Skill kc(int value)
	{
		return new Skill(value <= 0 ? -1 : 1000, value, 0L);
	}

	@Test
	public void mapsHiscoreBossesToDatasetMonsterKeys()
	{
		Map<HiscoreSkill, Skill> skills = new HashMap<>();
		skills.put(HiscoreSkill.VORKATH, kc(250));
		skills.put(HiscoreSkill.THE_GAUNTLET, kc(80));          // -> Crystalline Hunllef
		skills.put(HiscoreSkill.THE_CORRUPTED_GAUNTLET, kc(15)); // -> Corrupted Hunllef
		skills.put(HiscoreSkill.BARROWS_CHESTS, kc(40));         // -> Barrows
		skills.put(HiscoreSkill.NIGHTMARE, kc(12));              // -> The Nightmare
		skills.put(HiscoreSkill.ABYSSAL_SIRE, kc(-1));           // unranked -> skipped

		Map<String, Integer> out = HiscoreKcReader.read(new HiscoreResult("player", skills));

		assertEquals(Integer.valueOf(250), out.get("vorkath"));
		assertEquals(Integer.valueOf(80), out.get("crystalline hunllef"));
		assertEquals(Integer.valueOf(15), out.get("corrupted hunllef"));
		assertEquals(Integer.valueOf(40), out.get("barrows"));
		assertEquals(Integer.valueOf(12), out.get("the nightmare"));
		assertFalse("unranked boss is skipped", out.containsKey("abyssal sire"));
	}

	@Test
	public void nullResultIsEmpty()
	{
		assertEquals(0, HiscoreKcReader.read(null).size());
	}
}

package com.pluginideahub.combatachievements.bridge;

import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

public class KillCountTrackerTest
{
	@Test
	public void parsesStandardKillCountLine()
	{
		KillCountTracker.Update u = KillCountTracker.parse("Your Vorkath kill count is: 1,234.").get();
		assertEquals("Vorkath", u.boss());
		assertEquals(1234, u.count());
	}

	@Test
	public void parsesRaidCompletionLines()
	{
		assertEquals("Chambers of Xeric",
			KillCountTracker.parse("Your completed Chambers of Xeric count is: 50").get().boss());
		assertEquals(12, KillCountTracker.parse(
			"Your Theatre of Blood total completion count is: 12").get().count());
	}

	@Test
	public void ignoresNonKillCountMessages()
	{
		assertFalse(KillCountTracker.parse("You feel something weird sneaking into your backpack.").isPresent());
		assertFalse(KillCountTracker.parse(null).isPresent());
		// A bare "... count is:" (e.g. a non-boss tally) must NOT register as a fake boss.
		assertFalse(new KillCountTracker().onMessage("Your slayer task count is: 5"));
	}

	@Test
	public void canonicalisesBossNamesToTheDatasetNamespace()
	{
		KillCountTracker tracker = new KillCountTracker();
		tracker.onMessage("Your Nightmare kill count is: 30.");
		// Stored under the dataset spelling "The Nightmare", not the raw chat name.
		assertEquals(30, tracker.snapshot().kcFor("The Nightmare"));
		assertEquals(0, tracker.snapshot().kcFor("Nightmare"));
	}

	@Test
	public void accumulatesAndExposesExperience()
	{
		KillCountTracker tracker = new KillCountTracker();
		assertTrue(tracker.onMessage("Your Vorkath kill count is: 40."));
		assertTrue(tracker.onMessage("Your Vorkath kill count is: 41."));
		assertFalse(tracker.onMessage("just a normal message"));
		assertEquals(41, tracker.snapshot().kcFor("Vorkath"));
		// Counts only go up — a stale lower value never overwrites.
		tracker.onMessage("Your Vorkath kill count is: 5.");
		assertEquals(41, tracker.snapshot().kcFor("vorkath"));
	}
}

