import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

/**
 * Farming is bounded by the calendar, not by time at the keyboard: its patches grow on multi-hour
 * timers, so its bundled rate is an xpPerDay allowance the engine spreads over 24 elapsed hours.
 * Before this, the wiki's "per actively spent hour" figures (up to 2.5m xp/hr) were read literally and
 * the model believed 70-90 took about 27 minutes.
 */
public class DailyGatedSkillTest
{
	private final SkillXpLibrary lib = SkillXpLibrary.loadBundled();

	private static double days(double hours)
	{
		return hours / 24.0;
	}

	@Test
	public void farmingIsCostedInCalendarDays()
	{
		// 20,000/day to 50 and 50,000/day after: level 50 is 101,333 xp, level 65 is 449,428.
		double toFifty = lib.hoursToTrain("Farming", 1, 50);
		assertEquals("1-50 at 20k a day", 5.1, days(toFifty), 0.2);

		double toHespori = lib.hoursToTrain("Farming", 1, 65);
		assertEquals("1-65 for Hespori, a fortnight of tree runs", 12.0, days(toHespori), 0.3);
	}

	@Test
	public void theOldPerActiveHourFigureNoLongerMakesHighLevelFarmingFree()
	{
		// The bug this replaces: at 2.4m xp/hr, 70-90 came out at roughly 27 minutes, so any quest gated
		// on high Farming looked free to the unlock planner.
		double hours = lib.hoursToTrain("Farming", 70, 90);
		assertTrue("70-90 must not read as an afternoon (got " + hours + " hr)", hours > 100);
		// 70-90 is 4.6m xp — three months of daily runs, not 27 minutes.
		assertEquals("about 92 days at 50k a day", 92.2, days(hours), 1.0);
	}

	@Test
	public void onlyFarmingIsFlaggedAsCalendarTime()
	{
		// Drives whether the panel reads an estimate in days. Slayer is long but you have to sit and play
		// it, so it must never be flagged — showing its 83 hours as "3.5 days" implied it passes offline.
		assertTrue("Farming waits on patch timers", lib.isDailyGated("Farming", 1, 65));
		assertFalse("Slayer is time at the keyboard", lib.isDailyGated("Slayer", 1, 92));
		assertFalse(lib.isDailyGated("Firemaking", 1, 50));
		assertFalse("an unknown skill is not calendar-gated", lib.isDailyGated("Nonsense", 1, 50));
	}

	@Test
	public void slayerRatesAreCappedAtFortyThousand()
	{
		// Published Slayer rates assume barrage-stacking ideal tasks with a full setup; ordinary play with
		// travel, bad tasks and skips does not sustain them.
		double hours = lib.hoursToTrain("Slayer", 1, 92);
		assertTrue("1-92 Slayer is a real grind, not a weekend (got " + hours + " hr)",
			hours > 140 && hours < 200);
	}

	@Test
	public void anOrdinarySkillIsStillCostedInHoursPlayed()
	{
		// Only daily-gated brackets carry xpPerDay; everything else keeps the hours-played convention.
		double firemaking = lib.hoursToTrain("Firemaking", 1, 50);
		assertTrue("Firemaking 1-50 is an evening, not a fortnight (got " + firemaking + " hr)",
			firemaking > 0.5 && firemaking < 12);
	}

	@Test
	public void farmingOutranksNothingItShouldNot()
	{
		// The point of the change: per hour of effort, Farming must now cost far more than a skill you can
		// simply sit and train to the same level.
		assertTrue("Farming to 65 must cost more than Firemaking to 65",
			lib.hoursToTrain("Farming", 1, 65) > 10 * lib.hoursToTrain("Firemaking", 1, 65));
	}
}

package com.pluginideahub.combatachievements.core.effort;

import java.io.ByteArrayInputStream;
import java.nio.charset.StandardCharsets;
import java.util.Collections;
import java.util.HashSet;
import java.util.Set;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertSame;
import static org.junit.Assert.assertTrue;

public class EffortLibrariesTest
{
	private static ByteArrayInputStream stream(String json)
	{
		return new ByteArrayInputStream(json.getBytes(StandardCharsets.UTF_8));
	}

	@Test
	public void bundledTimingLoads()
	{
		BossTimingLibrary lib = BossTimingLibrary.loadBundled();
		assertTrue("expected the bundled boss timing", lib.count() >= 80);
		assertTrue(lib.timingFor("Vorkath").isKnown());
		assertEquals(BossTiming.UNKNOWN, lib.timingFor("Not A Boss"));
	}

	@Test
	public void timingSecondsPerKillAddsRespawn()
	{
		BossTimingLibrary lib = BossTimingLibrary.load(stream(
			"{\"monsters\":{\"Test Boss\":{\"ttkSeconds\":50,\"respawnSeconds\":10,\"killsPerHour\":60}}}"));
		assertEquals(60, lib.timingFor("test boss").secondsPerKill());
	}

	@Test
	public void malformedTimingIsSafe()
	{
		BossTimingLibrary lib = BossTimingLibrary.load(stream("not json"));
		assertEquals(0, lib.count());
		assertSame(BossTiming.UNKNOWN, lib.timingFor("anything"));
	}

	@Test
	public void questPrerequisiteClosureWalksTheGraph()
	{
		QuestEffortLibrary lib = QuestEffortLibrary.load(stream(
			"{\"quests\":{"
				+ "\"A\":{\"name\":\"A\",\"estMinutes\":10,\"directPrerequisiteQuests\":[\"B\"]},"
				+ "\"B\":{\"name\":\"B\",\"estMinutes\":20,\"directPrerequisiteQuests\":[\"C\"]},"
				+ "\"C\":{\"name\":\"C\",\"estMinutes\":30,\"directPrerequisiteQuests\":[]}"
				+ "}}"));
		Set<String> prereqs = lib.fullPrerequisites("A");
		assertTrue(prereqs.contains("B"));
		assertTrue(prereqs.contains("C"));
		assertEquals(2, prereqs.size());

		// Remaining minutes = A + B + C when nothing done; subtracts completed quests.
		assertEquals(60, lib.remainingQuestMinutes("A", Collections.emptySet()));
		Set<String> doneB = new HashSet<>(Collections.singletonList("b"));
		assertEquals(40, lib.remainingQuestMinutes("A", doneB)); // A(10)+C(30), B skipped
	}

	@Test
	public void questGraphToleratesCycles()
	{
		QuestEffortLibrary lib = QuestEffortLibrary.load(stream(
			"{\"quests\":{"
				+ "\"X\":{\"name\":\"X\",\"directPrerequisiteQuests\":[\"Y\"]},"
				+ "\"Y\":{\"name\":\"Y\",\"directPrerequisiteQuests\":[\"X\"]}}}"));
		// Should not stack-overflow.
		assertTrue(lib.fullPrerequisites("X").contains("Y"));
	}

	@Test
	public void skillXpTableMatchesKnownValues()
	{
		// Canonical OSRS experience milestones.
		assertEquals(0, SkillXpLibrary.xpAtLevel(1));
		assertEquals(83, SkillXpLibrary.xpAtLevel(2));
		assertEquals(273742, SkillXpLibrary.xpAtLevel(60));
		assertEquals(13034431, SkillXpLibrary.xpAtLevel(99));
	}

	@Test
	public void hoursToTrainUsesBracketRates()
	{
		// 100k xp/hr flat across the range; train 60->70 should be (xp(70)-xp(60))/100k hours.
		SkillXpLibrary lib = SkillXpLibrary.load(stream(
			"{\"skills\":{\"Magic\":{\"skill\":\"Magic\",\"brackets\":["
				+ "{\"fromLevel\":1,\"toLevel\":99,\"method\":\"x\",\"xpPerHour\":100000,\"members\":true}]}}}"));
		double expected = (SkillXpLibrary.xpAtLevel(70) - SkillXpLibrary.xpAtLevel(60)) / 100000.0;
		assertEquals(expected, lib.hoursToTrain("magic", 60, 70), 1e-6);
		assertEquals("already there", 0.0, lib.hoursToTrain("Magic", 80, 70), 1e-9);
		assertEquals("no data", 0.0, lib.hoursToTrain("Cooking", 1, 99), 1e-9);
	}
}

package com.pluginideahub.combatachievements.core.effort;

import org.junit.Test;

import static org.junit.Assert.assertEquals;

public class MonsterNamesTest
{
	@Test
	public void mapsArticledAndStructuralAliasesToDatasetKeys()
	{
		assertEquals("the nightmare", MonsterNames.toDatasetKey("Nightmare"));
		assertEquals("the mimic", MonsterNames.toDatasetKey("Mimic"));
		assertEquals("barrows", MonsterNames.toDatasetKey("Barrows Chests"));
		assertEquals("crystalline hunllef", MonsterNames.toDatasetKey("The Gauntlet"));
		assertEquals("crystalline hunllef", MonsterNames.toDatasetKey("Gauntlet"));
		assertEquals("corrupted hunllef", MonsterNames.toDatasetKey("The Corrupted Gauntlet"));
		assertEquals("leviathan", MonsterNames.toDatasetKey("The Leviathan"));
		assertEquals("moons of peril", MonsterNames.toDatasetKey("Lunar Chests"));
		assertEquals("fortis colosseum", MonsterNames.toDatasetKey("Sol Heredit"));
		// Raid mode variants: re-insert the colon the chat line drops.
		assertEquals("chambers of xeric: challenge mode",
			MonsterNames.toDatasetKey("Chambers of Xeric Challenge Mode"));
