	{
		assertEquals("vorkath", MonsterNames.toDatasetKey("Vorkath"));
		assertEquals("abyssal sire", MonsterNames.toDatasetKey("Abyssal Sire"));
		// Hiscore CoX-CM already has the colon — must stay stable.
		assertEquals("chambers of xeric: challenge mode",
			MonsterNames.toDatasetKey("Chambers of Xeric: Challenge Mode"));
		assertEquals("", MonsterNames.toDatasetKey(null));
	}
}

package com.pluginideahub.combatachievements.core.effort;

import com.pluginideahub.combatachievements.core.achievement.AchievementTier;
import com.pluginideahub.combatachievements.core.achievement.CombatAchievement;
import com.pluginideahub.combatachievements.core.achievement.TaskDifficultyLibrary;
import com.pluginideahub.combatachievements.core.achievement.TaskType;
import java.io.ByteArrayInputStream;
import java.nio.charset.StandardCharsets;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;

public class SynergyRankerTest
{
	// Distinct execution tasks (each its own attempts — additive within a boss, unlike nested KC).
	private static CombatAchievement task(int id, String monster, int points)
	{
		return new CombatAchievement(id, "T" + id, AchievementTier.HARD, monster,
			TaskType.RESTRICTION, points, "Restriction challenge " + id + ".", "", "");
	}

	private static CombatAchievement kc(int id, String monster, int killThreshold)
	{
		return new CombatAchievement(id, "KC" + id, AchievementTier.HARD, monster,
			TaskType.KILL_COUNT, 3, "Kill " + monster + " " + killThreshold + " times.", "", "");
	}

	// Both bosses kill in 60s; a CA = 1 kill = ~1 min each.
	private static BossTimingLibrary timing()
	{
		return BossTimingLibrary.load(new ByteArrayInputStream((
			"{\"monsters\":{"
				+ "\"Dense Boss\":{\"ttkSeconds\":54,\"respawnSeconds\":6,\"killsPerHour\":60},"
				+ "\"Lone Boss\":{\"ttkSeconds\":54,\"respawnSeconds\":6,\"killsPerHour\":60}}}")
			.getBytes(StandardCharsets.UTF_8)));
	}

	@Test
	public void denseBossBundleOutranksScatteredSingle()
	{
		// Dense Boss has 4 doable CAs (4 pts total); Lone Boss has 1 CA (2 pts). With a shared trip
		// overhead, the 4-CA boss is the better next session despite each CA being individually small.
		List<CombatAchievement> tasks = new ArrayList<>();
		for (int i = 0; i < 4; i++)
		{
			tasks.add(task(i, "Dense Boss", 1));
		}
		tasks.add(task(99, "Lone Boss", 2));

		List<BossSession> sessions = SynergyRanker.standard().rank(tasks, timing(), CombatExperience.empty(), com.pluginideahub.combatachievements.core.achievement.TaskDifficultyLibrary.empty());
		assertEquals("Dense Boss", sessions.get(0).monster());
		assertEquals(4, sessions.get(0).taskCount());
		assertEquals(4, sessions.get(0).totalPoints());
		assertTrue(sessions.get(0).score() > sessions.get(1).score());
	}

	@Test
	public void pointsPerHourIsScorePerMinuteScaledToAnHour()
	{
		// pts/hr is just the per-minute score × 60 — the same ranking, expressed in the units the
		// "Next session" tab and the curation spreadsheet show.
		List<CombatAchievement> tasks = Arrays.asList(kc(1, "Dense Boss", 60));
		BossSession s = new SynergyRanker(TaskTimeModel.standard(), 0)
			.rank(tasks, timing(), CombatExperience.empty(), TaskDifficultyLibrary.empty()).get(0);

		assertEquals(s.score() * 60.0, s.pointsPerHour(), 1e-9);
		// 3 pts over a 60-min grind (60s/kill × 60 kills, 0 overhead) ⇒ 3 pts/hr.
		assertEquals(3.0, s.pointsPerHour(), 1e-9);
	}

	@Test
	public void stackedKillCountChargesIncrementalMilestones()
	{
		// Three nested Kill Count CAs at one boss (25 / 75 / 150), zero KC, 60s/kill. Reaching 150 also
		// clears 25 and 75, so the rungs cost the INCREMENTAL kills (25, +50, +75 = 150 min total) — not
		// 25 + 75 + 150 = 250 — yet the lowest rung keeps a real, short time ("just do 25").
		List<CombatAchievement> tasks = Arrays.asList(
			kc(1, "Dense Boss", 25), kc(2, "Dense Boss", 75), kc(3, "Dense Boss", 150));
		TaskDifficultyLibrary none = TaskDifficultyLibrary.empty();

		BossSession s = new SynergyRanker(TaskTimeModel.standard(), 0)
			.rank(tasks, timing(), CombatExperience.empty(), none).get(0);

		assertEquals("collapsed to one 150-kill grind, not three", 150, s.totalMinutes());

		int sum = 0;
		int lowestRungMinutes = -1;
		int lowestThreshold = Integer.MAX_VALUE;
		for (BossSession.Item it : s.items())
		{
			sum += it.sessionMinutes();
			if (it.estimate().requiredKills() < lowestThreshold)
			{
				lowestThreshold = it.estimate().requiredKills();
				lowestRungMinutes = it.sessionMinutes();
			}
		}
		assertEquals("rungs sum to the single grind", 150, sum);
		assertEquals("the 25-kill rung is a real short option (25 min), not zero", 25, lowestRungMinutes);
	}

	@Test
	public void overheadDialControlsClustering()
	{
		// Dense Boss: 3 CAs (3 pts total, 3 min); Lone Boss: 1 CA (2 pts, 1 min, better points/min).
		List<CombatAchievement> tasks = new ArrayList<>();
		tasks.add(task(1, "Dense Boss", 1));
		tasks.add(task(2, "Dense Boss", 1));
		tasks.add(task(4, "Dense Boss", 1));
		tasks.add(task(3, "Lone Boss", 2));

		// With near-zero overhead, the single 2-pt CA (better points/min) leads.
		List<BossSession> lowO = new SynergyRanker(TaskTimeModel.standard(), 0)
			.rank(tasks, timing(), CombatExperience.empty(), com.pluginideahub.combatachievements.core.achievement.TaskDifficultyLibrary.empty());
		assertEquals("Lone Boss", lowO.get(0).monster());

		// With a big overhead, bundling the two Dense CAs wins.
		List<BossSession> highO = new SynergyRanker(TaskTimeModel.standard(), 30)
			.rank(tasks, timing(), CombatExperience.empty(), com.pluginideahub.combatachievements.core.achievement.TaskDifficultyLibrary.empty());
		assertEquals("Dense Boss", highO.get(0).monster());
	}

	@Test
	public void higherDifficultyExecutionTaskCostsMoreSessionMinutes()
	{
		// Two execution CAs at one boss; the higher-Difficulty one needs more attempts, so its session
		// contribution (minutes) is larger — proving Difficulty flows through the ranker into the estimate.
		TaskDifficultyLibrary diffs = TaskDifficultyLibrary.load(new ByteArrayInputStream(
			"{\"tasks\":{\"1\":{\"difficulty\":10},\"2\":{\"difficulty\":2}}}".getBytes(StandardCharsets.UTF_8)));

		BossSession s = new SynergyRanker(TaskTimeModel.standard(), 0)
			.rank(Arrays.asList(task(1, "Dense Boss", 3), task(2, "Dense Boss", 3)),
				timing(), CombatExperience.empty(), diffs).get(0);

		int hardMin = itemMinutes(s, 1);
		int easyMin = itemMinutes(s, 2);
		assertTrue("harder task costs more session minutes (" + hardMin + " vs " + easyMin + ")",
			hardMin > easyMin);
	}

	private static int itemMinutes(BossSession s, int taskId)
	{
		for (BossSession.Item it : s.items())
		{
			if (it.task().id() == taskId)
			{
				return it.sessionMinutes();
			}
		}
		return -1;
	}
}

package com.pluginideahub.combatachievements.core.effort;

import com.pluginideahub.combatachievements.core.achievement.AchievementTier;
import com.pluginideahub.combatachievements.core.achievement.CombatAchievement;
import com.pluginideahub.combatachievements.core.achievement.TaskType;
import java.util.HashMap;
import java.util.Map;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

public class TaskTimeModelTest
{
	private static final BossTiming SIXTY = new BossTiming(50, 10, 60, ""); // 60s per kill
	private static final BossTiming SIXTY_DEADLY = new BossTiming(50, 10, 60, "", 10.0); // 10 attempts/kill

	private static CombatAchievement kc(int id, int points, String desc)
	{
		return new CombatAchievement(id, "T" + id, AchievementTier.HARD, "Vorkath",
			TaskType.KILL_COUNT, points, desc, "", "");
	}

	private static CombatAchievement perfection()
	{
		return new CombatAchievement(9, "Perfect", AchievementTier.MASTER, "Vorkath",
			TaskType.PERFECTION, 5, "Kill Vorkath without taking damage.", "", "");
	}

	private static CombatExperience withKc(int vorkath)
	{
		Map<String, Integer> m = new HashMap<>();
		m.put("Vorkath", vorkath);
		return CombatExperience.of(m);
	}

	@Test
	public void parsesKillCountFromWording()
	{
		assertEquals(100, TaskTimeModel.requiredKills("Kill Vorkath 100 times."));
		assertEquals(6, TaskTimeModel.requiredKills("Kill 6 Giant Rats within the lair."));
		assertEquals(1, TaskTimeModel.requiredKills("Kill an Aberrant Spectre."));
		assertEquals("count at end of string", 6, TaskTimeModel.requiredKills("Kill 6"));
		assertEquals("uppercase still parses (locale-safe)", 50, TaskTimeModel.requiredKills("KILL VORKATH 50 TIMES"));
		assertEquals("overflow falls back to 1, not a crash", 1,
			TaskTimeModel.requiredKills("Kill it 99999999999 times"));
	}

	@Test
	public void nonKillCountTaskDoesNotSubtractKc()
	{
		// A counted Mechanical task ("kill 6 ... in 3s") must NOT treat boss KC as completions.
		CombatAchievement mech = new CombatAchievement(20, "Efficient", AchievementTier.MEDIUM, "Vorkath",
			TaskType.MECHANICAL, 2, "Kill 6 things within 3 seconds.", "", "");
		TaskTimeModel.Estimate est = TaskTimeModel.standard().estimate(mech, SIXTY, withKc(500));
		assertTrue("KC is not subtracted for execution tasks", est.minutes() > 0);
		assertFalse(est.hasPartialProgress());
	}

	@Test
	public void killCountUsesRemainingAfterPartialProgress()
	{
		TaskTimeModel model = TaskTimeModel.standard();
		// "Kill Vorkath 50 times", already 30 KC -> 20 left x 60s = 1200s = 20 min.
		TaskTimeModel.Estimate est = model.estimate(kc(1, 4, "Kill Vorkath 50 times."), SIXTY, withKc(30));
		assertEquals(50, est.requiredKills());
		assertEquals(30, est.currentKc());
		assertEquals(20, est.remainingKills());
		assertEquals(20, est.minutes());
		assertTrue(est.hasPartialProgress());
	}

	@Test
	public void completedGrindCostsNothing()
	{
		TaskTimeModel model = TaskTimeModel.standard();
		TaskTimeModel.Estimate est = model.estimate(kc(1, 4, "Kill Vorkath 50 times."), SIXTY, withKc(60));
		assertEquals(0, est.remainingKills());
		assertEquals(0, est.minutes());
	}

	@Test
	public void hardMechanicCostsMoreAttemptsThanEasyRestriction()
	{
		TaskTimeModel model = TaskTimeModel.standard();
		// Both Restriction, both novice. The high-Difficulty coordination task should cost materially
		// more attempts than a low-Difficulty one — the curated pure-skill Difficulty (which already
		// folds in the "within 3 seconds" bump), not completion %, now drives the ability rating.
		CombatAchievement coord = new CombatAchievement(30, "Three in Three", AchievementTier.HARD, "Vorkath",
			TaskType.RESTRICTION, 5, "Kill three within 3 seconds.", "", "");
		CombatAchievement easy = new CombatAchievement(31, "Stab It", AchievementTier.HARD, "Vorkath",
			TaskType.RESTRICTION, 4, "Kill it with a stab weapon.", "", "");

		int coordMin = model.estimate(coord, SIXTY, withKc(0), 10).minutes();   // difficulty 10 → rating 5
		int easyMin = model.estimate(easy, SIXTY, withKc(0), 3).minutes();      // difficulty 3 → rating 2
		assertTrue("the hard coordination task should estimate longer (" + coordMin + " vs " + easyMin + ")",
			coordMin > easyMin + 2);
		assertEquals(5, model.estimate(coord, SIXTY, withKc(0), 10).abilityRating());
		assertTrue(model.estimate(easy, SIXTY, withKc(0), 3).abilityRating() <= 2);
	}

	@Test
	public void competenceStillDiscountsTheHardTask()
	{
		TaskTimeModel model = TaskTimeModel.standard();
		CombatAchievement coord = new CombatAchievement(30, "Three in Three", AchievementTier.HARD, "Vorkath",
			TaskType.RESTRICTION, 5, "Kill three within 3 seconds.", "", "");
		int novice = model.estimate(coord, SIXTY, withKc(0), 10).minutes();
		int veteran = model.estimate(coord, SIXTY, withKc(500), 10).minutes();
		assertTrue("a veteran still clears the hard task far quicker", veteran < novice);
	}

	@Test
	public void competenceReducesExecutionTaskTime()
	{
		TaskTimeModel model = TaskTimeModel.standard();
		int novice = model.estimate(perfection(), SIXTY, withKc(0)).minutes();      // more attempts
		int veteran = model.estimate(perfection(), SIXTY, withKc(500)).minutes();   // competence discount
		assertTrue("a veteran needs fewer attempts at a perfection task", veteran < novice);
		assertEquals(CombatExperience.Competence.VETERAN,
			model.estimate(perfection(), SIXTY, withKc(500)).competence());
	}

	@Test
	public void abilityRatingMapsDifficultyToFivePointScale()
	{
		// Two difficulty points per rung; mid difficulty (5–6) is the neutral rating 3.
		assertEquals(1, TaskTimeModel.abilityRating(1));
		assertEquals(1, TaskTimeModel.abilityRating(2));
		assertEquals(2, TaskTimeModel.abilityRating(3));
		assertEquals(3, TaskTimeModel.abilityRating(5));
		assertEquals(3, TaskTimeModel.abilityRating(6));
		assertEquals(4, TaskTimeModel.abilityRating(7));
		assertEquals(5, TaskTimeModel.abilityRating(10));
		// Out-of-range is clamped, never throwing.
		assertEquals(1, TaskTimeModel.abilityRating(0));
		assertEquals(5, TaskTimeModel.abilityRating(99));
	}

	@Test
	public void deadlinessScalesSingleKillTimeForNovice()
	{
		TaskTimeModel model = TaskTimeModel.standard();
		CombatAchievement task = kc(1, 4, "Kill Vorkath.");   // one kill, 60s each
		int normal = model.estimate(task, SIXTY, withKc(0)).minutes();          // deadliness 1 -> 1 min
		int deadly = model.estimate(task, SIXTY_DEADLY, withKc(0)).minutes();   // deadliness 10 -> 10 min
		assertEquals("a normal single kill stays one kill", 1, normal);
		assertEquals("a deadly boss charges ~10 attempts for the same kill", 10, deadly);
	}

	@Test
	public void deadlinessOfOneMatchesTheOldEstimate()
	{
		// The whole model is unchanged for every non-deadly boss (attempts/kill defaults to 1).
		TaskTimeModel model = TaskTimeModel.standard();
		assertEquals(20, model.estimate(kc(1, 4, "Kill Vorkath 50 times."), SIXTY, withKc(30)).minutes());
	}

	@Test
	public void perCaOverrideReplacesBossDeadliness()
	{
		TaskTimeModel model = TaskTimeModel.standard();
		CombatAchievement task = kc(1, 4, "Kill Vorkath.");
		// Override 3 wins over the boss's 10 -> 3 attempts -> 3 min.
		int overridden = model.estimate(task, SIXTY_DEADLY, withKc(0), 1, 3.0).minutes();
		assertEquals(3, overridden);
	}

	@Test
	public void competenceDiscountsTheDeadlinessAttempts()
	{
		TaskTimeModel model = TaskTimeModel.standard();
		CombatAchievement task = kc(1, 4, "Kill Vorkath.");
		int novice = model.estimate(task, SIXTY_DEADLY, withKc(0)).minutes();     // 1 + 9*1.0  = 10 min
		int veteran = model.estimate(task, SIXTY_DEADLY, withKc(500)).minutes();  // 1 + 9*0.35 ≈ 5 min
		assertTrue("a veteran dies far less at a deadly boss (" + veteran + " < " + novice + ")",
			veteran < novice);
	}

	@Test
	public void unknownTimingFallsBackNotZero()
	{
		TaskTimeModel model = TaskTimeModel.standard();
		TaskTimeModel.Estimate est = model.estimate(
			kc(1, 4, "Kill Vorkath 10 times."), BossTiming.UNKNOWN, CombatExperience.empty());
		assertTrue("fallback keeps a non-zero estimate", est.minutes() > 0);
	}
}

package com.pluginideahub.combatachievements.core.effort;

import com.pluginideahub.combatachievements.core.achievement.CombatAchievementLibrary;
import com.pluginideahub.combatachievements.core.achievement.EffortDataLibrary;
import com.pluginideahub.combatachievements.core.achievement.RecStatsLibrary;
import com.pluginideahub.combatachievements.core.ranking.PlayerProfile;
import java.util.Arrays;
import java.util.Collections;
import java.util.HashMap;
import java.util.HashSet;
import java.util.List;
import java.util.Map;
import java.util.Set;
import org.junit.Test;

import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

/** The "Train next" planner: it must help a held-back account and stay silent for an established one. */
public class TrainingPlannerTest
{
	private static final String[] ALL = {
		"Attack", "Strength", "Defence", "Ranged", "Magic", "Hitpoints", "Prayer", "Slayer",
		"Mining", "Herblore", "Farming", "Construction", "Agility", "Thieving", "Firemaking", "Fishing",
		"Woodcutting", "Crafting", "Fletching", "Runecraft", "Hunter", "Smithing", "Cooking"
	};

	private final CombatAchievementLibrary lib = CombatAchievementLibrary.loadBundled();
	private final EffortDataLibrary effort = EffortDataLibrary.loadBundled();
	private final RecStatsLibrary recStats = RecStatsLibrary.loadBundled();
	private final TrainingPlanner planner = new TrainingPlanner(SkillXpLibrary.loadBundled());

	private static PlayerProfile account(int everySkill)
	{
		Map<String, Integer> levels = new HashMap<>();
		for (String s : ALL)
		{
			levels.put(s, everySkill);
		}
		Set<String> quests = new HashSet<>(Arrays.asList("Priest in Peril", "The Restless Ghost"));
		return PlayerProfile.of(levels, quests, quests);
	}

	private List<TrainingSuggestion> plan(PlayerProfile p)
	{
		return planner.plan(lib.all(), Collections.emptySet(), effort, recStats, p, 6);
	}

	@Test
	public void suggestsTrainingForAnAccountHeldBackByLevels()
	{
		List<TrainingSuggestion> out = plan(account(1));
		assertFalse("a level-1 account is held back and should get advice", out.isEmpty());
		for (TrainingSuggestion s : out)
		{
			assertTrue("every suggestion must open at least one CA", s.unlockedTaskCount() > 0);
			assertTrue("and name what to train", !s.label().isEmpty());
		}
	}

	@Test
	public void staysSilentForAnAccountThatIsNotHeldBack()
	{
		// Self-suppressing: a maxed account gains nothing from any goal, so the section disappears rather
		// than inventing busywork.
		assertTrue("a maxed account needs no training advice", plan(account(99)).isEmpty());
	}

	@Test
	public void rankedByRateFirstThenTheBeginnerLadderAscending()
	{
		// The scored goals (skilling, and for graduated accounts the combat milestones) lead in
		// best-rate order; a beginner's combat rungs ride after them, lowest level first.
		List<TrainingSuggestion> out = plan(account(1));
		int firstRung = out.size();
		for (int i = 0; i < out.size(); i++)
		{
			if (out.get(i).isToward())
			{
				firstRung = i;
				break;
			}
		}
		for (int i = 1; i < firstRung; i++)
		{
			assertTrue("scored suggestions must be ordered best-rate first",
				out.get(i - 1).score() >= out.get(i).score() - 1e-9);
		}
		for (int i = firstRung; i < out.size(); i++)
		{
			assertTrue("everything after the first rung is a rung", out.get(i).isToward());
			assertTrue("each rung raises one skill", out.get(i).skills().size() == 1);
			if (i > firstRung)
			{
				assertTrue("rungs climb, lowest first",
					out.get(i - 1).targetLevel() <= out.get(i).targetLevel());
			}
		}
	}

	@Test
	public void aSkillerIsNotToldToTrainWhatTheyAlreadyHave()
	{
		// Wintertodt (Firemaking 50) and Tempoross (Fishing 35) are the headline skilling gates: a level-1
		// account should be pointed at them, a 70-skilling account should not.
		Map<String, Integer> skiller = new HashMap<>();
		for (String s : ALL)
		{
			skiller.put(s, 1);
		}
		for (String s : new String[]{"Firemaking", "Fishing", "Woodcutting", "Fletching", "Mining",
			"Farming", "Herblore", "Crafting", "Smithing", "Agility", "Thieving", "Hunter", "Runecraft",
			"Construction", "Cooking"})
		{
			skiller.put(s, 70);
		}
		Set<String> quests = new HashSet<>(Arrays.asList("Priest in Peril", "The Restless Ghost"));
		PlayerProfile p = PlayerProfile.of(skiller, quests, quests);
		for (TrainingSuggestion s : plan(p))
		{
			// The real invariant: a goal must aim ABOVE what the player has. "Fishing 76" for a
			// 70-fishing skiller is a legitimate goal (a Tempoross CA recommends it); "Fishing 35" is not.
			for (String skill : s.skills())
			{
				assertTrue("goal " + s.label() + " targets a level already reached",
					s.targetLevel() > p.levelOf(skill) || s.skills().size() > 1);
			}
		}
	}

	@Test
	public void hasNoSuggestionsWithoutAProfile()
	{
		assertTrue(planner.plan(lib.all(), Collections.emptySet(), effort, recStats,
			PlayerProfile.empty(), 6).isEmpty());
	}

	@Test
	public void everySuggestionCarriesTheTasksItOpens()
	{
		for (TrainingSuggestion s : plan(account(1)))
		{
			assertTrue("points opened should be positive", s.unlockedPoints() > 0);
			assertTrue("target level should be a real level", s.targetLevel() > 0 && s.targetLevel() <= 99);
		}
	}
}

package com.pluginideahub.combatachievements.core.effort;

import com.pluginideahub.combatachievements.core.achievement.AchievementTier;
import com.pluginideahub.combatachievements.core.achievement.CombatAchievement;
import com.pluginideahub.combatachievements.core.achievement.EffortDataLibrary;
import com.pluginideahub.combatachievements.core.achievement.TaskDifficultyLibrary;
import com.pluginideahub.combatachievements.core.achievement.TaskType;
import com.pluginideahub.combatachievements.core.ranking.PlayerProfile;
import java.io.ByteArrayInputStream;
import java.nio.charset.StandardCharsets;
import java.util.Arrays;
import java.util.Collections;
import java.util.HashMap;
import java.util.HashSet;
import java.util.List;
import java.util.Map;
import java.util.Set;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;

public class UnlockPlannerTest
{
	private static ByteArrayInputStream s(String json)
	{
		return new ByteArrayInputStream(json.getBytes(StandardCharsets.UTF_8));
	}

	private static CombatAchievement task(int id, int points)
	{
		return new CombatAchievement(id, "T" + id, AchievementTier.ELITE, "Boss",
			TaskType.KILL_COUNT, points, "Kill Boss.", "", "");
	}

	// Tasks 1 & 2 gated by Dragon Slayer II; task 3 gated by Regicide.
	private static EffortDataLibrary effort()
	{
		return EffortDataLibrary.load(s("{\"tasks\":{"
			+ "\"1\":{\"questReqs\":[\"Dragon Slayer II\"]},"
			+ "\"2\":{\"questReqs\":[\"Dragon Slayer II\"]},"
			+ "\"3\":{\"questReqs\":[\"Regicide\"]}}}"));
	}

	private static QuestEffortLibrary quests()
	{
		return QuestEffortLibrary.load(s("{\"quests\":{"
			+ "\"Dragon Slayer II\":{\"name\":\"Dragon Slayer II\",\"difficulty\":\"Grandmaster\","
			+ "\"estMinutes\":75,\"skillRequirements\":{\"Magic\":75},\"directPrerequisiteQuests\":[\"Legends' Quest\"]},"
			+ "\"Legends' Quest\":{\"name\":\"Legends' Quest\",\"estMinutes\":60,\"directPrerequisiteQuests\":[]},"
			+ "\"Regicide\":{\"name\":\"Regicide\",\"difficulty\":\"Experienced\",\"estMinutes\":40,\"directPrerequisiteQuests\":[]}"
			+ "}}"));
	}

	private static SkillXpLibrary skills()
	{
		return SkillXpLibrary.load(s("{\"skills\":{\"Magic\":{\"skill\":\"Magic\",\"brackets\":["
			+ "{\"fromLevel\":1,\"toLevel\":99,\"method\":\"x\",\"xpPerHour\":250000,\"members\":true}]}}}"));
	}

	private static PlayerProfile player(int magic, Set<String> doneQuests)
	{
		Map<String, Integer> levels = new HashMap<>();
		levels.put("Magic", magic);
		return PlayerProfile.of(levels, doneQuests, doneQuests);
	}

	@Test
	public void ranksQuestsByUnlockedPointsPerEffort()
	{
		List<CombatAchievement> tasks = Arrays.asList(task(1, 4), task(2, 4), task(3, 4));
		UnlockPlanner planner = new UnlockPlanner(quests(), skills());
		List<UnlockSuggestion> out = planner.plan(tasks, Collections.emptySet(), effort(),
			player(99, Collections.emptySet()));

		assertEquals(2, out.size());
		UnlockSuggestion ds2 = out.stream().filter(u -> u.questName().equals("Dragon Slayer II")).findFirst().get();
		UnlockSuggestion reg = out.stream().filter(u -> u.questName().equals("Regicide")).findFirst().get();

		assertEquals("DS2 unlocks both gated tasks", 2, ds2.unlockedTaskCount());
		assertEquals(8, ds2.unlockedPoints());
		assertTrue("DS2 chain includes its prerequisite", ds2.remainingPrerequisites().contains("Legends' Quest"));
		assertEquals(1, reg.unlockedTaskCount());

		// Regicide (40 min, no training, 4 pts) beats DS2 (75+60 min chain, 4pts/each but heavier) per minute.
		assertTrue("cheaper-per-point quest ranks first", out.get(0).score() >= out.get(1).score());
	}

	@Test
	public void difficultyWeightingRanksEasyUnlockAboveEqualCostHardUnlock()
	{
		// Two quests with identical time cost (40 min, no prereqs/training), each unlocking one 4-pt task:
		// one easy (difficulty 1), one brutal (difficulty 10). Difficulty weighting must rank the quest
		// that opens easy points first, while the raw unlockedPoints prize stays unchanged.
		EffortDataLibrary el = EffortDataLibrary.load(s("{\"tasks\":{"
			+ "\"1\":{\"questReqs\":[\"Easy Unlock\"]},"
			+ "\"2\":{\"questReqs\":[\"Hard Unlock\"]}}}"));
		QuestEffortLibrary q = QuestEffortLibrary.load(s("{\"quests\":{"
			+ "\"Easy Unlock\":{\"name\":\"Easy Unlock\",\"estMinutes\":40,\"directPrerequisiteQuests\":[]},"
			+ "\"Hard Unlock\":{\"name\":\"Hard Unlock\",\"estMinutes\":40,\"directPrerequisiteQuests\":[]}}}"));
		TaskDifficultyLibrary diffs = TaskDifficultyLibrary.load(
			s("{\"tasks\":{\"1\":{\"difficulty\":1},\"2\":{\"difficulty\":10}}}"));

		List<UnlockSuggestion> out = new UnlockPlanner(q, skills()).plan(
			Arrays.asList(task(1, 4), task(2, 4)), Collections.emptySet(), el,
			player(99, Collections.emptySet()), diffs);

		assertEquals(2, out.size());
		assertEquals("unlocking easy points ranks first", "Easy Unlock", out.get(0).questName());
		UnlockSuggestion easy = out.get(0);
		assertEquals("raw prize is unchanged for display", 4, easy.unlockedPoints());
		assertEquals("easy points count at near-full weight", 4, easy.achievablePoints());
		UnlockSuggestion hard = out.stream().filter(u -> u.questName().equals("Hard Unlock")).findFirst().get();
		assertTrue("hard points are discounted", hard.achievablePoints() < hard.unlockedPoints());
	}

	@Test
	public void chargesSkillTrainingWhenLevelShort()
	{
		List<CombatAchievement> tasks = Arrays.asList(task(1, 4));
		UnlockPlanner planner = new UnlockPlanner(quests(), skills());
		// Player has Magic 60, DS2 needs 75 -> training time is added and the skill is flagged.
		UnlockSuggestion ds2 = planner.plan(tasks, Collections.emptySet(), effort(),
			player(60, Collections.emptySet())).get(0);
		assertTrue("training time charged", ds2.trainingMinutes() > 0);
		assertTrue(ds2.unmetSkills().stream().anyMatch(x -> x.startsWith("Magic")));
	}

	@Test
	public void startedSufficesQuestAlreadyStartedIsNotAnUnlock()
	{
		// Task 1 gated by a "started suffices" quest the player has STARTED (not completed): the CA is
		// already doable, so completing the quest unlocks nothing — it must not be a suggestion (else it
		// would render as a red "needs Regicide" locked Route card for an already-doable CA).
		EffortDataLibrary el = EffortDataLibrary.load(s("{\"tasks\":{"
			+ "\"1\":{\"questReqs\":[{\"name\":\"Regicide\",\"startedSuffices\":true}]}}}"));
		Map<String, Integer> levels = new HashMap<>();
		levels.put("Magic", 99);
		PlayerProfile p = PlayerProfile.of(levels, Collections.emptySet(),
			new HashSet<>(Collections.singletonList("Regicide")));

		List<UnlockSuggestion> out = new UnlockPlanner(quests(), skills())
			.plan(Arrays.asList(task(1, 4)), Collections.emptySet(), el, p);

		assertTrue("a merely-started started-suffices quest is not a pending unlock", out.isEmpty());
	}

	@Test
	public void completedQuestProducesNoSuggestion()
	{
		List<CombatAchievement> tasks = Arrays.asList(task(3, 4));
		Set<String> done = new HashSet<>(Collections.singletonList("Regicide"));
		List<UnlockSuggestion> out = new UnlockPlanner(quests(), skills())
			.plan(tasks, Collections.emptySet(), effort(), player(99, done));
		assertTrue("a finished quest is not an unlock suggestion", out.isEmpty());
	}

	@Test
	public void taskWithUnmetSkillsIsNotCountedAsPureUnlock()
	{
		// Task 1 also needs a skill the player lacks -> completing the quest alone wouldn't unlock it.
		EffortDataLibrary el = EffortDataLibrary.load(s("{\"tasks\":{"
			+ "\"1\":{\"questReqs\":[\"Dragon Slayer II\"],\"levelReqs\":{\"Slayer\":95}}}}"));
		List<UnlockSuggestion> out = new UnlockPlanner(quests(), skills())
			.plan(Arrays.asList(task(1, 4)), Collections.emptySet(), el, player(99, Collections.emptySet()));
		assertTrue(out.isEmpty());
	}
}

package com.pluginideahub.combatachievements.core.effort;

import com.pluginideahub.combatachievements.core.achievement.AchievementTier;
import com.pluginideahub.combatachievements.core.achievement.CombatAchievement;
import com.pluginideahub.combatachievements.core.achievement.CombatAchievementLibrary;
import com.pluginideahub.combatachievements.core.achievement.EffortDataLibrary;
import com.pluginideahub.combatachievements.core.achievement.RecStatsLibrary;
import com.pluginideahub.combatachievements.core.achievement.TaskDifficultyLibrary;
import com.pluginideahub.combatachievements.core.achievement.TaskType;
import com.pluginideahub.combatachievements.core.ranking.PlayerProfile;
import java.io.ByteArrayInputStream;
import java.nio.charset.StandardCharsets;
import java.util.Arrays;
import java.util.Collections;
import java.util.HashMap;
import java.util.HashSet;
import java.util.List;
import java.util.Map;
import java.util.Set;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

/**
 * "Unlock next" is ranked on the part of the prize you could actually collect. A quest opening 15 CAs
 * you are 40 levels short of has not opened 15 CAs — before this it was ranked and displayed on the raw
 * total, so a level-3 was offered The Final Dawn (a 25-hour questline) for content it could never do.
 */
public class UnlockReachabilityTest
{
	private static ByteArrayInputStream s(String json)
	{
		return new ByteArrayInputStream(json.getBytes(StandardCharsets.UTF_8));
	}

	private static CombatAchievement task(int id, int points)
	{
		return new CombatAchievement(id, "T" + id, AchievementTier.ELITE, "Boss",
			TaskType.KILL_COUNT, points, "Kill Boss.", "", "");
	}

	/** Task 1 gated by a short quest, task 2 by a long one. */
	private static EffortDataLibrary effort()
	{
		return EffortDataLibrary.load(s("{\"tasks\":{"
			+ "\"1\":{\"questReqs\":[\"Short Quest\"]},"
			+ "\"2\":{\"questReqs\":[\"Long Quest\"]}}}"));
	}

	private static QuestEffortLibrary quests()
	{
		return QuestEffortLibrary.load(s("{\"quests\":{"
			+ "\"Short Quest\":{\"name\":\"Short Quest\",\"difficulty\":\"Novice\",\"estMinutes\":10,"
			+ "\"directPrerequisiteQuests\":[]},"
			+ "\"Long Quest\":{\"name\":\"Long Quest\",\"difficulty\":\"Master\",\"estMinutes\":600,"
			+ "\"directPrerequisiteQuests\":[]},"
			+ "\"Training Quest\":{\"name\":\"Training Quest\",\"difficulty\":\"Novice\",\"estMinutes\":10,"
			+ "\"skillRequirements\":{\"Attack\":80},\"directPrerequisiteQuests\":[]}"
			+ "}}"));
	}

	private static SkillXpLibrary skills()
	{
		return SkillXpLibrary.load(s("{\"skills\":{\"Attack\":{\"skill\":\"Attack\",\"brackets\":["
			+ "{\"fromLevel\":1,\"toLevel\":99,\"method\":\"x\",\"xpPerHour\":250000,\"members\":true}]}}}"));
	}

	/** Both tasks softly want 80 Attack. */
	private static RecStatsLibrary recStats()
	{
		return RecStatsLibrary.load(s("{\"tasks\":{"
			+ "\"1\":{\"soft\":[{\"skills\":[\"Attack\"],\"level\":80}]},"
			+ "\"2\":{\"soft\":[{\"skills\":[\"Attack\"],\"level\":80}]}}}"));
	}

	private static PlayerProfile player(int attack)
	{
		Map<String, Integer> levels = new HashMap<>();
		levels.put("Attack", attack);
		return PlayerProfile.of(levels, Collections.emptySet(), Collections.emptySet());
	}

	private static List<UnlockSuggestion> plan(PlayerProfile profile, RecStatsLibrary rec,
		EffortDataLibrary effortLib)
	{
		return new UnlockPlanner(quests(), skills()).plan(
			Arrays.asList(task(1, 4), task(2, 40)), Collections.emptySet(), effortLib, profile,
			TaskDifficultyLibrary.empty(), 1.0, 1.0, rec);
	}

	@Test
	public void questsOpeningNothingReachableAreStillRankedSensiblyAmongThemselves()
	{
		// Attack 10 against tasks wanting 80 — a 70-level gap, far past the ready line. The suggestions are
		// kept, because a quest is permanent progress worth doing before you can use what it opens. They
		// must still order by value, though: scoring them all at a flat zero made the sort fall through to
		// alphabetical, which put the 600-minute quest above the 10-minute one.
		List<UnlockSuggestion> out = plan(player(10), recStats(), effort());
		assertEquals(2, out.size());
		for (UnlockSuggestion u : out)
		{
			assertEquals("nothing reachable at " + u.questName(), 0, u.reachableTaskCount());
			assertEquals(0, u.reachablePoints());
		}
		assertEquals("the 10-minute quest leads the 600-minute one", "Short Quest", out.get(0).questName());
	}

	@Test
	public void aReadyAccountStillGetsBothSuggestions()
	{
		List<UnlockSuggestion> out = plan(player(80), recStats(), effort());
		assertEquals(2, out.size());
		assertEquals("the big prize ranks on reachable points, and it is all reachable",
			"Long Quest", find(out, "Long Quest").questName());
		assertEquals(40, find(out, "Long Quest").reachablePoints());
	}

	@Test
	public void readinessIsJudgedAfterTheQuestsOwnTraining()
	{
		// A quest that requires Attack 80 leaves you AT 80 — so the CAs it opens, which want 80, are
		// reachable. Judging at today's levels would wrongly drop it.
		EffortDataLibrary gated = EffortDataLibrary.load(s(
			"{\"tasks\":{\"1\":{\"questReqs\":[\"Training Quest\"]}}}"));
		List<UnlockSuggestion> out = new UnlockPlanner(quests(), skills()).plan(
			Arrays.asList(task(1, 4)), Collections.emptySet(), gated, player(1),
			TaskDifficultyLibrary.empty(), 1.0, 1.0, recStats());

		assertEquals("the quest trains you into its own reward", 1, out.size());
		assertEquals(1, out.get(0).reachableTaskCount());
		assertTrue("and the training is still charged", out.get(0).trainingMinutes() > 0);
	}

	@Test
	public void theRawPrizeIsKeptSeparateFromTheReachableOne()
	{
		// Only task 2 is out of reach: 80 Attack wanted, player has 80 for task 1's boss but the rec stats
		// here are shared, so use a profile between the two — task 1 (4 pts) reachable, task 2 (40) not.
		RecStatsLibrary split = RecStatsLibrary.load(s("{\"tasks\":{"
			+ "\"1\":{\"soft\":[{\"skills\":[\"Attack\"],\"level\":40}]},"
			+ "\"2\":{\"soft\":[{\"skills\":[\"Attack\"],\"level\":90}]}}}"));
		List<UnlockSuggestion> out = plan(player(40), split, effort());

		UnlockSuggestion reachable = find(out, "Short Quest");
		assertEquals("raw total is preserved for reference", 4, reachable.unlockedPoints());
		assertEquals(4, reachable.reachablePoints());

		UnlockSuggestion unreachable = find(out, "Long Quest");
		assertEquals("the 40-point prize is out of reach and counts for nothing",
			0, unreachable.reachablePoints());
		assertEquals("even though it is worth far more on paper", 40, unreachable.unlockedPoints());
		assertEquals("so the small reachable quest ranks first", "Short Quest", out.get(0).questName());
	}

	@Test
	public void withoutRecommendedStatsNothingIsFiltered()
	{
		// Back-compat: callers that never supplied rec stats behave exactly as before.
		List<UnlockSuggestion> out = plan(player(1), RecStatsLibrary.empty(), effort());
		assertEquals(2, out.size());
		for (UnlockSuggestion u : out)
		{
			assertEquals("every unlocked CA counts as reachable",
				u.unlockedTaskCount(), u.reachableTaskCount());
		}
	}

	// ---- against the real bundled data --------------------------------------------------------------

	private static PlayerProfile account(int everyStat)
	{
		Map<String, Integer> levels = new HashMap<>();
		for (String s : new String[]{"Attack", "Strength", "Defence", "Ranged", "Magic", "Prayer", "Slayer",
			"Mining", "Herblore", "Farming", "Construction", "Agility", "Thieving", "Firemaking", "Fishing",
			"Woodcutting", "Crafting", "Fletching", "Runecraft", "Hunter", "Smithing", "Cooking"})
		{
			levels.put(s, everyStat);
		}
		levels.put("Hitpoints", Math.max(10, everyStat));
		Set<String> done = new HashSet<>(Arrays.asList(
			"Priest in Peril", "The Restless Ghost", "Children of the Sun"));
		return PlayerProfile.of(levels, done, done);
	}

	private static List<UnlockSuggestion> realPlan(PlayerProfile profile)
	{
		return new UnlockPlanner(QuestEffortLibrary.loadBundled(), SkillXpLibrary.loadBundled()).plan(
			CombatAchievementLibrary.loadBundled().all(), Collections.emptySet(),
			EffortDataLibrary.loadBundled(), profile, TaskDifficultyLibrary.loadBundled(), 1.0, 1.0,
			RecStatsLibrary.loadBundled());
	}

	@Test
	public void nothingIsReachableForALevelThree()
	{
		// The reported bug: a level-3 was offered The Final Dawn (~25 hrs) and A Kingdom Divided (~21 hrs),
		// ranked on prizes of 79 and 55 points it could never collect. Every one now counts zero, so the
		// panel's "Unlock next" section has nothing to show (asserted end-to-end in RouteReadinessTest).
		List<UnlockSuggestion> out = realPlan(account(1));
		assertFalse("precondition: the quests are still found", out.isEmpty());
		for (UnlockSuggestion u : out)
		{
			assertEquals("a level-3 can collect nothing from " + u.questName(),
				0, u.reachableTaskCount());
		}
	}

	@Test
	public void anEstablishedAccountKeepsItsBestUnlock()
	{
		// The other direction: this must not gut the section for an account that can use it.
		List<UnlockSuggestion> out = realPlan(account(80));
		assertFalse("an all-80s account still gets suggestions", out.isEmpty());
		assertEquals("and the biggest quick prize still leads", "Beneath Cursed Sands",
			out.get(0).questName());
		assertTrue("counted on what it can actually do", out.get(0).reachablePoints() > 200);
	}

	private static UnlockSuggestion find(List<UnlockSuggestion> out, String quest)
	{
		return out.stream().filter(u -> u.questName().equals(quest)).findFirst().orElseThrow(
			() -> new AssertionError("no suggestion for " + quest));
	}
}

