package com.pluginideahub.combatachievements.core.path;

import com.pluginideahub.combatachievements.core.achievement.AchievementTier;
import com.pluginideahub.combatachievements.core.achievement.CombatAchievement;
import com.pluginideahub.combatachievements.core.achievement.EffortDataLibrary;
import com.pluginideahub.combatachievements.core.achievement.TaskDifficulty;
import com.pluginideahub.combatachievements.core.achievement.TaskDifficultyLibrary;
import com.pluginideahub.combatachievements.core.achievement.TaskType;
import com.pluginideahub.combatachievements.core.ranking.EffortModel;
import com.pluginideahub.combatachievements.core.ranking.LowHangingFruitRanker;
import com.pluginideahub.combatachievements.core.ranking.RankedTask;
import com.pluginideahub.combatachievements.core.ranking.SignalsProvider;
import com.pluginideahub.combatachievements.core.ranking.TaskLiveSignals;
import java.io.ByteArrayInputStream;
import java.nio.charset.StandardCharsets;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

public class OptimalPathSolverTest
{
	private final OptimalPathSolver solver = new OptimalPathSolver();

	private static RankedTask ranked(int id, int points, double effort)
	{
		CombatAchievement a = new CombatAchievement(id, "Task " + id, AchievementTier.HARD, "Boss",
			TaskType.KILL_COUNT, points, "desc", "General", "url");
		return new RankedTask(a, effort, points / effort, "r", "", true, true, TaskDifficulty.UNKNOWN);
	}

	private static final List<RankedTask> CANDIDATES = Arrays.asList(
		ranked(1, 1, 1.0),
		ranked(2, 2, 1.5),
		ranked(3, 3, 5.0),
		ranked(4, 2, 1.2),
		ranked(5, 4, 3.0),
		ranked(6, 1, 0.5));

	@Test
	public void dpMatchesBruteForceOptimumForEveryGap()
	{
		int totalPoints = CANDIDATES.stream().mapToInt(rt -> rt.achievement().points()).sum();
		for (int gap = 1; gap <= totalPoints; gap++)
		{
			PathPlan plan = solver.solve(AchievementTier.ELITE, gap, CANDIDATES);
			double brute = bruteMinEffort(CANDIDATES, gap);
			assertTrue("reachable for gap " + gap, plan.reachable());
			assertEquals("min effort for gap " + gap, brute, plan.totalEffort(), 1e-9);
			assertTrue("points cover gap " + gap, plan.totalPoints() >= gap);
		}
	}

	@Test
	public void solveMinimisesTheSuppliedCostNotEffort()
	{
		// Two tasks that each cover a 2-point gap: task 1 is cheap on effort, task 2 is expensive.
		List<RankedTask> two = Arrays.asList(ranked(1, 2, 1.0), ranked(2, 2, 9.0));

		// Default cost is effort → the solver takes the low-effort task 1.
		PathPlan byEffort = solver.solve(AchievementTier.HARD, 2, two);
		assertEquals(1, byEffort.steps().get(0).achievement().id());

		// A custom cost that inverts effort (task 2 cheap) → the solver must instead take task 2,
		// proving the Route's quickest-path cost genuinely drives selection.
		PathPlan byCost = solver.solve(AchievementTier.HARD, 2, two,
			rt -> rt.achievement().id() == 2 ? 1.0 : 9.0);
		assertEquals(2, byCost.steps().get(0).achievement().id());
	}

	@Test
	public void planIsDeterministic()
	{
		PathPlan a = solver.solve(AchievementTier.ELITE, 5, CANDIDATES);
		PathPlan b = solver.solve(AchievementTier.ELITE, 5, CANDIDATES);
		assertEquals(stepIds(a), stepIds(b));
	}

	@Test
	public void zeroGapIsAlreadyUnlocked()
	{
		PathPlan plan = solver.solve(AchievementTier.ELITE, 0, CANDIDATES);
		assertTrue(plan.alreadyUnlocked());
		assertTrue(plan.steps().isEmpty());
	}

	@Test
	public void unreachableGapReturnsAllFlaggedNotReachable()
	{
		PathPlan plan = solver.solve(AchievementTier.ELITE, 1000, CANDIDATES);
		assertFalse(plan.reachable());
		assertEquals(CANDIDATES.size(), plan.steps().size());
	}

	@Test
	public void grandmasterBranchReturnsEveryTask()
	{
		PathPlan plan = solver.solveCompleteAll(AchievementTier.GRANDMASTER, CANDIDATES);
		assertEquals(CANDIDATES.size(), plan.steps().size());
		int sum = CANDIDATES.stream().mapToInt(rt -> rt.achievement().points()).sum();
		assertEquals(sum, plan.totalPoints());
		// steps are ordered easiest-first
		for (int i = 1; i < plan.steps().size(); i++)
		{
			assertTrue(plan.steps().get(i - 1).effort() <= plan.steps().get(i).effort() + 1e-9);
		}
	}

	@Test
	public void routePrefersLowerDifficultyTaskToCloseTheGapViaEffort()
	{
		// Two tasks that each alone close a 6-pt gap: one easy (difficulty 2), one hard (difficulty 9).
		// The Route feeds the difficulty-aware LowHangingFruitRanker effort into the solver, so the
		// min-effort path must pick the EASIER task — proving Difficulty reaches the Route (not just the
		// quick-wins / synergy rankers).
		//
		// The easier task deliberately gets the HIGHER id (11). The solver's effort tie-break is
		// (effort asc, id asc), so if difficulty were disconnected both efforts would tie and the LOWER
		// id (10, the hard task) would win — failing this assertion. It only passes because difficulty
		// gives the easy task strictly lower effort, so the id coincidence can't fake a green.
		CombatAchievement hard = new CombatAchievement(10, "Hard", AchievementTier.ELITE, "Boss",
			TaskType.KILL_COUNT, 6, "", "", "");
		CombatAchievement easy = new CombatAchievement(11, "Easy", AchievementTier.ELITE, "Boss",
			TaskType.KILL_COUNT, 6, "", "", "");
		EffortDataLibrary el = EffortDataLibrary.load(stream("{\"tasks\":{}}"));
		TaskDifficultyLibrary diff = TaskDifficultyLibrary.load(
			stream("{\"tasks\":{\"11\":{\"difficulty\":2},\"10\":{\"difficulty\":9}}}"));
		SignalsProvider allDoable = id -> new TaskLiveSignals(true, true, false, true);

		List<RankedTask> ranked = new LowHangingFruitRanker(el, EffortModel.standard(), diff)
			.rank(Arrays.asList(hard, easy), java.util.Collections.<Integer>emptySet(), allDoable, false);
		PathPlan plan = solver.solve(AchievementTier.ELITE, 6, ranked);

		assertEquals("route closes the 6-pt gap with one task", 1, plan.steps().size());
		assertEquals("route picks the easier task despite its higher id", 11,
			plan.steps().get(0).achievement().id());
	}

	// ---- clustering ---------------------------------------------------------------------------------

	private static RankedTask atBoss(int id, int points, double effort, String boss)
	{
		CombatAchievement a = new CombatAchievement(id, "Task " + id, AchievementTier.HARD, boss,
			TaskType.KILL_COUNT, points, "desc", "General", "url");
		return new RankedTask(a, effort, points / effort, "r", "", true, true, TaskDifficulty.UNKNOWN);
	}

	/** The clustered cost of a plan: the per-task cost plus one trip overhead for each distinct boss. */
	private static double clusteredCost(PathPlan plan, double overhead)
	{
		double cost = 0.0;
		java.util.Set<String> bosses = new java.util.HashSet<>();
		for (PathStep s : plan.steps())
		{
			cost += s.effort();
			bosses.add(s.achievement().monster());
		}
		return cost + overhead * bosses.size();
	}

	@Test
	public void clusteringKeepsYouAtOneBossWhenItCanCloseTheGap()
	{
		// Boss A alone can cover a gap of 3 (three 1-pt CAs). Boss B has a single cheaper 1-pt CA. With a
		// real trip overhead, doing all three at A beats two at A + a trip to B.
		List<RankedTask> tasks = Arrays.asList(
			atBoss(1, 1, 2.0, "A"), atBoss(2, 1, 2.0, "A"), atBoss(3, 1, 2.0, "A"),
			atBoss(4, 1, 0.5, "B"));

		PathPlan plan = solver.solveClustered(AchievementTier.ELITE, 3, tasks, RankedTask::effort, 10.0);

		assertTrue("reaches the gap", plan.totalPoints() >= 3);
		long bosses = plan.steps().stream().map(s -> s.achievement().monster()).distinct().count();
		assertEquals("stays at a single boss rather than making a second trip", 1, bosses);
	}

	@Test
	public void clusteringIsNeverWorseThanScatteringToCloseTheGap()
	{
		// Two bosses, three CAs each, mixed effort. For every gap and a range of overheads, the clustered
		// solver's true cost (with per-boss trips) must not exceed what the boss-blind solver would cost.
		List<RankedTask> tasks = Arrays.asList(
			atBoss(1, 2, 3.0, "A"), atBoss(2, 1, 1.0, "A"), atBoss(3, 3, 4.0, "A"),
			atBoss(4, 2, 2.0, "B"), atBoss(5, 1, 1.5, "B"), atBoss(6, 4, 5.0, "B"));
		int total = tasks.stream().mapToInt(rt -> rt.achievement().points()).sum();

		for (double overhead : new double[]{0.0, 2.0, 8.0})
		{
			for (int gap = 1; gap <= total; gap++)
			{
				PathPlan clustered = solver.solveClustered(AchievementTier.ELITE, gap, tasks,
					RankedTask::effort, overhead);
				PathPlan scattered = solver.solve(AchievementTier.ELITE, gap, tasks, RankedTask::effort);

				assertTrue("clustered reaches gap " + gap, clustered.totalPoints() >= gap);
				assertTrue("clustered (overhead " + overhead + ", gap " + gap + ") is no costlier than "
						+ "scattering once trips are counted",
					clusteredCost(clustered, overhead) <= clusteredCost(scattered, overhead) + EPS);
			}
		}
	}

	@Test
	public void withNoTripOverheadClusteringReachesTheSameCostAsThePlainSolver()
	{
		// Overhead 0 removes the only reason to cluster, so the two solvers must tie on total cost.
		int total = CANDIDATES.stream().mapToInt(rt -> rt.achievement().points()).sum();
		for (int gap = 1; gap <= total; gap++)
		{
			PathPlan clustered = solver.solveClustered(AchievementTier.ELITE, gap, CANDIDATES,
				RankedTask::effort, 0.0);
			double brute = bruteMinEffort(CANDIDATES, gap);
			assertEquals("clustered with no overhead is optimal at gap " + gap,
				brute, clusteredCost(clustered, 0.0), 1e-9);
		}
	}

	private static final double EPS = 1e-9;

	private static ByteArrayInputStream stream(String json)
	{
		return new ByteArrayInputStream(json.getBytes(StandardCharsets.UTF_8));
	}

	private static List<Integer> stepIds(PathPlan plan)
	{
		List<Integer> ids = new ArrayList<>();
		plan.steps().forEach(s -> ids.add(s.achievement().id()));
		return ids;
	}

	/** Exhaustive 2^N reference: minimum total effort of any subset whose points reach the gap. */
	private static double bruteMinEffort(List<RankedTask> items, int gap)
	{
		int n = items.size();
		double best = Double.POSITIVE_INFINITY;
		for (int mask = 0; mask < (1 << n); mask++)
		{
			int points = 0;
			double effort = 0.0;
			for (int i = 0; i < n; i++)
			{
				if ((mask & (1 << i)) != 0)
				{
					points += items.get(i).achievement().points();
					effort += items.get(i).effort();
				}
			}
			if (points >= gap && effort < best)
			{
				best = effort;
			}
		}
		return best;
	}
}

package com.pluginideahub.combatachievements.core.ranking;

import com.pluginideahub.combatachievements.core.achievement.AchievementTier;
import com.pluginideahub.combatachievements.core.achievement.CombatAchievement;
import com.pluginideahub.combatachievements.core.achievement.EffortDataLibrary;
import com.pluginideahub.combatachievements.core.achievement.TaskDifficultyLibrary;
import com.pluginideahub.combatachievements.core.achievement.TaskType;
import java.io.ByteArrayInputStream;
import java.nio.charset.StandardCharsets;
import java.util.Arrays;
import java.util.Collections;
import java.util.HashMap;
import java.util.HashSet;
import java.util.List;
import java.util.Set;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

public class LowHangingFruitRankerTest
{
	// Task 1: Hard Kill Count, 3 pts. Task 2: Master Perfection, 5 pts.
	private static final CombatAchievement HARD_KC = new CombatAchievement(
		1, "Abyssal Adept", AchievementTier.HARD, "Abyssal Sire", TaskType.KILL_COUNT, 3,
		"Kill the Abyssal Sire 20 times.", "General", "url");
	private static final CombatAchievement MASTER_PERFECTION = new CombatAchievement(
		2, "Flawless", AchievementTier.MASTER, "Some Boss", TaskType.PERFECTION, 5,
		"Do it perfectly.", "General", "url");

	private static EffortDataLibrary effortLib()
	{
		String json = "{\"tasks\":{"
			+ "\"1\":{\"gearTier\":\"mid\",\"rng\":\"low\",\"supply\":\"none\",\"soloable\":true},"
			+ "\"2\":{\"gearTier\":\"high\",\"rng\":\"high\",\"supply\":\"none\",\"soloable\":true}"
			+ "}}";
		return EffortDataLibrary.load(new ByteArrayInputStream(json.getBytes(StandardCharsets.UTF_8)));
	}

	private static SignalsProvider signals()
	{
		return taskId ->
		{
			if (taskId == 1)
			{
				// boss already farmed (KC>0): no learning penalty
				return new TaskLiveSignals(true, true, false, true);
			}
			// never-killed boss: learning penalty applies
			return new TaskLiveSignals(true, true, false, false);
		};
	}

	@Test
	public void hardKillCountOutranksMasterPerfection()
	{
		LowHangingFruitRanker ranker = new LowHangingFruitRanker(effortLib(), EffortModel.standard());
		List<RankedTask> ranked = ranker.rank(
			Arrays.asList(HARD_KC, MASTER_PERFECTION), Collections.emptySet(), signals(), false);

		assertEquals(2, ranked.size());
		assertEquals("Hard KC ranks first", 1, ranked.get(0).achievement().id());
		assertEquals(2, ranked.get(1).achievement().id());

		// The worked example in docs/DESIGN.md §6b.1, now carrying the repetition cost: the Hard task says
		// "20 times", so its base effort is multiplied by sqrt(20). The Master task is a single attempt and
		// is unaffected. The Hard grind still wins — 20 Abyssal Sire kills really is the easier job — which
		// is exactly the case that keeps the repetition curve honest rather than punishing every grind.
		double repeats = Math.sqrt(20);
		assertEquals(1.45 * repeats, ranked.get(0).effort(), 1e-6);
		assertEquals(3.0 / (1.45 * repeats), ranked.get(0).score(), 1e-6);
		assertEquals(12.4, ranked.get(1).effort(), 1e-6);
		assertEquals(5.0 / 12.4, ranked.get(1).score(), 1e-6);
		assertTrue(ranked.get(0).score() > ranked.get(1).score());
	}

	@Test
	public void completedTasksAreExcluded()
	{
		LowHangingFruitRanker ranker = new LowHangingFruitRanker(effortLib(), EffortModel.standard());
		List<RankedTask> ranked = ranker.rank(
			Arrays.asList(HARD_KC, MASTER_PERFECTION), Collections.singleton(1), signals(), false);
		assertEquals(1, ranked.size());
		assertEquals(2, ranked.get(0).achievement().id());
	}

	@Test
	public void doableNowFilterDropsLockedTasks()
	{
		// Task 2's access is not met → not doable now.
		SignalsProvider gated = taskId -> taskId == 1
			? new TaskLiveSignals(true, true, false, true)
			: new TaskLiveSignals(false, true, false, false);

		LowHangingFruitRanker ranker = new LowHangingFruitRanker(effortLib(), EffortModel.standard());
		List<RankedTask> doable = ranker.rank(
			Arrays.asList(HARD_KC, MASTER_PERFECTION), Collections.emptySet(), gated, true);
		assertEquals(1, doable.size());
		assertEquals(1, doable.get(0).achievement().id());

		// Without the filter the locked task still appears, flagged not-doable.
		List<RankedTask> all = ranker.rank(
			Arrays.asList(HARD_KC, MASTER_PERFECTION), Collections.emptySet(), gated, false);
		assertEquals(2, all.size());
	}

	@Test
	public void questGatedTaskIsExcludedFromRouteUntilQuestDone()
	{
		// Full stack: real ProfileSignalsProvider resolves the quest gate, ranker reflects it.
		EffortDataLibrary gatedLib = EffortDataLibrary.load(
			stream("{\"tasks\":{\"1\":{\"questReqs\":[\"Dragon Slayer II\"]}}}"));
		CombatAchievement vorkath = new CombatAchievement(1, "Vorkath Veteran", AchievementTier.ELITE,
			"Vorkath", TaskType.KILL_COUNT, 4, "Kill Vorkath.", "", "");

		// Without Dragon Slayer II the task is dropped from the doable-now route...
		ProfileSignalsProvider noQuest = new ProfileSignalsProvider(gatedLib, PlayerProfile.empty());
		LowHangingFruitRanker ranker = new LowHangingFruitRanker(gatedLib, EffortModel.standard());
		assertTrue(ranker.rank(Collections.singletonList(vorkath), Collections.emptySet(), noQuest, true)
			.isEmpty());

		// ...and is shown locked with an actionable reason when the filter is off.
		RankedTask locked = ranker.rank(
			Collections.singletonList(vorkath), Collections.emptySet(), noQuest, false).get(0);
		assertFalse(locked.doableNow());
		assertEquals("needs Dragon Slayer II", locked.lockReason());

		// With the quest finished, the task becomes doable.
		Set<String> done = new HashSet<>(Collections.singletonList("Dragon Slayer II"));
		ProfileSignalsProvider withQuest = new ProfileSignalsProvider(gatedLib,
			PlayerProfile.of(new HashMap<>(), done, done));
		List<RankedTask> nowDoable = ranker.rank(
			Collections.singletonList(vorkath), Collections.emptySet(), withQuest, true);
		assertEquals(1, nowDoable.size());
		assertTrue(nowDoable.get(0).doableNow());
		assertEquals("", nowDoable.get(0).lockReason());
	}

	@Test
	public void hardTasksSinkBelowEasyOnesViaDifficulty()
	{
		// An easy 2-pt task vs a hard 6-pt raid task, both equally cheap by the synthetic effort model.
		// Difficulty (pure skill) — not player completion % — must decide the ordering, so the popular-
		// but-hard raid no longer reads as easy.
		CombatAchievement easy = new CombatAchievement(10, "Easy", AchievementTier.MEDIUM, "Boss",
			TaskType.KILL_COUNT, 2, "", "", "");
		CombatAchievement hard = new CombatAchievement(11, "Hard", AchievementTier.GRANDMASTER, "Raid",
			TaskType.KILL_COUNT, 6, "", "", "");
		EffortDataLibrary el = EffortDataLibrary.load(stream("{\"tasks\":{}}"));
		TaskDifficultyLibrary diff = TaskDifficultyLibrary.load(
			stream("{\"tasks\":{\"10\":{\"difficulty\":2},\"11\":{\"difficulty\":9}}}"));
		SignalsProvider sig = id -> new TaskLiveSignals(true, true, false, true);

		// Without difficulty data the 6-pt task wins on raw points/effort...
		List<RankedTask> naive = new LowHangingFruitRanker(el, EffortModel.standard())
			.rank(Arrays.asList(hard, easy), Collections.emptySet(), sig, false);
		assertEquals(11, naive.get(0).achievement().id());

		// ...with the pure-skill difficulty factor, the easy task correctly ranks first.
		List<RankedTask> withDifficulty = new LowHangingFruitRanker(el, EffortModel.standard(), diff)
			.rank(Arrays.asList(hard, easy), Collections.emptySet(), sig, false);
		assertEquals(10, withDifficulty.get(0).achievement().id());
		// Each ranked task now carries its difficulty for card display / the Easiest sort.
		assertEquals(9, withDifficulty.get(1).difficulty().difficulty());
	}

	@Test
	public void belowRecStatsTaskIsSunkBelowAnOtherwiseEqualTask()
	{
		// Two identical tasks (same points, same neutral effort, no difficulty data). The only difference:
		// task 21's player is 40 summed levels below its soft recommended stats, so it must rank lower.
		// Different bosses so the entry-kill reprice (which lifts a "kill once" to its best boss-mate)
		// does not couple them — in reality two tasks at one boss share rec-stats and cannot differ like
		// this anyway.
		CombatAchievement metStats = new CombatAchievement(20, "Ready", AchievementTier.HARD, "Boss A",
			TaskType.KILL_COUNT, 3, "", "", "");
		CombatAchievement underLevelled = new CombatAchievement(21, "Underlevelled", AchievementTier.HARD,
			"Boss B", TaskType.KILL_COUNT, 3, "", "", "");
		EffortDataLibrary el = EffortDataLibrary.load(stream("{\"tasks\":{}}"));
		SignalsProvider sig = id -> id == 20
			? new TaskLiveSignals(true, true, false, true, 0)
			: new TaskLiveSignals(true, true, false, true, 40);

		List<RankedTask> ranked = new LowHangingFruitRanker(el, EffortModel.standard())
			.rank(Arrays.asList(underLevelled, metStats), Collections.emptySet(), sig, false);

		assertEquals("stats-met task ranks first", 20, ranked.get(0).achievement().id());
		assertEquals(21, ranked.get(1).achievement().id());
		assertTrue(ranked.get(1).belowRecStats());
		assertEquals(40, ranked.get(1).recStatsShortfall());
		// The penalty is SQUARED distance: at the 40-level scale, 40 short -> ×(1 + 1²) = ×2.0 effort.
		// Squaring is what stops a high-point task far out of reach from still looking like good value.
		assertEquals(2.0 * ranked.get(0).effort(), ranked.get(1).effort(), 1e-6);
		assertEquals(ranked.get(0).score() / 2.0, ranked.get(1).score(), 1e-6);
	}

	@Test
	public void aSingleKillEntryTaskLeadsItsBoss()
	{
		// "Kill Nex once" is completed for free by any other Nex task — you cannot do "kill Nex 25 times"
		// or "kill Nex without her healing" without a first kill — so it must never rank behind them just
		// because they are worth an extra point. Same boss, same rec-stats; only the wording differs.
		CombatAchievement once = new CombatAchievement(30, "Nex Veteran", AchievementTier.MASTER, "Nex",
			TaskType.KILL_COUNT, 4, "Kill Nex once.", "", "");
		CombatAchievement grind = new CombatAchievement(31, "Nex Master", AchievementTier.MASTER, "Nex",
			TaskType.KILL_COUNT, 5, "Kill Nex 25 times.", "", "");
		CombatAchievement restricted = new CombatAchievement(32, "A siphon will solve this",
			AchievementTier.MASTER, "Nex", TaskType.MECHANICAL, 5, "Kill Nex without her healing.", "", "");
		EffortDataLibrary el = EffortDataLibrary.load(stream("{\"tasks\":{}}"));
		SignalsProvider sig = id -> new TaskLiveSignals(true, true, false, true, 0);

		List<RankedTask> ranked = new LowHangingFruitRanker(el, EffortModel.standard())
			.rank(Arrays.asList(grind, restricted, once), Collections.emptySet(), sig, false);

		assertEquals("the single kill leads its boss", 30, ranked.get(0).achievement().id());
		assertTrue("and it is flagged as the entry kill", ranked.get(0).isEntryKill());
		assertFalse("a 25-kill task is not an entry kill", ranked.get(1).isEntryKill());
	}

	private static ByteArrayInputStream stream(String json)
	{
		return new ByteArrayInputStream(json.getBytes(StandardCharsets.UTF_8));
	}
}

package com.pluginideahub.combatachievements.core.ranking;

import com.pluginideahub.combatachievements.core.achievement.QuestRequirement;
import java.util.Arrays;
import java.util.Collections;
import java.util.HashMap;
import java.util.HashSet;
import java.util.Map;
import java.util.Set;
import org.junit.Test;

import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

public class PlayerProfileTest
{
	private static Set<String> set(String... names)
	{
		return new HashSet<>(Arrays.asList(names));
	}

	private static PlayerProfile withQuests(Set<String> completed, Set<String> started)
	{
		return PlayerProfile.of(new HashMap<>(), completed, started);
	}

	@Test
	public void completedQuestSatisfiesACompletionGate()
	{
		PlayerProfile p = withQuests(set("Dragon Slayer II"), set("Dragon Slayer II"));
		assertTrue(p.hasCompleted("Dragon Slayer II"));
		assertTrue(p.hasQuestAccess(Collections.singletonList(new QuestRequirement("Dragon Slayer II", false))));
	}

	@Test
	public void missingQuestFailsACompletionGate()
	{
		PlayerProfile p = withQuests(set("Regicide"), set("Regicide"));
		assertFalse(p.hasCompleted("Dragon Slayer II"));
		assertFalse(p.hasQuestAccess(Collections.singletonList(new QuestRequirement("Dragon Slayer II", false))));
	}

	@Test
	public void startedSufficesGateAcceptsAnInProgressQuest()
	{
		// Zulrah needs Regicide STARTED, not finished. A player mid-Regicide must not be locked out.
		PlayerProfile p = withQuests(Collections.emptySet(), set("Regicide"));
		assertFalse("not finished", p.hasCompleted("Regicide"));
		assertTrue("but started", p.hasStarted("Regicide"));
		assertTrue(p.hasQuestAccess(Collections.singletonList(new QuestRequirement("Regicide", true))));
		// The same in-progress quest does NOT satisfy a completion gate.
		assertFalse(p.hasQuestAccess(Collections.singletonList(new QuestRequirement("Regicide", false))));
	}

	@Test
	public void finishedImpliesStartedEvenWhenCallerForgets()
	{
		// Caller passes a finished quest but an empty "started" set; the profile back-fills it.
		PlayerProfile p = PlayerProfile.of(new HashMap<>(), set("Sins of the Father"), Collections.emptySet());
		assertTrue(p.hasStarted("Sins of the Father"));
		assertTrue(p.hasQuestAccess(Collections.singletonList(new QuestRequirement("Sins of the Father", true))));
	}

	@Test
	public void questNamesAreCaseInsensitive()
	{
		PlayerProfile p = withQuests(set("song of the elves"), set("song of the elves"));
		assertTrue(p.hasCompleted("Song of the Elves"));
		assertTrue(p.hasQuestAccess(Collections.singletonList(new QuestRequirement("SONG OF THE ELVES", false))));
	}

	@Test
	public void allGatesMustPass()
	{
		PlayerProfile p = withQuests(set("Monkey Madness II"), set("Monkey Madness II"));
		assertTrue(p.hasQuestAccess(Collections.singletonList(new QuestRequirement("Monkey Madness II", false))));
		assertFalse("second quest missing", p.hasQuestAccess(Arrays.asList(
			new QuestRequirement("Monkey Madness II", false),
			new QuestRequirement("Dragon Slayer II", false))));
	}

	@Test
	public void emptyOrNullGateIsTriviallyMet()
	{
		PlayerProfile p = PlayerProfile.empty();
		assertTrue(p.hasQuestAccess(Collections.emptyList()));
		assertTrue(p.hasQuestAccess(null));
	}

	@Test
	public void skillLevelsStillWorkAlongsideQuests()
	{
		Map<String, Integer> levels = new HashMap<>();
		levels.put("Slayer", 85);
		PlayerProfile p = PlayerProfile.of(levels, set("Priest in Peril"), set("Priest in Peril"));
		assertTrue(p.levelOf("slayer") == 85);
		Map<String, Integer> need = new HashMap<>();
		need.put("Slayer", 85);
		assertTrue(p.meets(need));
	}
}

package com.pluginideahub.combatachievements.core.ranking;

import com.pluginideahub.combatachievements.core.achievement.EffortDataLibrary;
import com.pluginideahub.combatachievements.core.achievement.RecStatsLibrary;
import java.io.ByteArrayInputStream;
import java.nio.charset.StandardCharsets;
import java.util.Arrays;
import java.util.HashMap;
import java.util.HashSet;
import java.util.Map;
import java.util.Set;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

public class ProfileSignalsProviderTest
{
	// Task 1 needs Slayer 85; task 2 has no skill gate; task 3 needs Dragon Slayer II (completion);
	// task 4 needs Regicide started.
	private static EffortDataLibrary effortLib()
	{
		String json = "{\"tasks\":{"
			+ "\"1\":{\"levelReqs\":{\"Slayer\":85}},"
			+ "\"2\":{\"gearTier\":\"mid\"},"
			+ "\"3\":{\"questReqs\":[\"Dragon Slayer II\"]},"
			+ "\"4\":{\"questReqs\":[{\"name\":\"Regicide\",\"startedSuffices\":true}]}"
			+ "}}";
		return EffortDataLibrary.load(new ByteArrayInputStream(json.getBytes(StandardCharsets.UTF_8)));
	}

	private static PlayerProfile profileWithSlayer(int level)
	{
		Map<String, Integer> levels = new HashMap<>();
		levels.put("Slayer", level);
		return PlayerProfile.of(levels);
	}

	private static Set<String> set(String... names)
	{
		return new HashSet<>(Arrays.asList(names));
	}

	@Test
	public void taskIsDoableWhenLevelsMet()
	{
		ProfileSignalsProvider provider = new ProfileSignalsProvider(effortLib(), profileWithSlayer(90));
		TaskLiveSignals s = provider.signalsFor(1);
		assertTrue(s.levelsMet());
		assertTrue(s.doableNow());
	}

	@Test
	public void taskIsLockedWhenLevelTooLow()
	{
		ProfileSignalsProvider provider = new ProfileSignalsProvider(effortLib(), profileWithSlayer(80));
		TaskLiveSignals s = provider.signalsFor(1);
		assertFalse(s.levelsMet());
		assertFalse(s.doableNow());
	}

	@Test
	public void taskWithoutGateIsAlwaysDoable()
	{
		ProfileSignalsProvider provider = new ProfileSignalsProvider(effortLib(), PlayerProfile.empty());
		TaskLiveSignals s = provider.signalsFor(2);
		assertTrue(s.levelsMet());
		assertTrue(s.doableNow());
	}

	@Test
	public void caseInsensitiveSkillNames()
	{
		Map<String, Integer> levels = new HashMap<>();
		levels.put("SLAYER", 99); // client may report different casing
		ProfileSignalsProvider provider = new ProfileSignalsProvider(effortLib(), PlayerProfile.of(levels));
		assertTrue(provider.signalsFor(1).levelsMet());
	}

	@Test
	public void questGatedTaskIsLockedWhenQuestNotDone()
	{
		// Player has the skills but has not completed Dragon Slayer II.
		ProfileSignalsProvider provider = new ProfileSignalsProvider(effortLib(),
			PlayerProfile.of(new HashMap<>(), set("Regicide"), set("Regicide")));
		TaskLiveSignals s = provider.signalsFor(3);
		assertFalse("quest gate not satisfied", s.accessMet());
		assertFalse(s.doableNow());
	}

	@Test
	public void questGatedTaskIsDoableWhenQuestComplete()
	{
		ProfileSignalsProvider provider = new ProfileSignalsProvider(effortLib(),
			PlayerProfile.of(new HashMap<>(), set("Dragon Slayer II"), set("Dragon Slayer II")));
		TaskLiveSignals s = provider.signalsFor(3);
		assertTrue(s.accessMet());
		assertTrue(s.doableNow());
	}

	@Test
	public void startedSufficesGateAcceptsAnInProgressQuest()
	{
		// Task 4 only needs Regicide STARTED; the player is mid-quest.
		ProfileSignalsProvider provider = new ProfileSignalsProvider(effortLib(),
			PlayerProfile.of(new HashMap<>(), new HashSet<>(), set("Regicide")));
		assertTrue(provider.signalsFor(4).accessMet());
	}

	@Test
	public void taskWithoutQuestGateIsAccessibleByDefault()
	{
		// Task 1 has only a skill gate (no questReqs) — access is never blocked on a missing quest.
		ProfileSignalsProvider provider = new ProfileSignalsProvider(effortLib(), profileWithSlayer(99));
		assertTrue(provider.signalsFor(1).accessMet());
	}

	// Task 2 (no effort level gate) carries a HARD 60 Slayer rec gate and a SOFT 90 Strength recommendation.
	private static RecStatsLibrary recStatsLib()
	{
		String json = "{\"tasks\":{\"2\":{"
			+ "\"hard\":[{\"skills\":[\"Slayer\"],\"level\":60,\"mode\":\"all\"}],"
			+ "\"soft\":[{\"skills\":[\"Strength\"],\"level\":90,\"mode\":\"all\"}]"
			+ "}}}";
		return RecStatsLibrary.load(new ByteArrayInputStream(json.getBytes(StandardCharsets.UTF_8)));
	}

	private static PlayerProfile profile(int slayer, int strength)
	{
		Map<String, Integer> levels = new HashMap<>();
		levels.put("Slayer", slayer);
		levels.put("Strength", strength);
		return PlayerProfile.of(levels);
	}

	@Test
	public void hardRecStatGateLocksTaskWithNoEffortLevelGate()
	{
		// Task 2 has no curated levelReqs, but its HARD rec gate (60 Slayer) must still lock it.
		ProfileSignalsProvider provider = new ProfileSignalsProvider(effortLib(), recStatsLib(),
			profile(50, 99));
		TaskLiveSignals s = provider.signalsFor(2);
		assertFalse("hard rec gate not met", s.levelsMet());
		assertFalse(s.doableNow());
	}

	@Test
	public void meetingHardAndSoftRecStatsLeavesTaskUnsunk()
	{
		ProfileSignalsProvider provider = new ProfileSignalsProvider(effortLib(), recStatsLib(),
			profile(70, 95));
		TaskLiveSignals s = provider.signalsFor(2);
		assertTrue(s.doableNow());
		assertFalse(s.belowRecStats());
		assertEquals(0, s.recStatsShortfall());
	}

	@Test
	public void belowSoftRecStatsSinksButDoesNotGate()
	{
		// Hard gate met (Slayer 70), but 10 Strength short of the soft 90 recommendation.
		ProfileSignalsProvider provider = new ProfileSignalsProvider(effortLib(), recStatsLib(),
			profile(70, 80));
		TaskLiveSignals s = provider.signalsFor(2);
		assertTrue("soft rec stats never gate", s.doableNow());
		assertTrue(s.belowRecStats());
		assertEquals(10, s.recStatsShortfall());
	}

	@Test
	public void legacyConstructorIgnoresRecStats()
	{
		// The 2-arg constructor keeps the old behaviour: no rec-stats library, so task 2 is never gated
		// or sunk on recommended stats regardless of the player's Slayer/Strength.
		ProfileSignalsProvider provider = new ProfileSignalsProvider(effortLib(), profile(1, 1));
		TaskLiveSignals s = provider.signalsFor(2);
		assertTrue(s.doableNow());
		assertFalse(s.belowRecStats());
	}

	@Test
	public void profileMeetsHandlesMultiSkillAndEmpty()
	{
		Map<String, Integer> levels = new HashMap<>();
		levels.put("Ranged", 70);
		levels.put("Slayer", 50);
		PlayerProfile p = PlayerProfile.of(levels);

		Map<String, Integer> needBoth = new HashMap<>();
		needBoth.put("Ranged", 70);
		needBoth.put("Slayer", 50);
		assertTrue(p.meets(needBoth));

		Map<String, Integer> needMore = new HashMap<>();
		needMore.put("Ranged", 70);
		needMore.put("Slayer", 60);
		assertFalse(p.meets(needMore));

		assertTrue(p.meets(new HashMap<>()));
	}
}

package com.pluginideahub.combatachievements.core.tier;

import com.pluginideahub.combatachievements.core.achievement.AchievementTier;
import com.pluginideahub.combatachievements.core.achievement.CombatAchievement;
import com.pluginideahub.combatachievements.core.achievement.CombatAchievementLibrary;
import java.util.Collections;
import java.util.HashSet;
import java.util.List;
import java.util.Set;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;

public class TierMathTest
{
	private static final List<CombatAchievement> ALL = CombatAchievementLibrary.loadBundled().all();

	@Test
	public void totalPointsMatchVerifiedNumber()
	{
		assertEquals(2697, TierMath.totalPointsAvailable(ALL));
	}

	@Test
	public void cumulativeThresholdsMatchVerifiedNumbers()
	{
		assertEquals(41, TierMath.thresholdFor(AchievementTier.EASY, ALL));
		assertEquals(169, TierMath.thresholdFor(AchievementTier.MEDIUM, ALL));
		assertEquals(436, TierMath.thresholdFor(AchievementTier.HARD, ALL));
		assertEquals(1100, TierMath.thresholdFor(AchievementTier.ELITE, ALL));
		assertEquals(1965, TierMath.thresholdFor(AchievementTier.MASTER, ALL));
		assertEquals(2697, TierMath.thresholdFor(AchievementTier.GRANDMASTER, ALL));
	}

	@Test
	public void currentTierTracksThresholds()
	{
		assertNull(TierMath.currentTierFor(0, ALL));
		assertNull(TierMath.currentTierFor(40, ALL));
		assertEquals(AchievementTier.EASY, TierMath.currentTierFor(41, ALL));
		assertEquals(AchievementTier.EASY, TierMath.currentTierFor(168, ALL));
		assertEquals(AchievementTier.MEDIUM, TierMath.currentTierFor(169, ALL));
		assertEquals(AchievementTier.MASTER, TierMath.currentTierFor(1965, ALL));
		assertEquals(AchievementTier.GRANDMASTER, TierMath.currentTierFor(2697, ALL));
		assertEquals(AchievementTier.GRANDMASTER, TierMath.currentTierFor(9999, ALL));
	}

	@Test
	public void gapToNextTierReportsShortfall()
	{
		TierMath.TierGap gap = TierMath.gapToNextTier(0, ALL);
		assertEquals(AchievementTier.EASY, gap.nextTier());
		assertEquals(41, gap.pointsNeeded());

		TierMath.TierGap gap2 = TierMath.gapToNextTier(168, ALL);
		assertEquals(AchievementTier.MEDIUM, gap2.nextTier());
		assertEquals(1, gap2.pointsNeeded());

		assertNull("fully unlocked has no next tier", TierMath.gapToNextTier(2697, ALL));
	}

	@Test
	public void progressByTierCountsCompletion()
	{
		// Complete every Easy task; nothing else.
		Set<Integer> completed = new HashSet<>();
		int easyPoints = 0;
		for (CombatAchievement task : ALL)
		{
			if (task.tier() == AchievementTier.EASY)
			{
				completed.add(task.id());
				easyPoints += task.points();
			}
		}

		List<TierProgress> rows = TierMath.progressByTier(completed, ALL, easyPoints);
		TierProgress easy = rows.get(0);
		assertEquals(AchievementTier.EASY, easy.tier());
		assertEquals(41, easy.completedCount());
		assertEquals(41, easy.totalCount());
		assertEquals(true, easy.unlocked());
		assertEquals(true, easy.fullyComplete());

		TierProgress medium = rows.get(1);
		assertEquals(0, medium.completedCount());
		assertEquals(false, medium.unlocked());
		assertEquals(169 - easyPoints, medium.pointsRemainingToUnlock());
	}

	@Test
	public void emptyProgressUnlocksNothing()
	{
		List<TierProgress> rows = TierMath.progressByTier(Collections.emptySet(), ALL, 0);
		for (TierProgress row : rows)
		{
			assertEquals(false, row.unlocked());
			assertEquals(0, row.completedCount());
		}
	}
}

package com.pluginideahub.combatachievements.core.ui;

import com.pluginideahub.combatachievements.core.achievement.CombatAchievementLibrary;
import com.pluginideahub.combatachievements.core.achievement.EffortDataLibrary;
import com.pluginideahub.combatachievements.core.achievement.TaskDifficultyLibrary;
import com.pluginideahub.combatachievements.core.guide.GuideLibrary;
import com.pluginideahub.combatachievements.core.progress.ProgressSnapshot;
import com.pluginideahub.combatachievements.core.ranking.EffortModel;
import com.pluginideahub.combatachievements.core.ranking.PlayerProfile;
import com.pluginideahub.combatachievements.core.ranking.ProfileSignalsProvider;
import com.pluginideahub.combatachievements.core.ranking.SignalsProvider;
import com.pluginideahub.combatachievements.core.ranking.TaskLiveSignals;
import com.pluginideahub.combatachievements.core.video.VideoGuideLibrary;
import java.io.ByteArrayInputStream;
import java.nio.charset.StandardCharsets;
import java.util.Collections;
import java.util.List;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertTrue;

/**
 * End-to-end guard that the injected Difficulty library actually reaches the ranking THROUGH the
 * builder API — not just through the ranker/model constructors the unit tests use. Without this test,
 * the plugin's {@code .difficulty(...)} call (or the builder's ranker rebuild in {@code difficulty()})
 * could be removed and every other test would still pass, silently disconnecting the headline feature.
 */
public class SidePanelViewModelBuilderTest
{
	private static ByteArrayInputStream stream(String json)
	{
		return new ByteArrayInputStream(json.getBytes(StandardCharsets.UTF_8));
	}

	// Two incomplete, doable tasks: an easy Medium (2 pts) and a hard Grandmaster (6 pts). On raw
	// points/effort the 6-pt task wins; a difficulty library that rates it hard must flip the order.
	private static CombatAchievementLibrary twoTaskLib()
	{
		return CombatAchievementLibrary.load(stream("{\"tasks\":["
			+ "{\"id\":10,\"name\":\"Easy\",\"tier\":\"Medium\",\"type\":\"Kill Count\","
			+ "\"monster\":\"Boss\",\"description\":\"\"},"
			+ "{\"id\":11,\"name\":\"Hard\",\"tier\":\"Grandmaster\",\"type\":\"Kill Count\","
			+ "\"monster\":\"Raid\",\"description\":\"\"}"
			+ "]}"));
	}

	private static SidePanelViewModelBuilder builder(CombatAchievementLibrary lib)
	{
		return new SidePanelViewModelBuilder(lib, EffortDataLibrary.empty(), VideoGuideLibrary.empty(),
			GuideLibrary.empty(), EffortModel.standard());
	}

	private static SidePanelViewModel build(SidePanelViewModelBuilder b)
	{
		ProgressSnapshot present = new ProgressSnapshot(Collections.<Integer>emptySet(), 0, 0, null, 0L);
		SignalsProvider allDoable = id -> new TaskLiveSignals(true, true, false, true);
		return b.build(present, allDoable, null);
	}

	@Test
	public void caDetailIsAssembledAndCarriesCuratedText()
	{
		// A doable task with curated setup/strategy: the drill-in detail must be attached to its row,
		// with the curated text and a breadcrumb type/monster.
		CombatAchievementLibrary lib = twoTaskLib();
		com.pluginideahub.combatachievements.core.achievement.TaskDetailLibrary detail =
			com.pluginideahub.combatachievements.core.achievement.TaskDetailLibrary.load(
				stream("{\"tasks\":{\"10\":{\"setup\":\"Bring a rock hammer\",\"strategy\":\"Smash it\"}}}"));

		SidePanelViewModel vm = build(builder(lib).detail(detail));

		SidePanelViewModel.TaskRow row = null;
		for (SidePanelViewModel.TaskRow r : vm.quickWins())
		{
			if (r.id == 10)
			{
				row = r;
				break;
			}
		}
		assertNotNull("row present", row);
		assertNotNull("detail attached to the row", row.detail);
		assertEquals("Bring a rock hammer", row.detail.setup);
		assertEquals("Smash it", row.detail.strategy);
		assertEquals("Boss", row.detail.monster);
		assertEquals("Kill Count", row.detail.type);
	}

	@Test
	public void bossFullyGatedByAQuestShowsLockedWithTheQuest()
	{
		// Vorkath's only CA is gated by a quest the player has NOT done → the boss appears in the
		// directory flagged locked, with the CA carrying the specific "needs Dragon Slayer II" reason.
		CombatAchievementLibrary lib = CombatAchievementLibrary.load(stream("{\"tasks\":["
			+ "{\"id\":10,\"name\":\"Vorkath Kill\",\"tier\":\"Elite\",\"type\":\"Kill Count\","
			+ "\"monster\":\"Vorkath\",\"description\":\"\"}]}"));
		EffortDataLibrary el = EffortDataLibrary.load(
			stream("{\"tasks\":{\"10\":{\"questReqs\":[\"Dragon Slayer II\"]}}}"));
		SignalsProvider signals = new ProfileSignalsProvider(el, PlayerProfile.empty()); // quest not done
		ProgressSnapshot present = new ProgressSnapshot(Collections.<Integer>emptySet(), 0, 0, null, 0L);

		SidePanelViewModel vm = new SidePanelViewModelBuilder(lib, el, VideoGuideLibrary.empty(),
			GuideLibrary.empty(), EffortModel.standard()).build(present, signals, null);

		SidePanelViewModel.BossRow vork = null;
		for (SidePanelViewModel.BossRow b : vm.bosses())
		{
			if ("Vorkath".equals(b.monster))
			{
				vork = b;
				break;
			}
		}
		assertNotNull("Vorkath appears in the Bosses directory", vork);
		assertTrue("a fully quest-gated boss is flagged locked", vork.locked);
		assertEquals("no doable CAs", 0, vork.doableCount);
		assertEquals("its one CA is locked", 1, vork.lockedCount);
		assertEquals("needs Dragon Slayer II", vork.lockedCas.get(0).lockReason);
	}

	@Test
	public void bossesModeCountsOnlyIncompleteCas()
	{
		// Two CAs at the same boss; one is already completed. The Bosses (sessions) view must exclude the
		// completed CA from both the CA count and the projected points.
		CombatAchievementLibrary lib = CombatAchievementLibrary.load(stream("{\"tasks\":["
			+ "{\"id\":10,\"name\":\"Done\",\"tier\":\"Medium\",\"type\":\"Kill Count\","
			+ "\"monster\":\"Boss\",\"description\":\"\"},"
			+ "{\"id\":11,\"name\":\"Todo\",\"tier\":\"Medium\",\"type\":\"Kill Count\","
			+ "\"monster\":\"Boss\",\"description\":\"\"}"
			+ "]}"));
		SignalsProvider allDoable = id -> new TaskLiveSignals(true, true, false, true);
		// id 10 is already completed; only id 11 remains.
		ProgressSnapshot snap = new ProgressSnapshot(Collections.singleton(10), 0, 0, null, 0L);

		SidePanelViewModel vm = builder(lib).build(snap, allDoable, null);

		SidePanelViewModel.SessionView boss = null;
		for (SidePanelViewModel.SessionView s : vm.sessions())
		{
			if ("Boss".equals(s.monster))
			{
				boss = s;
				break;
			}
		}
		assertNotNull("the boss should still appear (it has an incomplete CA)", boss);
		assertEquals("only the 1 incomplete CA is counted", 1, boss.taskCount);
		assertEquals("projected points exclude the completed CA", 2, boss.totalPoints);
		for (SidePanelViewModel.SessionTaskView t : boss.tasks)
		{
			assertTrue("the completed CA (id 10) must not be listed", t.id != 10);
		}
	}

	@Test
	public void injectedDifficultyLibraryChangesQuickWinsOrderThroughTheBuilder()
	{
		CombatAchievementLibrary lib = twoTaskLib();

		// Without difficulty data, the 6-pt Grandmaster task leads on raw points/effort.
		SidePanelViewModel noDifficulty = build(builder(lib));
		assertEquals("no difficulty -> higher-points task first", 11, noDifficulty.quickWins().get(0).id);

		// Injecting a difficulty library that rates the Grandmaster task hard (9) and the Medium easy (2)
		// must flip the order — proving .difficulty() is genuinely wired into the built ranker.
		TaskDifficultyLibrary diff = TaskDifficultyLibrary.load(
			stream("{\"tasks\":{\"10\":{\"difficulty\":2},\"11\":{\"difficulty\":9}}}"));
		SidePanelViewModel withDifficulty = build(builder(lib).difficulty(diff));
		assertEquals("difficulty wired -> easy task first", 10, withDifficulty.quickWins().get(0).id);
	}

	@Test
	public void rankingWeightsThroughTheBuilderTuneThePointsAndDifficultyBalance()
	{
		CombatAchievementLibrary lib = twoTaskLib(); // 10 = easy 2pt, 11 = hard 6pt
		TaskDifficultyLibrary diff = TaskDifficultyLibrary.load(
			stream("{\"tasks\":{\"10\":{\"difficulty\":2},\"11\":{\"difficulty\":9}}}"));

		// Neutral weights: the hard-but-high-points task sinks below the easy one (difficulty wins).
		assertEquals("neutral -> easy task first",
			10, build(builder(lib).difficulty(diff).rankingWeights(1.0, 1.0)).quickWins().get(0).id);

		// Difficulty weight 0 ignores difficulty, so the 6-pt task leads again on points.
		assertEquals("difficulty weight 0 -> high-point task first",
			11, build(builder(lib).difficulty(diff).rankingWeights(1.0, 0.0)).quickWins().get(0).id);

		// A strong points weight overpowers the difficulty penalty and re-floats the 6-pt task.
		assertEquals("high points weight -> high-point task first",
			11, build(builder(lib).difficulty(diff).rankingWeights(3.0, 1.0)).quickWins().get(0).id);
	}
}

package com.pluginideahub.combatachievements.core.video;

import java.io.ByteArrayInputStream;
import java.nio.charset.StandardCharsets;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

public class VideoGuideLibraryTest
{
	private static VideoGuideLibrary fixture()
	{
		String json = "{\"_comment\":\"ignored\","
			+ "\"1\":[\"https://youtu.be/aaa\"],"
			+ "\"2\":[\"https://youtu.be/bbb\",\"https://youtu.be/ccc\"]}";
		return VideoGuideLibrary.load(new ByteArrayInputStream(json.getBytes(StandardCharsets.UTF_8)));
	}

	@Test
	public void curatedLinksLoad()
	{
		VideoGuideLibrary lib = fixture();
		assertEquals(2, lib.curatedCount());
		assertTrue(lib.hasCuratedGuide(1));
		assertEquals(1, lib.guidesFor(1).size());
		assertEquals(2, lib.guidesFor(2).size());
		assertEquals("https://youtu.be/aaa", lib.bestGuideUrl(1, "Whatever"));
	}

	@Test
	public void missingTaskFallsBackToSearch()
	{
		VideoGuideLibrary lib = fixture();
		assertFalse(lib.hasCuratedGuide(99));
		assertTrue(lib.guidesFor(99).isEmpty());
		assertEquals("https://www.youtube.com/results?search_query=OSRS+Noxious+Foe",
			lib.bestGuideUrl(99, "https://www.youtube.com/results?search_query=OSRS+Noxious+Foe"));
	}

	@Test
	public void nonNumericKeysAreIgnored()
	{
		VideoGuideLibrary lib = fixture();
		// "_comment" must not have been parsed as a guide entry
		assertEquals(2, lib.curatedCount());
	}
}

package com.pluginideahub.combatachievements.varbit;

import com.google.gson.JsonArray;
import com.google.gson.JsonObject;
import com.google.gson.JsonParser;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.nio.charset.StandardCharsets;
import org.junit.Test;

import static org.junit.Assert.assertTrue;

/**
 * The bug this guards against shipped once already: the game grew from 637 to 646 tasks (Maggot
 * King) and the completion bitfield stayed at 20 varps / 640 bits, so tasks 640-645 silently read
 * as incomplete and players were shown the wrong tier. The reader bounds-checks rather than
 * crashing, which is correct at runtime, so this run is where the drift gets noticed. Warns rather
 * than fails: CA_POINTS keeps the tier right, only per-task checkmarks go stale.
 */
public class CaVarbitIdsTest
{
	@Test
	public void bitfieldCoversEveryBundledTask() throws Exception
	{
		int maxId = -1;
		try (InputStream in = CaVarbitIdsTest.class.getResourceAsStream(
			"/com/pluginideahub/combatachievements/combat_achievements.json"))
		{
			JsonObject root = new JsonParser()
				.parse(new InputStreamReader(in, StandardCharsets.UTF_8)).getAsJsonObject();
			JsonArray tasks = root.getAsJsonArray("tasks");
			for (int i = 0; i < tasks.size(); i++)
			{
				maxId = Math.max(maxId, tasks.get(i).getAsJsonObject().get("id").getAsInt());
			}
		}
		int capacity = CaVarbitIds.varpCount() * 32;
		if (maxId >= capacity)
		{
			// Deliberately a warning, not a failure: tier maths stays right via CA_POINTS, only the
			// per-task checkmarks past the capacity read as incomplete.
			System.err.println("WARNING: dataset has task id " + maxId
				+ " but the completion bitfield only covers ids 0-" + (capacity - 1)
				+ "; add the next ca_task_completed_N varp to CaVarbitIds or those tasks read as not done");
		}
		assertTrue("dataset looks empty", maxId > 600);
	}
}
